CREATE OR REPLACE FUNCTION "app_private"."can_manage_company_members"("target_company_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select auth.uid() is not null
     and exists (
       select 1
       from public.company_members cm
       join public.companies c on c.id = cm.company_id
       join public.users u on u.id = cm.user_id
       where cm.company_id = target_company_id
         and cm.user_id = auth.uid()
         and cm.is_active
         and c.is_active
         and upper(coalesce(cm.role, 'MEMBER')) in ('OWNER', 'ADMIN')
         and u.deleted_at is null
         and u.is_active
         and u.status::text = 'ACTIVE'
     );
$$;


ALTER FUNCTION "app_private"."can_manage_company_members"("target_company_id" "uuid") OWNER TO "postgres";


