CREATE OR REPLACE FUNCTION "public"."_owner_statement_expenses"("p_owner_id" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("tx_date" "text", "details" "text", "tx_type" "text", "property_name" "text", "gross" numeric, "deduction" numeric, "sort_no" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'expenses' AND column_name = 'charged_to'
  ) AND EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'expenses' AND column_name = 'status'
  ) AND EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'expenses' AND column_name = 'date_time'
  ) AND EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'expenses' AND column_name = 'contract_id'
  ) THEN
    RETURN QUERY EXECUTE $owner_expenses$
      SELECT e.date_time,
        'مصروف — ' || COALESCE(e.description, e.category),
        'expense', COALESCE(pr.title, ''), -e.amount, 0::numeric,
        COALESCE(e.no, e.id::text)
      FROM public.expenses e
      LEFT JOIN public.properties pr ON pr.id = e.property_id
      WHERE e.deleted_at IS NULL
        AND upper(COALESCE(e.status, '')) = 'POSTED'
        AND upper(COALESCE(e.charged_to, '')) = 'OWNER'
        AND public._safe_date(e.date_time) BETWEEN $2 AND $3
        AND EXISTS (
          SELECT 1 FROM public.property_owners po
          WHERE po.property_id = e.property_id AND po.owner_id = $1
            AND (po.starts_on IS NULL OR po.starts_on <= public._safe_date(e.date_time))
            AND (po.ends_on IS NULL OR po.ends_on >= public._safe_date(e.date_time))
        )
    $owner_expenses$ USING p_owner_id, p_from, p_to;
  END IF;
END;
$_$;


ALTER FUNCTION "public"."_owner_statement_expenses"("p_owner_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_r3"("v" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT round(COALESCE(v, 0), 3)
$$;


ALTER FUNCTION "public"."_r3"("v" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_safe_date"("v" "text") RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN v ~ '^\d{4}-\d{2}-\d{2}' THEN v::date ELSE NULL END
$$;


ALTER FUNCTION "public"."_safe_date"("v" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_contract_with_agreement_snapshot_atomic"("p_contract_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_company uuid := public.require_company_id();
  v_contract public.contracts%rowtype;
  -- Explicit columns (not %rowtype) so this SECURITY DEFINER function does not
  -- hard-require owner_agreement_versions to exist at CREATE time. The table is
  -- resolved only at execution; the historical P0 tenant-isolation checkpoint
  -- replays a curated subset of migrations without the S04 snapshot provider
  -- and still applies this hardening without a catalog dependency failure.
  v_version_id uuid;
  v_version_collection_role text;
  v_version_operating_model text;
  v_start date;
  v_end date;
  v_result jsonb;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'CONTRACT_ACTIVATION_FORBIDDEN' using errcode='42501';
  end if;

  select * into v_contract from public.contracts
  where id::text = p_contract_id and company_id=v_company and deleted_at is null
  for update;

  if not found then raise exception 'CONTRACT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if;
  if lower(coalesce(v_contract.status,'')) <> 'draft'
     or coalesce(v_contract.approval_status, '') <> 'APPROVED' then
    raise exception 'CONTRACT_APPROVAL_REQUIRED' using errcode='23514';
  end if;
  if v_contract.maker_user_id is null or v_contract.checker_user_id is null
     or v_contract.maker_user_id = v_contract.checker_user_id
     or nullif(btrim(coalesce(v_contract.maker_signature,'')), '') is null
     or nullif(btrim(coalesce(v_contract.checker_signature,'')), '') is null
     or v_contract.approved_at is null then
    raise exception 'CONTRACT_SIGNATURE_EVIDENCE_REQUIRED' using errcode='23514';
  end if;
  if v_contract.agreement_id is null then
    raise exception 'CONTRACT_AGREEMENT_REQUIRED' using errcode='23514';
  end if;
  if btrim(coalesce(v_contract.start_date::text,'')) !~ '^\d{4}-\d{2}-\d{2}$'
     or btrim(coalesce(v_contract.end_date::text,'')) !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception 'CONTRACT_DATES_INVALID' using errcode='22007';
  end if;

  v_start := btrim(v_contract.start_date::text)::date;
  v_end := btrim(v_contract.end_date::text)::date;

  select v.id, v.collection_role, v.operating_model
    into v_version_id, v_version_collection_role, v_version_operating_model
  from public.owner_agreement_versions v
  join public.owner_agreements oa on oa.id=v.owner_agreement_id
  where v.owner_agreement_id=v_contract.agreement_id
    and v.company_id=v_company
    and oa.company_id=v_company
    and oa.agreement_type='property_management'
    and v.effective_from <= v_start
    and (v.effective_to is null or v.effective_to >= v_end)
  order by v.version_no desc
  limit 1;

  if v_version_id is null then
    raise exception 'CONTRACT_AGREEMENT_VERSION_COVERAGE_REQUIRED' using errcode='23514';
  end if;

  update public.contracts c
  set agreement_version_id=v_version_id,
      collection_role_snapshot=v_version_collection_role,
      operating_model_snapshot=v_version_operating_model,
      status='active',
      updated_at=now()
  where c.id::text=p_contract_id and c.company_id=v_company and c.deleted_at is null
  returning to_jsonb(c) into v_result;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."activate_contract_with_agreement_snapshot_atomic"("p_contract_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."activate_contract_with_agreement_snapshot_atomic"("p_contract_id" "text") IS 'S04-T03 over S04-T02: activates only an independently approved draft contract with complete signature evidence and frozen owner-agreement snapshot.';



CREATE OR REPLACE FUNCTION "public"."apply_deposit_claim_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_claim_id uuid := nullif(p_payload->>'claim_id','')::uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_effective_date date := nullif(p_payload->>'effective_date','')::date;
  v_claim public.deposit_application_claims%rowtype;
  v_remaining numeric;
  v_deducted numeric;
  v_invoice_outstanding numeric;
  v_invoice_id uuid;
  v_dep_account text;
  v_target_account text;
  v_post jsonb;
  v_batch_id uuid;
  v_rows integer;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DEPOSIT_APPLICATION_ROLE_REQUIRED' using errcode='42501';
  end if;
  v_company_id := public.require_company_id();
  if p_payload ?| array['company_id','amount','allocation_amount','target_type','target_account_no','lines'] then
    raise exception 'DEPOSIT_APPLICATION_CLIENT_FINANCIAL_INPUT_FORBIDDEN' using errcode='22023';
  end if;
  if v_claim_id is null or v_request_id is null or v_effective_date is null then
    raise exception 'DEPOSIT_APPLICATION_CLAIM_REQUEST_DATE_REQUIRED' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('deposit_apply:'||v_company_id::text||':'||v_claim_id::text,0));
  select * into v_claim from public.deposit_application_claims
   where id=v_claim_id and company_id=v_company_id for update;
  if not found then raise exception 'DEPOSIT_CLAIM_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if;
  if v_claim.status='APPLIED' then
    if v_claim.application_request_id<>v_request_id then raise exception 'DEPOSIT_APPLICATION_IDEMPOTENCY_CONFLICT' using errcode='22023'; end if;
    return jsonb_build_object('success',true,'idempotent',true,'claim_id',v_claim.id,'batch_id',v_claim.application_journal_batch_id,'status','APPLIED');
  end if;
  if v_claim.status<>'APPROVED' then raise exception 'DEPOSIT_APPLICATION_APPROVED_CLAIM_REQUIRED' using errcode='22023'; end if;

  select d.remaining_amount,d.deducted_amount into v_remaining,v_deducted
  from public.tenant_deposits d
  where d.id::text=v_claim.deposit_id and d.company_id=v_company_id and d.deleted_at is null
  for update;
  if not found then raise exception 'DEPOSIT_APPLICATION_DEPOSIT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if;
  if v_claim.allocation_amount>v_remaining then raise exception 'DEPOSIT_APPLICATION_EXCEEDS_REMAINING' using errcode='22023'; end if;

  -- Re-validate the invoice at apply time (stale-invoice protection): the
  -- invoice must still exist, be company/contract scoped, not VOID/CANCELLED,
  -- and still have at least the allocation amount outstanding.
  if v_claim.claim_kind='INVOICE_ARREARS' then
    select i.id, public.gl_pm_round_omr(coalesce(i.amount,0)+coalesce(i.tax_amount,0)-coalesce(i.paid_amount,0))
      into v_invoice_id, v_invoice_outstanding
    from public.invoices i
    where i.id::text=v_claim.invoice_id
      and i.company_id=v_company_id
      and i.contract_id::text=v_claim.contract_id
      and i.deleted_at is null
      and coalesce(upper(i.status::text),'') not in ('VOID','VOIDED','CANCELLED')
    for update;
    if not found or v_invoice_outstanding<=0 or v_claim.allocation_amount>v_invoice_outstanding then
      raise exception 'DEPOSIT_APPLICATION_INVOICE_NO_LONGER_ELIGIBLE' using errcode='22023';
    end if;
  end if;

  v_dep_account := public.gl_pm_require_account(v_company_id,'2200');
  v_target_account := public.gl_pm_require_account(v_company_id,v_claim.target_account_no);
  v_post := public.post_journal_event(jsonb_build_object(
    'company_id',v_company_id,'source_type','pm_deposit_application','source_id',v_claim.id::text,
    'event_id','apply','effective_date',v_effective_date,
    'description','Approved evidence-backed deposit application',
    'lines',jsonb_build_array(
      jsonb_build_object('account_id',v_dep_account,'debit',v_claim.allocation_amount,'credit',0,'ref_source_id',v_claim.id::text,'ref_entity_type','deposit_claim','ref_entity_id',v_claim.deposit_id),
      jsonb_build_object('account_id',v_target_account,'debit',0,'credit',v_claim.allocation_amount,'ref_source_id',v_claim.id::text,'ref_entity_type','deposit_claim','ref_entity_id',coalesce(v_claim.invoice_id,v_claim.id::text))
    )
  ));
  v_batch_id := (v_post->>'batch_id')::uuid;

  -- GAP-009 subledger parity: an OFFICE-creditor arrears application settles
  -- the authoritative invoice/tenant-receivable operational subledger
  -- atomically with the GL posting (same mechanism post_receipt_atomic uses).
  -- OWNER-creditor arrears post to 2000 and intentionally leave the
  -- operational tenant AR untouched (FIN-003: tenant AR remains operational).
  if v_claim.claim_kind='INVOICE_ARREARS' and v_claim.target_account_no='1201' and v_invoice_id is not null then
    update public.invoices
       set paid_amount = public.gl_pm_round_omr(coalesce(paid_amount,0) + v_claim.allocation_amount),
           updated_at = now()
     where id = v_invoice_id and company_id = v_company_id;
    perform public.recalculate_invoice_status(v_invoice_id);
  end if;

  insert into public.deposit_transactions(deposit_id,type,amount,reason,description,request_id,company_id,journal_batch_id)
  values(v_claim.deposit_id,'deduction',v_claim.allocation_amount,
    case when v_claim.claim_kind='DAMAGE' then 'maintenance_damage' else 'unpaid_arrears' end,
    'Governed deposit claim '||v_claim.id::text,v_request_id,v_company_id,v_batch_id)
  on conflict(request_id) do nothing;
  get diagnostics v_rows=row_count;
  if v_rows<>1 then raise exception 'DEPOSIT_APPLICATION_TRANSACTION_CONFLICT' using errcode='23505'; end if;

  update public.tenant_deposits
     set deducted_amount=public.gl_pm_round_omr(deducted_amount+v_claim.allocation_amount),
         remaining_amount=public.gl_pm_round_omr(remaining_amount-v_claim.allocation_amount),
         status=case when public.gl_pm_round_omr(remaining_amount-v_claim.allocation_amount)=0
              then case when v_claim.claim_kind='DAMAGE' then 'forfeited_damage' else 'forfeited_arrears' end
              else 'partially_deducted' end,
         settled_date=case when public.gl_pm_round_omr(remaining_amount-v_claim.allocation_amount)=0 then v_effective_date else settled_date end,
         updated_at=now()
   where id::text=v_claim.deposit_id and company_id=v_company_id;

  update public.deposit_application_claims
     set status='APPLIED',application_request_id=v_request_id,application_effective_date=v_effective_date,
         application_journal_batch_id=v_batch_id,applied_by=v_actor,applied_at=now(),updated_at=now()
   where id=v_claim.id;

  return jsonb_build_object('success',true,'idempotent',false,'claim_id',v_claim.id,'deposit_id',v_claim.deposit_id,
    'amount',v_claim.allocation_amount,'target_account_no',v_claim.target_account_no,'batch_id',v_batch_id,
    'invoice_id',v_claim.invoice_id,'status','APPLIED');
end;
$$;


ALTER FUNCTION "public"."apply_deposit_claim_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_contract_atomic"("p_contract_id" "text", "p_checker_signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := public.require_company_id();
  v_actor uuid := auth.uid();
  v_contract public.contracts%rowtype;
  v_now timestamptz := now();
  v_result jsonb;
begin
  if v_actor is null or not public.is_admin_or_manager() then
    raise exception 'CONTRACT_APPROVAL_FORBIDDEN' using errcode='42501';
  end if;
  if nullif(btrim(coalesce(p_checker_signature,'')), '') is null then
    raise exception 'CHECKER_SIGNATURE_REQUIRED' using errcode='22023';
  end if;

  select * into v_contract
  from public.contracts
  where id::text = p_contract_id
    and company_id = v_company
    and deleted_at is null
  for update;

  if not found then
    raise exception 'CONTRACT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;
  if lower(coalesce(v_contract.status,'')) <> 'draft'
     or v_contract.approval_status <> 'PENDING' then
    raise exception 'CONTRACT_NOT_PENDING_APPROVAL' using errcode='22023';
  end if;
  if v_contract.maker_user_id is null
     or nullif(btrim(coalesce(v_contract.maker_signature,'')), '') is null then
    raise exception 'MAKER_EVIDENCE_REQUIRED' using errcode='23514';
  end if;
  if v_actor = v_contract.maker_user_id then
    if not public.wp01_is_sole_admin_allowed(v_company) then
      raise exception 'MAKER_CHECKER_MUST_BE_DISTINCT' using errcode='42501';
    end if;
  end if;

  update public.contracts c
  set checker_user_id = v_actor,
      checker_signature = btrim(p_checker_signature),
      approval_status = 'APPROVED',
      approved_at = v_now,
      rejected_at = null,
      rejection_reason = null,
      is_sole_admin_exception = (v_actor = v_contract.maker_user_id),
      updated_at = v_now
  where id = v_contract.id;

  v_result := jsonb_build_object(
    'success', true,
    'id', v_contract.id,
    'status', 'APPROVED',
    'checker_user_id', v_actor,
    'is_sole_admin_exception', (v_actor = v_contract.maker_user_id)
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."approve_contract_atomic"("p_contract_id" "text", "p_checker_signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_contract_atomic"("p_contract_id" "text", "p_checker_signature" "text") IS 'S04-T03: distinct checker approves a draft contract pending approval and records checker signature evidence.';



CREATE OR REPLACE FUNCTION "public"."approve_deposit_application_claim_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_claim_id uuid := nullif(p_payload->>'claim_id','')::uuid;
  v_claim public.deposit_application_claims%rowtype;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DEPOSIT_CLAIM_APPROVER_ROLE_REQUIRED' using errcode='42501';
  end if;
  v_company_id := public.require_company_id();
  select * into v_claim from public.deposit_application_claims
   where id=v_claim_id and company_id=v_company_id for update;
  if not found then raise exception 'DEPOSIT_CLAIM_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if;
  if v_claim.status='APPROVED' then
    return jsonb_build_object('success',true,'idempotent',true,'claim_id',v_claim.id,'status',v_claim.status);
  end if;
  if v_claim.status<>'PENDING' then raise exception 'DEPOSIT_CLAIM_NOT_PENDING' using errcode='22023'; end if;
  
  if v_claim.created_by=v_actor then
    if not public.wp01_is_sole_admin_allowed(v_company_id) then
      raise exception 'DEPOSIT_CLAIM_MAKER_CHECKER_REQUIRED' using errcode='42501';
    end if;
  end if;

  update public.deposit_application_claims
     set status='APPROVED',
         approved_by=v_actor,
         approved_at=now(),
         is_sole_admin_exception=(v_claim.created_by=v_actor),
         updated_at=now()
   where id=v_claim.id;
  return jsonb_build_object('success',true,'idempotent',false,'claim_id',v_claim.id,'status','APPROVED');
end;
$$;


ALTER FUNCTION "public"."approve_deposit_application_claim_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_fee_tax_treatment_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid := public.require_company_id();
  v_id uuid := nullif(p_payload->>'treatment_id','')::uuid;
  v_request_id text := nullif(btrim(p_payload->>'request_id'),'');
  v_t public.company_fee_tax_treatments%rowtype;
  v_fp text;
  v_cached jsonb;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'FEE_TAX_TREATMENT_APPROVER_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_payload ? 'company_id' or v_id is null or v_request_id is null then
    raise exception 'FEE_TAX_TREATMENT_APPROVAL_INPUT_REQUIRED' using errcode='22023';
  end if;

  v_fp := encode(sha256(convert_to(jsonb_build_object(
    'treatment_id', v_id::text
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended(
    'approve_fee_tax_treatment:' || v_company_id::text || ':' || v_request_id, 0
  ));

  select response_payload into v_cached
    from public.financial_operation_idempotency
   where operation_name = 'approve_fee_tax_treatment:' || v_company_id::text
     and request_id = v_request_id
   for update;

  if v_cached is not null then
    if v_cached->>'_request_fingerprint' is distinct from v_fp
       or v_cached->>'_target' is distinct from v_id::text
       or not (v_cached ? 'response') then
      raise exception 'FEE_TAX_TREATMENT_APPROVAL_IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode='22023';
    end if;
    return v_cached->'response';
  end if;

  select * into v_t
    from public.company_fee_tax_treatments
   where id = v_id
     and company_id = v_company_id
   for update;
  if not found then
    raise exception 'FEE_TAX_TREATMENT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'fee_tax_treatment_approve:' || v_company_id::text || ':' || v_t.fee_kind, 0
  ));

  if v_t.tax_code in ('NON_TAXABLE','VAT_ZERO') and v_t.tax_rate <> 0 then
    raise exception 'FEE_TAX_TREATMENT_ZERO_CODE_RATE_INVALID: % must use 0.000.', v_t.tax_code
      using errcode='23514';
  end if;

  if v_t.status = 'ACTIVE' then
    v_result := jsonb_build_object(
      'success', true,
      'idempotent', true,
      'already_active', true,
      'treatment_id', v_id,
      'status', 'ACTIVE'
    );
  else
    if v_t.status <> 'DRAFT' or v_t.created_by = v_actor then
      raise exception 'FEE_TAX_TREATMENT_MAKER_CHECKER_REQUIRED' using errcode='42501';
    end if;

    update public.company_fee_tax_treatments
       set status = 'SUPERSEDED',
           updated_at = now(),
           effective_to = least(coalesce(effective_to, v_t.effective_from - 1), v_t.effective_from - 1)
     where company_id = v_company_id
       and fee_kind = v_t.fee_kind
       and status = 'ACTIVE'
       and effective_from < v_t.effective_from;

    update public.company_fee_tax_treatments
       set status = 'ACTIVE',
           approved_by = v_actor,
           approved_at = now(),
           updated_at = now()
     where id = v_id
       and company_id = v_company_id;

    v_result := jsonb_build_object(
      'success', true,
      'idempotent', false,
      'treatment_id', v_id,
      'status', 'ACTIVE'
    );
  end if;

  insert into public.financial_operation_idempotency(operation_name, request_id, response_payload)
  values (
    'approve_fee_tax_treatment:' || v_company_id::text,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_fp,
      '_target', v_id::text,
      'response', v_result
    )
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."approve_fee_tax_treatment_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_owner_funds_cutover_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid := public.require_company_id();
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_cutover public.owner_funds_event_cutovers%rowtype;
  v_balance numeric;
  v_count bigint;
  v_fingerprint text;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'OWNER_FUNDS_CUTOVER_APPROVER_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_payload ? 'company_id' or v_request_id is null then
    raise exception 'OWNER_FUNDS_CUTOVER_APPROVAL_REQUEST_REQUIRED' using errcode='22023';
  end if;

  select * into v_cutover
    from public.owner_funds_event_cutovers
   where company_id = v_company_id
   for update;
  if not found then
    raise exception 'OWNER_FUNDS_CUTOVER_NOT_FOUND' using errcode='P0002';
  end if;

  if v_cutover.status = 'APPROVED' then
    if v_cutover.approval_request_id <> v_request_id then
      raise exception 'OWNER_FUNDS_CUTOVER_ALREADY_APPROVED' using errcode='22023';
    end if;
    return jsonb_build_object('success', true, 'idempotent', true, 'status', 'APPROVED');
  end if;

  if v_cutover.status <> 'DRAFT' or v_cutover.created_by = v_actor then
    raise exception 'OWNER_FUNDS_CUTOVER_MAKER_CHECKER_REQUIRED' using errcode='42501';
  end if;
  if not exists (
    select 1
      from public.s08_frozen_reviews r
     where r.id = v_cutover.s08_review_id
       and r.company_id = v_company_id
       and r.reviewer_decision = 'APPROVED'
  ) then
    raise exception 'OWNER_FUNDS_CUTOVER_S08_APPROVAL_REQUIRED' using errcode='42501';
  end if;

  select public.wp05_gl_balance(v_company_id, '2000', v_cutover.cutover_date),
         public.wp05_gl_line_count(v_company_id, '2000', v_cutover.cutover_date)
    into v_balance, v_count;

  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'company_id', v_company_id,
    'cutover_date', v_cutover.cutover_date,
    'opening_balance', public.wp05_round_omr(v_balance),
    'gl_line_count', v_count,
    's08_review_id', v_cutover.s08_review_id
  )::text, 'UTF8')), 'hex');

  if public.wp05_round_omr(v_balance) is distinct from v_cutover.opening_balance
     or v_count is distinct from v_cutover.gl_line_count
     or v_fingerprint is distinct from v_cutover.source_fingerprint then
    raise exception 'OWNER_FUNDS_CUTOVER_STALE_REVIEW_REQUIRED: 2000 changed after the draft baseline; create a fresh S08-backed cutover.'
      using errcode='23514';
  end if;

  update public.owner_funds_event_cutovers
     set status = 'APPROVED',
         approved_by = v_actor,
         approved_at = now(),
         approval_request_id = v_request_id
   where company_id = v_company_id;

  return jsonb_build_object('success', true, 'idempotent', false, 'status', 'APPROVED');
end;
$$;


ALTER FUNCTION "public"."approve_owner_funds_cutover_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_owner_settlement_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_id text := nullif(p_payload->>'settlement_id', '');
  v_status text;
  v_result jsonb;
begin
  v_company_id := public.current_company_id();

  if v_id is not null and v_company_id is not null then
    select s.status
      into v_status
      from public.owner_settlements s
     where s.id::text = v_id
       and s.company_id = v_company_id;

    if v_status = 'DRAFT' then
      perform public.assert_owner_settlement_totals_fresh(v_id);
    end if;
  end if;

  v_result := public.approve_owner_settlement_atomic_s02_base(p_payload);

  if not coalesce((v_result->>'idempotent')::boolean, false) then
    perform public.assert_owner_settlement_totals_fresh(v_result->>'settlement_id');
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."approve_owner_settlement_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_owner_settlement_atomic"("p_payload" "jsonb") IS 'S02-T05 guarded approval: FA-003 lifecycle semantics plus exact reserved-set parity and live stale-total rejection before first approval.';



CREATE OR REPLACE FUNCTION "public"."approve_owner_settlement_atomic_s02_base"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_id text := nullif(p_payload->>'settlement_id', '');
  v_row public.owner_settlements%rowtype;
  v_cached jsonb;
  v_result jsonb;
  v_operation_name text;
  v_request_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target_id text;
  v_updated_count integer;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to approve owner settlements.'
      using errcode = '42501';
  end if;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Company context is required (no company_id claim in JWT).'
      using errcode = '42501';
  end if;
  if v_id is null or v_request_id is null then
    raise exception 'settlement_id and request_id are required.'
      using errcode = '22023';
  end if;

  v_operation_name := 'approve_owner_settlement_atomic:' || v_company_id::text;
  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'settlement_id', v_id
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_operation_name || ':' || v_request_id, 0)
  );

  select *
    into v_row
  from public.owner_settlements s
  where s.id::text = v_id
    and s.company_id = v_company_id
  for update;

  if not found then
    raise exception 'Owner settlement not found.'
      using errcode = 'P0002';
  end if;

  select response_payload
    into v_cached
  from public.financial_operation_idempotency
  where operation_name = v_operation_name
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    v_cached_target_id := v_cached->>'_target_id';
    if v_cached_fingerprint is null
       or v_cached_target_id is null
       or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        using errcode = '22023';
    end if;
    if v_cached_fingerprint <> v_request_fingerprint
       or v_cached_target_id <> v_id then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode = '22023';
    end if;
    return (v_cached->'response') || jsonb_build_object('idempotent', true);
  end if;

  if v_row.status <> 'DRAFT' then
    raise exception 'Only DRAFT settlements can be approved.'
      using errcode = '22023';
  end if;

  -- ── FA-003: the settlement must be fully reserved by its derived items and
  -- must own no released link. We never re-select items from the date range.
  if exists (
    select 1
      from public.owner_settlement_reservable_payments(
        v_company_id, v_row.owner_id::uuid, v_row.period_start, v_row.period_end, v_row.property_id::text) p
      left join public.owner_settlement_payment_links l
        on l.payment_id = p and l.settlement_id = v_row.id::text
       and l.company_id = v_company_id and l.released_at is null
     where l.id is null
  ) or exists (
    select 1
      from public.owner_settlement_reservable_expenses(
        v_company_id, v_row.owner_id::uuid, v_row.period_start, v_row.period_end, v_row.property_id::text) e
      left join public.owner_settlement_expense_links l
        on l.expense_id = e and l.settlement_id = v_row.id::text
       and l.company_id = v_company_id and l.released_at is null
     where l.id is null
  ) then
    raise exception 'OWNER_SETTLEMENT_INCOMPLETE_RESERVATION: settlement is not fully reserved by its derived items.'
      using errcode = 'P0001';
  end if;
  if exists (
    select 1 from public.owner_settlement_payment_links l
     where l.settlement_id = v_row.id::text and l.company_id = v_company_id and l.released_at is not null
  ) or exists (
    select 1 from public.owner_settlement_expense_links l
     where l.settlement_id = v_row.id::text and l.company_id = v_company_id and l.released_at is not null
  ) then
    raise exception 'OWNER_SETTLEMENT_HAS_RELEASED_LINKS: released items cannot be approved.'
      using errcode = 'P0001';
  end if;

  update public.owner_settlements
     set status = 'APPROVED',
         approved_at = now(),
         approved_by = auth.uid(),
         updated_at = now()
   where id::text = v_id
     and company_id = v_company_id;
  get diagnostics v_updated_count = row_count;
  if v_updated_count <> 1 then
    raise exception 'OWNER_SETTLEMENT_UPDATE_COUNT_MISMATCH'
      using errcode = 'P0001';
  end if;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'APPROVE', 'owner_settlements', v_id,
    'Owner settlement approved; owner payable is recognized operationally',
    'owner_settlements', left(p_payload::text, 4000), now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'settlement_id', v_id,
    'status', 'APPROVED',
    'net_payable', v_row.net_payable,
    'request_id', v_request_id
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload
  ) values (
    v_operation_name,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_id,
      'response', v_result
    )
  )
  on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."approve_owner_settlement_atomic_s02_base"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_owner_settlement_atomic_s02_base"("p_payload" "jsonb") IS 'FA-003: approval requires the settlement to be fully reserved by its derived items with no released link.';



CREATE OR REPLACE FUNCTION "public"."approve_receipt_void_atomic"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid := public.current_company_id();
  v_void_request_id uuid := nullif(btrim(payload->>'void_request_id'), '')::uuid;
  v_execution_request_id text := nullif(btrim(payload->>'request_id'), '');
  v_request public.receipt_void_requests%rowtype;
  v_result jsonb;
  v_is_sole_admin_exception boolean := false;
begin
  if v_actor is null or not exists (
    select 1
    from public.users u
    where u.id = v_actor
      and u.status::text = 'ACTIVE'
      and u.role::text in ('ADMIN', 'MANAGER')
  ) then
    raise exception 'ADMIN or MANAGER role is required to approve receipt VOID.'
      using errcode = '42501';
  end if;

  if v_company_id is null then
    raise exception 'Company context is required to approve receipt VOID.'
      using errcode = '42501';
  end if;

  if v_void_request_id is null or v_execution_request_id is null then
    raise exception 'void_request_id and request_id are required.'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('receipt_void_approval:' || v_company_id::text || ':' || v_void_request_id::text, 0)
  );

  select q.*
    into v_request
  from public.receipt_void_requests q
  where q.id = v_void_request_id
    and q.company_id = v_company_id
  for update;

  if v_request.id is null then
    raise exception 'Receipt VOID request was not found in the active company.'
      using errcode = 'P0002';
  end if;

  if v_request.status = 'EXECUTED' then
    if v_request.execution_request_id <> v_execution_request_id
       or v_request.result_payload is null then
      raise exception 'RECEIPT_VOID_REQUEST_ALREADY_EXECUTED'
        using errcode = '22023';
    end if;
    return v_request.result_payload || jsonb_build_object('idempotent', true);
  end if;

  if v_request.status <> 'PENDING' then
    raise exception 'Only PENDING receipt VOID requests can be approved.'
      using errcode = '22023';
  end if;

  v_is_sole_admin_exception := (v_request.requested_by = v_actor);

  if v_is_sole_admin_exception
     and not public.wp01_is_sole_admin_allowed(v_company_id) then
    raise exception 'MAKER_CHECKER_SELF_APPROVAL_DENIED: receipt VOID requester cannot approve the same request.'
      using errcode = '42501';
  end if;

  v_result := public.execute_receipt_void_internal(jsonb_build_object(
    'receipt_id', v_request.receipt_id,
    'reason', v_request.reason,
    'request_id', 'void-approved:' || v_execution_request_id
  ));

  v_result := v_result || jsonb_build_object(
    'void_request_id', v_request.id,
    'void_request_status', 'EXECUTED',
    'requested_by', v_request.requested_by,
    'approved_by', v_actor,
    'approval_request_id', v_execution_request_id,
    'is_sole_admin_exception', v_is_sole_admin_exception
  );

  update public.receipt_void_requests
     set status = 'EXECUTED',
         reviewed_by = v_actor,
         reviewed_at = now(),
         execution_request_id = v_execution_request_id,
         reversal_batch_id = nullif(v_result->>'journal_reversal_batch_id', '')::uuid,
         result_payload = v_result,
         is_sole_admin_exception = v_is_sole_admin_exception,
         updated_at = now()
   where id = v_request.id;

  -- Preserve the canonical audit action/entity contract used by release
  -- evidence and operational audit queries. The sole-admin flag is additive.
  insert into public.audit_log (
    id, ts, user_id, action, entity, entity_id, note, "table", details,
    old_value, new_value, action_timestamp, created_at, updated_at
  ) values (
    gen_random_uuid()::text,
    extract(epoch from now())::bigint,
    v_actor::text,
    'APPROVE_RECEIPT_VOID',
    'receipt_void_request',
    v_request.id::text,
    'Receipt VOID separately approved and executed through the canonical reversal engine.',
    'receipt_void_requests',
    jsonb_build_object(
      'company_id', v_company_id,
      'receipt_id', v_request.receipt_id,
      'reason', v_request.reason,
      'requested_by', v_request.requested_by,
      'approved_by', v_actor,
      'approval_request_id', v_execution_request_id,
      'journal_reversal_batch_id', v_result->>'journal_reversal_batch_id',
      'is_sole_admin_exception', v_is_sole_admin_exception
    )::text,
    jsonb_build_object('status', 'PENDING'),
    jsonb_build_object(
      'status', 'EXECUTED',
      'requested_by', v_request.requested_by,
      'approved_by', v_actor,
      'is_sole_admin_exception', v_is_sole_admin_exception
    ),
    now(), now(), now()
  );

  return v_result || jsonb_build_object('idempotent', false);
end;
$$;


ALTER FUNCTION "public"."approve_receipt_void_atomic"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_receipt_void_atomic"("payload" "jsonb") IS 'WP-01 OPS-007/SEC-008: distinct ADMIN/MANAGER checker executes a PENDING receipt VOID request through the canonical reversal engine.';



CREATE OR REPLACE FUNCTION "public"."approve_tax_profile_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_profile_id uuid := nullif(p_payload->>'profile_id','')::uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_profile public.company_tax_profiles%rowtype;
  v_cached jsonb;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'TAX_PROFILE_APPROVER_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if v_profile_id is null or v_request_id is null then
    raise exception 'TAX_PROFILE_APPROVE_ID_REQUEST_REQUIRED' using errcode = '22023';
  end if;

  select * into v_profile
    from public.company_tax_profiles where id = v_profile_id and company_id = v_company_id for update;
  if not found then
    raise exception 'TAX_PROFILE_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;
  if v_profile.status = 'ACTIVE' then
    return jsonb_build_object('success', true, 'idempotent', true, 'profile_id', v_profile.id, 'status', 'ACTIVE');
  end if;
  if v_profile.status <> 'DRAFT' then
    raise exception 'TAX_PROFILE_NOT_DRAFT' using errcode = '22023';
  end if;

  if v_profile.created_by = v_actor then
    if not public.wp01_is_sole_admin_allowed(v_company_id) then
      raise exception 'TAX_PROFILE_MAKER_CHECKER_REQUIRED: a different approver must activate the profile.' using errcode = '42501';
    end if;
  end if;

  -- Supersede any currently ACTIVE profile with an overlapping effective window.
  update public.company_tax_profiles
     set status = 'SUPERSEDED', updated_at = now()
   where company_id = v_company_id
     and id <> v_profile.id
     and status = 'ACTIVE'
     and (effective_to is null or effective_from <= coalesce(v_profile.effective_to, 'infinity'::date));

  update public.company_tax_profiles
     set status = 'ACTIVE',
         approved_by = v_actor,
         approved_at = now(),
         is_sole_admin_exception = (v_profile.created_by = v_actor),
         updated_at = now()
   where id = v_profile.id;

  v_result := jsonb_build_object('success', true, 'idempotent', false, 'profile_id', v_profile.id, 'status', 'ACTIVE',
    'tax_code', v_profile.tax_code, 'tax_rate', v_profile.tax_rate, 'request_id', v_request_id);
  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('approve_tax_profile_atomic:' || v_company_id::text, v_request_id, v_result)
  on conflict (operation_name, request_id) do nothing;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."approve_tax_profile_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_service_provider_atomic"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_provider public.service_providers;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if not public.current_user_has_effective_app_permission('service_providers.write') then
    raise exception 'Service provider write permission required' using errcode = '42501';
  end if;

  update public.service_providers provider
  set is_active = false,
      deleted_at = now()
  where provider.id = p_provider_id
    and provider.company_id = v_company_id
    and provider.deleted_at is null
  returning * into v_provider;
  if not found then
    raise exception 'Service provider not found' using errcode = 'P0002';
  end if;

  return jsonb_build_object('provider_id', v_provider.id, 'archived', true);
end;
$$;


