CREATE OR REPLACE FUNCTION "public"."assert_owner_funds_event_cutover"("p_company_id" "uuid", "p_effective_date" "date", "p_current_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_cutover public.owner_funds_event_cutovers%rowtype;
begin
  if p_company_id is null or p_effective_date is null then
    raise exception 'OWNER_FUNDS_CUTOVER_INPUT_REQUIRED' using errcode='22023';
  end if;
  select * into v_cutover from public.owner_funds_event_cutovers where company_id = p_company_id;
  if found and v_cutover.status = 'APPROVED' then
    if p_effective_date <= v_cutover.cutover_date then
      raise exception 'OWNER_FUNDS_EVENT_PRE_CUTOVER_REVIEW_REQUIRED' using errcode='23514';
    end if;
    return;
  end if;

  -- A clean/new company has no pre-existing 2000 source batch and may begin
  -- with a zero opening position. A company with historical 2000 history must
  -- freeze and approve an S08-backed baseline before its first RC1 event.
  if exists (
    select 1
      from public.journal_lines jl
      join public.accounts a on a.id = jl.account_id and a.company_id = p_company_id
      join public.journal_batches jb on jb.id = jl.batch_id and jb.company_id = p_company_id
     where jl.company_id = p_company_id
       and a.no = '2000'
       and jl.batch_id is distinct from p_current_batch_id
       and not exists (
         select 1 from public.owner_funds_events e
          where e.company_id = p_company_id and e.journal_batch_id = jl.batch_id
       )
  ) then
    raise exception 'OWNER_FUNDS_CUTOVER_REVIEW_REQUIRED: historical 2000 position requires an approved S08-backed cutover baseline before RC1 owner-funds events.'
      using errcode='23514';
  end if;
end;
$$;


ALTER FUNCTION "public"."assert_owner_funds_event_cutover"("p_company_id" "uuid", "p_effective_date" "date", "p_current_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_owner_funds_event_cutover"("p_company_id" "uuid", "p_effective_date" "date", "p_current_batch_id" "uuid") IS 'Fails closed for a company with historical 2000 GL sources until an S08-approved immutable opening cutover is approved.';



CREATE OR REPLACE FUNCTION "public"."assert_owner_settlement_links_backfillable"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dupe_payments int;
  v_dupe_expenses int;
  v_mismatch int;
begin
  with ps as (
    select s.id as settlement_id, p.id as payment_id
      from public.owner_settlements s
      cross join lateral public.owner_settlement_reservable_payments(
        s.company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
      ) as p(id)
     where s.status <> 'CANCELLED'
  )
  select coalesce(count(*), 0) into v_dupe_payments
    from (select payment_id from ps group by payment_id having count(*) > 1) t;

  with es as (
    select s.id as settlement_id, e.id as expense_id
      from public.owner_settlements s
      cross join lateral public.owner_settlement_reservable_expenses(
        s.company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
      ) as e(id)
     where s.status <> 'CANCELLED'
  )
  select coalesce(count(*), 0) into v_dupe_expenses
    from (select expense_id from es group by expense_id having count(*) > 1) t;

  select coalesce(count(*), 0) into v_mismatch
    from public.owner_settlements s
   where s.status <> 'CANCELLED'
     and (
       abs(s.owner_expenses - coalesce((
         select sum(e.amount)
           from public.owner_settlement_reservable_expenses(
             s.company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
           ) as eid
           join public.expenses e on e.id = eid
       ), 0)) > 0.001
       or (
         exists (select 1 from public.owner_settlement_reservable_payments(
           s.company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text))
         and abs(s.gross_collected - coalesce((
           select sum(p.amount)
             from public.owner_settlement_reservable_payments(
               s.company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
             ) as pid
             join public.payments p on p.id = pid
         ), 0)) > 0.001
       )
     );

  if v_dupe_payments > 0 or v_dupe_expenses > 0 or v_mismatch > 0 then
    raise exception 'OWNER_SETTLEMENT_BACKFILL_BLOCKED: historical conflicts detected (duplicate_payments=%, duplicate_expenses=%, amount_mismatches=%). No partial backfill performed and no winner chosen; resolve the historical duplicates before enabling reservation backfill.',
      v_dupe_payments, v_dupe_expenses, v_mismatch
      using errcode = 'P0001';
  end if;
end;
$$;


ALTER FUNCTION "public"."assert_owner_settlement_links_backfillable"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_owner_settlement_links_backfillable"() IS 'FA-003: historical stop-gate. Raises if any payment/expense belongs to more than one non-cancelled settlement or any stored amount does not match the deterministic derivation. Never chooses a winner, never mutates data.';



CREATE OR REPLACE FUNCTION "public"."assert_owner_settlement_totals_fresh"("p_settlement_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_row public.owner_settlements%rowtype;
  v_gross numeric;
  v_fee numeric;
  v_expenses numeric;
  v_tax numeric;
  v_net numeric;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to validate owner settlements.'
      using errcode = '42501';
  end if;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'Company context is required (no company_id claim in JWT).'
      using errcode = '42501';
  end if;

  select *
    into v_row
    from public.owner_settlements s
   where s.id::text = p_settlement_id
     and s.company_id = v_company_id
   for update;

  if not found then
    raise exception 'Owner settlement not found.'
      using errcode = 'P0002';
  end if;

  -- Lock every currently linked source row. A concurrent UPDATE of a linked
  -- amount/status cannot slip between the freshness check and lifecycle commit.
  perform 1
    from public.payments p
    join public.owner_settlement_payment_links l
      on l.payment_id = p.id
     and l.company_id = p.company_id
   where l.settlement_id = v_row.id::text
     and l.company_id = v_company_id
     and l.released_at is null
   order by p.id
   for update of p;

  perform 1
    from public.expenses e
    join public.owner_settlement_expense_links l
      on l.expense_id = e.id
     and l.company_id = e.company_id
   where l.settlement_id = v_row.id::text
     and l.company_id = v_company_id
     and l.released_at is null
   order by e.id
   for update of e;

  -- Exact set equality in BOTH directions. This uses the shared FA-003 helpers,
  -- so membership cannot drift independently from create/approve/pay semantics.
  if exists (
    select 1
      from (
        select rp.item_id
          from public.owner_settlement_reservable_payments(
            v_company_id,
            v_row.owner_id::uuid,
            v_row.period_start,
            v_row.period_end,
            v_row.property_id::text
          ) as rp(item_id)
        except
        select l.payment_id
          from public.owner_settlement_payment_links l
         where l.settlement_id = v_row.id::text
           and l.company_id = v_company_id
           and l.released_at is null
      ) missing_payment
  ) or exists (
    select 1
      from (
        select l.payment_id
          from public.owner_settlement_payment_links l
         where l.settlement_id = v_row.id::text
           and l.company_id = v_company_id
           and l.released_at is null
        except
        select rp.item_id
          from public.owner_settlement_reservable_payments(
            v_company_id,
            v_row.owner_id::uuid,
            v_row.period_start,
            v_row.period_end,
            v_row.property_id::text
          ) as rp(item_id)
      ) extra_payment
  ) or exists (
    select 1
      from (
        select re.item_id
          from public.owner_settlement_reservable_expenses(
            v_company_id,
            v_row.owner_id::uuid,
            v_row.period_start,
            v_row.period_end,
            v_row.property_id::text
          ) as re(item_id)
        except
        select l.expense_id
          from public.owner_settlement_expense_links l
         where l.settlement_id = v_row.id::text
           and l.company_id = v_company_id
           and l.released_at is null
      ) missing_expense
  ) or exists (
    select 1
      from (
        select l.expense_id
          from public.owner_settlement_expense_links l
         where l.settlement_id = v_row.id::text
           and l.company_id = v_company_id
           and l.released_at is null
        except
        select re.item_id
          from public.owner_settlement_reservable_expenses(
            v_company_id,
            v_row.owner_id::uuid,
            v_row.period_start,
            v_row.period_end,
            v_row.property_id::text
          ) as re(item_id)
      ) extra_expense
  ) then
    raise exception 'OWNER_SETTLEMENT_INPUT_SET_DRIFT: reserved source membership changed after draft creation; cancel and recreate the settlement.'
      using errcode = '22023';
  end if;

  select c.gross_collected, c.office_fee, c.owner_expenses, c.tax_amount, c.net_payable
    into v_gross, v_fee, v_expenses, v_tax, v_net
    from public.calculate_owner_net_payout(
      v_row.owner_id::uuid,
      v_row.period_start,
      v_row.period_end,
      v_row.property_id::text
    ) as c;

  -- Compare the stored tuple to the current server-derived tuple. The stale guard
  -- is 0.001-sensitive even though today's payment/expense source columns persist
  -- only 2dp; this avoids weakening the invariant when those sources move to 3dp.
  if v_row.gross_collected is null
     or v_row.office_fee is null
     or v_row.owner_expenses is null
     or v_row.tax_amount is null
     or v_row.net_payable is null
     or v_gross is null
     or v_fee is null
     or v_expenses is null
     or v_tax is null
     or v_net is null
     or abs(v_row.gross_collected - v_gross) >= 0.001
     or abs(v_row.office_fee - v_fee) >= 0.001
     or abs(v_row.owner_expenses - v_expenses) >= 0.001
     or abs(v_row.tax_amount - v_tax) >= 0.001
     or abs(v_row.net_payable - v_net) >= 0.001 then
    raise exception 'OWNER_SETTLEMENT_STALE_TOTALS: source amounts changed after draft creation; cancel and recreate the settlement.'
      using errcode = '22023';
  end if;
end;
$$;


ALTER FUNCTION "public"."assert_owner_settlement_totals_fresh"("p_settlement_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_owner_settlement_totals_fresh"("p_settlement_id" "text") IS 'S02-T05 internal fail-closed guard: exact FA-003 reserved-set parity plus live gross/fee/expense/tax/net re-derivation. Raises 22023 on stale differences at or above 0.001.';



CREATE OR REPLACE FUNCTION "public"."assert_property_owner_temporal_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_range daterange;
  v_violation_date date;
BEGIN
  IF NEW.ownership_percentage IS NULL OR NEW.ownership_percentage <= 0 OR NEW.ownership_percentage > 100 THEN
    RAISE EXCEPTION 'نسبة الملكية يجب أن تكون أكبر من صفر وألا تتجاوز 100%%.';
  END IF;

  IF NEW.starts_on IS NOT NULL AND NEW.ends_on IS NOT NULL AND NEW.ends_on < NEW.starts_on THEN
    RAISE EXCEPTION 'تاريخ نهاية الملكية يجب ألا يسبق تاريخ البداية.';
  END IF;

  -- Serialize ownership edits for the same property. Without this lock, two
  -- concurrent inserts can both pass the percentage check before either row
  -- becomes visible to the other transaction.
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.property_id::text, 0));

  v_range := daterange(
    COALESCE(NEW.starts_on, '-infinity'::date),
    COALESCE(NEW.ends_on, '9999-12-31'::date),
    '[]'
  );

  -- The active total can only increase at the beginning of NEW or at the
  -- beginning of another overlapping ownership period. Evaluate those change
  -- points instead of summing every row that touches the whole range, which
  -- would incorrectly reject sequential, non-concurrent ownership periods.
  WITH candidate_dates AS (
    SELECT lower(v_range)::date AS effective_on
    UNION
    SELECT GREATEST(COALESCE(po.starts_on, '-infinity'::date), lower(v_range)::date)
    FROM public.property_owners po
    WHERE po.property_id = NEW.property_id
      AND po.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND daterange(
        COALESCE(po.starts_on, '-infinity'::date),
        COALESCE(po.ends_on, '9999-12-31'::date),
        '[]'
      ) && v_range
  )
  SELECT cd.effective_on
    INTO v_violation_date
  FROM candidate_dates cd
  WHERE NEW.ownership_percentage + COALESCE((
    SELECT sum(po.ownership_percentage)
    FROM public.property_owners po
    WHERE po.property_id = NEW.property_id
      AND po.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND COALESCE(po.starts_on, '-infinity'::date) <= cd.effective_on
      AND COALESCE(po.ends_on, '9999-12-31'::date) >= cd.effective_on
  ), 0) > 100
  ORDER BY cd.effective_on
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'نسب الملكية المتزامنة لهذا العقار تتجاوز 100%% بتاريخ %.', v_violation_date;
  END IF;

  IF NEW.is_primary AND EXISTS (
    SELECT 1
    FROM public.property_owners po
    WHERE po.property_id = NEW.property_id
      AND po.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND po.is_primary
      AND daterange(
        COALESCE(po.starts_on, '-infinity'::date),
        COALESCE(po.ends_on, '9999-12-31'::date),
        '[]'
      ) && v_range
  ) THEN
    RAISE EXCEPTION 'لا يمكن وجود أكثر من مالك أساسي لنفس العقار في فترة زمنية متداخلة.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."assert_property_owner_temporal_integrity"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_property_owner_temporal_integrity"() IS 'Internal trigger helper. Direct API execution is revoked.';



CREATE OR REPLACE FUNCTION "public"."assign_document_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row         jsonb;
  v_company     uuid;
  v_occurred_at timestamptz;
  v_year        integer;
begin
  v_row := to_jsonb(NEW);

  -- Explicit reference always wins (idempotent retries, backfills).
  if nullif(btrim(coalesce(v_row ->> 'reference', '')), '') is not null then
    return NEW;
  end if;

  v_company := nullif(btrim(coalesce(v_row ->> 'company_id', '')), '')::uuid;
  if v_company is null then
    select c.id into v_company
    from public.company_settings c
    where c.singleton_key = true
    limit 1;
  end if;
  if v_company is null then
    return NEW;
  end if;

  -- Use the row's own occurrence timestamp when one exists. Tables without
  -- created_at (e.g. bank_statement_imports, which has imported_at) must not
  -- fail; any future timestamp-less table falls back to now().
  v_occurred_at := coalesce(
    nullif(btrim(coalesce(v_row ->> 'created_at', '')), '')::timestamptz,
    nullif(btrim(coalesce(v_row ->> 'imported_at', '')), '')::timestamptz,
    now()
  );
  v_year := extract(year from v_occurred_at)::integer;

  NEW.reference := public.next_document_reference(
    v_company,
    TG_ARGV[0],
    TG_ARGV[1],
    v_year
  );
  return NEW;
end;
$$;


ALTER FUNCTION "public"."assign_document_reference"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_document_reference"() IS 'Generic BEFORE INSERT document-reference trigger. Derives optional fields from to_jsonb(NEW) so tables without created_at (bank_statement_imports) work; preserves created_at behavior everywhere else. Assigns only when NEW.reference is null.';



CREATE OR REPLACE FUNCTION "public"."audit_journal_entry_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'posted' then
    insert into public.audit_log (
      id, user_id, action, entity, entity_id, note, "table",
      old_value, new_value, action_timestamp, created_at, updated_at
    ) values (
      gen_random_uuid()::text,
      auth.uid(),
      'INSERT_POSTED_JOURNAL_ENTRY',
      'journal_entry',
      new.id::text,
      'Posted journal entry created. Corrections must use reversing entries.',
      'journal_entries',
      null,
      to_jsonb(new),
      now(),
      now(),
      now()
    );
  end if;

  return new;
end;
$$;


