CREATE OR REPLACE FUNCTION "public"."audit_service_provider_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_row jsonb;
  v_company_id text;
  v_entity text;
  v_entity_id text;
  v_action text;
  v_category_id text;
begin
  v_row := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_company_id := v_row ->> 'company_id';
  v_category_id := v_row ->> 'category_id';

  if tg_table_name = 'service_provider_category_links' then
    v_entity := 'service_provider';
    v_entity_id := v_row ->> 'service_provider_id';
    v_action := case when tg_op = 'INSERT' then 'SERVICE_PROVIDER_CATEGORY_LINKED' else 'SERVICE_PROVIDER_CATEGORY_UNLINKED' end;
  elsif tg_table_name = 'service_provider_categories' then
    v_entity := 'service_provider_category';
    v_entity_id := v_row ->> 'id';
    v_action := case
      when tg_op = 'INSERT' then 'SERVICE_PROVIDER_CATEGORY_CREATED'
      when old.deleted_at is null and new.deleted_at is not null then 'SERVICE_PROVIDER_CATEGORY_ARCHIVED'
      else 'SERVICE_PROVIDER_CATEGORY_UPDATED'
    end;
  else
    v_entity := 'service_provider';
    v_entity_id := v_row ->> 'id';
    v_action := case
      when tg_op = 'INSERT' then 'SERVICE_PROVIDER_CREATED'
      when old.deleted_at is null and new.deleted_at is not null then 'SERVICE_PROVIDER_ARCHIVED'
      else 'SERVICE_PROVIDER_UPDATED'
    end;
  end if;

  insert into public.audit_log(
    id, ts, user_id, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(), v_action,
    v_entity, v_entity_id, v_action, tg_table_name,
    jsonb_strip_nulls(jsonb_build_object('company_id', v_company_id, 'category_id', v_category_id))::text,
    now()
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."audit_service_provider_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_business_document_references"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  v_company uuid;
  v_ref text;
begin
  for r in
    select c.id, c.company_id, c.created_at
    from public.contracts c
    where c.reference is null
    order by c.created_at, c.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'contract', 'CNT',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.contracts set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select i.id, i.company_id, i.created_at
    from public.invoices i
    where i.reference is null
    order by i.created_at, i.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'invoice', 'INV',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.invoices set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select r2.id, r2.company_id, r2.created_at
    from public.receipts r2
    where r2.reference is null
    order by r2.created_at, r2.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'receipt', 'RCT',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.receipts set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select e.id, e.company_id, e.created_at
    from public.expenses e
    where e.reference is null
    order by e.created_at, e.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'expense', 'EXP',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.expenses set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select m.id, m.company_id, m.created_at
    from public.maintenance_records m
    where m.reference is null
    order by m.created_at, m.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'maintenance', 'MNT',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.maintenance_records set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select a.id, a.company_id, a.created_at
    from public.owner_agreements a
    where a.reference is null
    order by a.created_at, a.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'owner_agreement', 'AGR',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.owner_agreements set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select s.id, s.company_id, s.created_at
    from public.owner_settlements s
    where s.reference is null
    order by s.created_at, s.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'owner_settlement', 'STL',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.owner_settlements set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select d.id, d.company_id, d.created_at
    from public.tenant_deposits d
    where d.reference is null
    order by d.created_at, d.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'tenant_deposit', 'DEP',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.tenant_deposits set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select u.id, u.company_id, u.created_at
    from public.utility_bills u
    where u.reference is null
    order by u.created_at, u.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'utility_bill', 'UTL',
      extract(year from coalesce(r.created_at, now()))::integer) into v_ref;
    update public.utility_bills set reference = v_ref where id = r.id and reference is null;
  end loop;

  for r in
    select b.id, b.company_id, b.imported_at as occurred_at
    from public.bank_statement_imports b
    where b.reference is null
    order by b.imported_at, b.id
  loop
    if r.company_id is null then continue; end if;
    select public.next_document_reference(r.company_id, 'bank_import', 'BNK',
      extract(year from coalesce(r.occurred_at, now()))::integer) into v_ref;
    update public.bank_statement_imports set reference = v_ref where id = r.id and reference is null;
  end loop;
end;
$$;


ALTER FUNCTION "public"."backfill_business_document_references"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_owner_settlement_links"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_created_p int := 0;
  v_created_e int := 0;
  v_released_p int := 0;
  v_released_e int := 0;
  v_skipped int := 0;
  v_pmt bigint;
  v_exp bigint;
begin
  perform public.assert_owner_settlement_links_backfillable();

  for r in
    select s.*
      from public.owner_settlements s
     order by s.created_at nulls last, s.id
  loop
    if exists (
      select 1 from public.owner_settlement_payment_links
      where settlement_id = r.id
    ) or exists (
      select 1 from public.owner_settlement_expense_links
      where settlement_id = r.id
    ) then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    if r.status = 'CANCELLED' then
      insert into public.owner_settlement_payment_links (
        id, company_id, settlement_id, payment_id,
        reserved_at, reserved_by, released_at, released_by, release_reason,
        created_at, updated_at
      )
      select gen_random_uuid(), r.company_id, r.id, p.id,
             coalesce(r.created_at, now()), r.cancelled_by,
             now(), r.cancelled_by, 'SETTLEMENT_CANCELLED_BACKFILL',
             now(), now()
        from public.owner_settlement_reservable_payments(
          r.company_id, r.owner_id::uuid, r.period_start, r.period_end, r.property_id::text
        ) as p(id);
      get diagnostics v_pmt = row_count;
      v_released_p := v_released_p + v_pmt;

      insert into public.owner_settlement_expense_links (
        id, company_id, settlement_id, expense_id,
        reserved_at, reserved_by, released_at, released_by, release_reason,
        created_at, updated_at
      )
      select gen_random_uuid(), r.company_id, r.id, e.id,
             coalesce(r.created_at, now()), r.cancelled_by,
             now(), r.cancelled_by, 'SETTLEMENT_CANCELLED_BACKFILL',
             now(), now()
        from public.owner_settlement_reservable_expenses(
          r.company_id, r.owner_id::uuid, r.period_start, r.period_end, r.property_id::text
        ) as e(id);
      get diagnostics v_exp = row_count;
      v_released_e := v_released_e + v_exp;
    else
      insert into public.owner_settlement_payment_links (
        id, company_id, settlement_id, payment_id,
        reserved_at, reserved_by, created_at, updated_at
      )
      select gen_random_uuid(), r.company_id, r.id, p.id,
             coalesce(r.created_at, now()), null, now(), now()
        from public.owner_settlement_reservable_payments(
          r.company_id, r.owner_id::uuid, r.period_start, r.period_end, r.property_id::text
        ) as p(id);
      get diagnostics v_pmt = row_count;
      v_created_p := v_created_p + v_pmt;

      insert into public.owner_settlement_expense_links (
        id, company_id, settlement_id, expense_id,
        reserved_at, reserved_by, created_at, updated_at
      )
      select gen_random_uuid(), r.company_id, r.id, e.id,
             coalesce(r.created_at, now()), null, now(), now()
        from public.owner_settlement_reservable_expenses(
          r.company_id, r.owner_id::uuid, r.period_start, r.period_end, r.property_id::text
        ) as e(id);
      get diagnostics v_exp = row_count;
      v_created_e := v_created_e + v_exp;
    end if;
  end loop;

  return jsonb_build_object(
    'active_payment_links_created', v_created_p,
    'active_expense_links_created', v_created_e,
    'released_payment_links_created', v_released_p,
    'released_expense_links_created', v_released_e,
    'settlements_skipped', v_skipped
  );
end;
$$;


ALTER FUNCTION "public"."backfill_owner_settlement_links"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_owner_settlement_links"() IS 'FA-003: creates reservation link rows only (no amounts/status/accounting changes). Active settlements get permanent unreleased links; CANCELLED settlements get released links for audit. Idempotent and guarded by assert_owner_settlement_links_backfillable().';



CREATE OR REPLACE FUNCTION "public"."calculate_owner_net_payout"("p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text" DEFAULT NULL::"text") RETURNS TABLE("gross_collected" numeric, "office_fee" numeric, "owner_expenses" numeric, "tax_amount" numeric, "net_payable" numeric, "breakdown" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_collected numeric := 0;
  v_rate_fees numeric := 0;
  v_fixed_fees numeric := 0;
  v_obligations numeric := 0;
  v_payments_count integer := 0;
  v_gross numeric;
  v_fee numeric;
  v_expenses numeric := 0;
  v_tax numeric := 0;
  v_net numeric;
  v_vat_enabled boolean := false;
  v_vat_rate numeric := 0;
  v_props jsonb;
begin
  -- Preview is open to any authenticated app user; the write path keeps its
  -- own stricter ADMIN/MANAGER guard (unchanged from P0).
  if auth.uid() is null or not coalesce(public.is_app_user(), false) then
    raise exception 'Authenticated app user is required.' using errcode = '42501';
  end if;

  -- Company derivation is self-contained (same semantics as
  -- public.require_company_id()) so this migration replays in harness phases
  -- where the P0 helper is intentionally absent.
  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Company context is required (no company_id claim in JWT).' using errcode = '42501';
  end if;

  if p_period_start is null or p_period_end is null or p_period_start > p_period_end then
    raise exception 'A valid settlement period is required.' using errcode = '22023';
  end if;

  -- Same F-SET scoping as the write path (defense in depth for direct callers).
  if not exists (
    select 1 from public.owners o
    where o.id = p_owner_id and o.company_id = v_company_id and o.deleted_at is null
  ) then
    raise exception 'Settlement target owner is not in your company.' using errcode = '42501';
  end if;
  if p_property_id is not null and not exists (
    select 1 from public.properties p
    where p.id::text = p_property_id and p.company_id = v_company_id and p.deleted_at is null
  ) then
    raise exception 'Settlement target property is not in your company.' using errcode = '42501';
  end if;

  -- Collected-cash basis: payments reach the owner through their contract's
  -- OWN agreement (per-contract rate), exactly like public.rpt_owner_statement.
  with owner_contracts as (
    select c.id as contract_id, oa.agreement_type, oa.commission_type
      , oa.commission_value
    from public.contracts c
    join public.owner_agreements oa
      on oa.id = c.agreement_id
     and oa.owner_id = p_owner_id
     and oa.company_id = v_company_id
    where c.deleted_at is null
      and c.company_id = v_company_id
      and (p_property_id is null or c.property_id::text = p_property_id::text)
  ), payment_math as (
    select
      case when oc.agreement_type = 'master_lease' then 0::numeric else p.amount end as gross,
      case
        when oc.agreement_type = 'master_lease' then 0::numeric
        when oc.commission_type = 'RATE' then public._r3(p.amount * oc.commission_value / 100)
        else 0::numeric
      end as fee
    from public.payments p
    join owner_contracts oc on oc.contract_id = p.contract_id
    where p.deleted_at is null
      and p.company_id = v_company_id
      and upper(coalesce(p.status, '')) <> 'VOID'
      and coalesce(p.payment_date, public._safe_date(p.date_time::text)) between p_period_start and p_period_end
  )
  select
    coalesce(sum(pm.gross), 0),
    coalesce(sum(pm.fee), 0),
    count(*) filter (where pm.gross <> 0)
  into v_collected, v_rate_fees, v_payments_count
  from payment_math pm;

  -- Period-based parts (FIXED_MONTHLY fees, master-lease obligations), from the
  -- governing agreement per property: latest agreement overlapping the period,
  -- same selection rule as public.rpt_owner_statement's commission pick.
  with scoped_properties as (
    select oa.property_id
    from public.owner_agreements oa
    where oa.owner_id = p_owner_id
      and oa.company_id = v_company_id
      and (p_property_id is null or oa.property_id::text = p_property_id::text)
    group by oa.property_id
  ), governing as (
    select distinct on (oa.property_id)
      oa.property_id, oa.agreement_type, oa.commission_type, oa.commission_value,
      greatest(
        (extract(year from least(coalesce(oa.ends_on, p_period_end), p_period_end))
           - extract(year from greatest(oa.starts_on, p_period_start))) * 12
        + extract(month from least(coalesce(oa.ends_on, p_period_end), p_period_end))
           - extract(month from greatest(oa.starts_on, p_period_start))
        + 1,
        0
      )::int as months
    from public.owner_agreements oa
    join scoped_properties sp on sp.property_id = oa.property_id
    where oa.company_id = v_company_id
      and oa.starts_on <= p_period_end
      and (oa.ends_on is null or oa.ends_on >= p_period_start)
    order by oa.property_id, oa.starts_on desc
  ), fixed_math as (
    select
      coalesce(sum(case when g.agreement_type = 'master_lease'
        then public._r3(g.commission_value * g.months) else 0 end), 0) as obligations,
      coalesce(sum(case when g.agreement_type <> 'master_lease' and g.commission_type = 'FIXED_MONTHLY'
        then public._r3(g.commission_value * g.months) else 0 end), 0) as fixed_fees,
      jsonb_agg(jsonb_build_object(
        'property_id', g.property_id,
        'agreement_type', g.agreement_type,
        'commission_type', g.commission_type,
        'commission_value', g.commission_value,
        'months_covered', g.months
      ) order by g.property_id) as props
    from governing g
  )
  select fm.obligations, fm.fixed_fees, fm.props
  into v_obligations, v_fixed_fees, v_props
  from fixed_math fm;

  -- Owner expenses: mirrors public._owner_statement_expenses with explicit
  -- company/property scoping (the canonical table layout — status/charged_to/
  -- date_time exist on every replayed chain since 20260720180530, so no
  -- information_schema variance guard is needed here).
  select coalesce(sum(e.amount), 0)
  into v_expenses
  from public.expenses e
  where e.deleted_at is null
    and e.company_id = v_company_id
    and upper(coalesce(e.status, '')) = 'POSTED'
    and upper(coalesce(e.charged_to, '')) = 'OWNER'
    and (p_property_id is null or e.property_id::text = p_property_id::text)
    and public._safe_date(e.date_time) between p_period_start and p_period_end
    and exists (
      select 1 from public.property_owners po
      where po.property_id = e.property_id
        and po.owner_id = p_owner_id
        and (po.starts_on is null or po.starts_on <= public._safe_date(e.date_time))
        and (po.ends_on is null or po.ends_on >= public._safe_date(e.date_time))
    );

  -- VAT on the office fee, strictly company-scoped; disabled by default.
  -- company_settings is a singleton: it is inherited only when the row belongs
  -- to the caller's company (isolation-first rule).
  select coalesce(cs.vat_enabled, false), coalesce(cs.vat_rate, 0)
    into v_vat_enabled, v_vat_rate
  from public.company_settings cs
  where cs.company_id = v_company_id
  limit 1;
  v_vat_enabled := coalesce(v_vat_enabled, false);
  v_vat_rate := coalesce(v_vat_rate, 0);

  v_gross := public._r3(v_collected + v_obligations);
  v_fee := public._r3(v_rate_fees + v_fixed_fees);
  v_expenses := public._r3(v_expenses);
  if v_vat_enabled and v_vat_rate > 0 and v_fee > 0 then
    v_tax := public._r3(v_fee * v_vat_rate / 100);
  end if;
  v_net := greatest(v_gross - v_fee - v_expenses - v_tax, 0);

  return query
  select
    v_gross,
    v_fee,
    v_expenses,
    v_tax,
    v_net,
    jsonb_build_object(
      'source', 'server_derived',
      'payments_count', v_payments_count,
      'collected_gross', public._r3(v_collected),
      'rate_fees', v_rate_fees,
      'fixed_fees', v_fixed_fees,
      'master_obligations', v_obligations,
      'agreements', coalesce(v_props, '[]'::jsonb),
      'vat', jsonb_build_object('enabled', v_vat_enabled, 'rate', v_vat_rate),
      'policy', jsonb_build_object(
        'basis', 'collected_cash (ADR 0001)',
        'fixed_monthly_accrual', 'commission_value × calendar months covered by the period, clipped to agreement validity',
        'master_lease_basis', 'obligation basis: gross = value × months, fee = 0',
        'rounding', 'public._r3 with per-payment rate-fee rounding (rpt_owner_statement parity)'
      )
    );
end;
$$;


ALTER FUNCTION "public"."calculate_owner_net_payout"("p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_owner_net_payout"("p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text") IS 'P1 canonical owner-settlement derivation (ADR 0001, collected-cash basis). Client inputs are never financial sources. Establishes the FIXED_MONTHLY months accrual previously deferred by 20260718113414; supersede only via a new written decision record.';



CREATE OR REPLACE FUNCTION "public"."cancel_commission_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_id text := nullif(btrim(p_payload->>'commission_id'), '');
  v_request_id text := nullif(btrim(p_payload->>'request_id'), '');
  v_comm public.commissions%rowtype;
  v_cached jsonb;
  v_result jsonb;
  v_operation_name text;
  v_request_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target_id text;
  v_updated_count integer;
begin
  if auth.uid() is null or not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لإلغاء عمولة'
      using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  if v_id is null then
    raise exception 'معرّف العمولة مطلوب' using errcode = '22023';
  end if;
  if v_request_id is null then
    v_request_id := gen_random_uuid()::text;
  end if;

  v_operation_name := 'cancel_commission_atomic:' || v_company_id::text;
  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'commission_id', v_id
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_operation_name || ':' || v_request_id, 0)
  );

  select *
    into v_comm
  from public.commissions
  where id = v_id
    and company_id = v_company_id
  for update;

  if not found then
    raise exception 'COMMISSION_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;

  select response_payload
    into v_cached
  from public.financial_operation_idempotency
  where operation_name = v_operation_name
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    v_cached_target_id := v_cached->>'_target_id';
    if v_cached_fingerprint is null
       or v_cached_target_id is null
       or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        using errcode = '22023';
    end if;
    if v_cached_fingerprint <> v_request_fingerprint or v_cached_target_id <> v_id then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode = '22023';
    end if;
    return (v_cached->'response') || jsonb_build_object('idempotent', true);
  end if;

  if lower(coalesce(v_comm.status, '')) = 'paid' then
    raise exception 'COMMISSION_PAID_REQUIRES_REVERSAL' using errcode = '22023';
  end if;

  if lower(coalesce(v_comm.status, '')) = 'cancelled' then
    return jsonb_build_object(
      'success', true,
      'idempotent', true,
      'already_cancelled', true,
      'commission_id', v_comm.id,
      'status', v_comm.status,
      'request_id', v_request_id,
      'commission', to_jsonb(v_comm)
    );
  end if;

  update public.commissions
     set status = 'cancelled',
         updated_at = now()
   where id = v_id
     and company_id = v_company_id
  returning * into v_comm;

  get diagnostics v_updated_count = row_count;
  if v_updated_count <> 1 then
    raise exception 'COMMISSION_UPDATE_COUNT_MISMATCH' using errcode = 'P0001';
  end if;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'CANCEL', 'commissions', v_id,
    'Commission cancelled through trusted RPC; no journal entry created',
    'commissions',
    left(jsonb_build_object('request_id', v_request_id, 'commission_id', v_id)::text, 4000),
    now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'commission_id', v_comm.id,
    'status', v_comm.status,
    'request_id', v_request_id,
    'commission', to_jsonb(v_comm)
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload
  ) values (
    v_operation_name,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_id,
      'response', v_result
    )
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."cancel_commission_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_commission_atomic"("p_payload" "jsonb") IS 'PR-C: cancels an unpaid commission. Paid commissions require reverse_commission_atomic.';



CREATE OR REPLACE FUNCTION "public"."cancel_owner_settlement_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_id text := nullif(p_payload->>'settlement_id', '');
  v_reason text := nullif(btrim(p_payload->>'reason'), '');
  v_row public.owner_settlements%rowtype;
  v_cached jsonb;
  v_result jsonb;
  v_operation_name text;
  v_request_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target_id text;
  v_updated_count integer;
  v_released_payments integer := 0;
  v_released_expenses integer := 0;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to cancel owner settlements.'
      using errcode = '42501';
  end if;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Company context is required (no company_id claim in JWT).'
      using errcode = '42501';
  end if;
  if v_id is null or v_request_id is null or v_reason is null then
    raise exception 'settlement_id, request_id, and reason are required.'
      using errcode = '22023';
  end if;

  v_operation_name := 'cancel_owner_settlement_atomic:' || v_company_id::text;
  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'settlement_id', v_id,
    'reason', v_reason
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_operation_name || ':' || v_request_id, 0)
  );

  select *
    into v_row
  from public.owner_settlements s
  where s.id::text = v_id
    and s.company_id = v_company_id
  for update;

  if not found then
    raise exception 'Owner settlement not found.'
      using errcode = 'P0002';
  end if;

  select response_payload
    into v_cached
  from public.financial_operation_idempotency
  where operation_name = v_operation_name
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    v_cached_target_id := v_cached->>'_target_id';
    if v_cached_fingerprint is null
       or v_cached_target_id is null
       or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        using errcode = '22023';
    end if;
    if v_cached_fingerprint <> v_request_fingerprint
       or v_cached_target_id <> v_id then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode = '22023';
    end if;
    return (v_cached->'response') || jsonb_build_object('idempotent', true);
  end if;

  if v_row.status not in ('DRAFT', 'APPROVED') then
    raise exception 'Only DRAFT or APPROVED settlements can be cancelled; paid settlements require a controlled reversal.'
      using errcode = '22023';
  end if;

  update public.owner_settlements
     set status = 'CANCELLED',
         cancelled_at = now(),
         cancelled_by = auth.uid(),
         cancellation_reason = v_reason,
         updated_at = now()
   where id::text = v_id
     and company_id = v_company_id;
  get diagnostics v_updated_count = row_count;
  if v_updated_count <> 1 then
    raise exception 'OWNER_SETTLEMENT_UPDATE_COUNT_MISMATCH'
      using errcode = 'P0001';
  end if;

  -- ── FA-003: release this settlement's reservations so its items may be used
  -- by a replacement settlement. Links are NEVER deleted; PAID links are never
  -- touched because cancel disallows PAID above.
  update public.owner_settlement_payment_links
     set released_at = now(),
         released_by = auth.uid(),
         release_reason = 'SETTLEMENT_CANCELLED',
         updated_at = now()
   where settlement_id = v_row.id::text
     and company_id = v_company_id
     and released_at is null;
  get diagnostics v_released_payments = row_count;

  update public.owner_settlement_expense_links
     set released_at = now(),
         released_by = auth.uid(),
         release_reason = 'SETTLEMENT_CANCELLED',
         updated_at = now()
   where settlement_id = v_row.id::text
     and company_id = v_company_id
     and released_at is null;
  get diagnostics v_released_expenses = row_count;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'CANCEL', 'owner_settlements', v_id,
    'Owner settlement cancelled: ' || v_reason,
    'owner_settlements', left(p_payload::text, 4000), now()
  );

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'RELEASE', 'owner_settlement_payment_links', v_id,
    'Released ' || v_released_payments || ' payment link(s) and ' || v_released_expenses || ' expense link(s) on cancellation',
    'owner_settlement_payment_links', left(p_payload::text, 4000), now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'settlement_id', v_id,
    'status', 'CANCELLED',
    'released_payments', v_released_payments,
    'released_expenses', v_released_expenses,
    'request_id', v_request_id
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload
  ) values (
    v_operation_name,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_id,
      'response', v_result
    )
  )
  on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."cancel_owner_settlement_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_owner_settlement_atomic"("p_payload" "jsonb") IS 'FA-003: cancellation releases the settlement reservations (released_at/by + SETTLEMENT_CANCELLED) so items may be reused; links are never deleted.';



CREATE OR REPLACE FUNCTION "public"."capture_owner_funds_receipt_void_reversal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_event public.owner_funds_events%rowtype;
begin
  if new.status = 'EXECUTED' and old.status is distinct from 'EXECUTED' then
    for v_event in
      select *
        from public.owner_funds_events e
       where e.company_id = new.company_id
         and e.source_id = new.receipt_id::text
         and e.source_type in ('OWNER_COLLECTION', 'MANAGEMENT_FEE')
    loop
      insert into public.owner_funds_events (
        company_id, owner_id, contract_id, invoice_id, source_type, source_id,
        event_id, amount_delta, effective_date, journal_batch_id
      ) values (
        new.company_id, v_event.owner_id, v_event.contract_id, v_event.invoice_id,
        'RECEIPT_VOID_REVERSAL', new.id::text, v_event.id::text,
        -v_event.amount_delta, current_date, new.reversal_batch_id
      ) on conflict (company_id, source_type, source_id, event_id) do nothing;
    end loop;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."capture_owner_funds_receipt_void_reversal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_owner_funds_settlement_payout"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch_id uuid;
begin
  if new.status = 'PAID' and coalesce(old.status, '') <> 'PAID'
     and new.owner_id is not null and coalesce(new.net_payable, 0) > 0 then
    select jb.id into v_batch_id
      from public.journal_batches jb
     where jb.company_id = new.company_id
       and jb.source_type = 'owner_settlement_payment'
       and jb.source_id = new.id::text
     order by jb.created_at, jb.id
     limit 1;

    insert into public.owner_funds_events (
      company_id, owner_id, source_type, source_id, event_id, amount_delta,
      effective_date, journal_batch_id
    ) values (
      new.company_id, new.owner_id::uuid, 'OWNER_SETTLEMENT_PAYOUT', new.id::text,
      'payout', -public.gl_pm_round_omr(new.net_payable),
      coalesce(new.paid_at::date, nullif(new.date::text, '')::date, current_date), v_batch_id
    ) on conflict (company_id, source_type, source_id, event_id) do nothing;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."capture_owner_funds_settlement_payout"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_unit_maintenance_block"("p_unit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_count integer;
  v_requests jsonb;
begin
  select count(*),
    jsonb_agg(jsonb_build_object(
      'id', m.id,
      'title', coalesce(m.title, m.description, ''),
      'priority', coalesce(m.priority, 'medium'),
      'status', m.status
    ))
  into v_count, v_requests
  from public.maintenance_records m
  where m.unit_id = p_unit_id
    and lower(coalesce(m.status, '')) in ('open', 'in_progress')
    and m.deleted_at is null;

  return jsonb_build_object(
    'blocked', v_count > 0,
    'count', coalesce(v_count, 0),
    'requests', coalesce(v_requests, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."check_unit_maintenance_block"("p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_journal_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch_total numeric;
  v_entry_count integer;
  v_debit_total numeric;
  v_credit_total numeric;
BEGIN
  -- Auth check
  IF auth.uid() IS NULL OR NOT public.is_admin_or_manager() THEN
    RAISE EXCEPTION 'ADMIN or MANAGER role required to close journal batches' USING ERRCODE = '42501';
  END IF;

  IF p_batch_id IS NULL THEN
    RAISE EXCEPTION 'batch_id is required';
  END IF;

  -- Calculate batch totals
  SELECT 
    SUM(CASE WHEN type = 'DEBIT' THEN amount ELSE 0 END),
    SUM(CASE WHEN type = 'CREDIT' THEN amount ELSE 0 END),
    COUNT(*)
  INTO v_debit_total, v_credit_total, v_entry_count
  FROM public.journal_entries
  WHERE batch_id = p_batch_id;

  IF v_entry_count = 0 THEN
    RAISE EXCEPTION 'Batch % not found or has no entries', p_batch_id;
  END IF;

  v_batch_total := v_debit_total - v_credit_total;

  -- Validate balance
  IF v_batch_total <> 0 THEN
    RAISE EXCEPTION 'Batch % is unbalanced: DEBITs (%) - CREDITs (%) = %. Cannot close.',
      p_batch_id, v_debit_total, v_credit_total, v_batch_total;
  END IF;

  -- Log successful close
  INSERT INTO public.audit_log (
    id, user_id, action, entity, entity_id, note, "table", details, created_at, updated_at
  ) VALUES (
    gen_random_uuid(),
    auth.uid(),
    'JOURNAL_BATCH_CLOSED',
    'journal_batch',
    p_batch_id::text,
    format('Batch %s closed: %s entries, %s DEBIT, %s CREDIT', 
           p_batch_id, v_entry_count, v_debit_total, v_credit_total),
    'journal_entries',
    jsonb_build_object(
      'batch_id', p_batch_id,
      'entry_count', v_entry_count,
      'debit_total', v_debit_total,
      'credit_total', v_credit_total,
      'balanced', true
    )::text,
    now(),
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'batch_id', p_batch_id,
    'entry_count', v_entry_count,
    'debit_total', v_debit_total,
    'credit_total', v_credit_total,
    'balanced', true
  );
END;
$$;


ALTER FUNCTION "public"."close_journal_batch"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_superseded_tax_profile_windows"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status <> 'ACTIVE' or old.status = 'ACTIVE' then
    return new;
  end if;

  -- Activation is version-forward. Refuse a back-dated/equal-date activation
  -- that would make a previously active later version ambiguous.
  if exists (
    select 1
      from public.company_tax_profiles p
     where p.company_id = new.company_id
       and p.id <> new.id
       and p.status = 'SUPERSEDED'
       and p.effective_from >= new.effective_from
       and (p.effective_to is null or p.effective_to >= new.effective_from)
  ) then
    raise exception 'TAX_PROFILE_ACTIVATION_ORDER_CONFLICT: activation date % must be later than the profile it supersedes.',
      new.effective_from using errcode = '22023';
  end if;

  -- Preserve the predecessor as historical authority while removing the
  -- overlap with the newly-active version.
  update public.company_tax_profiles p
     set effective_to = new.effective_from - 1,
         updated_at = now()
   where p.company_id = new.company_id
     and p.id <> new.id
     and p.status = 'SUPERSEDED'
     and p.effective_from < new.effective_from
     and (p.effective_to is null or p.effective_to >= new.effective_from);

  return new;
end;
$$;


ALTER FUNCTION "public"."close_superseded_tax_profile_windows"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_company_onboarding_atomic"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := public.require_company_id();
  v_actor   uuid := auth.uid();
  v_authority text := coalesce(public.current_app_role(), 'ADMIN');
  v_t       public.onboarding_requirement_templates%rowtype;
  v_data_ok boolean;
  v_result  jsonb;
begin
  if v_actor is null or not public.is_admin_or_manager() then
    raise exception 'ONBOARDING_COMPLETE_FORBIDDEN' using errcode = '42501';
  end if;

  -- Server-derived gate evaluation: every required requirement must be
  -- satisfied. NON_WAIVABLE gates require the underlying data; ADMIN_WAIVABLE
  -- gates require data OR a valid (non-revoked) admin waiver.
  for v_t in
    select * from public.onboarding_requirement_templates
    where required
    order by sort_order
  loop
    v_data_ok := case v_t.completion_source
      when 'OWNER_EXISTS'    then exists (select 1 from public.owners o    where o.company_id = v_company)
      when 'PROPERTY_EXISTS' then exists (select 1 from public.properties p where p.company_id = v_company)
      when 'UNIT_EXISTS'     then exists (select 1 from public.units u     where u.company_id = v_company)
      when 'CONTRACT_EXISTS' then exists (select 1 from public.contracts c where c.company_id = v_company and c.deleted_at is null)
      when 'INVOICE_EXISTS'  then exists (select 1 from public.invoices i  where i.company_id = v_company)
      else true
    end;

    if not v_data_ok then
      if v_t.waiver_policy = 'ADMIN_WAIVABLE' and exists (
        select 1 from public.company_onboarding_waivers w
        where w.company_id = v_company
          and w.requirement_code = v_t.code
          and w.revoked_at is null
      ) then
        v_data_ok := true;
      end if;
    end if;

    if not v_data_ok then
      raise exception 'ONBOARDING_INCOMPLETE_REQUIREMENT'
        using errcode = '23514', detail = v_t.code;
    end if;
  end loop;

  insert into public.company_onboarding_completion (company_id, completed_by)
  values (v_company, v_actor)
  on conflict (company_id) do update
    set completed_by = excluded.completed_by,
        completed_at = now()
  returning to_jsonb(public.company_onboarding_completion.*) into v_result;

  insert into public.company_onboarding_events (
    company_id, requirement_code, action, actor, authority
  ) values (
    v_company, null, 'COMPLETE', v_actor, v_authority
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."complete_company_onboarding_atomic"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_contract_inspection_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_company uuid:=public.require_company_id(); v_record public.contract_inspections%rowtype; v_request text:=nullif(btrim(p_payload->>'request_id'),'');
begin
  if v_actor is null or not public.contract_evidence_actor_can_operate() then raise exception 'CONTRACT_EVIDENCE_FORBIDDEN' using errcode='42501'; end if;
  select * into v_record from public.contract_inspections where id=nullif(p_payload->>'inspection_id','')::uuid and company_id=v_company for update;
  if not found then raise exception 'INSPECTION_NOT_FOUND' using errcode='42501'; end if;
  if v_record.completion_request_id=v_request then return to_jsonb(v_record); end if;
  if v_record.status not in ('DRAFT','CHANGES_REQUESTED') or v_request is null then raise exception 'INSPECTION_NOT_COMPLETABLE' using errcode='22023'; end if;
  perform public.contract_inspection_validate_checklist(v_record.template_snapshot->'checklist_definition',v_record.checklist,true);
  if nullif(btrim(p_payload->>'tenant_signature'),'') is null or nullif(btrim(p_payload->>'office_signature'),'') is null then
    raise exception 'INSPECTION_SIGNATURES_REQUIRED' using errcode='22023';
  end if;
  update public.contract_inspections set status='COMPLETED',tenant_signature=btrim(p_payload->>'tenant_signature'),office_signature=btrim(p_payload->>'office_signature'),
    completion_request_id=v_request,completed_by=v_actor,completed_at=now(),updated_at=now() where id=v_record.id returning * into v_record;
  insert into public.contract_evidence_events(company_id,contract_id,entity_type,entity_id,event_type,from_status,to_status,payload,actor_id)
    values(v_company,v_record.contract_id,'INSPECTION',v_record.id,'COMPLETED','DRAFT','COMPLETED',jsonb_build_object('request_id',v_request),v_actor);
  return to_jsonb(v_record);
end;
$$;


ALTER FUNCTION "public"."complete_contract_inspection_atomic"("p_payload" "jsonb") OWNER TO "postgres";


