CREATE OR REPLACE FUNCTION "public"."contract_inspection_validate_checklist"("p_template" "jsonb", "p_checklist" "jsonb", "p_require_complete" boolean) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_item jsonb; v_code text; v_condition text;
begin
  if jsonb_typeof(p_checklist)<>'array' then raise exception 'INSPECTION_CHECKLIST_INVALID' using errcode='22023'; end if;
  for v_item in select value from jsonb_array_elements(p_checklist) loop
    v_code:=nullif(v_item->>'code',''); v_condition:=nullif(v_item->>'condition','');
    if v_code is null or not exists(select 1 from jsonb_array_elements(p_template) t where t->>'code'=v_code) then
      raise exception 'INSPECTION_CHECKLIST_ITEM_INVALID' using errcode='22023';
    end if;
    if v_condition is not null and v_condition not in ('GOOD','FAIR','DAMAGED','NOT_APPLICABLE') then
      raise exception 'INSPECTION_CONDITION_INVALID' using errcode='22023';
    end if;
  end loop;
  if p_require_complete and exists(
    select 1 from jsonb_array_elements(p_template) t
    where coalesce((t->>'required')::boolean,false)
      and not exists(select 1 from jsonb_array_elements(p_checklist) c where c->>'code'=t->>'code' and nullif(c->>'condition','') is not null)
  ) then raise exception 'INSPECTION_REQUIRED_ITEMS_INCOMPLETE' using errcode='22023'; end if;
end;
$$;


ALTER FUNCTION "public"."contract_inspection_validate_checklist"("p_template" "jsonb", "p_checklist" "jsonb", "p_require_complete" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_accounting_period"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_name text := nullif(btrim(coalesce(p_payload->>'name', '')), '');
  v_start_date date := nullif(p_payload->>'start_date', '')::date;
  v_end_date date := nullif(p_payload->>'end_date', '')::date;
  v_status text := upper(coalesce(nullif(btrim(p_payload->>'status', ''), ''), 'OPEN'));
  v_period_id uuid;
  v_conflict_id uuid;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to manage accounting periods.' using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  if v_start_date is null or v_end_date is null then
    raise exception 'ACCOUNTING_PERIOD_DATES_REQUIRED: start_date and end_date are required.' using errcode = '22023';
  end if;
  if v_start_date > v_end_date then
    raise exception 'ACCOUNTING_PERIOD_RANGE_INVALID: start_date must be on or before end_date.' using errcode = '22023';
  end if;
  if v_status not in ('OPEN', 'SOFT_CLOSED', 'HARD_CLOSED') then
    raise exception 'ACCOUNTING_PERIOD_STATUS_INVALID: status must be OPEN, SOFT_CLOSED or HARD_CLOSED.' using errcode = '22023';
  end if;

  if v_name is null then
    v_name := to_char(v_start_date, 'YYYY-MM');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('accounting_period:' || v_company_id::text, 0));

  select p.id into v_conflict_id
    from public.accounting_periods p
   where p.company_id = v_company_id
     and p.start_date <= v_end_date
     and p.end_date >= v_start_date
   limit 1;

  if v_conflict_id is not null then
    raise exception 'ACCOUNTING_PERIOD_OVERLAP: the range overlaps existing period %.', v_conflict_id using errcode = '23P01';
  end if;

  insert into public.accounting_periods (
    company_id, name, start_date, end_date, status, created_by, updated_at
  ) values (
    v_company_id, v_name, v_start_date, v_end_date, v_status, auth.uid(), now()
  )
  returning id into v_period_id;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid()::text, extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'CREATE', 'accounting_periods', v_period_id::text,
    'Accounting period created: ' || v_name || ' (' || v_start_date || ' .. ' || v_end_date || ') ' || v_status,
    'accounting_periods', left(p_payload::text, 4000), now()
  );

  return jsonb_build_object(
    'success', true,
    'id', v_period_id,
    'name', v_name,
    'start_date', v_start_date,
    'end_date', v_end_date,
    'status', v_status
  );
end;
$$;


ALTER FUNCTION "public"."create_accounting_period"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_commission_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(btrim(p_payload->>'request_id'), '');
  v_staff_name text := nullif(btrim(p_payload->>'staff_name'), '');
  v_type text := lower(nullif(btrim(p_payload->>'type'), ''));
  v_source_id text := nullif(btrim(p_payload->>'source_id'), '');
  v_deal_value numeric := nullif(btrim(p_payload->>'deal_value'), '')::numeric;
  v_percentage numeric := nullif(btrim(p_payload->>'percentage'), '')::numeric;
  v_amount numeric := nullif(btrim(p_payload->>'amount'), '')::numeric;
  v_comm public.commissions%rowtype;
  v_cached jsonb;
  v_result jsonb;
  v_operation_name text;
  v_request_fingerprint text;
  v_cached_fingerprint text;
begin
  if auth.uid() is null or not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لإنشاء عمولة'
      using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  if v_staff_name is null then
    raise exception 'اسم الموظف أو الوسيط مطلوب.' using errcode = '22023';
  end if;
  if v_type is null or v_type not in ('contract', 'payment', 'owner', 'lead', 'land') then
    raise exception 'نوع مصدر العمولة غير صحيح.' using errcode = '22023';
  end if;
  if v_deal_value is not null and v_deal_value < 0 then
    raise exception 'قيمة الصفقة يجب أن تكون صفراً أو أكبر.' using errcode = '22023';
  end if;
  if v_percentage is not null and (v_percentage < 0 or v_percentage > 100) then
    raise exception 'نسبة العمولة يجب أن تكون بين صفر و100.' using errcode = '22023';
  end if;

  -- Preserve the existing application behavior exactly: an explicit amount
  -- wins; otherwise derive deal_value * percentage / 100 rounded to 2 decimals.
  if v_amount is null and v_deal_value is not null and v_percentage is not null then
    v_amount := round(v_deal_value * (v_percentage / 100.0), 2);
  end if;
  if v_amount is null or v_amount <= 0 then
    raise exception 'أدخل قيمة عمولة أكبر من صفر أو قيمة الصفقة والنسبة.'
      using errcode = '22023';
  end if;

  if v_request_id is null then
    v_request_id := gen_random_uuid()::text;
  end if;

  v_operation_name := 'create_commission_atomic:' || v_company_id::text;
  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'staff_name', v_staff_name,
    'type', v_type,
    'source_id', v_source_id,
    'deal_value', v_deal_value,
    'percentage', v_percentage,
    'amount', v_amount
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_operation_name || ':' || v_request_id, 0)
  );

  select response_payload
    into v_cached
  from public.financial_operation_idempotency
  where operation_name = v_operation_name
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    if v_cached_fingerprint is null or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        using errcode = '22023';
    end if;
    if v_cached_fingerprint <> v_request_fingerprint then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode = '22023';
    end if;
    return (v_cached->'response') || jsonb_build_object('idempotent', true);
  end if;

  insert into public.commissions (
    id, staff_name, type, status, source_id, deal_value, percentage, amount,
    paid_at, expense_id, company_id, created_at, updated_at
  ) values (
    gen_random_uuid()::text, v_staff_name, v_type, 'pending', v_source_id,
    v_deal_value, v_percentage, v_amount,
    null, null, v_company_id, now(), now()
  )
  returning * into v_comm;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'CREATE', 'commissions', v_comm.id,
    'Commission created through trusted RPC with server-derived company and pending status',
    'commissions',
    left(jsonb_build_object(
      'request_id', v_request_id,
      'staff_name', v_staff_name,
      'type', v_type,
      'source_id', v_source_id,
      'deal_value', v_deal_value,
      'percentage', v_percentage,
      'amount', v_amount
    )::text, 4000),
    now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'commission_id', v_comm.id,
    'status', v_comm.status,
    'request_id', v_request_id,
    'commission', to_jsonb(v_comm)
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload
  ) values (
    v_operation_name,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      'response', v_result
    )
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_commission_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_commission_atomic"("p_payload" "jsonb") IS 'PR-C: creates a pending operational commission with server-derived company_id. Does not post a journal entry.';



CREATE OR REPLACE FUNCTION "public"."create_contract_atomic"("p_property_id" "text", "p_unit_id" "uuid", "p_tenant_id" "uuid", "p_agreement_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_payment_cycle" "text", "p_payment_terms_id" "uuid", "p_status" "text", "p_cancellation_reason" "text", "p_notes" "text", "p_attachment_url" "text", "p_billing_day" integer DEFAULT 1, "p_grace_days" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_company_id uuid;
  v_contract_id public.contracts.id%type;
  v_property_id public.contracts.property_id%type;
  v_unit_id public.contracts.unit_id%type;
  v_tenant_id public.contracts.tenant_id%type;
  v_agreement_id public.contracts.agreement_id%type;
  v_payment_terms_id public.contracts.payment_terms_id%type;
  v_start_date public.contracts.start_date%type;
  v_end_date public.contracts.end_date%type;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لإنشاء عقد' using errcode = '42501';
  end if;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'سياق الشركة مطلوب لإنشاء العقد' using errcode = '42501';
  end if;

  v_property_id := p_property_id;
  v_unit_id := p_unit_id;
  v_tenant_id := p_tenant_id;
  v_agreement_id := p_agreement_id;
  v_payment_terms_id := p_payment_terms_id;
  v_start_date := p_start_date;
  v_end_date := p_end_date;

  if p_end_date <= p_start_date then
    raise exception 'تاريخ نهاية العقد يجب أن يكون بعد تاريخ البداية';
  end if;
  if p_rent_amount is null or p_rent_amount <= 0 then
    raise exception 'قيمة الإيجار يجب أن تكون أكبر من صفر';
  end if;
  if p_status not in ('draft', 'active', 'expired', 'terminated') then
    raise exception 'حالة العقد غير مدعومة';
  end if;
  if lower(coalesce(p_status, '')) <> 'draft' then
    raise exception 'CONTRACT_CREATE_MUST_BE_DRAFT' using errcode = '23514';
  end if;
  if p_payment_cycle not in ('monthly', 'quarterly', 'semi_annual', 'annual') then
    raise exception 'دورة السداد غير مدعومة';
  end if;
  if p_billing_day is null or p_billing_day < 1 or p_billing_day > 28 then
    raise exception 'CONTRACT_BILLING_DAY_INVALID: يوم الفوترة يجب أن يكون بين 1 و28' using errcode = '23514';
  end if;
  if p_grace_days is null or p_grace_days < 0 or p_grace_days > 90 then
    raise exception 'CONTRACT_GRACE_DAYS_INVALID: أيام السماح يجب أن تكون بين 0 و90' using errcode = '23514';
  end if;

  if not exists (
    select 1 from public.people person_record
    where person_record.id::text = v_tenant_id::text
      and person_record.type = 'tenant'
      and person_record.company_id = v_company_id
      and person_record.deleted_at is null
  ) then
    raise exception 'المستأجر غير موجود أو نوعه غير صحيح';
  end if;

  if not exists (
    select 1 from public.properties property_record
    where property_record.id::text = v_property_id::text
      and property_record.company_id = v_company_id
      and property_record.deleted_at is null
  ) then
    raise exception 'العقار غير موجود';
  end if;

  if not exists (
    select 1 from public.units unit_record
    where unit_record.id::text = v_unit_id::text
      and unit_record.company_id = v_company_id
      and unit_record.property_id::text = v_property_id::text
      and unit_record.deleted_at is null
  ) then
    raise exception 'الوحدة غير موجودة أو لا تتبع العقار المحدد';
  end if;

  if exists (
    select 1 from public.units unit_record
    where unit_record.id::text = v_unit_id::text
      and lower(unit_record.status) in ('maintenance', 'reserved')
  ) then
    raise exception 'لا يمكن إنشاء عقد على وحدة تحت الصيانة أو محجوزة تشغيلياً';
  end if;

  -- Restored GAP-004 guard: reject inclusive date overlaps with any live
  -- draft/active contract on the same unit (defensive against text-typed
  -- live date columns; the DB exclusion constraint remains the last line).
  if exists (
    select 1 from public.contracts contract_record
    where contract_record.unit_id::text = v_unit_id::text
      and contract_record.company_id = v_company_id
      and contract_record.deleted_at is null
      and lower(contract_record.status) in ('active', 'draft')
      and btrim(coalesce(contract_record.start_date::text, '')) ~ '^\d{4}-\d{2}-\d{2}$'
      and btrim(coalesce(contract_record.end_date::text, '')) ~ '^\d{4}-\d{2}-\d{2}$'
      and btrim(contract_record.start_date::text)::date <= p_end_date
      and btrim(contract_record.end_date::text)::date >= p_start_date
  ) then
    raise exception 'الوحدة محجوزة خلال هذه الفترة';
  end if;

  if v_agreement_id is null or not exists (
    select 1 from public.owner_agreements agreement_record
    where agreement_record.id::text = v_agreement_id::text
      and agreement_record.company_id = v_company_id
      and agreement_record.property_id::text = v_property_id::text
      and agreement_record.starts_on <= p_start_date
      and (agreement_record.ends_on is null or agreement_record.ends_on >= p_end_date)
  ) then
    raise exception 'اتفاقية المالك لا تغطي فترة العقد بالكامل أو لا تنتمي لهذا العقار';
  end if;

  insert into public.contracts (
    property_id, unit_id, tenant_id, agreement_id, start_date, end_date,
    rent_amount, payment_cycle, payment_terms_id, status, company_id,
    cancellation_reason, notes, attachment_url, billing_day, grace_days
  ) values (
    v_property_id, v_unit_id, v_tenant_id, v_agreement_id,
    v_start_date, v_end_date, p_rent_amount,
    p_payment_cycle, v_payment_terms_id, p_status, v_company_id,
    p_cancellation_reason, p_notes, p_attachment_url, p_billing_day, p_grace_days
  )
  returning id into v_contract_id;

  return (select to_jsonb(c) from public.contracts c where c.id::text = v_contract_id::text);
end;
$_$;


ALTER FUNCTION "public"."create_contract_atomic"("p_property_id" "text", "p_unit_id" "uuid", "p_tenant_id" "uuid", "p_agreement_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_payment_cycle" "text", "p_payment_terms_id" "uuid", "p_status" "text", "p_cancellation_reason" "text", "p_notes" "text", "p_attachment_url" "text", "p_billing_day" integer, "p_grace_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_contract_atomic"("p_property_id" "text", "p_unit_id" "uuid", "p_tenant_id" "uuid", "p_agreement_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_payment_cycle" "text", "p_payment_terms_id" "uuid", "p_status" "text", "p_cancellation_reason" "text", "p_notes" "text", "p_attachment_url" "text", "p_billing_day" integer, "p_grace_days" integer) IS 'R4 billing-policy contract creation with the GAP-004 unit-overlap guard restored («الوحدة محجوزة خلال هذه الفترة»). DRAFT-only creation; activation via the S04 snapshot RPC.';



CREATE OR REPLACE FUNCTION "public"."create_deposit_application_claim_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_deposit_id text := nullif(btrim(coalesce(p_payload->>'deposit_id','')), '');
  v_kind text := upper(nullif(btrim(coalesce(p_payload->>'claim_kind','')), ''));
  v_invoice_id text := nullif(btrim(coalesce(p_payload->>'invoice_id','')), '');
  v_amount numeric := public.gl_pm_round_omr(nullif(p_payload->>'allocation_amount','')::numeric);
  v_evidence text := nullif(btrim(coalesce(p_payload->>'evidence_uri','')), '');
  v_note text := nullif(btrim(coalesce(p_payload->>'claim_note','')), '');
  v_contract_id text;
  v_collection_role text;
  v_beneficiary text;
  v_target_type text;
  v_target_no text;
  v_invoice_outstanding numeric;
  v_fingerprint text;
  v_existing public.deposit_application_claims%rowtype;
  v_id uuid := gen_random_uuid();
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DEPOSIT_CLAIM_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if not public.is_company_member(v_company_id, v_actor) then
    raise exception 'DEPOSIT_CLAIM_COMPANY_MEMBERSHIP_REQUIRED' using errcode = '42501';
  end if;
  if p_payload ?| array['company_id','target_type','target_account_no','collection_role','deposit_beneficiary','journal_lines'] then
    raise exception 'DEPOSIT_CLAIM_SERVER_OWNED_FIELDS_FORBIDDEN' using errcode = '22023';
  end if;
  if v_request_id is null or v_deposit_id is null or v_kind is null or v_amount is null or v_amount <= 0 or v_evidence is null then
    raise exception 'DEPOSIT_CLAIM_REQUEST_DEPOSIT_KIND_AMOUNT_EVIDENCE_REQUIRED' using errcode = '22023';
  end if;
  if v_kind not in ('INVOICE_ARREARS','DAMAGE') then
    raise exception 'DEPOSIT_CLAIM_KIND_INVALID' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('deposit_claim:'||v_company_id::text||':'||v_request_id,0));

  select c.id::text, c.collection_role_snapshot, av.deposit_beneficiary
    into v_contract_id, v_collection_role, v_beneficiary
  from public.tenant_deposits d
  join public.contracts c on c.id::text = d.contract_id::text and c.company_id = v_company_id and c.deleted_at is null
  left join public.owner_agreement_versions av on av.id = c.agreement_version_id and av.company_id = v_company_id
  where d.id::text = v_deposit_id and d.company_id = v_company_id and d.deleted_at is null;
  if not found then
    raise exception 'DEPOSIT_CLAIM_DEPOSIT_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;

  if v_kind = 'INVOICE_ARREARS' then
    if v_invoice_id is null then
      raise exception 'DEPOSIT_CLAIM_INVOICE_REQUIRED' using errcode = '22023';
    end if;
    select public.gl_pm_round_omr(coalesce(i.amount,0) + coalesce(i.tax_amount,0) - coalesce(i.paid_amount,0))
      into v_invoice_outstanding
    from public.invoices i
    where i.id::text = v_invoice_id
      and i.company_id = v_company_id
      and i.contract_id::text = v_contract_id
      and i.deleted_at is null;
    if not found or v_invoice_outstanding <= 0 or v_amount > v_invoice_outstanding then
      raise exception 'DEPOSIT_CLAIM_INVOICE_NOT_OPEN_OR_ALLOCATION_EXCEEDS_OUTSTANDING' using errcode = '22023';
    end if;
    if v_collection_role = 'OFFICE_IS_CREDITOR' then
      v_target_type := 'rent_arrears'; v_target_no := '1201';
    elsif v_collection_role = 'OWNER_IS_CREDITOR' then
      v_target_type := 'owner_arrears'; v_target_no := '2000';
    else
      raise exception 'DEPOSIT_CLAIM_COLLECTION_ROLE_MISSING' using errcode = '23514';
    end if;
  else
    v_invoice_id := null;
    v_target_type := 'damage';
    if v_beneficiary = 'OWNER' then
      v_target_no := '2000';
    elsif v_beneficiary = 'OFFICE' then
      v_target_no := '4300';
    else
      raise exception 'DEPOSIT_CLAIM_DAMAGE_BENEFICIARY_MISSING' using errcode = '23514';
    end if;
  end if;

  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'deposit_id',v_deposit_id,'claim_kind',v_kind,'invoice_id',v_invoice_id,
    'allocation_amount',v_amount,'evidence_uri',v_evidence,'claim_note',v_note,
    'contract_id',v_contract_id,'target_type',v_target_type,'target_account_no',v_target_no,
    'collection_role',v_collection_role,'deposit_beneficiary',v_beneficiary
  )::text,'UTF8')),'hex');

  select * into v_existing from public.deposit_application_claims
   where company_id=v_company_id and request_id=v_request_id;
  if found then
    if v_existing.source_fingerprint <> v_fingerprint then
      raise exception 'DEPOSIT_CLAIM_IDEMPOTENCY_CONFLICT' using errcode = '22023';
    end if;
    return jsonb_build_object('success',true,'idempotent',true,'claim_id',v_existing.id,'status',v_existing.status);
  end if;

  insert into public.deposit_application_claims(
    id,company_id,deposit_id,contract_id,claim_kind,invoice_id,allocation_amount,evidence_uri,claim_note,
    target_type,target_account_no,collection_role_snapshot,deposit_beneficiary_snapshot,
    request_id,source_fingerprint,status,created_by
  ) values (
    v_id,v_company_id,v_deposit_id,v_contract_id,v_kind,v_invoice_id,v_amount,v_evidence,v_note,
    v_target_type,v_target_no,v_collection_role,v_beneficiary,
    v_request_id,v_fingerprint,'PENDING',v_actor
  );

  return jsonb_build_object('success',true,'idempotent',false,'claim_id',v_id,'status','PENDING','target_type',v_target_type);
end;
$$;


ALTER FUNCTION "public"."create_deposit_application_claim_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_deposit_application_claim_with_inspection_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_company uuid:=public.require_company_id(); v_inspection public.contract_inspections%rowtype;
  v_inspection_id uuid:=nullif(p_payload->>'inspection_id','')::uuid; v_claim_kind text:=p_payload->>'claim_kind';
  v_result jsonb; v_claim_id uuid;
begin
  if v_claim_kind='DAMAGE' then
    if v_inspection_id is null then raise exception 'DAMAGE_CLAIM_REVIEWED_MOVE_OUT_INSPECTION_REQUIRED' using errcode='22023'; end if;
    select * into v_inspection from public.contract_inspections i
      where i.id=v_inspection_id and i.company_id=v_company and i.kind='MOVE_OUT' and i.status='REVIEWED';
    if not found then raise exception 'DAMAGE_CLAIM_INSPECTION_INVALID' using errcode='23514'; end if;
  elsif v_inspection_id is not null then
    raise exception 'INSPECTION_ONLY_ALLOWED_FOR_DAMAGE_CLAIM' using errcode='22023';
  end if;

  execute 'select public.create_deposit_application_claim_atomic($1)' into v_result using p_payload - 'inspection_id';
  v_claim_id:=nullif(v_result->>'claim_id','')::uuid;
  if v_claim_id is null then raise exception 'DEPOSIT_CLAIM_ID_MISSING' using errcode='23514'; end if;
  if v_inspection_id is not null then
    update public.deposit_application_claims c set inspection_id=v_inspection_id
      where c.id=v_claim_id and c.company_id=v_company and c.contract_id=v_inspection.contract_id::text;
    if not found then raise exception 'DAMAGE_CLAIM_CONTRACT_INSPECTION_MISMATCH' using errcode='23514'; end if;
  end if;
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."create_deposit_application_claim_with_inspection_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_deposit_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_company uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_contract_id text := nullif(p_payload->>'contract_id', '');
  v_tenant_id text := nullif(p_payload->>'tenant_id', '');
  v_property_id text := nullif(p_payload->>'property_id', '');
  v_unit_id text := nullif(p_payload->>'unit_id', '');
  v_amount numeric := round(coalesce(nullif(p_payload->>'amount', '')::numeric, 0), 3);
  v_received_date date := coalesce(nullif(p_payload->>'received_date', '')::date, current_date);
  v_notes text := nullif(p_payload->>'notes', '');
  v_deposit_id uuid := gen_random_uuid();
  v_cached jsonb;
  v_contract_company uuid;
  v_kernel jsonb;
  v_result jsonb;
  v_operation_name text;
begin
  if v_actor is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role required' using errcode = '42501';
  end if;
  v_company := public.require_company_id();

  if v_request_id is null then
    v_request_id := gen_random_uuid()::text;
  end if;

  -- Company-scoped idempotency: same request_id + same canonical request = safe
  -- replay; same key + different request = fail closed (verified via the
  -- stored response below; a fingerprint is kept for conflicts on replay).
  v_operation_name := 'create_deposit_atomic:' || v_company::text;
  select response_payload into v_cached
  from public.financial_operation_idempotency
  where operation_name = v_operation_name and request_id = v_request_id;
  if v_cached is not null then
    if not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED' using errcode = '22023';
    end if;
    return (v_cached->'response') || jsonb_build_object('idempotent', true);
  end if;

  if v_contract_id is null then
    raise exception 'contract_id required' using errcode = '22023';
  end if;
  if v_contract_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'contract_id is not a valid identifier' using errcode = '22023';
  end if;
  if v_amount is null or v_amount <= 0 or v_amount::text in ('NaN', 'Infinity', '-Infinity') then
    raise exception 'amount must be >0' using errcode = '22023';
  end if;

  -- Company isolation: the contract must belong to the caller's company.
  select c.company_id into v_contract_company
  from public.contracts c
  where c.id = v_contract_id::uuid
    and c.deleted_at is null;
  if v_contract_company is null or v_contract_company <> v_company then
    raise exception 'Contract not found in current company.' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_operation_name || ':' || v_request_id, 0));

  insert into public.tenant_deposits (
    id, contract_id, tenant_id, property_id, unit_id,
    deposit_amount, deducted_amount, refunded_amount, remaining_amount,
    status, received_date, notes, request_id, company_id
  ) values (
    v_deposit_id, v_contract_id::uuid, nullif(v_tenant_id, ''),
    nullif(v_property_id, '')::uuid, nullif(v_unit_id, '')::uuid,
    v_amount, 0, 0, v_amount,
    'held', v_received_date, v_notes, v_request_id, v_company
  );

  -- GL through the canonical engine: Dr 1111 / Cr 2200 with full provenance.
  v_kernel := public.gl_pm_post_deposit_receipt(jsonb_build_object(
    'company_id', v_company,
    'deposit_id', v_deposit_id,
    'amount', v_amount,
    'cash_account_no', '1111',
    'effective_date', v_received_date
  ));

  -- Append-only held transaction, batch-linked from the start.
  insert into public.deposit_transactions (
    deposit_id, type, amount, reason, description, request_id, company_id, journal_batch_id
  ) values (
    v_deposit_id::text, 'held', v_amount, 'initial_deposit',
    'استلام وديعة تأمين', v_request_id || '-held', v_company,
    (v_kernel->'batch'->>'batch_id')::uuid
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'deposit_id', v_deposit_id,
    'request_id', v_request_id,
    'amount', v_amount,
    'journal_batch_id', (v_kernel->'batch'->>'batch_id')::uuid
  );

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values (v_operation_name, v_request_id, jsonb_build_object('response', v_result))
  on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."create_deposit_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_expense_with_journal_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_internal_request_id text;
  v_cached jsonb;
  v_result jsonb;
  v_impl_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to create expenses.' using errcode = '42501';
  end if;
  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Active company is required.' using errcode = '42501';
  end if;
  if v_request_id is null then
    return public.create_expense_with_journal_atomic_phase3a1a_impl(p_payload);
  end if;

  select response_payload into v_cached
  from public.financial_operation_idempotency
  where operation_name = 'create_expense_with_journal_atomic:' || v_company_id::text
    and request_id = v_request_id;
  if v_cached is not null then
    return v_cached || jsonb_build_object('idempotent', true);
  end if;

  -- The wrapped implementation still contains the legacy un-namespaced lookup.
  -- Give it a company-derived internal request id so it can never read another
  -- company's historical cache row, then persist an external namespaced alias.
  v_internal_request_id := 'phase3a1a:' || v_company_id::text || ':' || v_request_id;
  v_impl_payload := jsonb_set(v_impl_payload, '{request_id}', to_jsonb(v_internal_request_id), true);
  v_result := public.create_expense_with_journal_atomic_phase3a1a_impl(v_impl_payload);
  v_result := jsonb_set(v_result, '{request_id}', to_jsonb(v_request_id), true);

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('create_expense_with_journal_atomic:' || v_company_id::text, v_request_id, v_result)
  on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_expense_with_journal_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_expense_with_journal_atomic_phase3a1a_impl"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_property_id public.expenses.property_id%type := nullif(p_payload->>'property_id', '');
  v_category text := nullif(p_payload->>'category', '');
  v_amount numeric := nullif(p_payload->>'amount', '')::numeric;
  v_expense_date public.expenses.expense_date%type := nullif(p_payload->>'expense_date', '')::date;
  v_description text := nullif(p_payload->>'description', '');
  v_cost_center_id public.expenses.cost_center_id%type := nullif(p_payload->>'cost_center_id', '');
  v_contract_id public.expenses.contract_id%type := nullif(p_payload->>'contract_id', '');
  v_charged_to text := nullif(p_payload->>'charged_to', '');
  v_attachment_url text := nullif(p_payload->>'attachment_url', '');
  v_expense_id public.expenses.id%type;
  v_expense_no text;
  v_expense_account_id public.accounts.id%type;
  v_cash_account_id public.accounts.id%type;
  v_result jsonb;
  v_cached jsonb;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to create expenses.' using errcode = '42501';
  end if;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;

  if v_request_id is null then
    v_request_id := gen_random_uuid()::text;
  end if;

  select response_payload into v_cached
  from public.financial_operation_idempotency
  where operation_name = 'create_expense_with_journal_atomic'
    and request_id = v_request_id;
  if v_cached is not null then
    return v_cached || jsonb_build_object('idempotent', true);
  end if;

  if v_property_id is null then raise exception 'property_id is required.'; end if;
  if v_category is null then raise exception 'category is required.'; end if;
  if v_amount is null or v_amount <= 0 then raise exception 'amount must be greater than zero.'; end if;
  if v_expense_date is null then raise exception 'expense_date is required.'; end if;

  if not exists (
    select 1 from public.properties p
    where p.id::text = v_property_id::text and p.company_id = v_company_id and p.deleted_at is null
  ) then
    raise exception 'Property not found.';
  end if;

  if v_cost_center_id is not null and not exists (
    select 1 from public.cost_centers cc where cc.id::text = v_cost_center_id::text and cc.company_id = v_company_id
  ) then
    raise exception 'Cost center not found.';
  end if;

  if v_contract_id is not null and not exists (
    select 1 from public.contracts c
    where c.id::text = v_contract_id::text
      and c.property_id::text = v_property_id::text
      and c.company_id = v_company_id
      and c.deleted_at is null
  ) then
    raise exception 'Contract does not belong to the selected property.';
  end if;

  v_expense_account_id := public.ensure_company_account(v_company_id, '6100', 'Operating Expenses');
  v_cash_account_id := public.ensure_company_account(v_company_id, '1111', 'Cash');
  if v_expense_account_id is null or v_cash_account_id is null then
    raise exception 'Expense accounting accounts are not configured';
  end if;

  v_expense_id := gen_random_uuid()::text;
  v_expense_no := 'EXP-' || to_char(now(), 'YYYYMMDD') || '-' || substr(replace(v_expense_id::text, '-', ''), 1, 8);

  insert into public.expenses (
    id, property_id, category, amount, expense_date, description,
    cost_center_id, contract_id, charged_to, attachment_url, status, date_time, no
  , company_id) values (
    v_expense_id, v_property_id, v_category, v_amount, v_expense_date, v_description,
    v_cost_center_id, v_contract_id, v_charged_to, v_attachment_url, 'POSTED', v_expense_date::text, v_expense_no
  , v_company_id);

  insert into public.journal_entries
    (id, no, date, account_id, amount, type, source_id, entity_type, entity_id, created_at, company_id)
  values
    (gen_random_uuid(), v_expense_no || '-D', v_expense_date::text, v_expense_account_id, v_amount, 'DEBIT', v_expense_id, 'expense', v_expense_id, now(), v_company_id),
    (gen_random_uuid(), v_expense_no || '-C', v_expense_date::text, v_cash_account_id, v_amount, 'CREDIT', v_expense_id, 'expense', v_expense_id, now(), v_company_id);

  insert into public.audit_log
    (id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at)
  values (
    gen_random_uuid()::text, extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'CREATE', 'expenses', v_expense_id, 'Expense recorded with journal entry',
    'expenses', left(p_payload::text, 4000), now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'expense_id', v_expense_id,
    'expense_no', v_expense_no,
    'request_id', v_request_id
  );

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('create_expense_with_journal_atomic'||':'||v_company_id::text, v_request_id, v_result)
  on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_expense_with_journal_atomic_phase3a1a_impl"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_fee_tax_treatment_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid := public.require_company_id();
  v_kind text := nullif(btrim(p_payload->>'fee_kind'),'');
  v_tax_code text := nullif(btrim(p_payload->>'tax_code'),'');
  v_tax_rate numeric := nullif(p_payload->>'tax_rate','')::numeric;
  v_from date := nullif(p_payload->>'effective_from','')::date;
  v_to date := nullif(p_payload->>'effective_to','')::date;
  v_request_id text := nullif(btrim(p_payload->>'request_id'),'');
  v_version integer;
  v_id uuid := gen_random_uuid();
  v_fp text;
  v_cached jsonb;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'FEE_TAX_TREATMENT_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_payload ? 'company_id'
     or v_kind not in ('RATE_MANAGEMENT_FEE','FIXED_MONTHLY')
     or v_tax_code is null
     or v_tax_rate is null
     or v_tax_rate < 0
     or v_tax_rate > 100
     or v_from is null
     or v_request_id is null
     or (v_to is not null and v_to < v_from) then
    raise exception 'FEE_TAX_TREATMENT_INPUT_REQUIRED' using errcode='22023';
  end if;
  if v_tax_code in ('NON_TAXABLE','VAT_ZERO') and v_tax_rate <> 0 then
    raise exception 'FEE_TAX_TREATMENT_ZERO_CODE_RATE_INVALID: % must use 0.000.', v_tax_code
      using errcode='23514';
  end if;
  if not exists(
    select 1 from public.tax_code_catalog c
     where c.code = v_tax_code and c.is_active
  ) then
    raise exception 'FEE_TAX_TREATMENT_CODE_FORBIDDEN' using errcode='42501';
  end if;

  v_fp := encode(sha256(convert_to(jsonb_build_object(
    'fee_kind', v_kind,
    'tax_code', v_tax_code,
    'tax_rate', round(v_tax_rate, 3),
    'effective_from', v_from,
    'effective_to', v_to
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended(
    'create_fee_tax_treatment:' || v_company_id::text || ':' || v_request_id, 0
  ));

  select response_payload into v_cached
    from public.financial_operation_idempotency
   where operation_name = 'create_fee_tax_treatment:' || v_company_id::text
     and request_id = v_request_id
   for update;

  if v_cached is not null then
    if v_cached->>'_request_fingerprint' is distinct from v_fp
       or not (v_cached ? 'response') then
      raise exception 'FEE_TAX_TREATMENT_IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode='22023';
    end if;
    return v_cached->'response';
  end if;

  -- Serialize version allocation independently from request-id serialization.
  perform pg_advisory_xact_lock(hashtextextended(
    'fee_tax_treatment_version:' || v_company_id::text || ':' || v_kind, 0
  ));

  select coalesce(max(version_no),0)+1
    into v_version
    from public.company_fee_tax_treatments
   where company_id = v_company_id
     and fee_kind = v_kind;

  insert into public.company_fee_tax_treatments(
    id, company_id, fee_kind, version_no, tax_code, tax_rate,
    effective_from, effective_to, status, created_by
  ) values (
    v_id, v_company_id, v_kind, v_version, v_tax_code, round(v_tax_rate,3),
    v_from, v_to, 'DRAFT', v_actor
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'treatment_id', v_id,
    'version_no', v_version,
    'status', 'DRAFT',
    'request_id', v_request_id
  );

  insert into public.financial_operation_idempotency(operation_name, request_id, response_payload)
  values (
    'create_fee_tax_treatment:' || v_company_id::text,
    v_request_id,
    jsonb_build_object('_request_fingerprint', v_fp, 'response', v_result)
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_fee_tax_treatment_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_future_owner_agreement_version_atomic"("p_owner_agreement_id" "uuid", "p_terms" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_company uuid := public.require_company_id();
  v_effective_from date := nullif(p_terms->>'effective_from', '')::date;
  v_has_current boolean;
  v_result jsonb;
begin
  select exists (
    select 1
    from public.owner_agreement_versions version_record
    where version_record.owner_agreement_id = p_owner_agreement_id
      and version_record.company_id = v_company
      and version_record.superseded_at is null
  ) into v_has_current;

  if v_effective_from is null then
    raise exception 'OWNER_AGREEMENT_VERSION_EFFECTIVE_DATE_REQUIRED' using errcode = '22023';
  end if;
  if v_has_current and v_effective_from <= current_date then
    raise exception 'OWNER_AGREEMENT_VERSION_MUST_BE_FUTURE' using errcode = '22023';
  end if;

  execute 'select to_jsonb(public.create_owner_agreement_version_atomic($1,$2))'
    into v_result
    using p_owner_agreement_id, p_terms;
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."create_future_owner_agreement_version_atomic"("p_owner_agreement_id" "uuid", "p_terms" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_future_owner_agreement_version_atomic"("p_owner_agreement_id" "uuid", "p_terms" "jsonb") IS 'GAP-004 browser authority: creates only a genuinely future owner-agreement amendment and delegates immutable versioning to the controlled kernel.';



CREATE OR REPLACE FUNCTION "public"."create_invoice_credit_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_invoice_id uuid;
  v_amount numeric;
  v_credit_type text;
  v_reason text;
  v_reason_code text;
  v_request_id text;
  v_effective_date date;
  v_invoice public.invoices%rowtype;
  v_outstanding numeric;
  v_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target text;
  v_existing jsonb;
  v_credit_id uuid := gen_random_uuid();
  v_batch_id uuid;
  v_original_batch_id uuid;
  v_source_batch_count integer := 0;
  v_classification text;
  v_taxable boolean := false;
  v_credit_tax numeric := 0;
  v_credit_net numeric := 0;
  v_prior_credit_amount numeric := 0;
  v_prior_credit_tax numeric := 0;
  v_prior_unclassified_tax_count integer := 0;
  v_ar_id text;
  v_source_ar_id text;
  v_source_ar_debit numeric := 0;
  v_source_non_tax_credit numeric := 0;
  v_source_tax_credit numeric := 0;
  v_source_debit_other numeric := 0;
  v_source_credit_other numeric := 0;
  v_remaining_non_tax numeric;
  v_target_portion numeric;
  v_target record;
  v_lines jsonb;
  v_post_result jsonb;
  v_result jsonb;
  v_credit_tax_snapshot_id uuid;
  v_period_id uuid;
  v_owner_id uuid;
begin
  if v_actor is null then
    raise exception 'Authentication is required to create invoice credits.' using errcode='42501';
  end if;
  if not coalesce(public.is_admin_or_manager(), false) and not coalesce(public.is_accountant(), false) then
    raise exception 'CREDIT_ROLE_REQUIRED: ADMIN, MANAGER or ACCOUNTANT role is required to create invoice credits.' using errcode='42501';
  end if;

  v_company_id := public.require_company_id();
  if p_payload ?| array['company_id','account_id','account_no','tax_rate','tax_code','tax_amount','journal_lines'] then
    raise exception 'CREDIT_SERVER_OWNED_ACCOUNTING_FIELDS_FORBIDDEN' using errcode='22023';
  end if;

  v_invoice_id := nullif(p_payload->>'invoice_id', '')::uuid;
  v_amount := public.gl_pm_round_omr(coalesce((p_payload->>'amount')::numeric, 0));
  v_credit_type := coalesce(nullif(p_payload->>'credit_type', ''), 'PARTIAL');
  v_reason := nullif(btrim(coalesce(p_payload->>'reason', '')), '');
  v_reason_code := nullif(p_payload->>'reason_code', '');
  v_request_id := nullif(p_payload->>'request_id', '');
  v_effective_date := coalesce(nullif(p_payload->>'effective_date', '')::date, current_date);
  if v_invoice_id is null or v_amount <= 0 or v_request_id is null or v_reason is null then
    raise exception 'CREDIT_REQUIRED: invoice_id, amount, reason and request_id are required.' using errcode='22023';
  end if;
  if v_credit_type not in ('PARTIAL','FULL') then
    raise exception 'CREDIT_TYPE_INVALID: credit_type must be PARTIAL or FULL.' using errcode='22023';
  end if;

  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'invoice_id', v_invoice_id::text,
    'amount', trim_scale(v_amount),
    'credit_type', v_credit_type,
    'reason', v_reason,
    'reason_code', v_reason_code,
    'effective_date', v_effective_date
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended('invoice_credit:' || v_company_id::text || ':' || v_request_id, 0));

  select response_payload into v_existing
    from public.financial_operation_idempotency
   where operation_name = 'invoice_credit:' || v_company_id::text
     and request_id = v_request_id
   for update;
  if v_existing is not null then
    v_cached_fingerprint := v_existing->>'_fingerprint';
    v_cached_target := v_existing->>'_target';
    if v_cached_fingerprint is null or v_cached_target is null or not (v_existing ? 'response') then
      raise exception 'CREDIT_IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED' using errcode='22023';
    end if;
    if v_cached_fingerprint <> v_fingerprint or v_cached_target <> v_invoice_id::text then
      raise exception 'CREDIT_IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode='22023';
    end if;
    return v_existing->'response';
  end if;

  select * into v_invoice
    from public.invoices
   where id = v_invoice_id
     and company_id = v_company_id
     and deleted_at is null
   for update;
  if not found then
    raise exception 'CREDIT_INVOICE_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;
  if v_invoice.document_status <> 'POSTED' then
    raise exception 'CREDIT_INVOICE_NOT_POSTED: only posted invoices can be credited.' using errcode='22023';
  end if;

  select oa.owner_id into v_owner_id
    from public.owner_agreement_versions av
    join public.owner_agreements oa
      on oa.id = av.owner_agreement_id
     and oa.company_id = av.company_id
   where av.id = v_invoice.invoice_agreement_version_id
     and av.company_id = v_company_id;

  v_outstanding := public.gl_pm_round_omr(
    v_invoice.amount + coalesce(v_invoice.tax_amount, 0)
    - coalesce(v_invoice.paid_amount, 0)
    - coalesce(v_invoice.credited_amount, 0)
  );
  if v_amount > v_outstanding + 0.001 then
    raise exception 'CREDIT_EXCEEDS_OUTSTANDING: credit % exceeds eligible invoice outstanding %.', v_amount, v_outstanding using errcode='22023';
  end if;

  -- Period control applies to all credits, including the operational owner-
  -- creditor path that has no invoice GL batch. The resolver enforces OPEN /
  -- SOFT_CLOSED / HARD_CLOSED and late-posting policy without caller input.
  perform public.gl_ensure_initial_open_period(v_company_id, v_effective_date);
  select period_id into v_period_id
    from public.gl_resolve_accounting_period(v_company_id, v_effective_date);
  if v_period_id is null then
    raise exception 'CREDIT_ACCOUNTING_PERIOD_UNAVAILABLE' using errcode='P0001';
  end if;

  v_classification := v_invoice.invoice_accounting_classification;
  if v_classification = 'OWNER_AGENCY_OWNER_CREDITOR_OPERATIONAL' then
    v_original_batch_id := null;
  elsif v_classification = 'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS' then
    v_original_batch_id := v_invoice.invoice_posting_batch_id;
    if v_original_batch_id is null then
      raise exception 'CREDIT_INVOICE_POSTING_LINEAGE_MISSING' using errcode='23514';
    end if;
  elsif v_classification is null then
    select count(*)::integer, min(b.id)
      into v_source_batch_count, v_original_batch_id
      from public.journal_batches b
     where b.company_id = v_company_id
       and b.source_type = 'invoice'
       and b.source_id = v_invoice_id::text;
    if v_source_batch_count <> 1 then
      raise exception 'CREDIT_LEGACY_INVOICE_LINEAGE_REVIEW_REQUIRED: historical invoice has no unique canonical source batch.'
        using errcode='23514';
    end if;
    v_classification := 'LEGACY_SOURCE_BATCH_REVERSAL';
  else
    raise exception 'CREDIT_INVOICE_ACCOUNTING_CLASSIFICATION_UNSUPPORTED' using errcode='23514';
  end if;

  -- Tax is derived from the original immutable invoice snapshot. Existing
  -- taxable rows without that snapshot are not guessed from a current profile.
  if v_invoice.tax_treatment in ('TAXABLE', 'NON_TAXABLE') then
    if v_invoice.tax_snapshot_id is null
       or v_invoice.tax_profile_id is null
       or v_invoice.tax_code is null
       or not exists (
         select 1 from public.taxable_line_tax_snapshots s
          where s.id = v_invoice.tax_snapshot_id
            and s.company_id = v_company_id
            and s.source_type = 'invoice'
            and s.source_id = v_invoice_id::text
            and s.tax_code = v_invoice.tax_code
            and s.tax_rate = v_invoice.tax_rate
            and s.net_amount = v_invoice.amount
            and s.tax_amount = v_invoice.tax_amount
       ) then
      raise exception 'CREDIT_TAX_LINEAGE_MISSING: invoice lacks immutable original profile/snapshot lineage.'
        using errcode='23514';
    end if;
    if v_invoice.tax_treatment = 'TAXABLE' then
      if v_invoice.tax_basis <> 'NET_PLUS_TAX' then
        raise exception 'CREDIT_TAXABLE_INVOICE_BASIS_INVALID' using errcode='23514';
      end if;
      v_taxable := true;
    elsif coalesce(v_invoice.tax_amount, 0) <> 0
       or coalesce(v_invoice.tax_rate, 0) <> 0
       or v_invoice.tax_code <> 'NON_TAXABLE'
       or v_invoice.tax_basis <> 'NON_TAXABLE' then
      raise exception 'CREDIT_NON_TAXABLE_INVOICE_TAX_INVALID' using errcode='23514';
    end if;
  elsif coalesce(v_invoice.tax_amount, 0) > 0 then
    raise exception 'CREDIT_LEGACY_TAX_LINEAGE_REVIEW_REQUIRED: historical taxable invoice cannot be credited without its original immutable tax snapshot.'
      using errcode='23514';
  end if;

  -- Tax credit allocation is based on cumulative original-invoice economics.
  -- The final credit receives the rounding residue so every sequence sums
  -- exactly to the original tax amount at OMR 3dp.
  select
    coalesce(sum(ic.amount) filter (where ic.status = 'POSTED'), 0),
    coalesce(sum(ic.tax_amount) filter (where ic.status = 'POSTED'), 0),
    count(*) filter (where ic.status = 'POSTED' and ic.tax_amount is null)
  into v_prior_credit_amount, v_prior_credit_tax, v_prior_unclassified_tax_count
  from public.invoice_credits ic
  where ic.company_id = v_company_id
    and ic.invoice_id = v_invoice_id;

  if v_taxable and (v_prior_unclassified_tax_count > 0 or abs(v_prior_credit_amount - coalesce(v_invoice.credited_amount, 0)) > 0.001) then
    raise exception 'CREDIT_EXISTING_TAX_LINEAGE_REVIEW_REQUIRED: prior credit rows lack immutable tax components.'
      using errcode='23514';
  end if;

  if v_taxable then
    if v_prior_credit_amount + v_amount >= v_invoice.amount + v_invoice.tax_amount - 0.001 then
      v_credit_tax := public.gl_pm_round_omr(v_invoice.tax_amount - v_prior_credit_tax);
    else
      v_credit_tax := public.gl_pm_round_omr(
        public.gl_pm_round_omr((v_prior_credit_amount + v_amount) * v_invoice.tax_amount / (v_invoice.amount + v_invoice.tax_amount))
        - v_prior_credit_tax
      );
    end if;
  end if;
  v_credit_net := public.gl_pm_round_omr(v_amount - v_credit_tax);

  -- For a journal-backed invoice, validate the original source economics and
  -- construct the controlled inverse using its actual credited accounts. The
  -- caller cannot nominate a GL account. This naturally reverses a historical
  -- 4000 source as 4000, while new owner-agency OFFICE sources reverse 2000.
  v_lines := '[]'::jsonb;
  if v_original_batch_id is not null then
    select
      coalesce(sum(jl.debit) filter (where a.no = '1201'), 0),
      coalesce(sum(jl.credit) filter (where a.no <> '2100'), 0),
      coalesce(sum(jl.credit) filter (where a.no = '2100'), 0),
      coalesce(sum(jl.debit) filter (where a.no <> '1201'), 0),
      coalesce(sum(jl.credit) filter (where a.no = '1201'), 0)
    into v_source_ar_debit, v_source_non_tax_credit, v_source_tax_credit,
         v_source_debit_other, v_source_credit_other
    from public.journal_lines jl
    join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
    join public.journal_batches b on b.id = jl.batch_id and b.company_id = v_company_id
    where jl.batch_id = v_original_batch_id
      and jl.company_id = v_company_id
      and b.status in ('POSTED','REVERSED');

    if round(v_source_ar_debit, 3) <> round(v_invoice.amount + coalesce(v_invoice.tax_amount,0), 3)
       or round(v_source_non_tax_credit, 3) <> round(v_invoice.amount, 3)
       or round(v_source_tax_credit, 3) <> round(coalesce(v_invoice.tax_amount,0), 3)
       or round(v_source_debit_other, 3) <> 0
       or round(v_source_credit_other, 3) <> 0 then
      raise exception 'CREDIT_SOURCE_ECONOMICS_UNSUPPORTED: source invoice must be a controlled Dr 1201 / Cr economic target (+2100) batch.'
        using errcode='23514';
    end if;

    select a.id into v_source_ar_id
      from public.journal_lines jl
      join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
     where jl.batch_id = v_original_batch_id
       and jl.company_id = v_company_id
       and a.no = '1201'
       and jl.debit > 0
     limit 1;
    if v_source_ar_id is null then
      raise exception 'CREDIT_SOURCE_AR_LINE_MISSING' using errcode='23514';
    end if;

    v_lines := jsonb_build_array(
      jsonb_build_object(
        'account_id', v_source_ar_id,
        'debit', 0,
        'credit', v_amount,
        'line_description', 'CREDIT-' || v_credit_id::text || '-CR-AR',
        'ref_source_id', v_invoice_id::text,
        'ref_entity_type', 'invoice',
        'ref_entity_id', v_invoice_id::text
      )
    );

    v_remaining_non_tax := v_credit_net;
    for v_target in
      select a.id as account_id, a.no as account_no, jl.credit as original_credit,
             row_number() over (order by a.no, a.id) as line_no,
             count(*) over () as line_count
        from public.journal_lines jl
        join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
       where jl.batch_id = v_original_batch_id
         and jl.company_id = v_company_id
         and jl.credit > 0
         and a.no <> '2100'
       order by a.no, a.id
    loop
      if v_target.line_no = v_target.line_count then
        v_target_portion := v_remaining_non_tax;
      else
        v_target_portion := public.gl_pm_round_omr(v_credit_net * v_target.original_credit / v_source_non_tax_credit);
        v_remaining_non_tax := public.gl_pm_round_omr(v_remaining_non_tax - v_target_portion);
      end if;
      if v_target_portion > 0 then
        v_lines := v_lines || jsonb_build_array(
          jsonb_build_object(
            'account_id', v_target.account_id,
            'debit', v_target_portion,
            'credit', 0,
            'line_description', 'CREDIT-' || v_credit_id::text || '-DR-' || v_target.account_no,
            'ref_source_id', v_invoice_id::text,
            'ref_entity_type', 'invoice',
            'ref_entity_id', v_invoice_id::text
          )
        );
      end if;
    end loop;

    if v_credit_tax > 0 then
      select a.id into v_ar_id
        from public.journal_lines jl
        join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
       where jl.batch_id = v_original_batch_id
         and jl.company_id = v_company_id
         and a.no = '2100'
         and jl.credit > 0
       limit 1;
      if v_ar_id is null then
        raise exception 'CREDIT_SOURCE_VAT_LINE_MISSING' using errcode='23514';
      end if;
      v_lines := v_lines || jsonb_build_array(
        jsonb_build_object(
          'account_id', v_ar_id,
          'debit', v_credit_tax,
          'credit', 0,
          'line_description', 'CREDIT-' || v_credit_id::text || '-DR-VAT',
          'ref_source_id', v_invoice_id::text,
          'ref_entity_type', 'invoice',
          'ref_entity_id', v_invoice_id::text
        )
      );
    end if;
  end if;

  insert into public.invoice_credits (
    id, company_id, invoice_id, amount, credit_type, reason, reason_code,
    effective_date, created_by, request_id, status,
    net_amount, tax_amount, tax_profile_id, tax_snapshot_id, tax_code, tax_rate,
    tax_basis, accounting_classification, original_invoice_posting_batch_id
  ) values (
    v_credit_id, v_company_id, v_invoice_id, v_amount, v_credit_type, v_reason, v_reason_code,
    v_effective_date, v_actor, v_request_id, 'POSTED',
    v_credit_net, v_credit_tax,
    v_invoice.tax_profile_id,
    v_invoice.tax_snapshot_id,
    v_invoice.tax_code,
    coalesce(v_invoice.tax_rate, 0),
    coalesce(v_invoice.tax_basis, case when v_taxable then 'NET_PLUS_TAX' else 'NON_TAXABLE' end),
    v_classification, v_original_batch_id
  );

  if v_original_batch_id is not null then
    v_post_result := public.post_journal_event(jsonb_build_object(
      'company_id', v_company_id,
      'source_type', 'invoice_credit',
      'source_id', v_invoice_id::text,
      'event_id', v_request_id,
      'effective_date', v_effective_date,
      'description', 'Invoice credit ' || v_credit_id::text || ' reverses original invoice economics',
      'lines', v_lines
    ));
    v_batch_id := nullif(v_post_result->>'batch_id', '')::uuid;
    if v_batch_id is null then
      raise exception 'CREDIT_POSTING_BATCH_MISSING' using errcode='P0001';
    end if;
    update public.invoice_credits
       set journal_batch_id = v_batch_id
     where id = v_credit_id;
  end if;

  if v_taxable then
    insert into public.taxable_line_tax_snapshots (
      company_id, source_type, source_id, journal_batch_id, account_no,
      tax_code, tax_rate, net_amount, tax_amount, effective_date
    ) values (
      v_company_id, 'invoice_credit', v_credit_id::text, v_batch_id, '2100',
      v_invoice.tax_code, v_invoice.tax_rate, v_credit_net, v_credit_tax, v_effective_date
    ) returning id into v_credit_tax_snapshot_id;
  end if;

  if v_classification = 'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS' then
    if v_owner_id is null then
      raise exception 'CREDIT_OWNER_FUNDS_OWNER_REQUIRED' using errcode='23514';
    end if;
    insert into public.owner_funds_events (
      company_id, owner_id, contract_id, invoice_id, source_type, source_id,
      event_id, amount_delta, effective_date, journal_batch_id
    ) values (
      v_company_id, v_owner_id, v_invoice.contract_id, v_invoice_id,
      'INVOICE_CREDIT', v_credit_id::text, 'credit', -v_credit_net,
      v_effective_date, v_batch_id
    );
  end if;

  update public.invoices
     set credited_amount = public.gl_pm_round_omr(credited_amount + v_amount),
         updated_at = now()
   where id = v_invoice_id
     and company_id = v_company_id;
  perform public.recalculate_invoice_status(v_invoice_id);

  v_result := jsonb_build_object(
    'success', true,
    'credit_id', v_credit_id::text,
    'invoice_id', v_invoice_id::text,
    'amount', trim_scale(v_amount)::text,
    'net_amount', trim_scale(v_credit_net)::text,
    'tax_amount', trim_scale(v_credit_tax)::text,
    'credit_type', v_credit_type,
    'request_id', v_request_id,
    'batch_id', v_batch_id::text,
    'tax_posting_snapshot_id', v_credit_tax_snapshot_id::text,
    'outstanding_after', trim_scale(public.gl_pm_round_omr(v_outstanding - v_amount))::text
  );

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values (
    'invoice_credit:' || v_company_id::text,
    v_request_id,
    jsonb_build_object('_fingerprint', v_fingerprint, '_target', v_invoice_id::text, 'response', v_result)
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_invoice_credit_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_invoice_credit_atomic"("p_payload" "jsonb") IS 'RC1 controlled credit. Reverses the original invoice source economics and original tax snapshot; callers never choose accounts or current tax rates.';



CREATE OR REPLACE FUNCTION "public"."create_maintenance_atomic"("p_property_id" "text", "p_unit_id" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_priority" "text" DEFAULT 'medium'::"text", "p_assigned_to" "text" DEFAULT NULL::"text", "p_technician_name" "text" DEFAULT NULL::"text", "p_scheduled_date" "date" DEFAULT NULL::"date", "p_attachment_url" "text" DEFAULT NULL::"text", "p_request_id" "text" DEFAULT NULL::"text", "p_service_provider_category_id" "uuid" DEFAULT NULL::"uuid", "p_service_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_property public.properties%rowtype;
  v_unit public.units%rowtype;
  v_priority text;
  v_title text;
  v_record public.maintenance_records;
  v_audit_id text;
begin
  if auth.uid() is null then
    raise exception 'غير مصرح: يجب تسجيل الدخول' using errcode = '42501';
  end if;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'لم يتم تحديد الشركة الحالية' using errcode = '42501';
  end if;

  v_title := btrim(coalesce(p_title, ''));
  if v_title = '' then raise exception 'عنوان طلب الصيانة مطلوب'; end if;

  v_priority := lower(coalesce(p_priority, 'medium'));
  if v_priority not in ('low', 'medium', 'high', 'urgent') then
    raise exception 'أولوية غير صحيحة';
  end if;

  -- ::text comparisons: correct on clean uuid schemas AND live text schemas.
  select * into v_property
  from public.properties
  where id::text = p_property_id and company_id = v_company_id and deleted_at is null;
  if not found then raise exception 'العقار غير موجود أو تابع لشركة أخرى أو مؤرشف'; end if;

  if p_unit_id is not null and btrim(p_unit_id) <> '' then
    select * into v_unit
    from public.units
    where id::text = p_unit_id
      and property_id::text = v_property.id::text
      and company_id = v_company_id
      and deleted_at is null;
    if not found then raise exception 'الوحدة غير موجودة أو لا تتبع العقار المحدد'; end if;
  end if;

  -- Validate both assignment records before the write so an invalid
  -- cross-company retry cannot use the RPC as an existence oracle.
  if p_service_provider_category_id is not null and not exists (
    select 1 from public.service_provider_categories c
    where c.id = p_service_provider_category_id and c.company_id = v_company_id
      and c.is_active and c.deleted_at is null
  ) then
    raise exception 'نوع الخدمة غير متاح للشركة الحالية' using errcode = '23503';
  end if;
  if p_service_provider_id is not null and not exists (
    select 1 from public.service_providers p
    where p.id = p_service_provider_id and p.company_id = v_company_id
      and p.is_active and p.deleted_at is null
  ) then
    raise exception 'مزود الخدمة غير متاح للشركة الحالية' using errcode = '23503';
  end if;
  if p_service_provider_id is not null and p_service_provider_category_id is not null
     and not exists (
       select 1 from public.service_provider_category_links link
       where link.company_id = v_company_id
         and link.service_provider_id = p_service_provider_id
         and link.category_id = p_service_provider_category_id
     ) then
    raise exception 'مزود الخدمة المحدد لا يدعم نوع الخدمة المختار' using errcode = '23514';
  end if;

  -- Race-safe idempotency: INSERT ... ON CONFLICT DO NOTHING is atomic with
  -- respect to the company-scoped unique index, so two concurrent identical
  -- requests can never both insert; the "loser" reloads the canonical existing
  -- row and returns the same semantic result instead of a unique violation.
  v_record := null;
  insert into public.maintenance_records (
    company_id, property_id, unit_id, title, description, priority,
    assigned_to, technician_name, scheduled_date, attachment_url,
    request_id, status, request_date, service_provider_category_id, service_provider_id
  ) values (
    v_company_id, v_property.id, v_unit.id, v_title,
    nullif(btrim(coalesce(p_description, '')), ''), v_priority,
    nullif(btrim(coalesce(p_assigned_to, '')), ''),
    nullif(btrim(coalesce(p_technician_name, '')), ''),
    p_scheduled_date, nullif(btrim(coalesce(p_attachment_url, '')), ''),
    nullif(btrim(coalesce(p_request_id, '')), ''), 'open', current_date,
    p_service_provider_category_id, p_service_provider_id
  )
  on conflict (company_id, request_id) where request_id is not null and deleted_at is null
  do nothing
  returning * into v_record;

  if v_record.id is null then
    -- A concurrent identical request already created the row: return the
    -- canonical cached result (same semantic outcome, idempotent).
    select * into v_record
    from public.maintenance_records
    where request_id = nullif(btrim(coalesce(p_request_id, '')), '')
      and company_id = v_company_id
      and deleted_at is null
    limit 1;
    return jsonb_build_object('maintenance', to_jsonb(v_record), 'idempotent', true);
  end if;

  insert into public.audit_log(user_id, action, entity, entity_id, note, "table", details)
  values (
    auth.uid(), 'create', 'maintenance_record', v_record.id::text,
    'create_maintenance_atomic: ' || v_title || ' (company=' || v_company_id || ')',
    'maintenance_records',
    jsonb_strip_nulls(jsonb_build_object(
      'company_id', v_company_id,
      'service_provider_id', p_service_provider_id,
      'service_provider_category_id', p_service_provider_category_id
    ))::text
  ) returning id into v_audit_id;

  return jsonb_build_object('maintenance', to_jsonb(v_record), 'idempotent', false);
end;
$$;


ALTER FUNCTION "public"."create_maintenance_atomic"("p_property_id" "text", "p_unit_id" "text", "p_title" "text", "p_description" "text", "p_priority" "text", "p_assigned_to" "text", "p_technician_name" "text", "p_scheduled_date" "date", "p_attachment_url" "text", "p_request_id" "text", "p_service_provider_category_id" "uuid", "p_service_provider_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_maintenance_atomic"("p_property_id" "text", "p_unit_id" "text", "p_title" "text", "p_description" "text", "p_priority" "text", "p_assigned_to" "text", "p_technician_name" "text", "p_scheduled_date" "date", "p_attachment_url" "text", "p_request_id" "text", "p_service_provider_category_id" "uuid", "p_service_provider_id" "uuid") IS 'R13: race-safe canonical maintenance creation. Idempotency is INSERT ... ON CONFLICT (company_id, request_id) DO NOTHING + reload of the canonical row, so concurrent identical requests return the same deterministic result without a unique violation. Company isolation, cross-company validation order, audit behavior and ::text-safe identifier comparisons are preserved.';



