    "owner_id" "uuid" NOT NULL,
    "property_id" "uuid" NOT NULL,
    "agreement_type" "text" NOT NULL,
    "commission_type" "text" NOT NULL,
    "commission_value" numeric(14,4) NOT NULL,
    "starts_on" "date" NOT NULL,
    "ends_on" "date",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "company_id" "uuid" DEFAULT "public"."current_company_id"(),
    "reference" "text",
    "current_version_id" "uuid",
    CONSTRAINT "owner_agreements_agreement_type_check" CHECK (("agreement_type" = ANY (ARRAY['property_management'::"text", 'master_lease'::"text"]))),
    CONSTRAINT "owner_agreements_check" CHECK (((("commission_type" = 'RATE'::"text") AND ("commission_value" >= (0)::numeric) AND ("commission_value" <= (100)::numeric)) OR (("commission_type" = 'FIXED_MONTHLY'::"text") AND ("commission_value" >= (0)::numeric)))),
    CONSTRAINT "owner_agreements_check1" CHECK ((("ends_on" IS NULL) OR ("ends_on" >= "starts_on"))),
    CONSTRAINT "owner_agreements_commission_type_check" CHECK (("commission_type" = ANY (ARRAY['FIXED_MONTHLY'::"text", 'RATE'::"text"])))
);


ALTER TABLE "public"."owner_agreements" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_owner_agreement_atomic"("payload" "jsonb") RETURNS "public"."owner_agreements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_owner_id public.owner_agreements.owner_id%type;
  v_property_id public.owner_agreements.property_id%type;
  v_row public.owner_agreements%rowtype;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'غير مصرح: يحتاج هذا الإجراء صلاحية مدير أو مشرف.' using errcode = '42501';
  end if;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Company context is required (no company_id claim in JWT).' using errcode = '42501';
  end if;

  v_owner_id := nullif(payload->>'owner_id', '');
  v_property_id := nullif(payload->>'property_id', '');

  if v_owner_id is null or v_property_id is null then
    raise exception 'owner_id and property_id are required.' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.owners o
    where o.id::text = v_owner_id::text
      and o.company_id = v_company_id
      and o.deleted_at is null
  ) then
    raise exception 'Agreement owner is not in your company.' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.properties pr
    where pr.id::text = v_property_id::text
      and pr.company_id = v_company_id
      and pr.deleted_at is null
  ) then
    raise exception 'Agreement property is not in your company.' using errcode = '42501';
  end if;

  insert into public.owner_agreements (
    owner_id, property_id, agreement_type, commission_type, commission_value,
    starts_on, ends_on, notes, company_id
  ) values (
    v_owner_id,
    v_property_id,
    payload->>'agreement_type',
    payload->>'commission_type',
    (payload->>'commission_value')::numeric,
    (payload->>'starts_on')::date,
    nullif(payload->>'ends_on', '')::date,
    nullif(payload->>'notes', ''),
    v_company_id
  )
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."create_owner_agreement_atomic"("payload" "jsonb") OWNER TO "postgres";


