    "version_no" integer NOT NULL,
    "operating_model" "text" NOT NULL,
    "collection_role" "text" NOT NULL,
    "commission_type" "text" NOT NULL,
    "commission_value" numeric(14,4) NOT NULL,
    "commission_recognition_basis" "text" NOT NULL,
    "offset_allowed" boolean DEFAULT false NOT NULL,
    "reserve_amount" numeric(14,3) DEFAULT 0 NOT NULL,
    "deposit_beneficiary" "text",
    "deposit_custodian" "text",
    "effective_from" "date" NOT NULL,
    "effective_to" "date",
    "notes" "text",
