    CONSTRAINT "owner_agreement_versions_collection_role_check" CHECK (("collection_role" = ANY (ARRAY['OWNER_IS_CREDITOR'::"text", 'OFFICE_IS_CREDITOR'::"text"]))),
    CONSTRAINT "owner_agreement_versions_commission_recognition_basis_check" CHECK (("commission_recognition_basis" = ANY (ARRAY['ON_COLLECTION'::"text", 'DAILY_ACCRUAL'::"text"]))),
    CONSTRAINT "owner_agreement_versions_commission_type_check" CHECK (("commission_type" = ANY (ARRAY['RATE'::"text", 'FIXED_MONTHLY'::"text"]))),
    CONSTRAINT "owner_agreement_versions_date_order" CHECK ((("effective_to" IS NULL) OR ("effective_to" >= "effective_from"))),
    CONSTRAINT "owner_agreement_versions_deposit_beneficiary_check" CHECK (("deposit_beneficiary" = ANY (ARRAY['OWNER'::"text", 'OFFICE'::"text"]))),
    CONSTRAINT "owner_agreement_versions_deposit_custodian_check" CHECK (("deposit_custodian" = ANY (ARRAY['OWNER'::"text", 'OFFICE'::"text"]))),
    CONSTRAINT "owner_agreement_versions_operating_model_check" CHECK (("operating_model" = ANY (ARRAY['OWNER_AGENCY'::"text", 'BROKERAGE_OR_COLLECTION_ONLY'::"text"]))),
    CONSTRAINT "owner_agreement_versions_rate_range" CHECK (((("commission_type" = 'RATE'::"text") AND ("commission_value" >= (0)::numeric) AND ("commission_value" <= (100)::numeric)) OR (("commission_type" = 'FIXED_MONTHLY'::"text") AND ("commission_value" >= (0)::numeric)))),
    CONSTRAINT "owner_agreement_versions_recognition_matches_commission" CHECK (((("commission_type" = 'RATE'::"text") AND ("commission_recognition_basis" = 'ON_COLLECTION'::"text")) OR (("commission_type" = 'FIXED_MONTHLY'::"text") AND ("commission_recognition_basis" = 'DAILY_ACCRUAL'::"text")))),
    CONSTRAINT "owner_agreement_versions_reserve_amount_check" CHECK (("reserve_amount" >= (0)::numeric)),
    CONSTRAINT "owner_agreement_versions_version_no_check" CHECK (("version_no" > 0))
);


ALTER TABLE "public"."owner_agreement_versions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_owner_agreement_version_atomic"("p_owner_agreement_id" "uuid", "p_terms" "jsonb") RETURNS "public"."owner_agreement_versions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company uuid := public.require_company_id();
  v_parent public.owner_agreements%rowtype;
  v_current public.owner_agreement_versions%rowtype;
  v_new public.owner_agreement_versions%rowtype;
  v_commission_type text;
  v_commission_value numeric;
  v_operating_model text;
  v_collection_role text;
  v_recognition text;
  v_effective_from date;
  v_effective_to date;
begin
  if v_actor is null or not public.is_admin_or_manager() then
    raise exception 'OWNER_AGREEMENT_VERSION_FORBIDDEN' using errcode = '42501';
  end if;

  select * into v_parent
  from public.owner_agreements
  where id = p_owner_agreement_id
    and company_id = v_company
  for update;

  if not found or v_parent.agreement_type <> 'property_management' then
    raise exception 'OWNER_AGREEMENT_NOT_FOUND_OR_NOT_AGENCY' using errcode = '42501';
  end if;

  select * into v_current
  from public.owner_agreement_versions
  where owner_agreement_id = p_owner_agreement_id
    and company_id = v_company
    and superseded_at is null
  for update;

  v_operating_model := coalesce(nullif(p_terms->>'operating_model',''), coalesce(v_current.operating_model,'OWNER_AGENCY'));
  v_collection_role := coalesce(nullif(p_terms->>'collection_role',''), coalesce(v_current.collection_role,'OWNER_IS_CREDITOR'));
  v_commission_type := coalesce(nullif(p_terms->>'commission_type',''), coalesce(v_current.commission_type,v_parent.commission_type));
  v_commission_value := coalesce(nullif(p_terms->>'commission_value','')::numeric, coalesce(v_current.commission_value,v_parent.commission_value));
  v_effective_from := coalesce(nullif(p_terms->>'effective_from','')::date, greatest(current_date, v_parent.starts_on));
  v_effective_to := case when p_terms ? 'effective_to' then nullif(p_terms->>'effective_to','')::date else v_parent.ends_on end;

  if v_operating_model not in ('OWNER_AGENCY','BROKERAGE_OR_COLLECTION_ONLY')
     or v_collection_role not in ('OWNER_IS_CREDITOR','OFFICE_IS_CREDITOR')
     or v_commission_type not in ('RATE','FIXED_MONTHLY') then
    raise exception 'OWNER_AGREEMENT_VERSION_TERMS_INVALID' using errcode = '22023';
  end if;

  if v_commission_value::text in ('NaN','Infinity','-Infinity')
     or (v_commission_type = 'RATE' and (v_commission_value < 0 or v_commission_value > 100))
     or (v_commission_type = 'FIXED_MONTHLY' and v_commission_value < 0)
     or (v_effective_to is not null and v_effective_to < v_effective_from) then
    raise exception 'OWNER_AGREEMENT_VERSION_TERMS_INVALID' using errcode = '22023';
  end if;

  v_recognition := case when v_commission_type = 'RATE' then 'ON_COLLECTION' else 'DAILY_ACCRUAL' end;

  if v_current.id is not null then
    if v_effective_from <= v_current.effective_from then
      raise exception 'OWNER_AGREEMENT_VERSION_RETROACTIVE_CHANGE_FORBIDDEN' using errcode = '22023';
    end if;

    update public.owner_agreement_versions
    set effective_to = v_effective_from - 1,
        superseded_at = now()
    where id = v_current.id
      and company_id = v_company;
  end if;

  insert into public.owner_agreement_versions (
    owner_agreement_id,
    company_id,
    version_no,
    operating_model,
    collection_role,
    commission_type,
    commission_value,
    commission_recognition_basis,
    offset_allowed,
    reserve_amount,
    deposit_beneficiary,
    deposit_custodian,
    effective_from,
    effective_to,
    notes,
    created_by
  ) values (
    p_owner_agreement_id,
    v_company,
    coalesce(v_current.version_no,0) + 1,
    v_operating_model,
    v_collection_role,
    v_commission_type,
    v_commission_value,
    v_recognition,
    coalesce((p_terms->>'offset_allowed')::boolean, coalesce(v_current.offset_allowed,false)),
    coalesce(nullif(p_terms->>'reserve_amount','')::numeric, coalesce(v_current.reserve_amount,0)),
    case when p_terms ? 'deposit_beneficiary' then nullif(p_terms->>'deposit_beneficiary','') else v_current.deposit_beneficiary end,
    case when p_terms ? 'deposit_custodian' then nullif(p_terms->>'deposit_custodian','') else v_current.deposit_custodian end,
    v_effective_from,
    v_effective_to,
    case when p_terms ? 'notes' then nullif(p_terms->>'notes','') else v_current.notes end,
    v_actor
  ) returning * into v_new;

  update public.owner_agreements
  set current_version_id = v_new.id,
      updated_at = now()
  where id = p_owner_agreement_id
    and company_id = v_company;

  return v_new;
end;
$$;


ALTER FUNCTION "public"."create_owner_agreement_version_atomic"("p_owner_agreement_id" "uuid", "p_terms" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_owner_agreement_version_atomic"("p_owner_agreement_id" "uuid", "p_terms" "jsonb") IS 'S04-T01: creates a new non-retroactive owner-agency terms version; current commercial terms are never silently overwritten.';



CREATE OR REPLACE FUNCTION "public"."create_owner_agreement_with_version_atomic"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_agreement jsonb;
  v_version jsonb;
  v_agreement_type text := coalesce(nullif(payload->>'agreement_type', ''), 'property_management');
begin
  if v_agreement_type <> 'property_management' then
    raise exception 'MASTER_LEASE_EXCLUDED_FROM_RC1' using errcode = '0A000';
  end if;

  -- Reuse the existing company, role, ownership, overlap and field validation.
  select to_jsonb(public.create_owner_agreement_atomic(payload)) into v_agreement;

  -- The first version is created in this same transaction. Any invalid terms
  -- roll back both records, so an unversioned agreement cannot escape.
  execute 'select to_jsonb(public.create_owner_agreement_version_atomic($1,$2))'
    into v_version
    using
      (v_agreement->>'id')::uuid,
      jsonb_build_object(
        'operating_model', coalesce(nullif(payload->>'operating_model', ''), 'OWNER_AGENCY'),
        'collection_role', nullif(payload->>'collection_role', ''),
        'commission_type', payload->>'commission_type',
        'commission_value', payload->>'commission_value',
        'offset_allowed', coalesce(nullif(payload->>'offset_allowed', '')::boolean, false),
        'reserve_amount', coalesce(nullif(payload->>'reserve_amount', '')::numeric, 0),
        'deposit_beneficiary', nullif(payload->>'deposit_beneficiary', ''),
        'deposit_custodian', nullif(payload->>'deposit_custodian', ''),
        'effective_from', payload->>'starts_on',
        'effective_to', nullif(payload->>'ends_on', ''),
        'notes', nullif(payload->>'notes', '')
      );

  if v_version->>'id' is null then
    raise exception 'OWNER_AGREEMENT_INITIAL_VERSION_REQUIRED' using errcode = '23514';
  end if;

  select to_jsonb(agreement_record) into strict v_agreement
  from public.owner_agreements agreement_record
  where agreement_record.id = (v_agreement->>'id')::uuid
    and agreement_record.company_id = public.require_company_id();

  return v_agreement;
end;
$_$;


ALTER FUNCTION "public"."create_owner_agreement_with_version_atomic"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_owner_agreement_with_version_atomic"("payload" "jsonb") IS 'GAP-004: atomically creates an RC1 owner-agency identity and its explicit first immutable commercial version; MASTER_LEASE is excluded.';



CREATE OR REPLACE FUNCTION "public"."create_owner_funds_cutover_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid := public.require_company_id();
  v_cutover_date date := nullif(p_payload->>'cutover_date','')::date;
  v_review_id uuid := nullif(p_payload->>'s08_review_id','')::uuid;
  v_reason text := nullif(btrim(coalesce(p_payload->>'reason','')), '');
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_balance numeric;
  v_count bigint;
  v_fingerprint text;
  v_existing jsonb;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'OWNER_FUNDS_CUTOVER_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_payload ? 'company_id' then
    raise exception 'OWNER_FUNDS_CUTOVER_COMPANY_SERVER_DERIVED' using errcode='22023';
  end if;
  if v_cutover_date is null or v_review_id is null or v_reason is null or v_request_id is null then
    raise exception 'OWNER_FUNDS_CUTOVER_INPUT_REQUIRED' using errcode='22023';
  end if;
  if not exists (
    select 1 from public.s08_frozen_reviews r
     where r.id = v_review_id and r.company_id = v_company_id and r.reviewer_decision = 'APPROVED'
  ) then
    raise exception 'OWNER_FUNDS_CUTOVER_S08_APPROVAL_REQUIRED' using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('owner_funds_cutover:' || v_company_id::text, 0));
  select public.wp05_gl_balance(v_company_id, '2000', v_cutover_date),
         public.wp05_gl_line_count(v_company_id, '2000', v_cutover_date)
    into v_balance, v_count;
  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'company_id', v_company_id,
    'cutover_date', v_cutover_date,
    'opening_balance', public.wp05_round_omr(v_balance),
    'gl_line_count', v_count,
    's08_review_id', v_review_id
  )::text, 'UTF8')), 'hex');

  select jsonb_build_object(
    'company_id', company_id, 'cutover_date', cutover_date,
    'opening_balance', opening_balance, 'status', status,
    'source_fingerprint', source_fingerprint
  ) into v_existing
  from public.owner_funds_event_cutovers
  where company_id = v_company_id
  for update;
  if v_existing is not null then
    return jsonb_build_object('success', true, 'idempotent', true, 'cutover', v_existing);
  end if;

  insert into public.owner_funds_event_cutovers (
    company_id, cutover_date, opening_balance, gl_line_count, source_fingerprint,
    s08_review_id, status, created_by, reason
  ) values (
    v_company_id, v_cutover_date, public.wp05_round_omr(v_balance), v_count, v_fingerprint,
    v_review_id, 'DRAFT', v_actor, v_reason
  );

  v_result := jsonb_build_object(
    'success', true, 'idempotent', false, 'company_id', v_company_id,
    'cutover_date', v_cutover_date, 'opening_balance', public.wp05_round_omr(v_balance),
    'source_fingerprint', v_fingerprint, 'status', 'DRAFT', 'request_id', v_request_id
  );
  insert into public.financial_operation_idempotency(operation_name, request_id, response_payload)
  values ('create_owner_funds_cutover:' || v_company_id::text, v_request_id, v_result)
  on conflict do nothing;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_owner_funds_cutover_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_owner_receivable_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_owner_id uuid := nullif(p_payload->>'owner_id','')::uuid;
  v_agreement_id uuid := nullif(p_payload->>'owner_agreement_id','')::uuid;
  v_agreement_version_id uuid;
  v_property_id text := nullif(btrim(coalesce(p_payload->>'property_id','')), '');
  v_amount numeric := public.wp02_gap008_round_omr(nullif(p_payload->>'amount','')::numeric);
  v_cash_no text := coalesce(nullif(p_payload->>'cash_account_no',''), '1120');
  v_date date := nullif(p_payload->>'effective_date','')::date;
  v_source_id text := nullif(btrim(coalesce(p_payload->>'source_id','')), '');
  v_offset_right boolean := false;
  v_expense_id uuid := gen_random_uuid();
  v_dfo_id uuid := gen_random_uuid();
  v_fp text;
  v_cached jsonb;
  v_post jsonb;
  v_batch_id uuid;
  v_owner_company uuid;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DUE_FROM_OWNER_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if not public.is_company_member(v_company_id, v_actor) then
    raise exception 'DUE_FROM_OWNER_COMPANY_MEMBERSHIP_REQUIRED' using errcode = '42501';
  end if;
  if p_payload ?| array['company_id','owner_agreement','offset_allowed','cash_account','target_account'] then
    raise exception 'DUE_FROM_OWNER_SERVER_OWNED_FIELDS_FORBIDDEN' using errcode = '22023';
  end if;
  if v_request_id is null or v_owner_id is null or v_amount is null or v_amount <= 0 or v_date is null then
    raise exception 'DUE_FROM_OWNER_REQUEST_OWNER_AMOUNT_DATE_REQUIRED' using errcode = '22023';
  end if;
  if v_cash_no not in ('1111','1120') then
    raise exception 'DUE_FROM_OWNER_CASH_ACCOUNT_INVALID' using errcode = '22023';
  end if;

  select o.company_id into v_owner_company
    from public.owners o where o.id = v_owner_id and o.deleted_at is null;
  if v_owner_company is null or v_owner_company <> v_company_id then
    raise exception 'DUE_FROM_OWNER_OWNER_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;

  if v_agreement_id is not null then
    -- The browser names an agreement; the server resolves the authoritative
    -- effective version at the economic date and snapshots its offset authority.
    select av.id, coalesce(av.offset_allowed, false)
      into v_agreement_version_id, v_offset_right
      from public.owner_agreement_versions av
      join public.owner_agreements oa on oa.id = av.owner_agreement_id and oa.company_id = v_company_id
     where av.owner_agreement_id = v_agreement_id
       and av.company_id = v_company_id
       and av.effective_from <= v_date
       and (av.effective_to is null or av.effective_to >= v_date)
     order by av.effective_from desc, av.version_no desc
     limit 1;
    if not found then
      raise exception 'DUE_FROM_OWNER_AGREEMENT_VERSION_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
    end if;
  end if;

  v_fp := encode(sha256(convert_to(jsonb_build_object(
    'owner_id', v_owner_id, 'owner_agreement_id', v_agreement_id, 'property_id', v_property_id,
    'amount', v_amount, 'cash_account_no', v_cash_no, 'effective_date', v_date, 'source_id', v_source_id
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended('due_from_owner_create:' || v_company_id::text || ':' || v_request_id, 0));

  select response_payload into v_cached
    from public.financial_operation_idempotency
   where operation_name = 'create_owner_receivable_atomic:' || v_company_id::text
     and request_id = v_request_id
   for update;
  if v_cached is not null then
    if v_cached->>'_request_fingerprint' is distinct from v_fp or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode = '22023';
    end if;
    return v_cached->'response';
  end if;

  -- Book the owner obligation to 1300 (never 6100) — reuse the canonical kernel.
  v_post := public.gl_pm_post_owner_expense(jsonb_build_object(
    'company_id', v_company_id,
    'expense_id', v_expense_id,
    'amount', v_amount,
    'cash_account_no', v_cash_no,
    'effective_date', v_date
  ));
  v_batch_id := (v_post->'batch'->>'batch_id')::uuid;

  insert into public.due_from_owners (
    id, company_id, owner_id, owner_agreement_id, property_id, source_type, source_id,
    amount, outstanding, lawful_offset_right, request_id, source_fingerprint, created_by, journal_batch_id
  ) values (
    v_dfo_id, v_company_id, v_owner_id, v_agreement_id, v_property_id, 'OWNER_EXPENSE', v_source_id,
    v_amount, v_amount, v_offset_right, v_request_id, v_fp, v_actor, v_batch_id
  );

  v_result := jsonb_build_object(
    'success', true, 'idempotent', false, 'due_from_owner_id', v_dfo_id, 'owner_id', v_owner_id,
    'amount', v_amount, 'outstanding', v_amount, 'lawful_offset_right', v_offset_right,
    'journal_batch_id', v_batch_id, 'status', 'OPEN', 'request_id', v_request_id
  );

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('create_owner_receivable_atomic:' || v_company_id::text, v_request_id,
          jsonb_build_object('_request_fingerprint', v_fp, 'response', v_result));

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_owner_receivable_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_owner_settlement_draft_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_owner_id text := nullif(p_payload->>'owner_id', '');
  v_property_id text := nullif(p_payload->>'property_id', '');
  v_period_start date := nullif(p_payload->>'period_start', '')::date;
  v_period_end date := nullif(p_payload->>'period_end', '')::date;
  v_notes text := nullif(btrim(p_payload->>'notes'), '');
  v_gross numeric;
  v_fee numeric;
  v_expenses numeric;
  v_tax numeric;
  v_net numeric;
  v_id text;
  v_no text;
  v_result jsonb;
  v_cached jsonb;
  v_operation_name text;
  v_target_id text;
  v_request_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target_id text;
  -- FA-003: item sets derived for reservation (payment_id / expense_id units).
  v_payment_ids uuid[];
  v_expense_ids uuid[];
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to create owner settlements.'
      using errcode = '42501';
  end if;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Company context is required (no company_id claim in JWT).'
      using errcode = '42501';
  end if;

  if v_owner_id is null or v_period_start is null or v_period_end is null or v_request_id is null then
    raise exception 'owner_id, period_start, period_end, and request_id are required.'
      using errcode = '22023';
  end if;
  if v_period_start > v_period_end then
    raise exception 'period_start must be on or before period_end.'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.owners o
    where o.id::text = v_owner_id
      and o.company_id = v_company_id
      and o.deleted_at is null
  ) then
    raise exception 'Settlement target owner was not found.'
      using errcode = 'P0002';
  end if;

  if v_property_id is not null and not exists (
    select 1
    from public.properties p
    where p.id::text = v_property_id
      and p.company_id = v_company_id
      and p.deleted_at is null
  ) then
    raise exception 'Settlement target property was not found.'
      using errcode = 'P0002';
  end if;

  v_operation_name := 'create_owner_settlement_draft_atomic:' || v_company_id::text;
  v_target_id := v_owner_id || ':' || coalesce(v_property_id, '*') || ':'
    || v_period_start::text || ':' || v_period_end::text;
  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'owner_id', v_owner_id,
    'property_id', v_property_id,
    'period_start', v_period_start,
    'period_end', v_period_end,
    'notes', v_notes
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_operation_name || ':' || v_request_id, 0)
  );

  select response_payload
    into v_cached
  from public.financial_operation_idempotency
  where operation_name = v_operation_name
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    v_cached_target_id := v_cached->>'_target_id';
    if v_cached_fingerprint is null
       or v_cached_target_id is null
       or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        using errcode = '22023';
    end if;
    if v_cached_fingerprint <> v_request_fingerprint
       or v_cached_target_id <> v_target_id then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode = '22023';
    end if;
    return (v_cached->'response') || jsonb_build_object('idempotent', true);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'owner_settlement:' || v_company_id::text || ':' || v_target_id,
    0
  ));

  if exists (
    select 1
    from public.owner_settlements s
    where s.company_id = v_company_id
      and s.owner_id::text = v_owner_id
      and coalesce(s.property_id::text, '') = coalesce(v_property_id, '')
      and s.period_start = v_period_start
      and s.period_end = v_period_end
      and s.status <> 'CANCELLED'
  ) then
    raise exception 'An active settlement already exists for this owner, property, and period.'
      using errcode = '23505';
  end if;

  -- P1: derive every amount from canonical sources (unchanged).
  select c.gross_collected, c.office_fee, c.owner_expenses, c.tax_amount, c.net_payable
    into v_gross, v_fee, v_expenses, v_tax, v_net
  from public.calculate_owner_net_payout(
    v_owner_id::uuid,
    v_period_start,
    v_period_end,
    v_property_id
  ) as c;

  -- ── FA-003: derive the exact item sets and validate they are free. ─────────
  v_payment_ids := array(
    select public.owner_settlement_reservable_payments(
      v_company_id, v_owner_id::uuid, v_period_start, v_period_end, v_property_id
    )
  );
  v_expense_ids := array(
    select public.owner_settlement_reservable_expenses(
      v_company_id, v_owner_id::uuid, v_period_start, v_period_end, v_property_id
    )
  );

  -- Reject up-front with a clear error when any target item is already actively
  -- reserved (overlapping period or an earlier non-cancelled settlement).
  if exists (
    select 1
      from public.owner_settlement_payment_links l
     where l.company_id = v_company_id
       and l.released_at is null
       and l.payment_id = any(v_payment_ids)
  ) then
    raise exception 'SETTLEMENT_INPUT_ALREADY_RESERVED: one or more payments in this period are already reserved by another active settlement in your company. Cancel that settlement first to reuse them.'
      using errcode = '23505';
  end if;

  if exists (
    select 1
      from public.owner_settlement_expense_links l
     where l.company_id = v_company_id
       and l.released_at is null
       and l.expense_id = any(v_expense_ids)
  ) then
    raise exception 'SETTLEMENT_INPUT_ALREADY_RESERVED: one or more expenses in this period are already reserved by another active settlement in your company. Cancel that settlement first to reuse them.'
      using errcode = '23505';
  end if;

  v_id := gen_random_uuid()::text;
  v_no := 'OST-' || to_char(v_period_end, 'YYYYMM') || '-'
    || upper(substr(replace(v_id, '-', ''), 1, 8));

  insert into public.owner_settlements (
    id, no, owner_id, property_id, date, period_start, period_end,
    gross_collected, office_fee, owner_expenses, tax_amount, net_payable,
    amount, status, request_id, notes, created_at, updated_at, company_id
  ) values (
    v_id, v_no, v_owner_id, v_property_id, v_period_end::text, v_period_start, v_period_end,
    v_gross, v_fee, v_expenses, v_tax, v_net,
    v_net, 'DRAFT', v_request_id::uuid, v_notes, now(), now(), v_company_id
  );

  -- ── FA-003: persist the reservations in the SAME transaction. The partial
  -- unique index is the authoritative concurrency gate: if a truly concurrent
  -- overlapping settlement already reserved any of these items, this insert
  -- violates the unique index and the whole RPC (including the settlement row
  -- just inserted) is rolled back. No partial settlement, no orphan links.
  begin
    insert into public.owner_settlement_payment_links (
      id, company_id, settlement_id, payment_id,
      reserved_at, reserved_by, created_at, updated_at
    )
    select gen_random_uuid(), v_company_id, v_id, t.payment_id,
           now(), auth.uid(), now(), now()
      from unnest(v_payment_ids) as t(payment_id);

    insert into public.owner_settlement_expense_links (
      id, company_id, settlement_id, expense_id,
      reserved_at, reserved_by, created_at, updated_at
    )
    select gen_random_uuid(), v_company_id, v_id, t.expense_id,
           now(), auth.uid(), now(), now()
      from unnest(v_expense_ids) as t(expense_id);
  exception when unique_violation then
    raise exception 'SETTLEMENT_INPUT_ALREADY_RESERVED: a concurrent or earlier settlement already reserved an item in this period.'
      using errcode = '23505';
  end;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'CREATE', 'owner_settlements', v_id,
    'Owner settlement draft created (server-derived amounts, items reserved)',
    'owner_settlements', left(p_payload::text, 4000), now()
  );

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'RESERVE', 'owner_settlement_payment_links', v_id,
    'Reserved ' || coalesce(array_length(v_payment_ids, 1), 0) || ' payment(s) and '
      || coalesce(array_length(v_expense_ids, 1), 0) || ' expense(s)',
    'owner_settlement_payment_links', left(p_payload::text, 4000), now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'settlement_id', v_id,
    'settlement_no', v_no,
    'status', 'DRAFT',
    'net_payable', v_net,
    'amounts_source', 'server_derived',
    'reserved_payments', coalesce(array_length(v_payment_ids, 1), 0),
    'reserved_expenses', coalesce(array_length(v_expense_ids, 1), 0),
    'request_id', v_request_id
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload
  ) values (
    v_operation_name,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_target_id,
      'response', v_result
    )
  )
  on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_owner_settlement_draft_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_owner_settlement_draft_atomic"("p_payload" "jsonb") IS 'FA-003: atomically reserves every derived payment/expense for a settlement; rejects SETTLEMENT_INPUT_ALREADY_RESERVED on any active conflict. Amounts remain server-derived (P1).';



CREATE OR REPLACE FUNCTION "public"."create_property_with_agreement"("p_title" "text", "p_type" "text", "p_address" "text", "p_owner_id" "uuid", "p_agreement_type" "text", "p_commission_type" "text", "p_commission_value" numeric, "p_agreement_starts_on" "date", "p_agreement_ends_on" "date" DEFAULT NULL::"date", "p_owner_name" "text" DEFAULT NULL::"text", "p_purchase_value" numeric DEFAULT NULL::numeric, "p_current_value" numeric DEFAULT NULL::numeric, "p_status" "text" DEFAULT 'active'::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_property_id public.properties.id%type;
  v_agreement_id uuid;
  v_owner_name text;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لإنشاء عقار'
      using errcode = '42501';
  end if;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'سياق الشركة مطلوب لإنشاء العقار'
      using errcode = '42501';
  end if;

  if nullif(btrim(p_title), '') is null
     or nullif(btrim(p_type), '') is null
     or nullif(btrim(p_address), '') is null then
    raise exception 'اسم العقار ونوعه وعنوانه مطلوبة';
  end if;
  if p_agreement_starts_on is null
     or (p_agreement_ends_on is not null and p_agreement_ends_on < p_agreement_starts_on) then
    raise exception 'فترة اتفاقية التشغيل غير صحيحة';
  end if;
  if p_agreement_type not in ('property_management', 'master_lease') then
    raise exception 'نوع اتفاقية التشغيل غير مدعوم';
  end if;
  if p_commission_type not in ('RATE', 'FIXED_MONTHLY') then
    raise exception 'نوع العمولة غير مدعوم';
  end if;
  if p_commission_type = 'RATE' and (p_commission_value < 0 or p_commission_value > 100) then
    raise exception 'نسبة العمولة يجب أن تكون بين 0 و100 عند نوع RATE';
  end if;
  if p_commission_type = 'FIXED_MONTHLY' and p_commission_value < 0 then
    raise exception 'قيمة العمولة الثابتة لا يمكن أن تكون سالبة';
  end if;

  -- The relationship is the source of truth. The legacy p_owner_name input
  -- remains only for client signature compatibility and is never trusted.
  select coalesce(nullif(btrim(o.display_name), ''), nullif(btrim(o.full_name), ''), o.name)
    into v_owner_name
  from public.owners o
  where o.id = p_owner_id
    and o.company_id = v_company_id
    and o.deleted_at is null
    and o.is_active;

  if not found then
    raise exception 'المالك غير موجود في شركتك أو غير نشط أو مؤرشف'
      using errcode = '23514';
  end if;

  insert into public.properties (
    name, title, type, address, owner_id, owner_name, purchase_value,
    current_value, status, notes, company_id
  ) values (
    btrim(p_title), btrim(p_title), btrim(p_type), btrim(p_address),
    p_owner_id, v_owner_name, p_purchase_value, p_current_value,
    p_status, p_notes, v_company_id
  )
  returning id into v_property_id;

  insert into public.property_owners (
    property_id, owner_id, ownership_percentage, is_primary,
    starts_on, ends_on, company_id
  ) values (
    v_property_id, p_owner_id, 100, true,
    p_agreement_starts_on, p_agreement_ends_on, v_company_id
  );

  insert into public.owner_agreements (
    owner_id, property_id, agreement_type, commission_type,
    commission_value, starts_on, ends_on, company_id
  ) values (
    p_owner_id, v_property_id, p_agreement_type, p_commission_type,
    p_commission_value, p_agreement_starts_on, p_agreement_ends_on, v_company_id
  )
  returning id into v_agreement_id;

  return jsonb_build_object('property_id', v_property_id, 'agreement_id', v_agreement_id);
end;
$$;


ALTER FUNCTION "public"."create_property_with_agreement"("p_title" "text", "p_type" "text", "p_address" "text", "p_owner_id" "uuid", "p_agreement_type" "text", "p_commission_type" "text", "p_commission_value" numeric, "p_agreement_starts_on" "date", "p_agreement_ends_on" "date", "p_owner_name" "text", "p_purchase_value" numeric, "p_current_value" numeric, "p_status" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_property_with_versioned_agreement_atomic"("p_title" "text", "p_type" "text", "p_address" "text", "p_owner_id" "uuid", "p_agreement_type" "text", "p_commission_type" "text", "p_commission_value" numeric, "p_agreement_starts_on" "date", "p_agreement_ends_on" "date" DEFAULT NULL::"date", "p_owner_name" "text" DEFAULT NULL::"text", "p_purchase_value" numeric DEFAULT NULL::numeric, "p_current_value" numeric DEFAULT NULL::numeric, "p_status" "text" DEFAULT 'active'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_collection_role" "text" DEFAULT 'OWNER_IS_CREDITOR'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_result jsonb;
  v_version jsonb;
begin
  if p_agreement_type <> 'property_management' then
    raise exception 'MASTER_LEASE_EXCLUDED_FROM_RC1' using errcode = '0A000';
  end if;

  select public.create_property_with_agreement(
    p_title, p_type, p_address, p_owner_id, p_agreement_type,
    p_commission_type, p_commission_value, p_agreement_starts_on,
    p_agreement_ends_on, p_owner_name, p_purchase_value, p_current_value,
    p_status, p_notes
  ) into v_result;

  execute 'select to_jsonb(public.create_owner_agreement_version_atomic($1,$2))'
    into v_version
    using
      (v_result->>'agreement_id')::uuid,
      jsonb_build_object(
        'operating_model', 'OWNER_AGENCY',
        'collection_role', p_collection_role,
        'commission_type', p_commission_type,
        'commission_value', p_commission_value,
        'effective_from', p_agreement_starts_on,
        'effective_to', p_agreement_ends_on,
        'notes', p_notes
      );

  if v_version->>'id' is null then
    raise exception 'OWNER_AGREEMENT_INITIAL_VERSION_REQUIRED' using errcode = '23514';
  end if;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."create_property_with_versioned_agreement_atomic"("p_title" "text", "p_type" "text", "p_address" "text", "p_owner_id" "uuid", "p_agreement_type" "text", "p_commission_type" "text", "p_commission_value" numeric, "p_agreement_starts_on" "date", "p_agreement_ends_on" "date", "p_owner_name" "text", "p_purchase_value" numeric, "p_current_value" numeric, "p_status" "text", "p_notes" "text", "p_collection_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_property_with_versioned_agreement_atomic"("p_title" "text", "p_type" "text", "p_address" "text", "p_owner_id" "uuid", "p_agreement_type" "text", "p_commission_type" "text", "p_commission_value" numeric, "p_agreement_starts_on" "date", "p_agreement_ends_on" "date", "p_owner_name" "text", "p_purchase_value" numeric, "p_current_value" numeric, "p_status" "text", "p_notes" "text", "p_collection_role" "text") IS 'GAP-004: atomically creates a property, ownership, RC1 owner-agency identity and first commercial version.';



CREATE OR REPLACE FUNCTION "public"."create_tax_profile_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_code text := nullif(btrim(coalesce(p_payload->>'tax_code','')), '');
  v_rate numeric := public.gl_pm_round_omr(nullif(p_payload->>'tax_rate','')::numeric);
  v_from date := nullif(p_payload->>'effective_from','')::date;
  v_to date := nullif(p_payload->>'effective_to','')::date;
  v_desc text := nullif(btrim(coalesce(p_payload->>'description','')), '');
  v_version integer;
  v_id uuid := gen_random_uuid();
  v_cached jsonb;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'TAX_PROFILE_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if p_payload ?| array['company_id','tax_rate_override','default_rate'] then
    raise exception 'TAX_PROFILE_SERVER_OWNED_FIELDS_FORBIDDEN' using errcode = '22023';
  end if;
  if v_request_id is null or v_code is null or v_rate is null or v_rate < 0 or v_rate > 100 or v_from is null then
    raise exception 'TAX_PROFILE_REQUEST_CODE_RATE_FROM_REQUIRED' using errcode = '22023';
  end if;
  if v_to is not null and v_to < v_from then
    raise exception 'TAX_PROFILE_DATE_RANGE_INVALID' using errcode = '22023';
  end if;
  if not exists (select 1 from public.tax_code_catalog where code = v_code and is_active) then
    raise exception 'TAX_PROFILE_CODE_UNKNOWN' using errcode = '23514';
  end if;

  select coalesce(max(version_no), 0) + 1 into v_version
    from public.company_tax_profiles where company_id = v_company_id;

  select response_payload into v_cached
    from public.financial_operation_idempotency
   where operation_name = 'create_tax_profile_atomic:' || v_company_id::text
     and request_id = v_request_id;
  if v_cached is not null then
    return v_cached || jsonb_build_object('idempotent', true);
  end if;

  insert into public.company_tax_profiles (
    id, company_id, version_no, tax_code, tax_rate, effective_from, effective_to,
    status, description, created_by
  ) values (
    v_id, v_company_id, v_version, v_code, v_rate, v_from, v_to, 'DRAFT', v_desc, v_actor
  );

  v_result := jsonb_build_object(
    'success', true, 'idempotent', false, 'profile_id', v_id, 'company_id', v_company_id,
    'version_no', v_version, 'tax_code', v_code, 'tax_rate', v_rate, 'status', 'DRAFT', 'request_id', v_request_id
  );
  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('create_tax_profile_atomic:' || v_company_id::text, v_request_id, v_result)
  on conflict (operation_name, request_id) do nothing;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_tax_profile_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_app_role"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (
      select u.role::text
      from public.users u
      where u.id = auth.uid()
        and u.deleted_at is null
        and u.is_active
        and u.status::text = 'ACTIVE'
    ),
    'USER'::text
  );
$$;


ALTER FUNCTION "public"."current_app_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_user_can_delegate_app_permission"("p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ select public.is_admin() or public.current_user_has_effective_app_permission(p_permission) $$;


ALTER FUNCTION "public"."current_user_can_delegate_app_permission"("p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_user_has_effective_app_permission"("p_permission" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_company uuid := public.require_company_id();
begin
  if public.is_admin() then return true; end if;
  return public.role_has_app_permission(public.current_app_role(), p_permission)
    or exists (
      select 1 from public.user_permission_grants g
      where g.company_id = v_company and g.user_id = auth.uid()
        and g.permission = p_permission and g.revoked_at is null
    );
end;
$$;


ALTER FUNCTION "public"."current_user_has_effective_app_permission"("p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."custom_access_token_hook"("event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claims jsonb;
  user_role text;
  requested_company_id uuid;
  user_company uuid;
  user_metadata jsonb;
begin
  select u.role::text
    into user_role
    from public.users u
   where u.id = (event->>'user_id')::uuid
     and u.status = 'ACTIVE';

  select au.raw_user_meta_data
    into user_metadata
    from auth.users au
   where au.id = (event->>'user_id')::uuid;

  begin
    requested_company_id := nullif(user_metadata->>'company_id', '')::uuid;
  exception
    when invalid_text_representation then
      requested_company_id := null;
  end;

  -- A user-controlled preference becomes authoritative only after active
  -- membership + active-company validation. This prevents selecting another
  -- tenant by editing metadata and prevents disabled access from surviving.
  if requested_company_id is not null then
    select cm.company_id
      into user_company
      from public.company_members cm
      join public.companies c on c.id = cm.company_id
     where cm.user_id = (event->>'user_id')::uuid
       and cm.company_id = requested_company_id
       and cm.is_active
       and c.is_active
     limit 1;
  end if;

  -- Deterministic fallback for first sign-in / removed or invalid preference.
  if user_company is null then
    select cm.company_id
      into user_company
      from public.company_members cm
      join public.companies c on c.id = cm.company_id
     where cm.user_id = (event->>'user_id')::uuid
       and cm.is_active
       and c.is_active
     order by cm.created_at, cm.id
     limit 1;
  end if;

  claims := event -> 'claims';
  if jsonb_typeof(claims -> 'app_metadata') is null then
    claims := jsonb_set(claims, '{app_metadata}', '{}');
  end if;

  claims := jsonb_set(
    claims,
    '{app_metadata,user_role}',
    to_jsonb(coalesce(user_role, 'USER'))
  );

  if user_company is not null then
    claims := jsonb_set(
      claims,
      '{app_metadata,company_id}',
      to_jsonb(user_company)
    );
  else
    -- Never preserve a stale company claim when the user has no active access.
    claims := claims #- '{app_metadata,company_id}';
  end if;

  return jsonb_set(event, '{claims}', claims);
end;
$$;


ALTER FUNCTION "public"."custom_access_token_hook"("event" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_contract_registration_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_company uuid:=public.require_company_id();
  v_record public.contract_registration_records%rowtype; v_action text:=upper(p_payload->>'action');
  v_request text:=nullif(btrim(p_payload->>'request_id'),''); v_doc uuid:=nullif(p_payload->>'evidence_document_id','')::uuid;
  v_old text;
begin
  if v_actor is null or not public.contract_evidence_actor_can_verify() then raise exception 'CONTRACT_EVIDENCE_VERIFY_FORBIDDEN' using errcode='42501'; end if;
  select * into v_record from public.contract_registration_records
   where id=nullif(p_payload->>'registration_id','')::uuid and company_id=v_company for update;
  if not found then raise exception 'CONTRACT_REGISTRATION_NOT_FOUND' using errcode='42501'; end if;
  if v_record.decision_request_id=v_request then return to_jsonb(v_record); end if;
  if v_record.status<>'SUBMITTED' or v_request is null then raise exception 'CONTRACT_REGISTRATION_NOT_DECIDABLE' using errcode='22023'; end if;
  if v_record.submitted_by=v_actor then raise exception 'CONTRACT_REGISTRATION_SELF_VERIFICATION_FORBIDDEN' using errcode='42501'; end if;
  v_old:=v_record.status;
  if v_action='REGISTER' then
    if nullif(btrim(p_payload->>'registration_reference'),'') is null or nullif(p_payload->>'registered_on','') is null or v_doc is null then
      raise exception 'CONTRACT_REGISTRATION_EVIDENCE_REQUIRED' using errcode='22023';
    end if;
    perform public.contract_evidence_assert_documents(v_company,v_record.contract_id,array[v_doc]);
    update public.contract_registration_records set status='REGISTERED',registration_reference=btrim(p_payload->>'registration_reference'),
      registered_on=(p_payload->>'registered_on')::date,expires_on=nullif(p_payload->>'expires_on','')::date,
      fee_paid=nullif(p_payload->>'fee_paid','')::numeric,evidence_document_id=v_doc,decision_request_id=v_request,
      decided_by=v_actor,decided_at=now(),updated_at=now() where id=v_record.id returning * into v_record;
  elsif v_action='REJECT' then
    if nullif(btrim(p_payload->>'reason'),'') is null then raise exception 'CONTRACT_REGISTRATION_REJECTION_REASON_REQUIRED' using errcode='22023'; end if;
    update public.contract_registration_records set status='REJECTED',decision_reason=btrim(p_payload->>'reason'),
      decision_request_id=v_request,decided_by=v_actor,decided_at=now(),updated_at=now()
      where id=v_record.id returning * into v_record;
  else raise exception 'CONTRACT_REGISTRATION_ACTION_INVALID' using errcode='22023'; end if;
  insert into public.contract_evidence_events(company_id,contract_id,entity_type,entity_id,event_type,from_status,to_status,reason,payload,actor_id)
    values(v_company,v_record.contract_id,'REGISTRATION',v_record.id,v_action,v_old,v_record.status,v_record.decision_reason,jsonb_build_object('request_id',v_request),v_actor);
  return to_jsonb(v_record);
end;
$$;


ALTER FUNCTION "public"."decide_contract_registration_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."permission_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "requester_user_id" "uuid" NOT NULL,
    "permission" "text" NOT NULL,
    "resource_route" "text",
    "reason" "text" DEFAULT ''::"text" NOT NULL,
    "status" "text" DEFAULT 'PENDING'::"text" NOT NULL,
    "reviewer_user_id" "uuid",
    "decided_at" timestamp with time zone,
    "decision_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "permission_requests_status_check" CHECK (("status" = ANY (ARRAY['PENDING'::"text", 'APPROVED'::"text", 'REJECTED'::"text"])))
);


ALTER TABLE "public"."permission_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_permission_request"("p_request_id" "uuid", "p_decision" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."permission_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_company uuid := public.require_company_id(); v_decision text := upper(btrim(coalesce(p_decision, ''))); result public.permission_requests; v_admin_only boolean;
begin
  if not public.current_user_has_effective_app_permission('permission_requests.review') then raise exception 'Permission request review required' using errcode = '42501'; end if;
  if v_decision not in ('APPROVED','REJECTED') then raise exception 'Invalid decision' using errcode = '22023'; end if;
  if v_decision = 'REJECTED' and nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception 'Rejection reason is required' using errcode = '22023'; end if;
  select * into result from public.permission_requests pr where pr.id=p_request_id and pr.company_id=v_company for update;
  if result.id is null then raise exception 'Permission request not found' using errcode = 'P0002'; end if;
  if result.requester_user_id = auth.uid() then raise exception 'Requester cannot review own request' using errcode = '42501'; end if;
  if result.status <> 'PENDING' then if result.status = v_decision then return result; end if; raise exception 'Permission request already decided' using errcode = '23505'; end if;
  if v_decision = 'APPROVED' and not public.current_user_can_delegate_app_permission(result.permission) then
    select admin_only into v_admin_only from public.app_permission_catalog where permission=result.permission;
    if v_admin_only then raise exception 'Manager cannot grant an admin-only permission' using errcode = '42501'; end if;
    raise exception 'Reviewer cannot grant this permission' using errcode = '42501';
  end if;
  update public.permission_requests set status=v_decision, reviewer_user_id=auth.uid(), decided_at=now(), decision_reason=nullif(btrim(coalesce(p_reason,'')),''), updated_at=now() where id=result.id returning * into result;
  if result.status='APPROVED' then insert into public.user_permission_grants(company_id,user_id,permission,granted_by) values(result.company_id,result.requester_user_id,result.permission,auth.uid()) on conflict(company_id,user_id,permission) do update set revoked_at=null, granted_by=excluded.granted_by, granted_at=now(); end if;
  insert into public.app_notifications(id,company_id,recipient_user_id,created_at,is_read,role,type,title,message,link,source_type,source_id,notification_type)
  values(result.id::text||':'||result.requester_user_id::text||':decision',result.company_id,result.requester_user_id,now(),false,null,'permission_decision',case when result.status='APPROVED' then 'تمت الموافقة على طلب الصلاحية' else 'تم رفض طلب الصلاحية' end,coalesce(result.decision_reason,'تم اتخاذ قرار بشأن الطلب.'),coalesce(result.resource_route,'/dashboard'),'permission_request',result.id,'permission_decision') on conflict(id) do nothing;
  insert into public.audit_log(id,ts,user_id,action,entity,entity_id,note,"table",details,created_at)
  select gen_random_uuid(),extract(epoch from now())::bigint,auth.uid(),'PERMISSION_'||result.status,'permission_request',result.id::text,coalesce(result.decision_reason,'تم اتخاذ قرار بشأن طلب الصلاحية'),'permission_requests',jsonb_build_object('requester_user_id',result.requester_user_id,'permission',result.permission,'resource_route',result.resource_route)::text,now()
  where not exists(select 1 from public.audit_log a where a.action='PERMISSION_'||result.status and a.entity_id=result.id::text);
  return result;
end;
$$;


ALTER FUNCTION "public"."decide_permission_request"("p_request_id" "uuid", "p_decision" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deduct_deposit_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_deposit_id text := nullif(p_payload->>'deposit_id', '');
  v_payload_property_id text := nullif(p_payload->>'property_id', '');
  v_deposit_property_id text;
  v_cached jsonb;
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role required' using errcode = '42501';
  end if;
  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Active company is required.' using errcode = '42501';
  end if;
  if v_request_id is not null then
    select response_payload into v_cached
    from public.financial_operation_idempotency
    where operation_name = 'deduct_deposit_atomic:' || v_company_id::text
      and request_id = v_request_id;
    if v_cached is not null then
      return v_cached || jsonb_build_object('idempotent', true);
    end if;
  end if;
  if v_deposit_id is null then
    raise exception 'deposit_id required' using errcode = '22023';
  end if;
  select td.property_id::text into v_deposit_property_id
  from public.tenant_deposits td
  where td.id::text = v_deposit_id
    and td.company_id = v_company_id
    and td.deleted_at is null
  for share;
  if not found then
    raise exception 'Deposit not found in current company.' using errcode = '42501';
  end if;
  if v_payload_property_id is not null and v_payload_property_id <> v_deposit_property_id then
    raise exception 'Deposit property does not match canonical deposit property.' using errcode = '22023';
  end if;

  v_payload := jsonb_set(v_payload, '{property_id}', to_jsonb(v_deposit_property_id), true);
  if nullif(v_payload->>'reason', '') = 'damage' then
    v_payload := jsonb_set(v_payload, '{reason}', to_jsonb('maintenance_damage'::text), true);
  end if;

  return public.deduct_deposit_atomic_phase3a1a_impl(v_payload);
end;
$$;


ALTER FUNCTION "public"."deduct_deposit_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deduct_deposit_atomic_phase3a1a_impl"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id','');
  v_deposit_id text := nullif(p_payload->>'deposit_id','');
  v_amount numeric := nullif(p_payload->>'amount','')::numeric;
  v_reason text := nullif(p_payload->>'reason','');
  v_description text := nullif(p_payload->>'description','');
  v_charged_date date := nullif(p_payload->>'charged_date','')::date;
  v_property_id_raw text := nullif(p_payload->>'property_id','');
  v_deposit record;
  v_cached jsonb;
  v_result jsonb;
  v_expense_account_id text;
  v_deposit_account_id text;
  v_expense_id uuid;
  v_expense_property_id_type text;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role required' using errcode='42501';
  end if;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;

  if v_request_id is null then v_request_id := gen_random_uuid()::text; end if;
  select response_payload into v_cached from public.financial_operation_idempotency where operation_name='deduct_deposit_atomic'||':'||v_company_id::text and request_id=v_request_id;
  if v_cached is not null then return v_cached || jsonb_build_object('idempotent', true); end if;

  if v_deposit_id is null then raise exception 'deposit_id required'; end if;
  if v_amount is null or v_amount <=0 then raise exception 'amount >0 required'; end if;
  if v_reason is null then v_reason := 'other'; end if;
  if v_charged_date is null then v_charged_date := current_date; end if;

  perform pg_advisory_xact_lock(hashtextextended('deduct_deposit:'||v_deposit_id,0));

  select * into v_deposit from public.tenant_deposits where id=v_deposit_id and deleted_at is null   AND company_id = v_company_id
for update;
  if not found then raise exception 'Deposit not found'; end if;

  if v_amount > v_deposit.remaining_amount then
    raise exception 'Insufficient deposit balance: remaining % requested %', v_deposit.remaining_amount, v_amount;
  end if;

  update public.tenant_deposits
  set deducted_amount = deducted_amount + v_amount,
      remaining_amount = deposit_amount - (deducted_amount + v_amount) - refunded_amount,
      status = case 
        when (deposit_amount - (deducted_amount + v_amount) - refunded_amount) <=0 then 'forfeited_damage'
        when (deducted_amount + v_amount) >0 and refunded_amount =0 then 'partially_deducted'
        when refunded_amount >0 then 'partially_refunded'
        else 'held'
      end,
      updated_at = now()
  where id=v_deposit_id;

  insert into public.deposit_transactions (deposit_id, type, amount, reason, description, request_id, company_id)
  values (v_deposit_id, 'deduction', v_amount, v_reason, v_description, v_request_id, v_company_id);

  v_expense_account_id := public.ensure_company_account(v_company_id, '6100', 'Operating Expenses');
  v_deposit_account_id := public.ensure_company_account(v_company_id, '2200', 'Tenant Deposits Payable');

  if v_deposit_account_id is not null and v_expense_account_id is not null then
    SELECT format_type(a.atttypid, a.atttypmod) INTO v_expense_property_id_type
    FROM pg_attribute a
    JOIN pg_class c ON c.oid = a.attrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname='public' AND c.relname='expenses' AND a.attname='property_id' AND a.attnum>0 AND NOT a.attisdropped;

    IF v_expense_property_id_type IS NULL THEN
      RAISE EXCEPTION 'expenses.property_id type not found';
    END IF;

    v_expense_id := gen_random_uuid();
    EXECUTE format(
      'insert into public.expenses
        (id, property_id, category, amount, expense_date, description, status, no, company_id)
       values ($1, $2::%s, $3, $4, $5, $6, $7, $8, $9)',
      v_expense_property_id_type
    )
    USING v_expense_id,
          coalesce(v_property_id_raw, v_deposit.property_id::text),
          'صيانة من تأمين',
          v_amount,
          v_charged_date,
          'خصم تأمين: '||coalesce(v_description,''),
          'POSTED',
          'EXP-DEP-'||substr(v_deposit_id,1,6),
          v_company_id;

    insert into public.journal_entries (id, no, date, account_id, amount, type, source_id, entity_type, entity_id, company_id)
    values
      (gen_random_uuid(), 'DEP-DED-'||substr(v_deposit_id,1,6)||'-D', v_charged_date, v_deposit_account_id, v_amount, 'DEBIT', v_deposit_id, 'deposit_deduction', v_deposit_id, v_company_id),
      (gen_random_uuid(), 'DEP-DED-'||substr(v_deposit_id,1,6)||'-C', v_charged_date, v_expense_account_id, v_amount, 'CREDIT', v_deposit_id, 'deposit_deduction', v_deposit_id, v_company_id);
  end if;

  v_result := jsonb_build_object('success',true,'deposit_id',v_deposit_id,'deducted',v_amount,'remaining', v_deposit.remaining_amount - v_amount,'request_id',v_request_id, 'new_status', (case when (v_deposit.deposit_amount - (v_deposit.deducted_amount + v_amount) - v_deposit.refunded_amount) <=0 then 'forfeited_damage' else 'partially_deducted' end));

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('deduct_deposit_atomic'||':'||v_company_id::text, v_request_id, v_result) on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."deduct_deposit_atomic_phase3a1a_impl"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."diagnose_owner_settlement_duplication"() RETURNS TABLE("company_id" "uuid", "finding_type" "text", "subject" "text", "detail" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
begin
  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'Company context is required (no company_id claim in JWT).'
      using errcode = '42501';
  end if;

  -- payment present in >1 non-cancelled settlement
  return query
  with ps as (
    select s.id::text as settlement_id, p.id::text as payment_id
      from public.owner_settlements s
      cross join lateral public.owner_settlement_reservable_payments(
        v_company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
      ) as p(id)
     where s.company_id = v_company_id and s.status <> 'CANCELLED'
  )
  select v_company_id, 'payment_in_multiple_settlements'::text,
         payment_id,
         jsonb_build_object('settlements', jsonb_agg(settlement_id))
    from ps
   group by payment_id
  having count(*) > 1;

  return query
  with es as (
    select s.id::text as settlement_id, e.id::text as expense_id
      from public.owner_settlements s
      cross join lateral public.owner_settlement_reservable_expenses(
        v_company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
      ) as e(id)
     where s.company_id = v_company_id and s.status <> 'CANCELLED'
  )
  select v_company_id, 'expense_in_multiple_settlements'::text,
         expense_id,
         jsonb_build_object('settlements', jsonb_agg(settlement_id))
    from es
   group by expense_id
  having count(*) > 1;

  -- overlapping active settlements for same owner/property
  return query
  select v_company_id, 'overlapping_settlements'::text,
         s1.id::text,
         jsonb_build_object(
           'owner_id', s1.owner_id,
           'property_id', s1.property_id,
           'settlement_a', s1.id, 'period_a', jsonb_build_array(s1.period_start, s1.period_end),
           'settlement_b', s2.id, 'period_b', jsonb_build_array(s2.period_start, s2.period_end),
           'status_a', s1.status, 'status_b', s2.status
         )
    from public.owner_settlements s1
    join public.owner_settlements s2
      on s2.company_id = s1.company_id
     and s2.id <> s1.id
     and s2.owner_id = s1.owner_id
     and coalesce(s2.property_id::text, '') = coalesce(s1.property_id::text, '')
     and s2.status <> 'CANCELLED'
     and s1.period_start <= s2.period_end
     and s2.period_start <= s1.period_end
   where s1.company_id = v_company_id
     and s1.status <> 'CANCELLED';

  -- amount mismatch: stored expenses vs derived; stored gross vs derived
  -- payment gross (only when the settlement actually has reservable payments,
  -- so master-lease obligation-only settlements are not false-flagged).
  return query
  select v_company_id, 'amount_mismatch'::text,
         s.id::text,
         jsonb_build_object(
           'stored_gross', s.gross_collected,
           'derived_payment_gross', coalesce((
             select sum(p.amount)
               from public.owner_settlement_reservable_payments(
                 v_company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
               ) as pid
               join public.payments p on p.id = pid
           ), 0),
           'stored_expenses', s.owner_expenses,
           'derived_expenses', coalesce((
             select sum(e.amount)
               from public.owner_settlement_reservable_expenses(
                 v_company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
               ) as eid
               join public.expenses e on e.id = eid
           ), 0)
         )
    from public.owner_settlements s
   where s.company_id = v_company_id
     and s.status <> 'CANCELLED'
     and (
       abs(s.owner_expenses - coalesce((
         select sum(e.amount)
           from public.owner_settlement_reservable_expenses(
             v_company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
           ) as eid
           join public.expenses e on e.id = eid
       ), 0)) > 0.001
       or (
         exists (select 1 from public.owner_settlement_reservable_payments(
           v_company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text))
         and abs(s.gross_collected - coalesce((
           select sum(p.amount)
             from public.owner_settlement_reservable_payments(
               v_company_id, s.owner_id::uuid, s.period_start, s.period_end, s.property_id::text
             ) as pid
             join public.payments p on p.id = pid
         ), 0)) > 0.001
       )
     );

  -- settlements that cannot be attributed deterministically (missing period)
  return query
  select v_company_id, 'indeterminate_items'::text,
         s.id::text,
         jsonb_build_object('period_start', s.period_start, 'period_end', s.period_end)
    from public.owner_settlements s
   where s.company_id = v_company_id
     and s.status <> 'CANCELLED'
     and (s.period_start is null or s.period_end is null);
end;
$$;


ALTER FUNCTION "public"."diagnose_owner_settlement_duplication"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."diagnose_owner_settlement_duplication"() IS 'FA-003: read-only, company-scoped diagnostic over historical settlements. Returns only the caller company rows; never mutates data.';



CREATE OR REPLACE FUNCTION "public"."enforce_app_permission_catalog"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from public.app_permission_catalog c where c.permission = new.permission) then
    raise exception 'Unknown permission' using errcode = '22023';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_app_permission_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_contract_workflow_invariants"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_start_date date;
  v_end_date date;
begin
  if new.deleted_at is not null then
    return new;
  end if;

  if new.company_id is null then
    raise exception 'Company context is required for contract records.'
      using errcode = '23514';
  end if;

  if nullif(btrim(new.start_date::text), '') is null
     or btrim(new.start_date::text) !~ '^\d{4}-\d{2}-\d{2}$'
     or nullif(btrim(new.end_date::text), '') is null
     or btrim(new.end_date::text) !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception 'Contract dates must use YYYY-MM-DD.'
      using errcode = '22007';
  end if;

  v_start_date := btrim(new.start_date::text)::date;
  v_end_date := btrim(new.end_date::text)::date;

  if v_end_date <= v_start_date then
    raise exception 'Contract end date must be after its start date.'
      using errcode = '23514';
  end if;

  if lower(coalesce(new.status, '')) not in ('draft', 'active', 'expired', 'terminated', 'ended') then
    raise exception 'Unsupported contract status: %', new.status
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.properties p
    where p.id::text = new.property_id::text
      and p.company_id = new.company_id
      and p.deleted_at is null
      and (
        lower(new.status) not in ('active', 'draft')
        or lower(p.status) = 'active'
      )
  ) then
    raise exception 'Contract property must be live, company-owned, and active for operational contracts.'
      using errcode = '23514';
  end if;

  if lower(new.status) in ('active', 'draft') then
    if new.unit_id is null or not exists (
      select 1
      from public.units u
      where u.id::text = new.unit_id::text
        and u.property_id::text = new.property_id::text
        and u.company_id = new.company_id
        and u.deleted_at is null
    ) then
      raise exception 'Contract unit must belong to the selected property and company.'
        using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.people person_record
      where person_record.id::text = new.tenant_id::text
        and person_record.company_id = new.company_id
        and person_record.deleted_at is null
        and person_record.type = 'tenant'
    ) then
      raise exception 'Contract tenant must be a live tenant in the same company.'
        using errcode = '23514';
    end if;
  end if;

  if lower(new.status) in ('active', 'draft') and (
    new.agreement_id is null
    or not exists (
      select 1
      from public.owner_agreements agreement_record
      join public.owners owner_record
        on owner_record.id = agreement_record.owner_id
       and owner_record.company_id = new.company_id
       and owner_record.deleted_at is null
       and owner_record.is_active
      where agreement_record.id = new.agreement_id
        and agreement_record.property_id::text = new.property_id::text
        and agreement_record.starts_on <= v_start_date
        and (agreement_record.ends_on is null or agreement_record.ends_on >= v_end_date)
    )
  ) then
    raise exception 'Operational contract requires a covering agreement with an active owner in the same company.'
      using errcode = '23514';
  end if;

  return new;
end;
$_$;


ALTER FUNCTION "public"."enforce_contract_workflow_invariants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_owner_settlement_amount_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.gross_collected is distinct from old.gross_collected
     or new.office_fee is distinct from old.office_fee
     or new.owner_expenses is distinct from old.owner_expenses
     or new.tax_amount is distinct from old.tax_amount
     or new.net_payable is distinct from old.net_payable then
    raise exception 'Owner settlement amounts are server-derived and immutable; create a corrected settlement instead.'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_owner_settlement_amount_immutability"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_owner_settlement_amount_immutability"() IS 'P1: settlement amounts come only from calculate_owner_net_payout at insert time; no UPDATE may change them.';



CREATE OR REPLACE FUNCTION "public"."enforce_owner_settlement_link_company_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_settlement_company uuid;
  v_item_company uuid;
begin
  select s.company_id into v_settlement_company
    from public.owner_settlements s
   where s.id = NEW.settlement_id;
  if v_settlement_company is null or v_settlement_company is distinct from NEW.company_id then
    raise exception 'OWNER_SETTLEMENT_LINK_COMPANY_MISMATCH'
      using errcode = 'P0001';
  end if;

  if TG_TABLE_NAME = 'owner_settlement_payment_links' then
    select p.company_id into v_item_company
      from public.payments p
     where p.id = NEW.payment_id;
  else
    select e.company_id into v_item_company
      from public.expenses e
     where e.id = NEW.expense_id;
  end if;
  if v_item_company is null or v_item_company is distinct from NEW.company_id then
    raise exception 'OWNER_SETTLEMENT_LINK_COMPANY_MISMATCH'
      using errcode = 'P0001';
  end if;

  return NEW;
end;
$$;


ALTER FUNCTION "public"."enforce_owner_settlement_link_company_consistency"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_owner_settlement_link_company_consistency"() IS 'FA-003: prevents any owner-settlement link whose settlement or item belongs to a company different from the link company_id, independent of RLS.';



CREATE OR REPLACE FUNCTION "public"."enforce_payment_receipt_shared_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.receipt_id is null then
    raise exception 'payments.receipt_id is required: every payment must be backed by one receipt'
      using errcode = '23502';
  end if;

  -- `id` normally has a generated default. Replace it at the write boundary so
  -- all RPC variants converge on one immutable identity.
  new.id := new.receipt_id;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_payment_receipt_shared_identity"() OWNER TO "postgres";


