CREATE OR REPLACE FUNCTION "public"."execute_automation_rule"("p_rule_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rule record;
  v_run_id uuid;
  v_items_processed int := 0;
  v_items_failed int := 0;
  v_result jsonb;
  v_contract record;
  v_invoice record;
  v_maint record;
  v_notif_count int := 0;
  v_error_msg text;
  v_company_id uuid;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER required' using errcode = '42501';
  end if;

  -- Derive company from JWT (set by custom_access_token_hook)
  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;

  -- Load rule — must belong to the caller's company; treat cross-company as not found
  select * into v_rule
  from public.automation_rules
  where id = p_rule_id
    and deleted_at is null
    and company_id = v_company_id
  for update;

  if not found then
    raise exception 'Rule not found';
  end if;

  if not v_rule.is_enabled then
    raise exception 'Rule is disabled';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('automation_rule:' || p_rule_id, 0));

  if exists (
    select 1 from public.automation_runs
    where rule_id = p_rule_id
      and status = 'running'
      and started_at > extract(epoch from (now() - interval '5 minutes')) * 1000
  ) then
    return jsonb_build_object('success', false, 'skipped', true, 'reason', 'duplicate running execution prevented');
  end if;

  insert into public.automation_runs (job_name, rule_id, status, started_at, retry_count, company_id)
  values (v_rule.name, v_rule.id, 'running', extract(epoch from now()) * 1000, 0, v_company_id)
  returning id into v_run_id;

  begin
    if v_rule.rule_type = 'contract_expiry' then
      for v_contract in
        select id, property_id, tenant_id, end_date
        from public.contracts
        where deleted_at is null
          and status = 'active'
          and company_id = v_company_id
          and public._safe_date(end_date) between current_date and current_date + interval '30 days'
        limit 100
      loop
        insert into public.automation_notifications
          (rule_id, run_id, type, title, body, related_entity_type, related_entity_id, company_id)
        values (
          v_rule.id, v_run_id, 'contract_expiry',
          'عقد قريب من الانتهاء',
          'العقد ' || v_contract.id || ' ينتهي في ' || coalesce(v_contract.end_date, '?'),
          'contract', v_contract.id::text, v_company_id
        );
        v_items_processed := v_items_processed + 1;
        v_notif_count := v_notif_count + 1;
      end loop;

    elsif v_rule.rule_type = 'overdue_invoice' then
      for v_invoice in
        select id, contract_id, due_date, amount, paid_amount
        from public.invoices
        where deleted_at is null
          and status not in ('paid', 'cancelled', 'void')
          and company_id = v_company_id
          and public._safe_date(due_date) < current_date
          and (amount - coalesce(paid_amount, 0)) > 0
        limit 100
      loop
        insert into public.automation_notifications
          (rule_id, run_id, type, title, body, related_entity_type, related_entity_id, company_id)
        values (
          v_rule.id, v_run_id, 'overdue_invoice',
          'فاتورة متأخرة',
          'الفاتورة ' || v_invoice.id || ' متأخرة منذ ' || coalesce(v_invoice.due_date, '?')
            || ' بمبلغ ' || (v_invoice.amount - coalesce(v_invoice.paid_amount, 0)),
          'invoice', v_invoice.id::text, v_company_id
        );
        v_items_processed := v_items_processed + 1;
        v_notif_count := v_notif_count + 1;
      end loop;

    elsif v_rule.rule_type = 'maintenance_overdue' then
      for v_maint in
        select id, property_id, title, status
        from public.maintenance_records
        where deleted_at is null
          and status in ('open', 'in_progress')
          and company_id = v_company_id
          and created_at < now() - interval '7 days'
        limit 100
      loop
        insert into public.automation_notifications
          (rule_id, run_id, type, title, body, related_entity_type, related_entity_id, company_id)
        values (
          v_rule.id, v_run_id, 'maintenance_overdue',
          'صيانة متأخرة',
          'طلب الصيانة ' || coalesce(v_maint.title, v_maint.id::text) || ' متأخر أكثر من 7 أيام',
          'maintenance', v_maint.id::text, v_company_id
        );
        v_items_processed := v_items_processed + 1;
        v_notif_count := v_notif_count + 1;
      end loop;
    else
      v_items_processed := 0;
    end if;

    update public.automation_runs
    set completed_at = extract(epoch from now()) * 1000,
        status = case when v_items_failed > 0 then 'partial' else 'success' end,
        items_processed = v_items_processed,
        items_failed = v_items_failed,
        actions_taken = jsonb_build_array(jsonb_build_object('notifications_created', v_notif_count))
    where id = v_run_id;

    update public.automation_rules
    set last_run_at = now(),
        last_run_status = case when v_items_failed > 0 then 'PARTIAL' else 'SUCCESS' end,
        last_run_result = 'Processed ' || v_items_processed || ' items, created ' || v_notif_count || ' notifications',
        updated_at = now()
    where id = v_rule.id;

    v_result := jsonb_build_object(
      'success', true, 'run_id', v_run_id,
      'processed', v_items_processed, 'failed', v_items_failed,
      'notifications', v_notif_count
    );
    return v_result;

  exception when others then
    v_error_msg := SQLERRM;
    begin
      update public.automation_runs
      set completed_at = extract(epoch from now()) * 1000,
          status = 'failed',
          error_message = v_error_msg,
          items_processed = v_items_processed,
          items_failed = v_items_failed + 1
      where id = v_run_id;
    exception when others then
      raise notice 'Failed to update automation run to failed: %', SQLERRM;
    end;

    begin
      update public.automation_rules
      set last_run_at = now(),
          last_run_status = 'FAILED',
          last_run_result = v_error_msg,
          updated_at = now()
      where id = v_rule.id;
    exception when others then
      raise notice 'Failed to update automation rule to failed: %', SQLERRM;
    end;

    return jsonb_build_object('success', false, 'run_id', v_run_id, 'error', v_error_msg);
  end;
end;
$$;


ALTER FUNCTION "public"."execute_automation_rule"("p_rule_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_automation_rule_internal"("p_rule_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rule record;
  v_run_id uuid;
  v_items_processed int := 0;
  v_items_failed int := 0;
  v_result jsonb;
  v_contract record;
  v_invoice record;
  v_maint record;
  v_notif_count int := 0;
  v_error_msg text;
begin
  select * into v_rule
  from public.automation_rules
  where id = p_rule_id and deleted_at is null and is_enabled = true
  for update;

  if not found then
    return jsonb_build_object('success', false, 'skipped', true, 'reason', 'rule not found or disabled');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('automation_rule_internal:' || p_rule_id, 0));

  if exists (
    select 1 from public.automation_runs
    where rule_id = p_rule_id
      and status = 'running'
      and started_at > extract(epoch from (now() - interval '5 minutes')) * 1000
  ) then
    return jsonb_build_object('success', false, 'skipped', true, 'reason', 'duplicate prevention');
  end if;

  insert into public.automation_runs (job_name, rule_id, status, started_at, company_id)
  values (v_rule.name, v_rule.id, 'running', extract(epoch from now()) * 1000, v_rule.company_id)
  returning id into v_run_id;

  begin
    if v_rule.rule_type = 'contract_expiry' then
      for v_contract in
        select id, end_date
        from public.contracts
        where deleted_at is null
          and status = 'active'
          and company_id = v_rule.company_id
          and public._safe_date(end_date) between current_date and current_date + interval '30 days'
        limit 100
      loop
        insert into public.automation_notifications
          (rule_id, run_id, type, title, body, related_entity_type, related_entity_id, company_id)
        values (
          v_rule.id, v_run_id, 'contract_expiry',
          'عقد قريب من الانتهاء',
          'العقد ' || v_contract.id || ' ينتهي في ' || coalesce(v_contract.end_date, '?'),
          'contract', v_contract.id::text, v_rule.company_id
        );
        v_items_processed := v_items_processed + 1;
        v_notif_count := v_notif_count + 1;
      end loop;

    elsif v_rule.rule_type = 'overdue_invoice' then
      for v_invoice in
        select id, due_date, amount, paid_amount
        from public.invoices
        where deleted_at is null
          and status not in ('paid', 'cancelled', 'void')
          and company_id = v_rule.company_id
          and public._safe_date(due_date) < current_date
          and (amount - coalesce(paid_amount, 0)) > 0
        limit 100
      loop
        insert into public.automation_notifications
          (rule_id, run_id, type, title, body, related_entity_type, related_entity_id, company_id)
        values (
          v_rule.id, v_run_id, 'overdue_invoice',
          'فاتورة متأخرة',
          'الفاتورة ' || v_invoice.id || ' متأخرة',
          'invoice', v_invoice.id::text, v_rule.company_id
        );
        v_items_processed := v_items_processed + 1;
        v_notif_count := v_notif_count + 1;
      end loop;

    elsif v_rule.rule_type = 'maintenance_overdue' then
      for v_maint in
        select id, title
        from public.maintenance_records
        where deleted_at is null
          and status in ('open', 'in_progress')
          and company_id = v_rule.company_id
          and created_at < now() - interval '7 days'
        limit 100
      loop
        insert into public.automation_notifications
          (rule_id, run_id, type, title, body, related_entity_type, related_entity_id, company_id)
        values (
          v_rule.id, v_run_id, 'maintenance_overdue',
          'صيانة متأخرة',
          'طلب ' || coalesce(v_maint.title, v_maint.id::text) || ' متأخر',
          'maintenance', v_maint.id::text, v_rule.company_id
        );
        v_items_processed := v_items_processed + 1;
        v_notif_count := v_notif_count + 1;
      end loop;
    end if;

    update public.automation_runs
    set completed_at = extract(epoch from now()) * 1000,
        status = 'success',
        items_processed = v_items_processed,
        actions_taken = jsonb_build_array(jsonb_build_object('notifications_created', v_notif_count))
    where id = v_run_id;

    update public.automation_rules
    set last_run_at = now(),
        last_run_status = 'SUCCESS',
        last_run_result = 'Scheduled: ' || v_items_processed || ' items, ' || v_notif_count || ' notifs',
        updated_at = now()
    where id = v_rule.id;

    return jsonb_build_object(
      'success', true, 'run_id', v_run_id,
      'processed', v_items_processed, 'notifications', v_notif_count
    );

  exception when others then
    v_error_msg := SQLERRM;
    begin
      update public.automation_runs
      set completed_at = extract(epoch from now()) * 1000,
          status = 'failed',
          error_message = v_error_msg
      where id = v_run_id;
      update public.automation_rules
      set last_run_at = now(),
          last_run_status = 'FAILED',
          last_run_result = v_error_msg
      where id = v_rule.id;
    exception when others then
      raise notice 'Failed to update failed status: %', SQLERRM;
    end;
    return jsonb_build_object('success', false, 'run_id', v_run_id, 'error', v_error_msg);
  end;
end;
$$;


ALTER FUNCTION "public"."execute_automation_rule_internal"("p_rule_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_fixed_monthly_accruals_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id', '')), '');
  v_date_from date := nullif(p_payload->>'date_from', '')::date;
  v_date_to date := nullif(p_payload->>'date_to', '')::date;
  v_version_id uuid := nullif(p_payload->>'agreement_version_id', '')::uuid;
  v_company_today date;
  v_fingerprint text;
  v_cached jsonb;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'FIXED_MONTHLY_ROLE_REQUIRED: ADMIN, MANAGER or ACCOUNTANT is required.' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if not public.is_company_member(v_company_id, v_actor) then
    raise exception 'FIXED_MONTHLY_ACTIVE_COMPANY_MEMBERSHIP_REQUIRED' using errcode = '42501';
  end if;

  if p_payload ?| array['company_id','monthly_amount','commission_value','net_amount','tax_amount','tax_rate','gross_amount','lines'] then
    raise exception 'FIXED_MONTHLY_CLIENT_FINANCIAL_INPUT_FORBIDDEN' using errcode = '22023';
  end if;
  if v_request_id is null or length(v_request_id) > 200 then
    raise exception 'FIXED_MONTHLY_REQUEST_ID_REQUIRED' using errcode = '22023';
  end if;
  if v_date_from is null or v_date_to is null then
    raise exception 'FIXED_MONTHLY_RUN_RANGE_REQUIRED' using errcode = '22023';
  end if;

  select (now() at time zone c.timezone)::date into v_company_today
  from public.companies c
  where c.id = v_company_id and c.is_active;
  if v_company_today is null then
    raise exception 'FIXED_MONTHLY_COMPANY_NOT_FOUND_OR_INACTIVE' using errcode = '42501';
  end if;
  if v_date_to > v_company_today then
    raise exception 'FIXED_MONTHLY_FUTURE_ACCRUAL_FORBIDDEN' using errcode = '22023';
  end if;

  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'date_from', v_date_from,
    'date_to', v_date_to,
    'agreement_version_id', v_version_id
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended(
    'execute_fixed_monthly_accruals_atomic:' || v_company_id::text || ':' || v_request_id,
    0
  ));

  select response_payload into v_cached
  from public.financial_operation_idempotency
  where operation_name = 'execute_fixed_monthly_accruals_atomic:' || v_company_id::text
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    if v_cached->>'_request_fingerprint' is distinct from v_fingerprint
       or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode = '22023';
    end if;
    return v_cached->'response';
  end if;

  v_result := public.gl_run_fixed_monthly_accruals(
    v_company_id,
    v_date_from,
    v_date_to,
    v_version_id,
    v_actor
  );

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid()::text,
    extract(epoch from now())::bigint,
    v_actor,
    v_actor::text,
    'EXECUTE',
    'fixed_monthly_daily_accrual',
    v_request_id,
    'Bounded FIXED_MONTHLY daily accrual run.',
    'fixed_monthly_daily_accruals',
    jsonb_build_object(
      'company_id', v_company_id,
      'date_from', v_date_from,
      'date_to', v_date_to,
      'agreement_version_id', v_version_id,
      'result', v_result
    )::text,
    now()
  );

  insert into public.financial_operation_idempotency(operation_name, request_id, response_payload)
  values (
    'execute_fixed_monthly_accruals_atomic:' || v_company_id::text,
    v_request_id,
    jsonb_build_object('_request_fingerprint', v_fingerprint, 'response', v_result)
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."execute_fixed_monthly_accruals_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_receipt_void_internal"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_requested_id text := nullif(btrim(payload->>'receipt_id'), '');
  v_reason text := nullif(btrim(payload->>'reason'), '');
  v_request_id text := nullif(btrim(payload->>'request_id'), '');
  v_cached jsonb;
  v_payment public.payments%rowtype;
  v_receipt public.receipts%rowtype;
  v_receipt_was_void boolean := false;
  v_reversal_request_id text;
  v_reversal_batch_id uuid;
  v_original_count integer := 0;
  v_existing_reversal_count integer := 0;
  v_created_reversal_count integer := 0;
  v_original_debits numeric := 0;
  v_original_credits numeric := 0;
  v_result jsonb;
  v_company_id uuid;
  v_request_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target_id text;
BEGIN
  IF v_actor_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.users u
    WHERE u.id = v_actor_id
      AND u.status::text = 'ACTIVE'
      AND u.role::text IN ('ADMIN', 'MANAGER')
  ) THEN
    RAISE EXCEPTION 'ADMIN or MANAGER role is required to void receipts.'
      USING ERRCODE = '42501';
  END IF;

  -- 3A-1B: bind the operation to the caller's company BEFORE any replay/lookup.
  v_company_id := public.current_company_id();
  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'Company context is required to void receipts.'
      USING ERRCODE = '42501';
  END IF;

  IF v_requested_id IS NULL OR v_reason IS NULL OR v_request_id IS NULL THEN
    RAISE EXCEPTION 'receipt_id, reason, and request_id are required.'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('void_receipt_atomic:' || v_company_id::text || ':' || v_request_id, 0)
  );

  -- 3A-1B: resolution is company-scoped — cross-company identifiers behave
  -- exactly like "not found" (no existence leakage, no cross-company locks).
  SELECT p.*
  INTO v_payment
  FROM public.payments p
  WHERE p.id::text = v_requested_id
    AND p.deleted_at IS NULL
    AND p.company_id = v_company_id
  FOR UPDATE;

  IF v_payment.id IS NOT NULL THEN
    SELECT r.*
    INTO v_receipt
    FROM public.receipts r
    WHERE r.id::text = coalesce(nullif(v_payment.receipt_id::text, ''), v_payment.id::text)
      AND r.deleted_at IS NULL
      AND r.company_id = v_company_id
    FOR UPDATE;
  ELSE
    SELECT r.*
    INTO v_receipt
    FROM public.receipts r
    WHERE r.id::text = v_requested_id
      AND r.deleted_at IS NULL
      AND r.company_id = v_company_id
    FOR UPDATE;

    IF v_receipt.id IS NOT NULL THEN
      SELECT p.*
      INTO v_payment
      FROM public.payments p
      WHERE p.receipt_id::text = v_receipt.id::text
        AND p.deleted_at IS NULL
        AND p.company_id = v_company_id
      ORDER BY p.created_at DESC NULLS LAST, p.id
      LIMIT 1
      FOR UPDATE;
    END IF;
  END IF;

  IF v_payment.id IS NULL OR v_receipt.id IS NULL THEN
    RAISE EXCEPTION 'Linked payment and receipt were not found for identifier %.', v_requested_id
      USING ERRCODE = 'P0002';
  END IF;

  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'receipt_id', v_receipt.id::text,
    'reason', v_reason,
    'note', nullif(btrim(payload->>'note'), ''),
    'date', nullif(payload->>'date', '')::date,
    'voided_at', nullif(payload->>'voided_at', '')::timestamptz
  )::text, 'UTF8')), 'hex');

  SELECT response_payload
  INTO v_cached
  FROM public.financial_operation_idempotency
  WHERE operation_name = 'void_receipt_atomic:' || v_company_id::text
    AND request_id = v_request_id
  FOR UPDATE;

  IF v_cached IS NOT NULL THEN
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    v_cached_target_id := v_cached->>'_target_id';
    IF v_cached_fingerprint IS NULL
       OR v_cached_target_id IS NULL
       OR NOT (v_cached ? 'response') THEN
      RAISE EXCEPTION 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        USING ERRCODE = '22023';
    END IF;
    IF v_cached_fingerprint <> v_request_fingerprint
       OR v_cached_target_id <> v_receipt.id::text THEN
      RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        USING ERRCODE = '22023';
    END IF;
    RETURN (v_cached->'response') || jsonb_build_object('idempotent', true);
  END IF;

  v_receipt_was_void := upper(coalesce(v_receipt.status, '')) = 'VOID';
  v_reversal_request_id := 'void:' || v_receipt.id::text;

  SELECT
    count(*)::integer,
    coalesce(sum(je.amount) FILTER (WHERE upper(je.type) = 'DEBIT'), 0),
    coalesce(sum(je.amount) FILTER (WHERE upper(je.type) = 'CREDIT'), 0)
  INTO v_original_count, v_original_debits, v_original_credits
  FROM public.journal_entries je
  WHERE je.source_id::text = v_receipt.id::text
    AND je.deleted_at IS NULL
    AND coalesce(je.request_id, '') <> v_reversal_request_id
    AND coalesce(je.entity_type, '') <> 'receipt_void';

  SELECT count(*)::integer
  INTO v_existing_reversal_count
  FROM public.journal_entries je
  WHERE je.source_id::text = v_receipt.id::text
    AND je.deleted_at IS NULL
    AND je.request_id = v_reversal_request_id
    AND je.entity_type = 'receipt_void';

  -- Adjust invoices associated with allocations
  IF NOT v_receipt_was_void THEN
    WITH allocated AS (
      SELECT invoice_id, sum(amount) AS total
      FROM public.receipt_allocations
      WHERE receipt_id::text = v_receipt.id::text
        AND deleted_at IS NULL
      GROUP BY invoice_id
    )
    UPDATE public.invoices i
    SET
      paid_amount = coalesce(i.paid_amount, 0) - allocated.total,
      status = CASE
        WHEN coalesce(i.paid_amount, 0) - allocated.total <= 0 THEN 'UNPAID'
        WHEN coalesce(i.paid_amount, 0) - allocated.total
          < coalesce(i.amount, 0) + coalesce(i.tax_amount, 0) - 0.001 THEN 'PARTIALLY_PAID'
        ELSE 'PAID'
      END,
      updated_at = now()
    FROM allocated
    WHERE i.id = allocated.invoice_id
      AND i.company_id = v_company_id;
  END IF;

  UPDATE public.receipts
  SET status = 'VOID', voided_at = floor(extract(epoch from clock_timestamp()) * 1000)::bigint, updated_at = now()
  WHERE id::text = v_receipt.id::text;

  UPDATE public.payments
  SET status = 'VOID', updated_at = now()
  WHERE id = v_payment.id;

  -- Stage S03: canonical receipt batches use the engine-managed reversal.
  IF v_original_count > 0 AND v_existing_reversal_count = 0 THEN
    -- A receipt posted through Stage S03 has exactly one canonical source batch.
    -- Prefer that batch and let reverse_journal_batch own reversal identity,
    -- line inversion, period routing and idempotency.
    SELECT b.id
      INTO v_reversal_batch_id
    FROM public.journal_batches b
    WHERE b.company_id = v_company_id
      AND b.source_type = 'receipt'
      AND b.source_id = v_receipt.id::text
      AND NOT b.is_legacy_compat
    ORDER BY b.created_at, b.id
    LIMIT 1;

    IF v_reversal_batch_id IS NOT NULL THEN
      v_result := public.reverse_journal_batch(v_reversal_batch_id);

      -- The engine returns the created/reused reversal id. Preserve the public
      -- void_receipt_atomic response fields while reporting created line count
      -- only for a newly-created reversal.
      v_reversal_batch_id := nullif(v_result->>'reversal_batch_id', '')::uuid;
      IF coalesce((v_result->>'idempotent')::boolean, false) THEN
        v_created_reversal_count := 0;
      ELSE
        SELECT count(*)::integer
          INTO v_created_reversal_count
        FROM public.journal_lines jl
        WHERE jl.batch_id = v_reversal_batch_id
          AND jl.deleted_at IS NULL;
      END IF;
    ELSE
      -- Historical compatibility receipt: retain the pre-S03 behavior so old
      -- financial history remains voidable without rewriting legacy batches.
      v_reversal_batch_id := gen_random_uuid();

      INSERT INTO public.journal_entries (
        id, no, date, account_id, amount, type, source_id, entity_type,
        entity_id, created_at, request_id, status, batch_id, company_id
      )
      SELECT
        gen_random_uuid()::text,
        'VOID-' || left(replace(v_receipt.id::text, '-', ''), 12) || '-' || row_number() over (order by je.id),
        current_date::text,
        je.account_id,
        je.amount,
        CASE upper(je.type) WHEN 'DEBIT' THEN 'CREDIT' ELSE 'DEBIT' END,
        v_receipt.id::text,
        'receipt_void',
        v_receipt.id::text,
        now(),
        v_reversal_request_id,
        'posted',
        v_reversal_batch_id,
        je.company_id
      FROM public.journal_entries je
      WHERE je.source_id::text = v_receipt.id::text
        AND je.deleted_at IS NULL
        AND coalesce(je.request_id, '') <> v_reversal_request_id
        AND coalesce(je.entity_type, '') <> 'receipt_void';

      GET DIAGNOSTICS v_created_reversal_count = ROW_COUNT;
      PERFORM public.close_journal_batch(v_reversal_batch_id);
    END IF;
  END IF;

  IF NOT v_receipt_was_void OR v_created_reversal_count > 0 THEN
    INSERT INTO public.audit_log (
      id, ts, user_id, action, entity, entity_id, note, "table", details,
      old_value, new_value, action_timestamp, created_at, updated_at
    ) VALUES (
      gen_random_uuid()::text,
      extract(epoch from now())::bigint,
      v_actor_id::text,
      'VOID_RECEIPT_ATOMIC',
      'receipt',
      v_receipt.id::text,
      'Receipt voided atomically with payment, invoice, report, and journal parity.',
      'receipts',
      jsonb_build_object(
        'reason', v_reason,
        'request_id', v_request_id,
        'requested_id', v_requested_id,
        'payment_id', v_payment.id,
        'receipt_id', v_receipt.id,
        'journal_reversal_batch_id', v_reversal_batch_id,
        'journal_reversal_entries', v_created_reversal_count
      )::text,
      jsonb_build_object('payment_status', v_payment.status, 'receipt_status', v_receipt.status),
      jsonb_build_object('payment_status', 'VOID', 'receipt_status', 'VOID'),
      now(),
      now(),
      now()
    );
  END IF;

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', v_receipt_was_void AND v_created_reversal_count = 0,
    'request_id', v_request_id,
    'requested_receipt_id', v_requested_id,
    'payment_id', v_payment.id,
    'receipt_id', v_receipt.id,
    'status', 'VOID',
    'reason', v_reason,
    'journal_reversal_batch_id', v_reversal_batch_id,
    'journal_reversal_entries', v_created_reversal_count
  );

  INSERT INTO public.financial_operation_idempotency (
    operation_name, request_id, response_payload
  ) VALUES (
    'void_receipt_atomic:' || v_company_id::text,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_receipt.id::text,
      'response', v_result
    )
  )
  ON CONFLICT (operation_name, request_id) DO NOTHING;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."execute_receipt_void_internal"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."execute_receipt_void_internal"("payload" "jsonb") IS 'Internal engine-managed receipt VOID executor. Callable only by the governed approval RPC owner; never an exposed browser RPC.';



CREATE OR REPLACE FUNCTION "public"."find_payment_account_id"("account_role" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_target_no text;
  v_company_id uuid;
begin
  case account_role
    when 'cash' then v_target_no := '1111';
    when 'receivable' then v_target_no := '1201';
    else return null;
  end case;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'Company context is required to resolve payment accounts.' using errcode = '42501';
  end if;

  return public.require_company_account_id(v_company_id, v_target_no);
end;
$$;


ALTER FUNCTION "public"."find_payment_account_id"("account_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fixed_monthly_daily_amount_omr"("p_monthly_amount" numeric, "p_economic_date" "date") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_monthly_omr numeric;
  v_days integer;
  v_day integer;
  v_target_baisa bigint;
  v_base_baisa bigint;
  v_residue_days integer;
begin
  if p_monthly_amount is null or p_economic_date is null then
    raise exception 'FIXED_MONTHLY_ALLOCATOR_INPUT_REQUIRED' using errcode = '22023';
  end if;
  if p_monthly_amount::text in ('NaN', 'Infinity', '-Infinity') or p_monthly_amount < 0 then
    raise exception 'FIXED_MONTHLY_ALLOCATOR_AMOUNT_INVALID' using errcode = '22023';
  end if;

  v_monthly_omr := round(p_monthly_amount, 3);
  v_days := extract(day from (date_trunc('month', p_economic_date)::date + interval '1 month - 1 day'))::integer;
  v_day := extract(day from p_economic_date)::integer;
  v_target_baisa := round(v_monthly_omr * 1000)::bigint;
  v_base_baisa := floor(v_target_baisa::numeric / v_days)::bigint;
  v_residue_days := (v_target_baisa - (v_base_baisa * v_days))::integer;

  return ((v_base_baisa + case when v_day <= v_residue_days then 1 else 0 end)::numeric / 1000)::numeric(14,3);
end;
$$;


ALTER FUNCTION "public"."fixed_monthly_daily_amount_omr"("p_monthly_amount" numeric, "p_economic_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."format_document_reference"("p_company_id" "uuid", "p_doc_type" "text", "p_prefix" "text", "p_year" integer, "p_sequence" bigint) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select format('%s-%s-%s', p_prefix, p_year, lpad(p_sequence::text, 6, '0'))
$$;


