CREATE OR REPLACE FUNCTION "public"."generate_invoices_from_active_contracts"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_contract record;
  v_invoice_id uuid;
  v_batch_id uuid;
  v_tax_snapshot_id uuid;
  v_owner_id uuid;
  v_taxable boolean;
  v_tax_profile_id uuid;
  v_tax_code text;
  v_tax_rate numeric := 0;
  v_tax_amount numeric := 0;
  v_total_amount numeric;
  v_ar_account_id text;
  v_owner_funds_account_id text;
  v_vat_account_id text;
  v_count integer := 0;
  v_period_start date;
  v_period_end date;
  v_issue_date date;
  v_due_date date;
  v_billing_day integer;
  v_grace_days integer;
  v_lines jsonb;
  v_invoice_exists boolean;
  v_classification text;
  v_post_result jsonb;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to generate invoices' using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  for v_contract in
    select c.id,
           c.rent_amount,
           c.payment_cycle,
           c.billing_day,
           c.grace_days,
           c.agreement_version_id,
           c.operating_model_snapshot,
           c.collection_role_snapshot,
           oa.owner_id
      from public.contracts c
      join public.owner_agreements oa
        on oa.id = c.agreement_id
       and oa.company_id = c.company_id
     where c.deleted_at is null
       and lower(c.status) = 'active'
       and c.company_id = v_company_id
     order by c.id
  loop
    perform pg_advisory_xact_lock(hashtext('invoice_generation:' || v_contract.id::text));

    case v_contract.payment_cycle
      when 'monthly' then
        v_period_start := date_trunc('month', current_date)::date;
        v_period_end := (date_trunc('month', current_date) + interval '1 month' - interval '1 day')::date;
      when 'quarterly' then
        v_period_start := date_trunc('quarter', current_date)::date;
        v_period_end := (date_trunc('quarter', current_date) + interval '3 months' - interval '1 day')::date;
      when 'semi_annual' then
        if extract(month from current_date) <= 6 then
          v_period_start := make_date(extract(year from current_date)::int, 1, 1);
          v_period_end := make_date(extract(year from current_date)::int, 6, 30);
        else
          v_period_start := make_date(extract(year from current_date)::int, 7, 1);
          v_period_end := make_date(extract(year from current_date)::int, 12, 31);
        end if;
      when 'annual' then
        v_period_start := date_trunc('year', current_date)::date;
        v_period_end := (date_trunc('year', current_date) + interval '1 year' - interval '1 day')::date;
      else
        v_period_start := date_trunc('month', current_date)::date;
        v_period_end := (date_trunc('month', current_date) + interval '1 month' - interval '1 day')::date;
    end case;

    v_billing_day := coalesce(v_contract.billing_day, 1);
    v_grace_days := coalesce(v_contract.grace_days, 0);
    v_issue_date := least(
      make_date(extract(year from v_period_start)::int, extract(month from v_period_start)::int, v_billing_day),
      v_period_end
    );
    v_due_date := v_period_end + v_grace_days;

    select exists(
      select 1
        from public.invoices i
       where i.contract_id = v_contract.id
         and i.charge_type = 'RENT'
         and i.billing_period_start = v_period_start
         and i.deleted_at is null
         and i.document_status not in ('VOIDED','REVERSED')
    ) into v_invoice_exists;
    if v_invoice_exists then
      continue;
    end if;

    if v_contract.operating_model_snapshot is distinct from 'OWNER_AGENCY'
       or v_contract.agreement_version_id is null
       or v_contract.collection_role_snapshot not in ('OWNER_IS_CREDITOR', 'OFFICE_IS_CREDITOR') then
      raise exception 'RC1_INVOICE_GENERATION_MODEL_UNAVAILABLE: active contract % is not a fully snapshotted OWNER_AGENCY contract in the RC1 scope.', v_contract.id
        using errcode = '23514';
    end if;

    v_owner_id := v_contract.owner_id;
    if v_owner_id is null then
      raise exception 'RC1_OWNER_FUNDS_OWNER_REQUIRED: owner-agency invoice requires an owner-scoped agreement.'
        using errcode = '23514';
    end if;

    v_classification := case v_contract.collection_role_snapshot
      when 'OWNER_IS_CREDITOR' then 'OWNER_AGENCY_OWNER_CREDITOR_OPERATIONAL'
      when 'OFFICE_IS_CREDITOR' then 'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS'
      else null
    end;

    -- Every recurring invoice resolves an effective profile. This is the sole
    -- rate/code authority: no company_settings fallback exists.
    select profile_id, tax_code, tax_rate
      into v_tax_profile_id, v_tax_code, v_tax_rate
      from public.resolve_active_tax_profile(v_company_id, v_issue_date);
    v_taxable := v_tax_code <> 'NON_TAXABLE';
    v_tax_amount := public.compute_tax_amount(v_contract.rent_amount, v_tax_rate);
    if not v_taxable and (v_tax_rate <> 0 or v_tax_amount <> 0) then
      raise exception 'INVOICE_NON_TAXABLE_PROFILE_RATE_INVALID: NON_TAXABLE profiles must be configured at 0.000.'
        using errcode = '23514';
    end if;
    v_total_amount := public.gl_pm_round_omr(v_contract.rent_amount + v_tax_amount);

    -- Insert DRAFT first so the invoice id is available to the canonical batch
    -- and tax snapshot. It becomes POSTED only after every immutable lineage
    -- link is written in this same transaction.
    insert into public.invoices (
      contract_id,
      issue_date,
      due_date,
      amount,
      tax_amount,
      tax_rate,
      status,
      company_id,
      document_status,
      charge_type,
      billing_period_start,
      billing_period_end,
      invoice_agreement_version_id,
      invoice_operating_model,
      invoice_collection_role,
      invoice_accounting_classification,
      tax_treatment,
      tax_profile_id,
      tax_code,
      tax_basis
    ) values (
      v_contract.id,
      v_issue_date,
      v_due_date,
      v_contract.rent_amount,
      v_tax_amount,
      v_tax_rate,
      'UNPAID',
      v_company_id,
      'DRAFT',
      'RENT',
      v_period_start,
      v_period_end,
      v_contract.agreement_version_id,
      v_contract.operating_model_snapshot,
      v_contract.collection_role_snapshot,
      v_classification,
      case when v_taxable then 'TAXABLE' else 'NON_TAXABLE' end,
      v_tax_profile_id,
      v_tax_code,
      case when v_taxable then 'NET_PLUS_TAX' else 'NON_TAXABLE' end
    )
    returning id into v_invoice_id;

    -- Invoice issuance is a controlled financial obligation even when the
    -- OWNER_IS_CREDITOR document is operational-only. Resolve the period here
    -- so OPEN/SOFT_CLOSED/HARD_CLOSED and late-posting rules apply uniformly.
    perform public.gl_ensure_initial_open_period(v_company_id, v_issue_date);
    perform 1 from public.gl_resolve_accounting_period(v_company_id, v_issue_date);

    v_batch_id := null;
    if v_classification = 'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS' then
      v_ar_account_id := public.require_company_account_id(v_company_id, '1201');
      v_owner_funds_account_id := public.require_company_account_id(v_company_id, '2000');
      v_lines := jsonb_build_array(
        jsonb_build_object(
          'account_id', v_ar_account_id,
          'debit', v_total_amount,
          'credit', 0,
          'line_description', 'INV-' || v_invoice_id::text || '-DR-AR',
          'ref_source_id', v_invoice_id::text,
          'ref_entity_type', 'invoice',
          'ref_entity_id', v_invoice_id::text
        ),
        jsonb_build_object(
          'account_id', v_owner_funds_account_id,
          'debit', 0,
          'credit', v_contract.rent_amount,
          'line_description', 'INV-' || v_invoice_id::text || '-CR-OWNER-FUNDS',
          'ref_source_id', v_invoice_id::text,
          'ref_entity_type', 'invoice',
          'ref_entity_id', v_invoice_id::text
        )
      );
      if v_tax_amount > 0 then
        v_vat_account_id := public.require_company_account_id(v_company_id, '2100');
        v_lines := v_lines || jsonb_build_array(
          jsonb_build_object(
            'account_id', v_vat_account_id,
            'debit', 0,
            'credit', v_tax_amount,
            'line_description', 'INV-' || v_invoice_id::text || '-CR-VAT',
            'ref_source_id', v_invoice_id::text,
            'ref_entity_type', 'invoice',
            'ref_entity_id', v_invoice_id::text
          )
        );
      end if;

      perform public.gl_ensure_initial_open_period(v_company_id, v_issue_date);
      v_post_result := public.post_journal_event(jsonb_build_object(
        'company_id', v_company_id,
        'source_type', 'invoice',
        'source_id', v_invoice_id::text,
        'event_id', v_invoice_id::text,
        'effective_date', v_issue_date,
        'description', 'OWNER_AGENCY OFFICE_IS_CREDITOR rent invoice ' || v_invoice_id::text,
        'lines', v_lines
      ));
      v_batch_id := nullif(v_post_result->>'batch_id', '')::uuid;
      if v_batch_id is null then
        raise exception 'INVOICE_RC1_POSTING_BATCH_MISSING' using errcode = 'P0001';
      end if;
    end if;

    v_tax_snapshot_id := null;
    -- Store the resolved profile even for an explicit NON_TAXABLE invoice so
    -- future credits never infer a treatment from changed company settings.
    insert into public.taxable_line_tax_snapshots (
        company_id,
        source_type,
        source_id,
        journal_batch_id,
        account_no,
        tax_code,
        tax_rate,
        net_amount,
        tax_amount,
        effective_date
      ) values (
        v_company_id,
        'invoice',
        v_invoice_id::text,
        v_batch_id,
        '2100',
        v_tax_code,
        v_tax_rate,
        v_contract.rent_amount,
        v_tax_amount,
        v_issue_date
      )
      returning id into v_tax_snapshot_id;

    update public.invoices
       set invoice_posting_batch_id = v_batch_id,
           tax_snapshot_id = v_tax_snapshot_id,
           document_status = 'POSTED',
           updated_at = now()
     where id = v_invoice_id
       and company_id = v_company_id;

    if v_classification = 'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS' then
      insert into public.owner_funds_events (
        company_id, owner_id, contract_id, invoice_id, source_type, source_id,
        event_id, amount_delta, effective_date, journal_batch_id
      ) values (
        v_company_id, v_owner_id, v_contract.id, v_invoice_id, 'OFFICE_INVOICE',
        v_invoice_id::text, 'issue', v_contract.rent_amount, v_issue_date, v_batch_id
      );
    end if;

    v_count := v_count + 1;
  end loop;

  if v_count > 0 then
    insert into public.audit_log (
      id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
    ) values (
      gen_random_uuid()::text,
      extract(epoch from now())::bigint,
      auth.uid(),
      (select email from auth.users where id = auth.uid()),
      'GENERATE',
      'invoices',
      'batch',
      format('Generated %s RC1 owner-agency invoices from active contracts', v_count),
      'invoices',
      jsonb_build_object('count', v_count, 'taxability', case when v_taxable then 'TAXABLE' else 'NON_TAXABLE' end)::text,
      now()
    );
  end if;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."generate_invoices_from_active_contracts"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_invoices_from_active_contracts"() IS 'RC1 server-owned recurring OWNER_AGENCY invoice generation. OWNER_IS_CREDITOR remains operational at invoice issuance; OFFICE_IS_CREDITOR posts Dr 1201 / Cr 2000 (+2100). 4000 is never selected.';



CREATE OR REPLACE FUNCTION "public"."get_company_onboarding_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := public.require_company_id();
  v_result  jsonb;
begin
  select jsonb_build_object(
    'company_id', v_company,
    'completed', exists (
      select 1 from public.company_onboarding_completion c
      where c.company_id = v_company
    ),
    'requirements', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'code', t.code,
          'label_ar', t.label_ar,
          'required', t.required,
          'waiver_policy', t.waiver_policy,
          'sort_order', t.sort_order,
          'completion_source', t.completion_source,
          'waived', (w.id is not null and w.revoked_at is null),
          'waiver_reason', case when w.id is not null and w.revoked_at is null then w.waiver_reason end,
          'waived_at', case when w.id is not null and w.revoked_at is null then w.waived_at end,
          'waiver_authority', case when w.id is not null and w.revoked_at is null then w.waiver_authority end,
          'evidence_reference', case when w.id is not null and w.revoked_at is null then w.evidence_reference end,
          'revoked', (w.id is not null and w.revoked_at is not null),
          'revoked_at', w.revoked_at
        )
        order by t.sort_order
      )
      from public.onboarding_requirement_templates t
      left join public.company_onboarding_waivers w
        on w.requirement_code = t.code
       and w.company_id = v_company
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_company_onboarding_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contract_evidence_state"("p_contract_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := public.require_company_id();
  v_contract public.contracts%rowtype;
  v_profile jsonb;
  v_registration jsonb;
  v_inspections jsonb;
  v_templates jsonb;
begin
  select * into v_contract from public.contracts c
  where c.id = p_contract_id and c.company_id = v_company and c.deleted_at is null;
  if not found then raise exception 'CONTRACT_NOT_FOUND' using errcode = '42501'; end if;

  select to_jsonb(p) into v_profile
  from public.contract_registration_requirement_profiles p
  where p.company_id = v_company and p.effective_from <= v_contract.start_date
    and (p.effective_to is null or p.effective_to >= v_contract.start_date)
  order by p.effective_from desc limit 1;

  select to_jsonb(r) into v_registration
  from public.contract_registration_records r
  where r.company_id = v_company and r.contract_id = p_contract_id
  order by r.created_at desc limit 1;

  select coalesce(jsonb_agg(to_jsonb(i) order by i.inspected_on desc, i.created_at desc), '[]'::jsonb)
    into v_inspections from public.contract_inspections i
  where i.company_id = v_company and i.contract_id = p_contract_id;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.kind, t.version_no desc), '[]'::jsonb)
    into v_templates from public.contract_inspection_templates t
  where t.active and (t.company_id = v_company or t.company_id is null)
    and t.effective_from <= current_date and (t.effective_to is null or t.effective_to >= current_date);

  return jsonb_build_object(
    'registration_configuration_status', case when v_profile is null then 'NOT_CONFIGURED' else 'CONFIGURED' end,
    'registration_profile', v_profile,
    'registration', v_registration,
    'inspections', v_inspections,
    'inspection_templates', v_templates
  );
end;
$$;


ALTER FUNCTION "public"."get_contract_evidence_state"("p_contract_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_contract_evidence_state"("p_contract_id" "uuid") IS 'Company-isolated read model for contract registration and handover evidence.';



CREATE OR REPLACE FUNCTION "public"."gl_accrue_fixed_monthly_day"("p_company_id" "uuid", "p_agreement_version_id" "uuid", "p_economic_date" "date", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_owner_agreement_id uuid;
  v_owner_id uuid;
  v_property_id text;
  v_operating_model text;
  v_commission_type text;
  v_recognition_basis text;
  v_monthly_contract numeric;
  v_agreement_start date;
  v_agreement_end date;
  v_version_start date;
  v_version_end date;
  v_calendar_days integer;
  v_calendar_day integer;
  v_monthly_omr numeric(14,3);
  v_net numeric(14,3);
  v_tax numeric(14,3) := 0;
  v_gross numeric(14,3);
  v_fee_treatment_id uuid;
  v_fee_tax_profile_id uuid;
  v_fee_tax_code text;
  v_fee_tax_rate numeric := 0;
  v_accrual_id uuid;
  v_due_from_owner_id text;
  v_revenue_id text;
  v_vat_id text;
  v_post_result jsonb;
  v_batch_id uuid;
  v_fingerprint text;
  v_existing public.fixed_monthly_daily_accruals%rowtype;
  v_reversal public.fixed_monthly_daily_accrual_reversals%rowtype;
begin
  if current_user not in ('postgres', 'supabase_admin', 'service_role') then
    raise exception 'FIXED_MONTHLY_ENGINE_SERVER_ONLY' using errcode = '42501';
  end if;
  if p_company_id is null or p_agreement_version_id is null or p_economic_date is null then
    raise exception 'FIXED_MONTHLY_DAY_INPUT_REQUIRED' using errcode = '22023';
  end if;

  select
    v.owner_agreement_id,
    oa.owner_id,
    oa.property_id::text,
    v.operating_model,
    v.commission_type,
    v.commission_recognition_basis,
    v.commission_value,
    oa.starts_on,
    oa.ends_on,
    v.effective_from,
    v.effective_to
  into
    v_owner_agreement_id,
    v_owner_id,
    v_property_id,
    v_operating_model,
    v_commission_type,
    v_recognition_basis,
    v_monthly_contract,
    v_agreement_start,
    v_agreement_end,
    v_version_start,
    v_version_end
  from public.owner_agreement_versions v
  join public.owner_agreements oa
    on oa.id = v.owner_agreement_id
   and oa.company_id = v.company_id
  where v.id = p_agreement_version_id
    and v.company_id = p_company_id
    and oa.agreement_type = 'property_management';

  if not found then
    raise exception 'FIXED_MONTHLY_VERSION_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;

  if v_operating_model <> 'OWNER_AGENCY'
     or v_commission_type <> 'FIXED_MONTHLY'
     or v_recognition_basis <> 'DAILY_ACCRUAL'
     or v_monthly_contract is null
     or v_monthly_contract::text in ('NaN', 'Infinity', '-Infinity')
     or v_monthly_contract < 0 then
    raise exception 'FIXED_MONTHLY_TERMS_INVALID' using errcode = '22023';
  end if;

  if p_economic_date < greatest(v_agreement_start, v_version_start)
     or p_economic_date > least(
       coalesce(v_agreement_end, 'infinity'::date),
       coalesce(v_version_end, 'infinity'::date)
     ) then
    raise exception 'FIXED_MONTHLY_DATE_OUTSIDE_SERVICE_INTERVAL' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'fixed_monthly_day:' || p_company_id::text || ':' || p_agreement_version_id::text || ':' || p_economic_date::text,
    0
  ));

  v_calendar_days := extract(day from (date_trunc('month', p_economic_date)::date + interval '1 month - 1 day'))::integer;
  v_calendar_day := extract(day from p_economic_date)::integer;
  v_monthly_omr := round(v_monthly_contract, 3);
  v_net := public.fixed_monthly_daily_amount_omr(v_monthly_contract, p_economic_date);
  if v_net > 0 then
    select treatment_id, tax_profile_id, tax_code, tax_rate
      into v_fee_treatment_id, v_fee_tax_profile_id, v_fee_tax_code, v_fee_tax_rate
      from public.resolve_active_fee_tax_treatment(p_company_id, 'FIXED_MONTHLY', p_economic_date);
    v_tax := public.compute_tax_amount(v_net, v_fee_tax_rate);
  end if;
  v_gross := public.gl_pm_round_omr(v_net + v_tax);

  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'company_id', p_company_id,
    'agreement_version_id', p_agreement_version_id,
    'owner_agreement_id', v_owner_agreement_id,
    'economic_date', p_economic_date,
    'monthly_contract_amount', v_monthly_contract,
    'monthly_amount_omr', v_monthly_omr,
    'calendar_days', v_calendar_days,
    'calendar_day', v_calendar_day,
    'net_amount', v_net,
    'tax_amount', v_tax,
    'fee_tax_treatment_id', v_fee_treatment_id,
    'fee_tax_profile_id', v_fee_tax_profile_id,
    'fee_tax_code', v_fee_tax_code,
    'fee_tax_rate', v_fee_tax_rate,
    'tax_authority_status', 'VERSIONED_FEE_TREATMENT'
  )::text, 'UTF8')), 'hex');

  select * into v_existing
  from public.fixed_monthly_daily_accruals a
  where a.company_id = p_company_id
    and a.agreement_version_id = p_agreement_version_id
    and a.accrual_date = p_economic_date;

  if found then
    if v_existing.source_fingerprint <> v_fingerprint
       or v_existing.net_amount <> v_net
       or v_existing.tax_amount <> v_tax
       or v_existing.gross_amount <> v_gross
       or v_existing.fee_tax_treatment_id is distinct from v_fee_treatment_id
       or v_existing.fee_tax_profile_id is distinct from v_fee_tax_profile_id
       or v_existing.fee_tax_rate is distinct from v_fee_tax_rate then
      raise exception 'FIXED_MONTHLY_ACCRUAL_SOURCE_CONFLICT' using errcode = '23505';
    end if;

    select * into v_reversal
    from public.fixed_monthly_daily_accrual_reversals r
    where r.accrual_id = v_existing.id;

    return jsonb_build_object(
      'success', true,
      'created', false,
      'idempotent', true,
      'accrual_id', v_existing.id,
      'agreement_version_id', v_existing.agreement_version_id,
      'accrual_date', v_existing.accrual_date,
      'net_amount', v_existing.net_amount,
      'tax_amount', v_existing.tax_amount,
      'gross_amount', v_existing.gross_amount,
      'journal_batch_id', v_existing.journal_batch_id,
      'status', case
        when v_reversal.id is not null then 'REVERSED'
        when v_existing.journal_batch_id is null then 'ZERO_AMOUNT'
        else 'POSTED'
      end,
      'reversal_batch_id', v_reversal.reversal_journal_batch_id
    );
  end if;

  v_accrual_id := gen_random_uuid();

  if v_net > 0 then
    v_due_from_owner_id := public.gl_pm_require_account(p_company_id, '1300');
    v_revenue_id := public.gl_pm_require_account(p_company_id, '4100');
    if v_tax > 0 then
      v_vat_id := public.gl_pm_require_account(p_company_id, '2100');
    end if;

    v_post_result := public.post_journal_event(jsonb_build_object(
      'company_id', p_company_id,
      'source_type', 'pm_fixed_monthly_daily_accrual',
      'source_id', v_accrual_id::text,
      'event_id', 'DAILY-ACCRUAL',
      'effective_date', p_economic_date,
      'description', 'FIXED_MONTHLY daily accrual for frozen agreement version ' || p_agreement_version_id::text,
      'lines', jsonb_build_array(
        jsonb_build_object(
          'account_id', v_due_from_owner_id,
          'debit', v_gross,
          'credit', 0,
          'line_description', 'Daily management fee due from owner',
          'ref_source_id', v_accrual_id::text,
          'ref_entity_type', 'fixed_monthly_daily_accrual',
          'ref_entity_id', v_accrual_id::text
        ),
        jsonb_build_object(
          'account_id', v_revenue_id,
          'debit', 0,
          'credit', v_net,
          'line_description', 'Daily management fee revenue',
          'ref_source_id', v_accrual_id::text,
          'ref_entity_type', 'fixed_monthly_daily_accrual',
          'ref_entity_id', v_accrual_id::text
        )
      ) || case when v_tax > 0 then jsonb_build_array(
        jsonb_build_object(
          'account_id', v_vat_id,
          'debit', 0,
          'credit', v_tax,
          'line_description', 'Daily management fee VAT',
          'ref_source_id', v_accrual_id::text,
          'ref_entity_type', 'fixed_monthly_daily_accrual',
          'ref_entity_id', v_accrual_id::text
        )
      ) else '[]'::jsonb end
    ));
    v_batch_id := (v_post_result->>'batch_id')::uuid;
  end if;

  insert into public.fixed_monthly_daily_accruals (
    id, company_id, owner_agreement_id, agreement_version_id, owner_id, property_id,
    accrual_date, agreement_starts_on, agreement_ends_on,
    version_effective_from, version_effective_to,
    monthly_contract_amount, monthly_amount_omr, calendar_days, calendar_day,
    rounding_rule, net_amount, tax_amount, gross_amount, tax_authority_status,
    fee_tax_treatment_id, fee_tax_profile_id, fee_tax_code, fee_tax_rate,
    journal_batch_id, source_fingerprint, executed_by
  ) values (
    v_accrual_id, p_company_id, v_owner_agreement_id, p_agreement_version_id, v_owner_id, v_property_id,
    p_economic_date, v_agreement_start, v_agreement_end,
    v_version_start, v_version_end,
    v_monthly_contract, v_monthly_omr, v_calendar_days, v_calendar_day,
    'EARLIEST_DAYS_PLUS_ONE_BAISA', v_net, v_tax, v_gross,
    case when v_net > 0 then 'VERSIONED_FEE_TREATMENT' else 'VERSIONED_FEE_TREATMENT' end,
    v_fee_treatment_id, v_fee_tax_profile_id, v_fee_tax_code, v_fee_tax_rate,
    v_batch_id, v_fingerprint, p_actor_id
  );

  return jsonb_build_object(
    'success', true,
    'created', true,
    'idempotent', false,
    'accrual_id', v_accrual_id,
    'agreement_version_id', p_agreement_version_id,
    'accrual_date', p_economic_date,
    'net_amount', v_net,
    'tax_amount', v_tax,
    'gross_amount', v_gross,
    'journal_batch_id', v_batch_id,
    'status', case when v_batch_id is null then 'ZERO_AMOUNT' else 'POSTED' end,
    'period_resolution_reason', v_post_result->>'period_resolution_reason'
  );
end;
$$;


ALTER FUNCTION "public"."gl_accrue_fixed_monthly_day"("p_company_id" "uuid", "p_agreement_version_id" "uuid", "p_economic_date" "date", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_assert_batch_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch_id uuid;
  v_status text;
  v_debit_total numeric;
  v_credit_total numeric;
begin
  -- The function backs two constraint triggers: on journal_lines (row carries
  -- batch_id) and on journal_batches (row carries id).
  if tg_op in ('INSERT', 'UPDATE') then
    if tg_table_name = 'journal_batches' then
      v_batch_id := new.id;
    else
      v_batch_id := new.batch_id;
    end if;
  else
    if tg_table_name = 'journal_batches' then
      v_batch_id := old.id;
    else
      v_batch_id := old.batch_id;
    end if;
  end if;

  select b.status into v_status
    from public.journal_batches b
   where b.id = v_batch_id;

  if v_status is null or v_status = 'DRAFT' then
    return null;
  end if;

  select round(coalesce(sum(debit), 0), 3), round(coalesce(sum(credit), 0), 3)
    into v_debit_total, v_credit_total
    from public.journal_lines
   where batch_id = v_batch_id
     and deleted_at is null;

  if v_debit_total <> v_credit_total then
    raise exception 'JOURNAL_BATCH_UNBALANCED: batch % has debits % and credits % after three-decimal rounding. A posted batch must balance exactly.', v_batch_id, v_debit_total, v_credit_total
      using errcode = 'P0001';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."gl_assert_batch_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_create_journal_batch"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_source_type text;
  v_source_id text;
  v_event_id text;
  v_effective_date date;
  v_description text;
  v_lines jsonb;
  v_normalized jsonb;
  v_batch_id uuid;
  v_debit_total numeric;
  v_credit_total numeric;
begin
  if current_user not in ('postgres', 'supabase_admin', 'service_role') then
    raise exception 'GL_ENGINE_SERVER_ONLY: the posting engine is only callable from a trusted server context.' using errcode = '42501';
  end if;

  v_company_id := nullif(p_payload->>'company_id', '')::uuid;
  v_source_type := nullif(btrim(coalesce(p_payload->>'source_type', '')), '');
  v_source_id := nullif(btrim(coalesce(p_payload->>'source_id', '')), '');
  v_event_id := nullif(btrim(coalesce(p_payload->>'event_id', '')), '');
  v_effective_date := nullif(p_payload->>'effective_date', '')::date;
  v_description := nullif(p_payload->>'description', '');
  v_lines := p_payload->'lines';

  if v_company_id is null or v_source_type is null or v_source_id is null or v_event_id is null or v_effective_date is null then
    raise exception 'GL_BATCH_METADATA_REQUIRED: company_id, source_type, source_id, event_id and effective_date are required.' using errcode = '22023';
  end if;

  v_normalized := public.gl_validate_and_normalize_lines(v_company_id, v_lines);

  select round(coalesce(sum((l->>'debit')::numeric), 0), 3),
         round(coalesce(sum((l->>'credit')::numeric), 0), 3)
    into v_debit_total, v_credit_total
    from jsonb_array_elements(v_normalized) l;

  if v_debit_total <> v_credit_total then
    raise exception 'JOURNAL_BATCH_UNBALANCED: debits % do not equal credits % after three-decimal rounding.', v_debit_total, v_credit_total using errcode = 'P0001';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('gl_event:' || v_company_id::text || ':' || v_source_type || ':' || v_source_id || ':' || v_event_id, 0));

  insert into public.journal_batches (
    company_id, status, source_type, source_id, event_id,
    effective_date, description, created_by, updated_at
  ) values (
    v_company_id, 'DRAFT', v_source_type, v_source_id, v_event_id,
    v_effective_date, v_description, auth.uid(), now()
  )
  on conflict (company_id, source_type, source_id, event_id) do nothing;

  select id into v_batch_id
    from public.journal_batches
   where company_id = v_company_id
     and source_type = v_source_type
     and source_id = v_source_id
     and event_id = v_event_id;

  if v_batch_id is null then
    raise exception 'GL_BATCH_CREATE_FAILED: could not create the journal batch.' using errcode = 'P0001';
  end if;

  insert into public.journal_lines (
    id, no, batch_id, company_id, account_id, debit, credit,
    line_description, ref_source_id, ref_entity_type, ref_entity_id, created_at
  )
  select
    gen_random_uuid()::text, null, v_batch_id, v_company_id,
    l->>'account_id', (l->>'debit')::numeric, (l->>'credit')::numeric,
    l->>'line_description', l->>'ref_source_id', l->>'ref_entity_type', l->>'ref_entity_id',
    now()
  from jsonb_array_elements(v_normalized) l
  -- Idempotent create: when the event already produced a DRAFT batch (a retry
  -- of create-then-post), never duplicate its lines.
  where not exists (
    select 1 from public.journal_lines x where x.batch_id = v_batch_id
  );

  return jsonb_build_object(
    'success', true,
    'idempotent', false,
    'batch_id', v_batch_id,
    'status', 'DRAFT',
    'effective_date', v_effective_date,
    'line_count', jsonb_array_length(v_normalized),
    'debits', v_debit_total,
    'credits', v_credit_total
  );
end;
$$;


ALTER FUNCTION "public"."gl_create_journal_batch"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_derive_posting_metadata"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_period_start date;
begin
  if new.status = 'POSTED' and new.accounting_period_id is not null then
    select p.start_date
      into v_period_start
      from public.accounting_periods p
     where p.id = new.accounting_period_id
       and p.company_id = new.company_id;

    if v_period_start is null then
      raise exception 'GL_POSTING_PERIOD_SCOPE: accounting period % is missing or outside company %.',
        new.accounting_period_id, new.company_id
        using errcode = '22023';
    end if;

    new.late_posting := coalesce(
      new.period_resolution_reason = 'redirected_earliest_open_period',
      false
    );
    new.posting_date := case
      when new.late_posting then v_period_start
      else new.effective_date
    end;
  elsif new.status = 'POSTED' then
    -- Transitional legacy/compatibility batches deliberately do not participate
    -- in accounting-period resolution. They must still satisfy the NOT NULL
    -- storage contract without masquerading as period-resolved postings.
    new.late_posting := false;
    new.posting_date := null;
  else
    new.late_posting := false;
    new.posting_date := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."gl_derive_posting_metadata"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gl_derive_posting_metadata"() IS 'Derives canonical posting_date/late_posting for period-resolved POSTED batches, treating an absent resolution reason as not-late, and normalizes legacy POSTED/no-period batches to late_posting=false with no posting_date.';



CREATE OR REPLACE FUNCTION "public"."gl_diagnose_historical_financial_integrity"() RETURNS TABLE("company_id" "uuid", "category" "text", "finding" "text", "entity_id" "text", "details" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
begin
  -- 1. Check duplicate settlement usage
  return query
  select v_company_id,
         'duplicate_settlement_payment'::text,
         'Payment included in multiple active settlements'::text,
         p.payment_id::text,
         jsonb_build_object('settlement_count', count(*), 'settlements', jsonb_agg(p.settlement_id))
    from public.owner_settlement_payment_links p
   where p.company_id = v_company_id and p.released_at is null
   group by p.payment_id
  having count(*) > 1;

  -- 2. Check owner expenses incorrectly charged to 6100
  return query
  select v_company_id,
         'owner_expense_classification'::text,
         'Owner expense recorded as company expense'::text,
         e.id::text,
         jsonb_build_object('amount', e.amount, 'category', e.category, 'charged_to', e.charged_to)
    from public.expenses e
   where e.company_id = v_company_id
     and e.deleted_at is null
     and upper(coalesce(e.charged_to, '')) = 'OWNER'
     and exists (
       select 1 from public.journal_lines l
       join public.accounts a on a.id = l.account_id
       where l.ref_source_id = e.id::text and a.no = '6100'
     );

  -- 3. Check orphan journal batches (source entity missing or deleted)
  return query
  select v_company_id,
         'orphan_journal_batch'::text,
         'Journal batch source entity does not exist or is deleted'::text,
         b.id::text,
         jsonb_build_object('source_type', b.source_type, 'source_id', b.source_id)
    from public.journal_batches b
   where b.company_id = v_company_id
     and b.source_type in ('receipt', 'pm_collection_oic', 'pm_collection_ofc')
     and not exists (
       select 1 from public.receipts r where r.id::text = b.source_id::text and r.company_id = v_company_id
     );
end;
$$;


ALTER FUNCTION "public"."gl_diagnose_historical_financial_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ensure_initial_open_period"("p_company_id" "uuid", "p_anchor_date" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_existing_id uuid;
  v_period_id uuid;
  v_start date;
  v_end date;
begin
  if p_company_id is null or p_anchor_date is null then
    raise exception 'company_id and anchor_date are required to provision the initial accounting period.'
      using errcode = '22023';
  end if;

  if not exists (select 1 from public.companies c where c.id = p_company_id) then
    raise exception 'Company % does not exist.', p_company_id using errcode = 'P0002';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('initial_accounting_period:' || p_company_id::text, 0)
  );

  -- Never invent or reshape periods once accounting-period governance has begun.
  select p.id into v_existing_id
    from public.accounting_periods p
   where p.company_id = p_company_id
   order by p.start_date, p.id
   limit 1;

  if v_existing_id is not null then
    return v_existing_id;
  end if;

  v_start := date_trunc('month', p_anchor_date)::date;
  v_end := (date_trunc('month', p_anchor_date) + interval '1 month' - interval '1 day')::date;

  insert into public.accounting_periods (
    company_id, name, start_date, end_date, status, created_by, created_at, updated_at
  ) values (
    p_company_id,
    to_char(v_start, 'YYYY-MM'),
    v_start,
    v_end,
    'OPEN',
    auth.uid(),
    now(),
    now()
  )
  returning id into v_period_id;

  return v_period_id;
end;
$$;


ALTER FUNCTION "public"."gl_ensure_initial_open_period"("p_company_id" "uuid", "p_anchor_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gl_ensure_initial_open_period"("p_company_id" "uuid", "p_anchor_date" "date") IS 'Stage S03 internal bootstrap: creates the first monthly OPEN accounting period only when a company has zero periods; never modifies existing period governance.';



CREATE OR REPLACE FUNCTION "public"."gl_lines_fingerprint"("p_lines" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select encode(sha256(convert_to(
    (select jsonb_agg(
      jsonb_build_object(
        'a', l->>'account_id',
        'd', coalesce((l->>'debit')::numeric, 0),
        'c', coalesce((l->>'credit')::numeric, 0)
      ) order by l->>'account_id', coalesce((l->>'debit')::numeric, 0), coalesce((l->>'credit')::numeric, 0)
    ) from jsonb_array_elements(p_lines) l)::text, 'UTF8')), 'hex')
$$;


ALTER FUNCTION "public"."gl_lines_fingerprint"("p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_create_initial_measurement"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := nullif(p_payload->>'company_id','')::uuid;
  v_agreement uuid := nullif(p_payload->>'owner_agreement_id','')::uuid;
  v_request text := nullif(p_payload->>'request_id','');
  v_effective date := nullif(p_payload->>'effective_date','')::date;
  v_ppy integer := coalesce(nullif(p_payload->>'periods_per_year','')::integer,12);
  v_bps numeric := coalesce(nullif(p_payload->>'annual_discount_rate_bps','')::numeric,0);
  v_direct numeric := round(coalesce(nullif(p_payload->>'initial_direct_costs','')::numeric,0),3);
  v_incentives numeric := round(coalesce(nullif(p_payload->>'lease_incentives','')::numeric,0),3);
  v_prepay numeric := round(coalesce(nullif(p_payload->>'prepayments','')::numeric,0),3);
  v_short boolean := coalesce((p_payload->>'short_term_exempt')::boolean,false);
  v_payments jsonb := p_payload->'payments';
  v_measure jsonb;
  v_liability numeric;
  v_rou numeric;
  v_rate numeric;
  v_periods integer;
  v_id uuid;
  v_fingerprint text := md5((p_payload - 'company_id')::text);
  v_existing public.master_lease_measurements%rowtype;
begin
  if v_company is null or v_agreement is null or v_request is null or v_effective is null then
    raise exception 'GL_ML_INITIAL_METADATA_REQUIRED' using errcode = '22023';
  end if;
  if least(v_direct,v_incentives,v_prepay) < 0 then
    raise exception 'GL_ML_INITIAL_ADJUSTMENTS_INVALID' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('master-lease:'||v_company::text||':'||v_agreement::text,0));

  select * into v_existing
  from public.master_lease_measurements
  where company_id = v_company and request_id = v_request;
  if found then
    if v_existing.input_fingerprint <> v_fingerprint then
      raise exception 'GL_ML_REQUEST_CONFLICT' using errcode = '23505';
    end if;
    return jsonb_build_object('measurement_id',v_existing.id,'idempotent',true,'status',v_existing.status);
  end if;

  if not exists (
    select 1 from public.owner_agreements oa
    where oa.id = v_agreement
      and oa.company_id = v_company
      and oa.agreement_type = 'master_lease'
  ) then
    raise exception 'GL_ML_AGREEMENT_NOT_FOUND_OR_NOT_MASTER_LEASE' using errcode = '42501';
  end if;

  if exists (select 1 from public.master_lease_measurements where owner_agreement_id = v_agreement) then
    raise exception 'GL_ML_INITIAL_ALREADY_EXISTS' using errcode = '23505';
  end if;

  perform public.gl_ml_provision_supporting_accounts(v_company);
  v_measure := public.gl_ml_measure_payments(v_payments,v_bps,v_ppy);
  v_periods := (v_measure->>'max_period')::integer;
  v_rate := (v_measure->>'periodic_rate')::numeric;

  if v_short then
    if v_periods > v_ppy then
      raise exception 'GL_ML_SHORT_TERM_EXEMPTION_TERM_EXCEEDS_12_MONTHS' using errcode = '22023';
    end if;
    v_liability := 0;
    v_rou := 0;
  else
    v_liability := round((v_measure->>'initial_liability')::numeric,3);
    v_rou := round(v_liability + v_direct + v_prepay - v_incentives,3);
    if v_rou < 0 then
      raise exception 'GL_ML_INITIAL_ROU_NEGATIVE' using errcode = '22023';
    end if;
  end if;

  insert into public.master_lease_measurements(
    company_id,owner_agreement_id,version_no,measurement_type,status,
    effective_date,periods_per_year,periods_count,annual_discount_rate_bps,
    periodic_rate,short_term_exempt,initial_direct_costs,lease_incentives,
    prepayments,initial_liability,initial_rou_asset,request_id,input_fingerprint,
    input_payload,created_by
  ) values (
    v_company,v_agreement,1,'INITIAL','DRAFT',v_effective,v_ppy,v_periods,v_bps,
    v_rate,v_short,v_direct,v_incentives,v_prepay,v_liability,v_rou,v_request,
    v_fingerprint,p_payload,auth.uid()
  ) returning id into v_id;

  perform public.gl_ml_insert_schedule_rows(
    v_id,v_company,v_effective,v_payments,v_ppy,v_rate,v_liability,v_rou,v_short
  );

  return jsonb_build_object(
    'measurement_id',v_id,'idempotent',false,'status','DRAFT',
    'short_term_exempt',v_short,'initial_liability',v_liability,
    'initial_rou_asset',v_rou,'periods_count',v_periods
  );
end;
$$;


ALTER FUNCTION "public"."gl_ml_create_initial_measurement"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_create_remeasurement"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := nullif(p_payload->>'company_id','')::uuid;
  v_agreement uuid := nullif(p_payload->>'owner_agreement_id','')::uuid;
  v_request text := nullif(p_payload->>'request_id','');
  v_effective date := nullif(p_payload->>'effective_date','')::date;
  v_ppy integer := coalesce(nullif(p_payload->>'periods_per_year','')::integer,12);
  v_bps numeric := coalesce(nullif(p_payload->>'annual_discount_rate_bps','')::numeric,0);
  v_scope integer := coalesce(nullif(p_payload->>'scope_reduction_bps','')::integer,0);
  v_payments jsonb := coalesce(p_payload->'payments','[]'::jsonb);
  v_fingerprint text := md5((p_payload - 'company_id')::text);
  v_old public.master_lease_measurements%rowtype;
  v_existing public.master_lease_measurements%rowtype;
  v_last public.master_lease_schedule_rows%rowtype;
  v_measure jsonb;
  v_new_liability numeric := 0;
  v_new_rou numeric := 0;
  v_rate numeric := 0;
  v_periods integer := 0;
  v_carry_liability numeric;
  v_carry_rou numeric;
  v_liab_derec numeric;
  v_rou_derec numeric;
  v_remaining_liability numeric;
  v_delta_after_reduction numeric;
  v_liability_delta numeric;
  v_rou_adjustment numeric;
  v_gain_loss numeric;
  v_type text;
  v_new_id uuid;
  v_version integer;
begin
  if v_company is null or v_agreement is null or v_request is null or v_effective is null
     or v_scope < 0 or v_scope > 10000
     or v_ppy not in (1,2,3,4,6,12)
     or v_bps < 0 then
    raise exception 'GL_ML_REMEASUREMENT_METADATA_INVALID' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('master-lease:'||v_company::text||':'||v_agreement::text,0));

  select * into v_existing
  from public.master_lease_measurements
  where company_id=v_company and request_id=v_request;
  if found then
    if v_existing.input_fingerprint <> v_fingerprint then
      raise exception 'GL_ML_REQUEST_CONFLICT' using errcode='23505';
    end if;
    return jsonb_build_object('measurement_id',v_existing.id,'idempotent',true,'status',v_existing.status);
  end if;

  select * into v_old
  from public.master_lease_measurements
  where company_id=v_company
    and owner_agreement_id=v_agreement
    and status='ACTIVE'
  for update;
  if not found then raise exception 'GL_ML_ACTIVE_MEASUREMENT_NOT_FOUND' using errcode='P0002'; end if;
  if v_old.short_term_exempt then raise exception 'GL_ML_SHORT_TERM_REMEASUREMENT_NOT_APPLICABLE' using errcode='22023'; end if;
  if v_effective <= v_old.effective_date then raise exception 'GL_ML_RETROACTIVE_REMEASUREMENT_FORBIDDEN' using errcode='22023'; end if;
  if exists (select 1 from public.master_lease_measurements where owner_agreement_id=v_agreement and status='DRAFT') then
    raise exception 'GL_ML_DRAFT_ALREADY_EXISTS' using errcode='23505';
  end if;

  if not exists (
    select 1 from public.master_lease_schedule_rows r
    where r.measurement_id=v_old.id
      and r.company_id=v_company
      and r.due_date=v_effective
      and r.posted_at is not null
      and r.superseded_at is null
  ) then
    raise exception 'GL_ML_REMEASUREMENT_REQUIRES_POSTED_PERIOD_BOUNDARY' using errcode='22023';
  end if;

  if exists (
    select 1 from public.master_lease_schedule_rows r
    where r.measurement_id=v_old.id
      and r.company_id=v_company
      and r.due_date <= v_effective
      and r.superseded_at is null
      and r.posted_at is null
  ) then
    raise exception 'GL_ML_PRIOR_DUE_PERIOD_UNPOSTED' using errcode='22023';
  end if;

  if exists (
    select 1 from public.master_lease_schedule_rows r
    where r.measurement_id=v_old.id
      and r.company_id=v_company
      and r.due_date > v_effective
      and r.posted_at is not null
  ) then
    raise exception 'GL_ML_RETROACTIVE_REMEASUREMENT_POSTED_FUTURE_EXISTS' using errcode='22023';
  end if;

  select * into v_last
  from public.master_lease_schedule_rows
  where measurement_id=v_old.id
    and company_id=v_company
    and due_date=v_effective
    and posted_at is not null
  order by period_no desc
  limit 1;

  v_carry_liability := v_last.closing_liability;
  v_carry_rou := v_last.closing_rou_asset;

  if v_scope = 10000 then
    if jsonb_typeof(v_payments) <> 'array' or jsonb_array_length(v_payments) <> 0 then
      raise exception 'GL_ML_FULL_TERMINATION_REVISED_PAYMENTS_FORBIDDEN' using errcode='22023';
    end if;
    v_type := 'FULL_TERMINATION';
  else
    v_measure := public.gl_ml_measure_payments(v_payments,v_bps,v_ppy);
    v_new_liability := round((v_measure->>'initial_liability')::numeric,3);
    v_rate := (v_measure->>'periodic_rate')::numeric;
    v_periods := (v_measure->>'max_period')::integer;
  end if;

  v_liab_derec := round(v_carry_liability * v_scope / 10000,3);
  v_rou_derec := round(v_carry_rou * v_scope / 10000,3);
  v_remaining_liability := round(v_carry_liability - v_liab_derec,3);
  v_delta_after_reduction := round(v_new_liability - v_remaining_liability,3);
  v_new_rou := case
    when v_scope=10000 then 0
    else round(v_carry_rou - v_rou_derec + v_delta_after_reduction,3)
  end;
  if v_new_rou < 0 then
    raise exception 'GL_ML_REMEASUREMENT_ROU_NEGATIVE' using errcode='22023';
  end if;

  if v_scope=0 then v_type := 'REMEASUREMENT';
  elsif v_scope<10000 then v_type := 'PARTIAL_TERMINATION';
  end if;

  v_gain_loss := round(v_liab_derec - v_rou_derec,3);
  v_liability_delta := round(v_new_liability - v_carry_liability,3);
  v_rou_adjustment := case
    when v_scope=10000 then -v_carry_rou
    else round(-v_rou_derec + v_delta_after_reduction,3)
  end;

  if v_liability_delta=0 and v_rou_adjustment=0 and v_gain_loss=0 then
    raise exception 'GL_ML_REMEASUREMENT_NO_FINANCIAL_CHANGE' using errcode='22023';
  end if;

  select coalesce(max(version_no),0)+1
    into v_version
  from public.master_lease_measurements
  where owner_agreement_id=v_agreement;

  perform public.gl_ml_provision_supporting_accounts(v_company);

  insert into public.master_lease_measurements(
    company_id,owner_agreement_id,version_no,measurement_type,status,
    supersedes_measurement_id,effective_date,periods_per_year,periods_count,
    annual_discount_rate_bps,periodic_rate,short_term_exempt,
    initial_liability,initial_rou_asset,carrying_liability_before,
    carrying_rou_before,liability_delta,rou_adjustment,termination_gain_loss,
    scope_reduction_bps,request_id,input_fingerprint,input_payload,created_by
  ) values (
    v_company,v_agreement,v_version,v_type,'DRAFT',v_old.id,v_effective,v_ppy,
    v_periods,v_bps,v_rate,false,v_new_liability,v_new_rou,v_carry_liability,
    v_carry_rou,v_liability_delta,v_rou_adjustment,v_gain_loss,v_scope,v_request,
    v_fingerprint,p_payload,auth.uid()
  ) returning id into v_new_id;

  if v_scope < 10000 then
    perform public.gl_ml_insert_schedule_rows(
      v_new_id,v_company,v_effective,v_payments,v_ppy,v_rate,
      v_new_liability,v_new_rou,false
    );
  end if;

  return jsonb_build_object(
    'measurement_id',v_new_id,
    'supersedes_measurement_id',v_old.id,
    'idempotent',false,
    'measurement_type',v_type,
    'status','DRAFT',
    'carrying_liability_before',v_carry_liability,
    'carrying_rou_before',v_carry_rou,
    'initial_liability',v_new_liability,
    'initial_rou_asset',v_new_rou,
    'liability_delta',v_liability_delta,
    'rou_adjustment',v_rou_adjustment,
    'termination_gain_loss',v_gain_loss
  );
end;
$$;


ALTER FUNCTION "public"."gl_ml_create_remeasurement"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_insert_schedule_rows"("p_measurement_id" "uuid", "p_company_id" "uuid", "p_effective_date" "date", "p_payments" "jsonb", "p_periods_per_year" integer, "p_periodic_rate" numeric, "p_initial_liability" numeric, "p_initial_rou" numeric, "p_short_term_exempt" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_max integer;
  v_period integer;
  v_months integer := 12 / p_periods_per_year;
  v_liability numeric := round(p_initial_liability,3);
  v_rou numeric := round(p_initial_rou,3);
  v_open numeric;
  v_interest numeric;
  v_payment numeric;
  v_principal numeric;
  v_close numeric;
  v_dep numeric;
  v_close_rou numeric;
  v_straight numeric;
begin
  select max((value->>'period')::integer)
    into v_max
  from jsonb_array_elements(p_payments);

  if v_max is null or v_max <= 0 then
    raise exception 'GL_ML_SCHEDULE_PERIODS_REQUIRED' using errcode = '22023';
  end if;

  v_straight := p_initial_rou / v_max;

  for v_period in 1..v_max loop
    select round((value->>'amount')::numeric,3)
      into v_payment
    from jsonb_array_elements(p_payments)
    where (value->>'period')::integer = v_period
    limit 1;
    v_payment := coalesce(v_payment,0);

    if p_short_term_exempt then
      v_open := 0;
      v_interest := 0;
      v_principal := v_payment;
      v_close := 0;
      v_dep := 0;
      v_close_rou := 0;
    else
      v_open := v_liability;
      v_interest := round(v_open * p_periodic_rate,3);
      if v_period = v_max then
        v_payment := round(v_open + v_interest,3);
      end if;
      v_principal := round(v_payment - v_interest,3);
      v_close := round(v_open + v_interest - v_payment,3);
      if v_close < 0 then
        raise exception 'GL_ML_PAYMENT_OVER_SETTLES' using errcode = '22023';
      end if;

      v_dep := case
        when v_period = v_max then v_rou
        else least(v_rou,round(v_straight,3))
      end;
      v_close_rou := greatest(0,round(v_rou - v_dep,3));
    end if;

    insert into public.master_lease_schedule_rows(
      measurement_id,company_id,period_no,due_date,
      opening_liability,interest_amount,payment_amount,principal_amount,
      closing_liability,rou_depreciation,closing_rou_asset
    ) values (
      p_measurement_id,p_company_id,v_period,
      (p_effective_date + make_interval(months => v_months * v_period))::date,
      v_open,v_interest,v_payment,v_principal,v_close,v_dep,v_close_rou
    );

    if not p_short_term_exempt then
      v_liability := v_close;
      v_rou := v_close_rou;
    end if;
  end loop;

  return v_max;
end;
$$;


ALTER FUNCTION "public"."gl_ml_insert_schedule_rows"("p_measurement_id" "uuid", "p_company_id" "uuid", "p_effective_date" "date", "p_payments" "jsonb", "p_periods_per_year" integer, "p_periodic_rate" numeric, "p_initial_liability" numeric, "p_initial_rou" numeric, "p_short_term_exempt" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_measure_payments"("p_payments" "jsonb", "p_annual_discount_rate_bps" numeric, "p_periods_per_year" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_item jsonb;
  v_period integer;
  v_amount numeric;
  v_seen integer[] := '{}'::integer[];
  v_max integer := 0;
  v_rate numeric;
  v_pv numeric := 0;
  v_positive integer := 0;
begin
  if p_payments is null or jsonb_typeof(p_payments) <> 'array' or jsonb_array_length(p_payments) = 0 then
    raise exception 'GL_ML_PAYMENTS_REQUIRED' using errcode = '22023';
  end if;
  if p_periods_per_year not in (1,2,3,4,6,12) then
    raise exception 'GL_ML_PERIODS_PER_YEAR_INVALID' using errcode = '22023';
  end if;
  if p_annual_discount_rate_bps is null or p_annual_discount_rate_bps < 0
     or p_annual_discount_rate_bps::text in ('NaN','Infinity','-Infinity') then
    raise exception 'GL_ML_DISCOUNT_RATE_INVALID' using errcode = '22023';
  end if;

  v_rate := p_annual_discount_rate_bps / 10000 / p_periods_per_year;

  for v_item in select value from jsonb_array_elements(p_payments) loop
    begin
      v_period := nullif(v_item->>'period','')::integer;
      v_amount := round(nullif(v_item->>'amount','')::numeric,3);
    exception when others then
      raise exception 'GL_ML_PAYMENT_INVALID' using errcode = '22023';
    end;

    if v_period is null or v_period <= 0 or v_period = any(v_seen) then
      raise exception 'GL_ML_PAYMENT_PERIOD_INVALID_OR_DUPLICATE' using errcode = '22023';
    end if;
    if v_amount is null or v_amount < 0 or v_amount::text in ('NaN','Infinity','-Infinity') then
      raise exception 'GL_ML_PAYMENT_AMOUNT_INVALID' using errcode = '22023';
    end if;

    v_seen := array_append(v_seen,v_period);
    v_max := greatest(v_max,v_period);
    if v_amount > 0 then v_positive := v_positive + 1; end if;
    v_pv := v_pv + (v_amount / power(1 + v_rate,v_period));
  end loop;

  if v_positive = 0 then
    raise exception 'GL_ML_PAYMENTS_ALL_ZERO' using errcode = '22023';
  end if;

  return jsonb_build_object(
    'initial_liability',round(v_pv,3),
    'max_period',v_max,
    'periodic_rate',v_rate
  );
end;
$$;


ALTER FUNCTION "public"."gl_ml_measure_payments"("p_payments" "jsonb", "p_annual_discount_rate_bps" numeric, "p_periods_per_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_post_initial_recognition"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := nullif(p_payload->>'company_id','')::uuid;
  v_measurement_id uuid := nullif(p_payload->>'measurement_id','')::uuid;
  v_cash_no text := coalesce(nullif(p_payload->>'cash_account_no',''),'1120');
  v_m public.master_lease_measurements%rowtype;
  v_rou_id text;
  v_liability_id text;
  v_cash_id text;
  v_diff numeric;
  v_lines jsonb;
  v_batch jsonb;
begin
  if v_company is null or v_measurement_id is null or v_cash_no not in ('1111','1120') then
    raise exception 'GL_ML_INITIAL_POST_METADATA_INVALID' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('master-lease-measurement:'||v_measurement_id::text,0));
  select * into v_m
  from public.master_lease_measurements
  where id = v_measurement_id and company_id = v_company
  for update;

  if not found then raise exception 'GL_ML_MEASUREMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_m.measurement_type <> 'INITIAL' then raise exception 'GL_ML_NOT_INITIAL_MEASUREMENT' using errcode = '22023'; end if;
  if v_m.status = 'ACTIVE' then
    return jsonb_build_object('measurement_id',v_m.id,'status','ACTIVE','idempotent',true);
  end if;
  if v_m.status <> 'DRAFT' then raise exception 'GL_ML_INITIAL_STATUS_INVALID' using errcode = '22023'; end if;

  if v_m.short_term_exempt then
    update public.master_lease_measurements
       set status='ACTIVE',posted_at=now()
     where id=v_m.id and company_id=v_company;
    return jsonb_build_object('measurement_id',v_m.id,'status','ACTIVE','short_term_exempt',true,'batch',null);
  end if;

  perform public.gl_ml_provision_supporting_accounts(v_company);
  v_rou_id := public.require_company_account_id(v_company,'1600');
  v_liability_id := public.require_company_account_id(v_company,'2500');
  v_cash_id := public.require_company_account_id(v_company,v_cash_no);
  v_diff := round(v_m.initial_rou_asset - v_m.initial_liability,3);

  v_lines := jsonb_build_array(
    jsonb_build_object('account_id',v_rou_id,'debit',v_m.initial_rou_asset,'credit',0),
    jsonb_build_object('account_id',v_liability_id,'debit',0,'credit',v_m.initial_liability)
  );
  if v_diff > 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id',v_cash_id,'debit',0,'credit',v_diff));
  elsif v_diff < 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id',v_cash_id,'debit',abs(v_diff),'credit',0));
  end if;

  v_batch := public.post_journal_event(jsonb_build_object(
    'company_id',v_company,
    'source_type','master_lease_initial_recognition',
    'source_id',v_m.id::text,
    'event_id','initial-recognition',
    'effective_date',v_m.effective_date,
    'description','Master lease initial recognition',
    'lines',v_lines
  ));

  update public.master_lease_measurements
     set status='ACTIVE',posted_at=now()
   where id=v_m.id and company_id=v_company;

  return jsonb_build_object('measurement_id',v_m.id,'status','ACTIVE','batch',v_batch);
end;
$$;


ALTER FUNCTION "public"."gl_ml_post_initial_recognition"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_post_period"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := nullif(p_payload->>'company_id','')::uuid;
  v_measurement_id uuid := nullif(p_payload->>'measurement_id','')::uuid;
  v_period integer := nullif(p_payload->>'period_no','')::integer;
  v_cash_no text := coalesce(nullif(p_payload->>'cash_account_no',''),'1120');
  v_m public.master_lease_measurements%rowtype;
  v_r public.master_lease_schedule_rows%rowtype;
  v_cash_id text;
  v_liability_id text;
  v_interest_id text;
  v_dep_id text;
  v_rou_id text;
  v_expense_id text;
  v_lines jsonb := '[]'::jsonb;
  v_batch jsonb;
begin
  if v_company is null or v_measurement_id is null or v_period is null or v_period <= 0
     or v_cash_no not in ('1111','1120') then
    raise exception 'GL_ML_PERIOD_METADATA_INVALID' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('master-lease-period:'||v_measurement_id::text||':'||v_period::text,0));
  select * into v_m
  from public.master_lease_measurements
  where id=v_measurement_id and company_id=v_company
  for update;
  if not found then raise exception 'GL_ML_MEASUREMENT_NOT_FOUND' using errcode='P0002'; end if;
  if v_m.status <> 'ACTIVE' then raise exception 'GL_ML_MEASUREMENT_NOT_ACTIVE' using errcode='22023'; end if;

  select * into v_r
  from public.master_lease_schedule_rows
  where measurement_id=v_measurement_id
    and company_id=v_company
    and period_no=v_period
    and superseded_at is null
  for update;
  if not found then raise exception 'GL_ML_PERIOD_NOT_FOUND_OR_SUPERSEDED' using errcode='P0002'; end if;

  if exists (
    select 1 from public.master_lease_schedule_rows r
    where r.measurement_id=v_measurement_id
      and r.company_id=v_company
      and r.period_no < v_period
      and r.superseded_at is null
      and r.posted_at is null
  ) then
    raise exception 'GL_ML_PRIOR_PERIOD_NOT_POSTED' using errcode='22023';
  end if;

  -- Once a remeasurement draft is frozen at a posted boundary, future rows of
  -- the superseded measurement may not advance and make that draft stale.
  if exists (
    select 1 from public.master_lease_measurements d
    where d.company_id=v_company
      and d.owner_agreement_id=v_m.owner_agreement_id
      and d.status='DRAFT'
      and d.supersedes_measurement_id=v_m.id
      and v_r.due_date > d.effective_date
  ) then
    raise exception 'GL_ML_PERIOD_BLOCKED_BY_PENDING_REMEASUREMENT' using errcode='22023';
  end if;

  perform public.gl_ml_provision_supporting_accounts(v_company);
  v_cash_id := public.require_company_account_id(v_company,v_cash_no);

  if v_m.short_term_exempt then
    if v_r.payment_amount > 0 then
      v_expense_id := public.require_company_account_id(v_company,'6100');
      v_lines := jsonb_build_array(
        jsonb_build_object('account_id',v_expense_id,'debit',v_r.payment_amount,'credit',0),
        jsonb_build_object('account_id',v_cash_id,'debit',0,'credit',v_r.payment_amount)
      );
      v_batch := public.post_journal_event(jsonb_build_object(
        'company_id',v_company,
        'source_type','master_lease_short_term_payment',
        'source_id',v_m.id::text,
        'event_id','period:'||v_period::text,
        'effective_date',v_r.due_date,
        'description','Short-term lease payment expense',
        'lines',v_lines
      ));
    end if;
  else
    v_liability_id := public.require_company_account_id(v_company,'2500');
    v_interest_id := public.require_company_account_id(v_company,'6300');
    v_dep_id := public.require_company_account_id(v_company,'6200');
    v_rou_id := public.require_company_account_id(v_company,'1600');

    if v_r.interest_amount > 0 then
      v_lines := v_lines || jsonb_build_array(
        jsonb_build_object('account_id',v_interest_id,'debit',v_r.interest_amount,'credit',0),
        jsonb_build_object('account_id',v_liability_id,'debit',0,'credit',v_r.interest_amount)
      );
    end if;
    if v_r.payment_amount > 0 then
      v_lines := v_lines || jsonb_build_array(
        jsonb_build_object('account_id',v_liability_id,'debit',v_r.payment_amount,'credit',0),
        jsonb_build_object('account_id',v_cash_id,'debit',0,'credit',v_r.payment_amount)
      );
    end if;
    if v_r.rou_depreciation > 0 then
      v_lines := v_lines || jsonb_build_array(
        jsonb_build_object('account_id',v_dep_id,'debit',v_r.rou_depreciation,'credit',0),
        jsonb_build_object('account_id',v_rou_id,'debit',0,'credit',v_r.rou_depreciation)
      );
    end if;

    v_batch := public.post_journal_event(jsonb_build_object(
      'company_id',v_company,
      'source_type','master_lease_period',
      'source_id',v_m.id::text,
      'event_id','period:'||v_period::text,
      'effective_date',v_r.due_date,
      'description','Master lease period '||v_period::text,
      'lines',v_lines
    ));
  end if;

  update public.master_lease_schedule_rows
     set posted_at=coalesce(posted_at,now())
   where id=v_r.id and company_id=v_company;

  return jsonb_build_object(
    'measurement_id',v_m.id,'period_no',v_period,'batch',v_batch,
    'idempotent',v_r.posted_at is not null
  );
end;
$$;


ALTER FUNCTION "public"."gl_ml_post_period"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_post_remeasurement"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := nullif(p_payload->>'company_id','')::uuid;
  v_measurement_id uuid := nullif(p_payload->>'measurement_id','')::uuid;
  v_m public.master_lease_measurements%rowtype;
  v_old public.master_lease_measurements%rowtype;
  v_rou_id text;
  v_liability_id text;
  v_gain_id text;
  v_loss_id text;
  v_lines jsonb := '[]'::jsonb;
  v_batch jsonb;
begin
  if v_company is null or v_measurement_id is null then
    raise exception 'GL_ML_REMEASUREMENT_POST_METADATA_INVALID' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('master-lease-remeasurement-post:'||v_measurement_id::text,0));
  select * into v_m
  from public.master_lease_measurements
  where id=v_measurement_id and company_id=v_company
  for update;
  if not found then raise exception 'GL_ML_MEASUREMENT_NOT_FOUND' using errcode='P0002'; end if;
  if v_m.measurement_type='INITIAL' then raise exception 'GL_ML_NOT_REMEASUREMENT' using errcode='22023'; end if;
  if v_m.status in ('ACTIVE','TERMINATED') and v_m.posted_at is not null then
    return jsonb_build_object('measurement_id',v_m.id,'status',v_m.status,'idempotent',true);
  end if;
  if v_m.status <> 'DRAFT' then raise exception 'GL_ML_REMEASUREMENT_STATUS_INVALID' using errcode='22023'; end if;

  select * into v_old
  from public.master_lease_measurements
  where id=v_m.supersedes_measurement_id
    and company_id=v_company
    and status='ACTIVE'
  for update;
  if not found then raise exception 'GL_ML_SUPERSEDED_ACTIVE_MEASUREMENT_NOT_FOUND' using errcode='P0002'; end if;

  -- Defensive stale-draft check in addition to the post-period blocker.
  if exists (
    select 1 from public.master_lease_schedule_rows r
    where r.measurement_id=v_old.id
      and r.company_id=v_company
      and r.due_date > v_m.effective_date
      and r.posted_at is not null
  ) then
    raise exception 'GL_ML_REMEASUREMENT_DRAFT_STALE' using errcode='22023';
  end if;

  perform public.gl_ml_provision_supporting_accounts(v_company);
  v_rou_id := public.require_company_account_id(v_company,'1600');
  v_liability_id := public.require_company_account_id(v_company,'2500');
  v_gain_id := public.require_company_account_id(v_company,'4400');
  v_loss_id := public.require_company_account_id(v_company,'6400');

  if v_m.rou_adjustment > 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id',v_rou_id,'debit',v_m.rou_adjustment,'credit',0));
  elsif v_m.rou_adjustment < 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id',v_rou_id,'debit',0,'credit',abs(v_m.rou_adjustment)));
  end if;

  if v_m.liability_delta > 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id',v_liability_id,'debit',0,'credit',v_m.liability_delta));
  elsif v_m.liability_delta < 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id',v_liability_id,'debit',abs(v_m.liability_delta),'credit',0));
  end if;

  if v_m.termination_gain_loss > 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id',v_gain_id,'debit',0,'credit',v_m.termination_gain_loss));
  elsif v_m.termination_gain_loss < 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id',v_loss_id,'debit',abs(v_m.termination_gain_loss),'credit',0));
  end if;

  v_batch := public.post_journal_event(jsonb_build_object(
    'company_id',v_company,
    'source_type','master_lease_remeasurement',
    'source_id',v_m.id::text,
    'event_id','remeasurement',
    'effective_date',v_m.effective_date,
    'description','Master lease '||lower(v_m.measurement_type),
    'lines',v_lines
  ));

  update public.master_lease_schedule_rows
     set superseded_at=coalesce(superseded_at,now())
   where measurement_id=v_old.id
     and company_id=v_company
     and due_date > v_m.effective_date
     and posted_at is null;

  if v_m.measurement_type='FULL_TERMINATION' then
    update public.master_lease_measurements
       set status='TERMINATED',superseded_at=now()
     where id=v_old.id and company_id=v_company;
    update public.master_lease_measurements
       set status='TERMINATED',posted_at=now()
     where id=v_m.id and company_id=v_company;
    return jsonb_build_object('measurement_id',v_m.id,'status','TERMINATED','batch',v_batch);
  end if;

  update public.master_lease_measurements
     set status='SUPERSEDED',superseded_at=now()
   where id=v_old.id and company_id=v_company;
  update public.master_lease_measurements
     set status='ACTIVE',posted_at=now()
   where id=v_m.id and company_id=v_company;

  return jsonb_build_object('measurement_id',v_m.id,'status','ACTIVE','batch',v_batch);
end;
$$;


ALTER FUNCTION "public"."gl_ml_post_remeasurement"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_post_sublease_receipt"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := nullif(p_payload->>'company_id','')::uuid;
  v_contract_id text := nullif(p_payload->>'contract_id','');
  v_source_id text := nullif(p_payload->>'source_id','');
  v_amount numeric := round(nullif(p_payload->>'amount','')::numeric,3);
  v_effective date := nullif(p_payload->>'effective_date','')::date;
  v_cash_no text := coalesce(nullif(p_payload->>'cash_account_no',''),'1120');
  v_cash_id text;
  v_revenue_id text;
  v_batch jsonb;
begin
  if v_company is null or v_contract_id is null or v_source_id is null
     or v_effective is null or v_amount is null or v_amount <= 0
     or v_cash_no not in ('1111','1120') then
    raise exception 'GL_ML_SUBLEASE_RECEIPT_METADATA_INVALID' using errcode='22023';
  end if;

  if not exists (
    select 1
    from public.contracts c
    join public.owner_agreements oa on oa.id=c.agreement_id
    where c.id::text=v_contract_id
      and c.company_id=v_company
      and oa.company_id=v_company
      and oa.agreement_type='master_lease'
  ) then
    raise exception 'GL_ML_SUBLEASE_CONTRACT_NOT_MASTER_LEASE_OR_OUTSIDE_COMPANY' using errcode='42501';
  end if;

  v_cash_id := public.require_company_account_id(v_company,v_cash_no);
  v_revenue_id := public.require_company_account_id(v_company,'4000');

  v_batch := public.post_journal_event(jsonb_build_object(
    'company_id',v_company,
    'source_type','master_lease_sublease_receipt',
    'source_id',v_source_id,
    'event_id','collect',
    'effective_date',v_effective,
    'description','Master lease sublease rental revenue',
    'lines',jsonb_build_array(
      jsonb_build_object('account_id',v_cash_id,'debit',v_amount,'credit',0),
      jsonb_build_object('account_id',v_revenue_id,'debit',0,'credit',v_amount)
    )
  ));

  return jsonb_build_object('contract_id',v_contract_id,'amount',v_amount,'batch',v_batch);
end;
$$;


ALTER FUNCTION "public"."gl_ml_post_sublease_receipt"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_ml_provision_supporting_accounts"("p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_created integer := 0;
  v_rows integer := 0;
begin
  if p_company_id is null or not exists (select 1 from public.companies where id = p_company_id) then
    raise exception 'GL_ML_COMPANY_REQUIRED' using errcode = '22023';
  end if;

  insert into public.accounts(
    id,no,name,company_id,account_type,normal_balance,currency_code,precision,is_active,created_at,updated_at
  ) values (
    'coa:'||p_company_id::text||':4400','4400','Lease Modification / Termination Gain',
    p_company_id,'revenue','credit','OMR',3,true,now(),now()
  ) on conflict (company_id,no) do nothing;
  get diagnostics v_rows = row_count;
  v_created := v_created + v_rows;

  insert into public.accounts(
    id,no,name,company_id,account_type,normal_balance,currency_code,precision,is_active,created_at,updated_at
  ) values (
    'coa:'||p_company_id::text||':6400','6400','Lease Modification / Termination Loss',
    p_company_id,'expense','debit','OMR',3,true,now(),now()
  ) on conflict (company_id,no) do nothing;
  get diagnostics v_rows = row_count;
  v_created := v_created + v_rows;

  if exists (
    select 1 from public.accounts a
    where a.company_id = p_company_id and (
      (a.no = '4400' and (a.account_type <> 'revenue' or a.normal_balance <> 'credit' or a.currency_code <> 'OMR' or a.precision <> 3 or not a.is_active)) or
      (a.no = '6400' and (a.account_type <> 'expense' or a.normal_balance <> 'debit' or a.currency_code <> 'OMR' or a.precision <> 3 or not a.is_active))
    )
  ) then
    raise exception 'GL_ML_ACCOUNT_CONTRACT_MISMATCH' using errcode = '22023';
  end if;

  return jsonb_build_object('company_id',p_company_id,'created',v_created);
end;
$$;


ALTER FUNCTION "public"."gl_ml_provision_supporting_accounts"("p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_pm_accrue_fixed_monthly_fee"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id     uuid    := (p_payload->>'company_id')::uuid;
  v_agreement_id   uuid    := (p_payload->>'agreement_id')::uuid;
  v_accrual_period text    := p_payload->>'accrual_period';
  v_accrual_net    numeric := public.gl_pm_round_omr((p_payload->>'accrual_net')::numeric);
  v_vat_amount     numeric := public.gl_pm_round_omr(coalesce((p_payload->>'vat_amount')::numeric, 0));
  v_effective_date date    := (p_payload->>'effective_date')::date;
  v_accrual_gross  numeric;
  v_due_id text;
  v_mfr_id text;
  v_vat_id text;
  v_lines  jsonb;
  v_result jsonb;
begin
  if v_company_id is null then
    raise exception 'GL_PM_ACCRUE: company_id required' using errcode = '22023';
  end if;
  if v_agreement_id is null then
    raise exception 'GL_PM_ACCRUE: agreement_id required' using errcode = '22023';
  end if;
  if v_accrual_period is null or v_accrual_period = '' then
    raise exception 'GL_PM_ACCRUE: accrual_period required (e.g. 2026-08-01/2026-08-31)' using errcode = '22023';
  end if;
  if v_accrual_net is null or v_accrual_net < 0 then
    raise exception 'GL_PM_ACCRUE: accrual_net must be >= 0' using errcode = '22023';
  end if;
  if v_vat_amount < 0 then
    raise exception 'GL_PM_ACCRUE: vat_amount must be >= 0' using errcode = '22023';
  end if;
  if v_effective_date is null then
    raise exception 'GL_PM_ACCRUE: effective_date required' using errcode = '22023';
  end if;

  v_accrual_gross := public.gl_pm_round_omr(v_accrual_net + v_vat_amount);

  v_due_id := public.gl_pm_require_account(v_company_id, '1300');
  v_mfr_id := public.gl_pm_require_account(v_company_id, '4100');
  if v_vat_amount > 0 then
    v_vat_id := public.gl_pm_require_account(v_company_id, '2100');
  end if;

  v_lines := jsonb_build_array(
    jsonb_build_object('account_id', v_due_id, 'debit', v_accrual_gross, 'credit', 0),
    jsonb_build_object('account_id', v_mfr_id, 'debit', 0, 'credit', v_accrual_net)
  );
  if v_vat_amount > 0 then
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object('account_id', v_vat_id, 'debit', 0, 'credit', v_vat_amount)
    );
  end if;

  v_result := public.post_journal_event(jsonb_build_object(
    'company_id',    v_company_id,
    'source_type',   'pm_fixed_monthly_accrual',
    'source_id',     v_agreement_id::text,
    'event_id',      'accrual:' || v_accrual_period,
    'effective_date', v_effective_date,
    'description',   'PM FIXED_MONTHLY DAILY_ACCRUAL: Due from Owner → MFR period ' || v_accrual_period,
    'lines',         v_lines
  ));

  return jsonb_build_object(
    'model',          'FIXED_MONTHLY_DAILY_ACCRUAL',
    'accrual_period', v_accrual_period,
    'accrual_net',    v_accrual_net,
    'vat_amount',     v_vat_amount,
    'accrual_gross',  v_accrual_gross,
    'batch',          v_result
  );
end;
$$;


ALTER FUNCTION "public"."gl_pm_accrue_fixed_monthly_fee"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_pm_list_batches"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("batch_id" "uuid", "source_type" "text", "source_id" "text", "event_id" "text", "status" "text", "effective_date" "date", "posted_at" timestamp with time zone, "description" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
begin
  return query
    select b.id, b.source_type, b.source_id, b.event_id,
           b.status, b.effective_date, b.posted_at, b.description
      from public.journal_batches b
     where b.company_id = v_company_id
       and (b.source_type like 'pm_%' or b.source_type like 'broker_%' or b.source_type = 'receipt')
     order by b.effective_date desc, b.created_at desc
     limit p_limit
     offset p_offset;
end;
$$;


ALTER FUNCTION "public"."gl_pm_list_batches"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_pm_post_broker_commission_approval"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id     uuid    := (p_payload->>'company_id')::uuid;
  v_commission_id  uuid    := (p_payload->>'commission_id')::uuid;
  v_amount         numeric := public.gl_pm_round_omr((p_payload->>'amount')::numeric);
  v_effective_date date    := (p_payload->>'effective_date')::date;
  v_exp_id text;
  v_pay_id text;
  v_result jsonb;
begin
  if v_company_id is null or v_commission_id is null or v_effective_date is null then
    raise exception 'GL_PM_COMM_APPROVE: company_id, commission_id, and effective_date required' using errcode = '22023';
  end if;
  if v_amount is null or v_amount <= 0 then
    raise exception 'GL_PM_COMM_APPROVE: amount must be > 0' using errcode = '22023';
  end if;

  v_exp_id := public.gl_pm_require_account(v_company_id, '6110');
  v_pay_id := public.gl_pm_require_account(v_company_id, '2300');

  v_result := public.post_journal_event(jsonb_build_object(
    'company_id',    v_company_id,
    'source_type',   'broker_commission_accrual',
    'source_id',     v_commission_id::text,
    'event_id',      'approve_commission',
    'effective_date', v_effective_date,
    'description',   'Broker Commission: Broker Commission Expense → Broker Commissions Payable',
    'lines', jsonb_build_array(
      jsonb_build_object('account_id', v_exp_id, 'debit', v_amount, 'credit', 0),
      jsonb_build_object('account_id', v_pay_id, 'debit', 0, 'credit', v_amount)
    )
  ));

  return jsonb_build_object('step', 'broker_commission_approval', 'commission_id', v_commission_id, 'amount', v_amount, 'batch', v_result);
end;
$$;


ALTER FUNCTION "public"."gl_pm_post_broker_commission_approval"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_pm_post_broker_commission_payment"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id     uuid    := (p_payload->>'company_id')::uuid;
  v_commission_id  uuid    := (p_payload->>'commission_id')::uuid;
  v_amount         numeric := public.gl_pm_round_omr((p_payload->>'amount')::numeric);
  v_cash_no        text    := coalesce(nullif(p_payload->>'cash_account_no',''), '1120');
  v_effective_date date    := (p_payload->>'effective_date')::date;
  v_pay_id  text;
  v_cash_id text;
  v_result  jsonb;
begin
  if v_company_id is null or v_commission_id is null or v_effective_date is null then
    raise exception 'GL_PM_COMM_PAY: company_id, commission_id, and effective_date required' using errcode = '22023';
  end if;
  if v_amount is null or v_amount <= 0 then
    raise exception 'GL_PM_COMM_PAY: amount must be > 0' using errcode = '22023';
  end if;

  v_pay_id  := public.gl_pm_require_account(v_company_id, '2300');
  v_cash_id := public.gl_pm_require_account(v_company_id, v_cash_no);

  v_result := public.post_journal_event(jsonb_build_object(
    'company_id',    v_company_id,
    'source_type',   'broker_commission_payout',
    'source_id',     v_commission_id::text,
    'event_id',      'pay_commission',
    'effective_date', v_effective_date,
    'description',   'Broker Commission Payout: Broker Commissions Payable → Bank/Cash',
    'lines', jsonb_build_array(
      jsonb_build_object('account_id', v_pay_id,  'debit', v_amount, 'credit', 0),
      jsonb_build_object('account_id', v_cash_id, 'debit', 0, 'credit', v_amount)
    )
  ));

  return jsonb_build_object('step', 'broker_commission_payment', 'commission_id', v_commission_id, 'amount', v_amount, 'batch', v_result);
end;
