CREATE OR REPLACE FUNCTION "public"."gl_post_journal_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch public.journal_batches%rowtype;
  v_line_count integer;
  v_debit_total numeric;
  v_credit_total numeric;
  v_period_id uuid;
  v_reason text;
  v_lines jsonb;
begin
  if current_user not in ('postgres', 'supabase_admin', 'service_role') then
    raise exception 'GL_ENGINE_SERVER_ONLY: the posting engine is only callable from a trusted server context.' using errcode = '42501';
  end if;

  if p_batch_id is null then
    raise exception 'GL_BATCH_ID_REQUIRED: batch_id is required.' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('gl_post:' || p_batch_id::text, 0));

  select * into v_batch
    from public.journal_batches b
   where b.id = p_batch_id
   for update;

  if not found then
    raise exception 'GL_BATCH_NOT_FOUND: batch % does not exist.', p_batch_id using errcode = 'P0002';
  end if;

  -- Idempotent retry: an already-posted batch is returned as-is.
  if v_batch.status = 'POSTED' then
    select jsonb_agg(jsonb_build_object(
      'line_id', l.id, 'account_id', l.account_id,
      'debit', l.debit, 'credit', l.credit
    ) order by l.id)
      into v_lines
      from public.journal_lines l
     where l.batch_id = v_batch.id;

    return jsonb_build_object(
      'success', true,
      'idempotent', true,
      'batch_id', v_batch.id,
      'status', v_batch.status,
      'accounting_period_id', v_batch.accounting_period_id,
      'period_resolution_reason', v_batch.period_resolution_reason,
      'posted_at', v_batch.posted_at,
      'lines', coalesce(v_lines, '[]'::jsonb)
    );
  end if;

  if v_batch.status = 'REVERSED' then
    raise exception 'GL_BATCH_REVERSED: batch % is REVERSED and cannot be posted.', p_batch_id using errcode = 'P0001';
  end if;
  if v_batch.status <> 'DRAFT' then
    raise exception 'GL_BATCH_STATE_INVALID: batch % has unexpected status %.', p_batch_id, v_batch.status using errcode = 'P0001';
  end if;

  -- Reject an empty batch.
  select count(*) into v_line_count
    from public.journal_lines l
   where l.batch_id = v_batch.id
     and l.deleted_at is null;

  if v_line_count = 0 then
    raise exception 'JOURNAL_BATCH_EMPTY: batch % has no lines and cannot be posted.', p_batch_id using errcode = '22023';
  end if;

  -- Exact three-decimal balance (canonical rounding via the line CHECK).
  select round(coalesce(sum(l.debit), 0), 3), round(coalesce(sum(l.credit), 0), 3)
    into v_debit_total, v_credit_total
    from public.journal_lines l
   where l.batch_id = v_batch.id
     and l.deleted_at is null;

  if v_debit_total <> v_credit_total then
    raise exception 'JOURNAL_BATCH_UNBALANCED: debits % do not equal credits % after three-decimal rounding.', v_debit_total, v_credit_total using errcode = 'P0001';
  end if;

  -- Server-side accounting-period resolution (never client-supplied).
  select p.period_id, p.reason into v_period_id, v_reason
    from public.gl_resolve_accounting_period(v_batch.company_id, v_batch.effective_date) p;

  update public.journal_batches
     set status = 'POSTED',
         posted_at = now(),
         posted_by = auth.uid(),
         accounting_period_id = v_period_id,
         period_resolution_reason = v_reason,
         updated_at = now()
   where id = v_batch.id;

  select jsonb_agg(jsonb_build_object(
    'line_id', l.id, 'account_id', l.account_id,
    'debit', l.debit, 'credit', l.credit
  ) order by l.id)
    into v_lines
    from public.journal_lines l
   where l.batch_id = v_batch.id;

  return jsonb_build_object(
    'success', true,
    'idempotent', false,
    'batch_id', v_batch.id,
    'status', 'POSTED',
    'accounting_period_id', v_period_id,
    'period_resolution_reason', v_reason,
    'effective_date', v_batch.effective_date,
    'posted_at', now(),
    'debits', v_debit_total,
    'credits', v_credit_total,
    'lines', coalesce(v_lines, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."gl_post_journal_batch"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_reconcile_subledgers"("p_as_of_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("account_no" "text", "account_name" "text", "gl_balance" numeric, "subledger_balance" numeric, "mismatch" numeric, "is_reconciled" boolean, "details" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_gl_2000 numeric := 0;
  v_gl_1201 numeric := 0;
  v_gl_2200 numeric := 0;
  v_gl_1300 numeric := 0;
  v_gl_2300 numeric := 0;
  v_sub_2000 numeric := 0;
  v_sub_1201 numeric := 0;
  v_sub_2200 numeric := 0;
  v_sub_1300 numeric := 0;
  v_sub_2300 numeric := 0;
begin
  select coalesce(sum(l.credit - l.debit), 0) into v_gl_2000
    from public.journal_lines l join public.journal_batches b on b.id = l.batch_id join public.accounts a on a.id = l.account_id
   where b.company_id = v_company_id and b.status = 'POSTED' and a.no = '2000' and b.effective_date <= p_as_of_date;
  select coalesce(sum(l.debit - l.credit), 0) into v_gl_1201
    from public.journal_lines l join public.journal_batches b on b.id = l.batch_id join public.accounts a on a.id = l.account_id
   where b.company_id = v_company_id and b.status = 'POSTED' and a.no = '1201' and b.effective_date <= p_as_of_date;
  select coalesce(sum(l.credit - l.debit), 0) into v_gl_2200
    from public.journal_lines l join public.journal_batches b on b.id = l.batch_id join public.accounts a on a.id = l.account_id
   where b.company_id = v_company_id and b.status = 'POSTED' and a.no = '2200' and b.effective_date <= p_as_of_date;
  select coalesce(sum(l.debit - l.credit), 0) into v_gl_1300
    from public.journal_lines l join public.journal_batches b on b.id = l.batch_id join public.accounts a on a.id = l.account_id
   where b.company_id = v_company_id and b.status = 'POSTED' and a.no = '1300' and b.effective_date <= p_as_of_date;
  select coalesce(sum(l.credit - l.debit), 0) into v_gl_2300
    from public.journal_lines l join public.journal_batches b on b.id = l.batch_id join public.accounts a on a.id = l.account_id
   where b.company_id = v_company_id and b.status = 'POSTED' and a.no = '2300' and b.effective_date <= p_as_of_date;

  select coalesce(sum(s.net_payable - s.offset_applied), 0) into v_sub_2000
    from public.owner_settlements s where s.company_id = v_company_id and s.status in ('PENDING','APPROVED') and s.period_end <= p_as_of_date;
  select coalesce(sum(i.amount + coalesce(i.tax_amount, 0) - coalesce(i.paid_amount, 0)), 0) into v_sub_1201
    from public.invoices i where i.company_id = v_company_id and i.deleted_at is null and i.status in ('UNPAID','PARTIALLY_PAID') and i.due_date <= p_as_of_date;
  if to_regclass('public.tenant_deposits') is not null then
    select coalesce(sum(d.remaining_amount), 0) into v_sub_2200 from public.tenant_deposits d where d.company_id = v_company_id and d.deleted_at is null;
  end if;
  -- GAP-008: 1300 subledger = outstanding Due-from-Owner receivables.
  select coalesce(sum(o.outstanding), 0) into v_sub_1300
    from public.due_from_owners o where o.company_id = v_company_id and o.status <> 'REVERSED';
  if to_regclass('public.commissions') is not null then
    select coalesce(sum(c.amount), 0) into v_sub_2300 from public.commissions c where c.company_id = v_company_id and c.status = 'pending';
  end if;

  return query values
    ('2000'::text, 'Owner Funds Payable'::text, round(v_gl_2000, 3), round(v_sub_2000, 3), round(v_gl_2000 - v_sub_2000, 3), abs(v_gl_2000 - v_sub_2000) < 0.001, jsonb_build_object('account','2000','type','liability')),
    ('1201'::text, 'Tenant Receivable'::text, round(v_gl_1201, 3), round(v_sub_1201, 3), round(v_gl_1201 - v_sub_1201, 3), abs(v_gl_1201 - v_sub_1201) < 0.001, jsonb_build_object('account','1201','type','asset')),
    ('2200'::text, 'Tenant Deposits Payable'::text, round(v_gl_2200, 3), round(v_sub_2200, 3), round(v_gl_2200 - v_sub_2200, 3), abs(v_gl_2200 - v_sub_2200) < 0.001, jsonb_build_object('account','2200','type','liability')),
    ('1300'::text, 'Due from Owners'::text, round(v_gl_1300, 3), round(v_sub_1300, 3), round(v_gl_1300 - v_sub_1300, 3), abs(v_gl_1300 - v_sub_1300) < 0.001, jsonb_build_object('account','1300','type','asset')),
    ('2300'::text, 'Broker Commissions Payable'::text, round(v_gl_2300, 3), round(v_sub_2300, 3), round(v_gl_2300 - v_sub_2300, 3), abs(v_gl_2300 - v_sub_2300) < 0.001, jsonb_build_object('account','2300','type','liability'));
end;
$$;


ALTER FUNCTION "public"."gl_reconcile_subledgers"("p_as_of_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_resolve_accounting_period"("p_company_id" "uuid", "p_effective_date" "date") RETURNS TABLE("period_id" "uuid", "reason" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_period_id uuid;
  v_reason text;
begin
  if p_company_id is null or p_effective_date is null then
    raise exception 'company_id and effective_date are required for period resolution.' using errcode = '22023';
  end if;

  -- 1) an OPEN period that contains the effective date
  select p.id into v_period_id
    from public.accounting_periods p
   where p.company_id = p_company_id
     and p.status = 'OPEN'
     and p.start_date <= p_effective_date
     and p.end_date >= p_effective_date
   order by p.start_date
   limit 1;

  if v_period_id is not null then
    v_reason := 'open_period_contains_date';
    return query select v_period_id, v_reason;
    return;
  end if;

  -- 2) the earliest eligible open period: open, and not ended before the
  -- effective date. This is the target for late events whose own period is
  -- SOFT_CLOSED / HARD_CLOSED or missing.
  select p.id into v_period_id
    from public.accounting_periods p
   where p.company_id = p_company_id
     and p.status = 'OPEN'
     and p.end_date >= p_effective_date
   order by p.start_date
   limit 1;

  if v_period_id is not null then
    v_reason := 'redirected_earliest_open_period';
    return query select v_period_id, v_reason;
    return;
  end if;

  -- 3) no eligible open period
  raise exception 'NO_ELIGIBLE_OPEN_ACCOUNTING_PERIOD: no open accounting period can accept effective date % for company %. Create or reopen an OPEN period first.', p_effective_date, p_company_id
    using errcode = 'P0001';
end;
$$;


ALTER FUNCTION "public"."gl_resolve_accounting_period"("p_company_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_reverse_fixed_monthly_accrual"("p_company_id" "uuid", "p_accrual_id" "uuid", "p_reason" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_accrual public.fixed_monthly_daily_accruals%rowtype;
  v_existing public.fixed_monthly_daily_accrual_reversals%rowtype;
  v_reversal_id uuid;
  v_reversal_result jsonb;
  v_reversal_batch_id uuid;
begin
  if current_user not in ('postgres', 'supabase_admin', 'service_role') then
    raise exception 'FIXED_MONTHLY_ENGINE_SERVER_ONLY' using errcode = '42501';
  end if;
  if p_company_id is null or p_accrual_id is null then
    raise exception 'FIXED_MONTHLY_REVERSAL_INPUT_REQUIRED' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null or length(btrim(p_reason)) < 3 then
    raise exception 'FIXED_MONTHLY_REVERSAL_REASON_REQUIRED' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'fixed_monthly_reverse:' || p_company_id::text || ':' || p_accrual_id::text,
    0
  ));

  select * into v_accrual
  from public.fixed_monthly_daily_accruals a
  where a.id = p_accrual_id
    and a.company_id = p_company_id;

  if not found then
    raise exception 'FIXED_MONTHLY_ACCRUAL_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;

  select * into v_existing
  from public.fixed_monthly_daily_accrual_reversals r
  where r.accrual_id = p_accrual_id;

  if found then
    return jsonb_build_object(
      'success', true,
      'idempotent', true,
      'accrual_id', p_accrual_id,
      'reversal_id', v_existing.id,
      'original_batch_id', v_existing.original_journal_batch_id,
      'reversal_batch_id', v_existing.reversal_journal_batch_id,
      'status', 'REVERSED'
    );
  end if;

  if v_accrual.journal_batch_id is not null then
    v_reversal_result := public.reverse_journal_batch(v_accrual.journal_batch_id);
    v_reversal_batch_id := (v_reversal_result->>'reversal_batch_id')::uuid;
  end if;

  v_reversal_id := gen_random_uuid();
  insert into public.fixed_monthly_daily_accrual_reversals (
    id, company_id, accrual_id, original_journal_batch_id,
    reversal_journal_batch_id, original_economic_date, reason, reversed_by
  ) values (
    v_reversal_id, p_company_id, p_accrual_id, v_accrual.journal_batch_id,
    v_reversal_batch_id, v_accrual.accrual_date, btrim(p_reason), p_actor_id
  );

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid()::text,
    extract(epoch from now())::bigint,
    p_actor_id,
    p_actor_id::text,
    'REVERSE',
    'fixed_monthly_daily_accrual',
    p_accrual_id::text,
    'Compensating reversal of FIXED_MONTHLY daily accrual.',
    'fixed_monthly_daily_accrual_reversals',
    jsonb_build_object(
      'company_id', p_company_id,
      'accrual_id', p_accrual_id,
      'original_economic_date', v_accrual.accrual_date,
      'original_batch_id', v_accrual.journal_batch_id,
      'reversal_batch_id', v_reversal_batch_id,
      'reason', btrim(p_reason)
    )::text,
    now()
  );

  return jsonb_build_object(
    'success', true,
    'idempotent', false,
    'accrual_id', p_accrual_id,
    'reversal_id', v_reversal_id,
    'original_batch_id', v_accrual.journal_batch_id,
    'reversal_batch_id', v_reversal_batch_id,
    'status', 'REVERSED',
    'reversal_period_reason', v_reversal_result->>'reversal_period_reason'
  );
end;
$$;


ALTER FUNCTION "public"."gl_reverse_fixed_monthly_accrual"("p_company_id" "uuid", "p_accrual_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_run_fixed_monthly_accruals"("p_company_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_agreement_version_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_version record;
  v_day record;
  v_version_check record;
  v_result jsonb;
  v_attempted integer := 0;
  v_created integer := 0;
  v_idempotent integer := 0;
  v_reversed integer := 0;
  v_zero integer := 0;
  v_net numeric := 0;
  v_tax numeric := 0;
  v_gross numeric := 0;
begin
  if current_user not in ('postgres', 'supabase_admin', 'service_role') then
    raise exception 'FIXED_MONTHLY_ENGINE_SERVER_ONLY' using errcode = '42501';
  end if;
  if p_company_id is null or p_date_from is null or p_date_to is null then
    raise exception 'FIXED_MONTHLY_RUN_RANGE_REQUIRED' using errcode = '22023';
  end if;
  if p_date_from > p_date_to then
    raise exception 'FIXED_MONTHLY_RUN_RANGE_INVALID' using errcode = '22023';
  end if;
  if (p_date_to - p_date_from) > 91 then
    raise exception 'FIXED_MONTHLY_CATCH_UP_LIMIT_EXCEEDED: maximum range is 92 days.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.companies c where c.id = p_company_id and c.is_active) then
    raise exception 'FIXED_MONTHLY_COMPANY_NOT_FOUND_OR_INACTIVE' using errcode = '42501';
  end if;

  if p_agreement_version_id is not null then
    select
      v.operating_model,
      v.commission_type,
      v.commission_recognition_basis,
      v.commission_value,
      oa.agreement_type,
      oa.company_id as agreement_company_id
    into v_version_check
    from public.owner_agreement_versions v
    join public.owner_agreements oa on oa.id = v.owner_agreement_id
    where v.id = p_agreement_version_id
      and v.company_id = p_company_id
      and oa.company_id = p_company_id;

    if not found then
      raise exception 'FIXED_MONTHLY_VERSION_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
    end if;
    if v_version_check.operating_model <> 'OWNER_AGENCY'
       or v_version_check.commission_type <> 'FIXED_MONTHLY'
       or v_version_check.commission_recognition_basis <> 'DAILY_ACCRUAL'
       or v_version_check.agreement_type <> 'property_management'
       or v_version_check.commission_value is null
       or v_version_check.commission_value::text in ('NaN', 'Infinity', '-Infinity')
       or v_version_check.commission_value < 0 then
      raise exception 'FIXED_MONTHLY_TERMS_INVALID' using errcode = '22023';
    end if;
  end if;

  -- Two qualifying frozen versions for the same agreement must never charge
  -- the same economic day. Fail closed if historical data is malformed rather
  -- than silently double-accruing under two distinct version identities.
  if exists (
    select 1
    from public.owner_agreement_versions v1
    join public.owner_agreement_versions v2
      on v2.owner_agreement_id = v1.owner_agreement_id
     and v2.id > v1.id
     and v2.company_id = v1.company_id
    join public.owner_agreements oa
      on oa.id = v1.owner_agreement_id
     and oa.company_id = v1.company_id
    where v1.company_id = p_company_id
      and (p_agreement_version_id is null or v1.id = p_agreement_version_id or v2.id = p_agreement_version_id)
      and v1.operating_model = 'OWNER_AGENCY'
      and v2.operating_model = 'OWNER_AGENCY'
      and v1.commission_type = 'FIXED_MONTHLY'
      and v2.commission_type = 'FIXED_MONTHLY'
      and v1.commission_recognition_basis = 'DAILY_ACCRUAL'
      and v2.commission_recognition_basis = 'DAILY_ACCRUAL'
      and greatest(v1.effective_from, v2.effective_from, oa.starts_on, p_date_from)
          <= least(
            coalesce(v1.effective_to, 'infinity'::date),
            coalesce(v2.effective_to, 'infinity'::date),
            coalesce(oa.ends_on, 'infinity'::date),
            p_date_to
          )
  ) then
    raise exception 'FIXED_MONTHLY_VERSION_INTERVAL_OVERLAP' using errcode = '22023';
  end if;

  for v_version in
    select
      v.id,
      greatest(v.effective_from, oa.starts_on, p_date_from) as run_from,
      least(
        coalesce(v.effective_to, 'infinity'::date),
        coalesce(oa.ends_on, 'infinity'::date),
        p_date_to
      ) as run_to
    from public.owner_agreement_versions v
    join public.owner_agreements oa
      on oa.id = v.owner_agreement_id
     and oa.company_id = v.company_id
    where v.company_id = p_company_id
      and (p_agreement_version_id is null or v.id = p_agreement_version_id)
      and oa.agreement_type = 'property_management'
      and v.operating_model = 'OWNER_AGENCY'
      and v.commission_type = 'FIXED_MONTHLY'
      and v.commission_recognition_basis = 'DAILY_ACCRUAL'
      and v.commission_value >= 0
      and v.effective_from <= p_date_to
      and coalesce(v.effective_to, 'infinity'::date) >= p_date_from
      and oa.starts_on <= p_date_to
      and coalesce(oa.ends_on, 'infinity'::date) >= p_date_from
    order by v.id
  loop
    for v_day in
      select d::date as economic_date
      from generate_series(v_version.run_from, v_version.run_to, interval '1 day') d
      order by d
    loop
      v_result := public.gl_accrue_fixed_monthly_day(
        p_company_id,
        v_version.id,
        v_day.economic_date,
        p_actor_id
      );
      v_attempted := v_attempted + 1;
      v_created := v_created + case when coalesce((v_result->>'created')::boolean, false) then 1 else 0 end;
      v_idempotent := v_idempotent + case when coalesce((v_result->>'idempotent')::boolean, false) then 1 else 0 end;
      v_reversed := v_reversed + case when v_result->>'status' = 'REVERSED' then 1 else 0 end;
      v_zero := v_zero + case when v_result->>'status' = 'ZERO_AMOUNT' then 1 else 0 end;
      v_net := v_net + coalesce((v_result->>'net_amount')::numeric, 0);
      v_tax := v_tax + coalesce((v_result->>'tax_amount')::numeric, 0);
      v_gross := v_gross + coalesce((v_result->>'gross_amount')::numeric, 0);
    end loop;
  end loop;

  return jsonb_build_object(
    'success', true,
    'company_id', p_company_id,
    'date_from', p_date_from,
    'date_to', p_date_to,
    'agreement_version_id', p_agreement_version_id,
    'attempted_days', v_attempted,
    'created_days', v_created,
    'idempotent_days', v_idempotent,
    'already_reversed_days', v_reversed,
    'zero_amount_days', v_zero,
    'net_amount', round(v_net, 3),
    'tax_amount', round(v_tax, 3),
    'gross_amount', round(v_gross, 3),
    'tax_authority_status', 'OUT_OF_SCOPE_NO_VERSIONED_AUTHORITY'
  );
end;
$$;


ALTER FUNCTION "public"."gl_run_fixed_monthly_accruals"("p_company_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_agreement_version_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_validate_and_normalize_lines"("p_company_id" "uuid", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_line jsonb;
  v_account_id text;
  v_account_no text;
  v_debit numeric;
  v_credit numeric;
  v_result jsonb := '[]'::jsonb;
begin
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'JOURNAL_BATCH_EMPTY: at least one journal line is required.' using errcode = '22023';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_account_id := nullif(btrim(coalesce(v_line->>'account_id', '')), '');
    if v_account_id is null then
      raise exception 'JOURNAL_LINE_ACCOUNT_REQUIRED: every journal line must specify account_id.' using errcode = '22023';
    end if;

    -- Account must exist, belong to the batch company and be active.
    select a.no into v_account_no
      from public.accounts a
     where a.id = v_account_id
       and a.company_id = p_company_id;
    if v_account_no is null then
      raise exception 'JOURNAL_LINE_ACCOUNT_SCOPE: account % does not belong to company % or does not exist.', v_account_id, p_company_id using errcode = '22023';
    end if;

    v_debit := public._r3(coalesce(nullif(v_line->>'debit', '')::numeric, 0));
    v_credit := public._r3(coalesce(nullif(v_line->>'credit', '')::numeric, 0));

    if (v_debit > 0 and v_credit > 0) or (v_debit = 0 and v_credit = 0) then
      raise exception 'JOURNAL_LINE_SIDE_INVALID: each line must contain exactly one positive side (debit XOR credit); account %.', v_account_no using errcode = '22023';
    end if;
    if v_debit < 0 or v_credit < 0 then
      raise exception 'JOURNAL_LINE_NEGATIVE_INVALID: negative debit/credit amounts are not allowed; account %.', v_account_no using errcode = '22023';
    end if;

    v_result := v_result || jsonb_build_object(
      'account_id', v_account_id,
      'account_no', v_account_no,
      'debit', v_debit,
      'credit', v_credit,
      'line_description', nullif(v_line->>'line_description', ''),
      'ref_source_id', nullif(v_line->>'ref_source_id', ''),
      'ref_entity_type', nullif(v_line->>'ref_entity_type', ''),
      'ref_entity_id', nullif(v_line->>'ref_entity_id', '')
    );
  end loop;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."gl_validate_and_normalize_lines"("p_company_id" "uuid", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_accounting_period_no_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_conflict uuid;
begin
  perform pg_advisory_xact_lock(
    hashtextextended('accounting_period:' || new.company_id::text, 0)
  );

  select p.id into v_conflict
    from public.accounting_periods p
   where p.company_id = new.company_id
     and p.id is distinct from new.id
     and p.start_date <= new.end_date
     and p.end_date >= new.start_date
   limit 1;

  if v_conflict is not null then
    raise exception 'ACCOUNTING_PERIOD_OVERLAP: period % overlaps existing period % for the same company.', new.name, v_conflict
      using errcode = '23P01';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_accounting_period_no_overlap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_accounting_period_writes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'ACCOUNTING_PERIOD_IMMUTABLE: accounting periods cannot be deleted.' using errcode = '42501';
  end if;

  if coalesce(current_setting('malik.accounting_period_change_authorized', true), '') <> 'true' then
    raise exception 'ACCOUNTING_PERIOD_WRITE_UNAUTHORIZED: period status changes are only allowed through update_accounting_period_status().' using errcode = '42501';
  end if;

  if old.status = 'HARD_CLOSED' and new.status is distinct from 'HARD_CLOSED' then
    raise exception 'ACCOUNTING_PERIOD_HARD_CLOSED_IMMUTABLE: a HARD_CLOSED period cannot be reopened or changed.' using errcode = '42501';
  end if;

  if old.status in ('SOFT_CLOSED', 'HARD_CLOSED') and (
    new.start_date is distinct from old.start_date
    or new.end_date is distinct from old.end_date
    or new.name is distinct from old.name
    or new.company_id is distinct from old.company_id
  ) then
    raise exception 'ACCOUNTING_PERIOD_RANGE_FROZEN: period name/range/company cannot change once the period is closed.' using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_accounting_period_writes"() OWNER TO "postgres";


