CREATE OR REPLACE FUNCTION "public"."guard_invoice_payment_tax_allocation_lineage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_allocated numeric;
begin
  if not exists (
    select 1 from public.receipts r where r.id = new.receipt_id and r.company_id = new.company_id
  ) or not exists (
    select 1 from public.invoices i where i.id = new.invoice_id and i.company_id = new.company_id
  ) then
    raise exception 'INVOICE_PAYMENT_TAX_ALLOCATION_COMPANY_MISMATCH' using errcode='42501';
  end if;
  if not exists (
    select 1 from public.taxable_line_tax_snapshots s
     where s.id = new.tax_snapshot_id
       and s.company_id = new.company_id
       and s.source_type = 'invoice'
       and s.source_id = new.invoice_id::text
  ) then
    raise exception 'INVOICE_PAYMENT_TAX_ALLOCATION_SNAPSHOT_MISMATCH' using errcode='23514';
  end if;
  select coalesce(sum(ra.amount), 0) into v_allocated
    from public.receipt_allocations ra
   where ra.receipt_id = new.receipt_id
     and ra.invoice_id = new.invoice_id
     and ra.company_id = new.company_id
     and ra.deleted_at is null;
  if public.gl_pm_round_omr(new.net_amount + new.tax_amount) <> public.gl_pm_round_omr(v_allocated) then
    raise exception 'INVOICE_PAYMENT_TAX_ALLOCATION_AMOUNT_MISMATCH' using errcode='23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_invoice_payment_tax_allocation_lineage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_invoice_rc1_accounting_lineage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_contract public.contracts%rowtype;
  v_profile public.company_tax_profiles%rowtype;
  v_snapshot public.taxable_line_tax_snapshots%rowtype;
  v_batch public.journal_batches%rowtype;
  v_ar numeric := 0;
  v_ofp numeric := 0;
  v_vat numeric := 0;
  v_sublease numeric := 0;
begin
  -- Historical invoices have no RC1 classification and are intentionally not
  -- inferred/backfilled. This trigger protects only the new authoritative path.
  if new.invoice_accounting_classification is null then
    return new;
  end if;

  select * into v_contract
    from public.contracts
   where id = new.contract_id
     and company_id = new.company_id
     and deleted_at is null;
  if not found then
    raise exception 'INVOICE_RC1_CONTRACT_COMPANY_MISMATCH' using errcode = '42501';
  end if;

  if new.invoice_agreement_version_id is null
     or new.invoice_agreement_version_id is distinct from v_contract.agreement_version_id
     or new.invoice_operating_model is distinct from v_contract.operating_model_snapshot
     or new.invoice_collection_role is distinct from v_contract.collection_role_snapshot then
    raise exception 'INVOICE_RC1_CONTRACT_SNAPSHOT_MISMATCH: invoice accounting lineage must equal the immutable contract snapshot.'
      using errcode = '23514';
  end if;

  if new.invoice_operating_model <> 'OWNER_AGENCY' then
    raise exception 'RC1_OPERATING_MODEL_EXCLUDED: only OWNER_AGENCY recurring invoices are in the RC1 posting scope.'
      using errcode = '23514';
  end if;

  if (new.invoice_collection_role = 'OWNER_IS_CREDITOR'
        and new.invoice_accounting_classification <> 'OWNER_AGENCY_OWNER_CREDITOR_OPERATIONAL')
     or (new.invoice_collection_role = 'OFFICE_IS_CREDITOR'
        and new.invoice_accounting_classification <> 'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS') then
    raise exception 'INVOICE_RC1_ACCOUNTING_CLASSIFICATION_MISMATCH' using errcode = '23514';
  end if;

  if new.document_status <> 'POSTED' then
    return new;
  end if;

  if new.tax_treatment is null or new.tax_basis is null then
    raise exception 'INVOICE_RC1_TAX_LINEAGE_REQUIRED: posted RC1 invoices require an explicit tax treatment and basis.'
      using errcode = '23514';
  end if;

  if new.tax_profile_id is null
     or new.tax_snapshot_id is null
     or new.tax_code is null then
    raise exception 'INVOICE_RC1_TAX_PROFILE_AND_SNAPSHOT_REQUIRED: every RC1 invoice needs an effective configured tax treatment.'
      using errcode = '23514';
  end if;

  select * into v_profile
    from public.company_tax_profiles
   where id = new.tax_profile_id
     and company_id = new.company_id;
  if not found
     or v_profile.tax_code is distinct from new.tax_code
     or v_profile.tax_rate is distinct from new.tax_rate then
    raise exception 'INVOICE_RC1_TAX_PROFILE_COHERENCE_INVALID' using errcode = '23514';
  end if;

  select * into v_snapshot
    from public.taxable_line_tax_snapshots
   where id = new.tax_snapshot_id
     and company_id = new.company_id
     and source_type = 'invoice'
     and source_id = new.id::text;
  if not found
     or v_snapshot.tax_code is distinct from new.tax_code
     or v_snapshot.tax_rate is distinct from new.tax_rate
     or v_snapshot.net_amount is distinct from new.amount
     or v_snapshot.tax_amount is distinct from new.tax_amount
     or v_snapshot.effective_date is distinct from new.issue_date then
    raise exception 'INVOICE_RC1_TAX_SNAPSHOT_COHERENCE_INVALID' using errcode = '23514';
  end if;

  if new.tax_treatment = 'NON_TAXABLE' then
    if coalesce(new.tax_amount, 0) <> 0
       or coalesce(new.tax_rate, 0) <> 0
       or new.tax_code <> 'NON_TAXABLE'
       or new.tax_basis <> 'NON_TAXABLE' then
      raise exception 'INVOICE_RC1_NON_TAXABLE_LINEAGE_INVALID' using errcode = '23514';
    end if;
  elsif new.tax_treatment = 'TAXABLE' then
    if new.tax_code = 'NON_TAXABLE' or new.tax_basis <> 'NET_PLUS_TAX' then
      raise exception 'INVOICE_RC1_TAXABLE_LINEAGE_INCOMPLETE' using errcode = '23514';
    end if;
  else
    raise exception 'INVOICE_RC1_TAX_TREATMENT_INVALID' using errcode = '23514';
  end if;

  if new.invoice_accounting_classification = 'OWNER_AGENCY_OWNER_CREDITOR_OPERATIONAL' then
    if new.invoice_posting_batch_id is not null then
      raise exception 'INVOICE_RC1_OWNER_CREDITOR_NO_INVOICE_GL: OWNER_IS_CREDITOR rent remains an operational tenant obligation until collection.'
        using errcode = '23514';
    end if;
    if exists (
      select 1
        from public.journal_batches b
       where b.company_id = new.company_id
         and b.source_type = 'invoice'
         and b.source_id = new.id::text
    ) then
      raise exception 'INVOICE_RC1_OWNER_CREDITOR_UNEXPECTED_INVOICE_GL' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.invoice_posting_batch_id is null then
    raise exception 'INVOICE_RC1_OFFICE_CREDITOR_BATCH_REQUIRED' using errcode = '23514';
  end if;

  select * into v_batch
    from public.journal_batches
   where id = new.invoice_posting_batch_id
     and company_id = new.company_id
     and source_type = 'invoice'
     and source_id = new.id::text
     and status = 'POSTED';
  if not found then
    raise exception 'INVOICE_RC1_POSTING_BATCH_LINEAGE_INVALID' using errcode = '23514';
  end if;

  select
    coalesce(sum(jl.debit) filter (where a.no = '1201'), 0),
    coalesce(sum(jl.credit) filter (where a.no = '2000'), 0),
    coalesce(sum(jl.credit) filter (where a.no = '2100'), 0),
    coalesce(sum(jl.credit) filter (where a.no = '4000'), 0)
  into v_ar, v_ofp, v_vat, v_sublease
  from public.journal_lines jl
  join public.accounts a on a.id = jl.account_id and a.company_id = new.company_id
  where jl.batch_id = new.invoice_posting_batch_id
    and jl.company_id = new.company_id;

  if round(v_ar, 3) <> round(new.amount + coalesce(new.tax_amount, 0), 3)
     or round(v_ofp, 3) <> round(new.amount, 3)
     or round(v_vat, 3) <> round(coalesce(new.tax_amount, 0), 3)
     or round(v_sublease, 3) <> 0 then
    raise exception 'INVOICE_RC1_OFFICE_CREDITOR_POSTING_SHAPE_INVALID: expected Dr 1201 / Cr 2000 (+ Cr 2100), never 4000.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_invoice_rc1_accounting_lineage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_journal_batch_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'DRAFT' then
      raise exception 'JOURNAL_BATCH_IMMUTABLE: posted or reversed batches cannot be deleted. Corrections use reversal batches.' using errcode = '42501';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    if old.company_id is distinct from new.company_id then
      raise exception 'JOURNAL_BATCH_COMPANY_IMMUTABLE: a batch cannot be moved to another company.' using errcode = '42501';
    end if;

    if old.status = 'REVERSED' and new.status is distinct from 'REVERSED' then
      raise exception 'JOURNAL_BATCH_LIFECYCLE: a REVERSED batch cannot change status.' using errcode = '42501';
    end if;

    if old.status = 'POSTED' and new.status <> 'REVERSED' then
      raise exception 'JOURNAL_BATCH_LIFECYCLE: a POSTED batch can only transition to REVERSED.' using errcode = '42501';
    end if;

    if old.status = 'DRAFT' and new.status = 'REVERSED' then
      raise exception 'JOURNAL_BATCH_LIFECYCLE: a DRAFT batch must be posted before it can be reversed.' using errcode = '42501';
    end if;

    -- Defense in depth: marking a batch REVERSED requires a real, valid
    -- reversal batch that references this batch. The engine creates one; a
    -- privileged direct writer cannot fabricate the transition.
    if new.status = 'REVERSED' and not exists (
      select 1 from public.journal_batches r
       where r.id = new.reversal_of_batch_id
         and r.source_type = 'journal_reversal'
         and r.source_id = old.id::text
    ) then
      raise exception 'JOURNAL_BATCH_REVERSAL_REQUIRED: a batch can only be marked REVERSED with a valid reversal batch referencing it (reverse_journal_batch).' using errcode = '42501';
    end if;

    if old.status = 'POSTED' and (
      new.effective_date is distinct from old.effective_date
      or new.source_type is distinct from old.source_type
      or new.source_id is distinct from old.source_id
      or new.event_id is distinct from old.event_id
      or new.accounting_period_id is distinct from old.accounting_period_id
    ) then
      raise exception 'JOURNAL_BATCH_IMMUTABLE: posted batch identity and period cannot change.' using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_journal_batch_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_journal_line_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
  v_company uuid;
begin
  select b.status, b.company_id into v_status, v_company
    from public.journal_batches b
   where b.id = coalesce(new.batch_id, old.batch_id);

  if v_status is null then
    raise exception 'JOURNAL_LINE_ORPHAN: journal line has no batch.' using errcode = '23503';
  end if;

  if tg_op = 'DELETE' then
    if v_status <> 'DRAFT' then
      raise exception 'JOURNAL_LINE_IMMUTABLE: lines of posted or reversed batches cannot be deleted.' using errcode = '42501';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    if v_status <> 'DRAFT' then
      raise exception 'JOURNAL_LINE_IMMUTABLE: lines of posted or reversed batches cannot be changed. Corrections use reversal batches.' using errcode = '42501';
    end if;
    if old.company_id is distinct from new.company_id then
      raise exception 'JOURNAL_LINE_COMPANY_IMMUTABLE: a line cannot be moved to another company.' using errcode = '42501';
    end if;
    if old.batch_id is distinct from new.batch_id then
      raise exception 'JOURNAL_LINE_BATCH_IMMUTABLE: a line cannot be moved to another batch after creation.' using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_journal_line_immutability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_maintenance_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status then
    -- Sanctioned commands set the transaction-local key. resolve RPC and the
    -- transition command both run as definer functions that set it.
    if coalesce(current_setting('malek.maintenance_transition_sanctioned', true), '') <> 'true' then
      raise exception 'MAINTENANCE_STATUS_VIA_COMMAND: تغيير حالة الصيانة يتم عبر أوامر الخادم فقط (transition/resolve).'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


