CREATE OR REPLACE FUNCTION "public"."guard_property_archive"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if old.deleted_at is not null or new.deleted_at is null then
    return new;
  end if;

  if exists (
    select 1
    from public.units u
    where u.property_id::text = new.id::text
      and u.company_id = new.company_id
      and u.deleted_at is null
  ) then
    raise exception 'Cannot archive a property that still has non-archived units. Archive or reassign units first.'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.owner_agreements a
    where a.property_id::text = new.id::text
      and a.company_id = new.company_id
  ) then
    raise exception 'Cannot archive a property with a saved owner agreement. Use inactive or sold status to preserve history.'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.maintenance_records m
    where m.property_id::text = new.id::text
      and m.company_id = new.company_id
      and m.deleted_at is null
      and lower(coalesce(m.status, '')) in ('open', 'in_progress')
  ) then
    raise exception 'Cannot archive property while it has open or in-progress maintenance.'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.contracts c
    where c.property_id::text = new.id::text
      and c.company_id = new.company_id
      and c.deleted_at is null
      and lower(c.status) in ('active', 'draft')
  ) then
    raise exception 'Cannot archive property with an active or draft contract. Complete the contract cycle first.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_property_archive"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_receipt_allocation_invoice_credit_ceiling"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_invoice public.invoices%rowtype;
  v_receipt_total numeric;
begin
  if new.invoice_id is null or new.receipt_id is null or new.company_id is null then
    raise exception 'RECEIPT_ALLOCATION_LINEAGE_REQUIRED' using errcode='23514';
  end if;

  select * into v_invoice
    from public.invoices
   where id = new.invoice_id
     and company_id = new.company_id
     and deleted_at is null
   for update;
  if not found then
    raise exception 'RECEIPT_ALLOCATION_INVOICE_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;

  select coalesce(sum(ra.amount), 0)
    into v_receipt_total
    from public.receipt_allocations ra
   where ra.receipt_id = new.receipt_id
     and ra.invoice_id = new.invoice_id
     and ra.company_id = new.company_id
     and coalesce(ra.deleted_at, null) is null;

  if public.gl_pm_round_omr(coalesce(v_invoice.paid_amount, 0)
       + coalesce(v_invoice.credited_amount, 0)
       + coalesce(v_receipt_total, 0)
       + coalesce(new.amount, 0))
     > public.gl_pm_round_omr(v_invoice.amount + coalesce(v_invoice.tax_amount, 0) + 0.001) then
    raise exception 'RECEIPT_ALLOCATION_EXCEEDS_INVOICE_OUTSTANDING: payment allocation exceeds posted invoice less credits.'
      using errcode='22023';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_receipt_allocation_invoice_credit_ceiling"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_s08_frozen_review_writes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_authorized text := coalesce(current_setting('malik.s08_review_change_authorized', true), '');
begin
  if tg_op = 'DELETE' then
    raise exception 'S08_FROZEN_REVIEW_IMMUTABLE: frozen reviews cannot be deleted, they are append-only historical evidence.' using errcode='42501';
  end if;

  if tg_op = 'UPDATE' then
    -- Allow updates only through authorized RPCs (they set the marker)
    if v_authorized <> 'true' then
      raise exception 'S08_FROZEN_REVIEW_IMMUTABLE: direct updates are forbidden, use s08_* RPCs.' using errcode='42501';
    end if;

    -- Fingerprint, company, period, lineage, creation_timestamp, created_at are immutable
    if old.company_id is distinct from new.company_id then
      raise exception 'S08_FROZEN_REVIEW_IMMUTABLE_FIELD: company_id cannot be changed' using errcode='42501';
    end if;
    if old.accounting_period_id is distinct from new.accounting_period_id then
      raise exception 'S08_FROZEN_REVIEW_IMMUTABLE_FIELD: accounting_period_id cannot be changed' using errcode='42501';
    end if;
    if old.dataset_fingerprint is distinct from new.dataset_fingerprint then
      raise exception 'S08_FROZEN_REVIEW_IMMUTABLE_FIELD: dataset_fingerprint cannot be changed' using errcode='42501';
    end if;
    if old.dataset_lineage is distinct from new.dataset_lineage then
      raise exception 'S08_FROZEN_REVIEW_IMMUTABLE_FIELD: dataset_lineage cannot be changed' using errcode='42501';
    end if;
    if old.creation_timestamp is distinct from new.creation_timestamp then
      raise exception 'S08_FROZEN_REVIEW_IMMUTABLE_FIELD: creation_timestamp cannot be changed' using errcode='42501';
    end if;
    if old.created_at is distinct from new.created_at then
      raise exception 'S08_FROZEN_REVIEW_IMMUTABLE_FIELD: created_at cannot be changed' using errcode='42501';
    end if;

    -- Lifecycle transitions enforcement
    if old.reviewer_decision = 'CREATED' and new.reviewer_decision not in ('ANALYZED','REJECTED') then
      raise exception 'S08_REVIEW_LIFECYCLE_ILLEGAL: CREATED can only transition to ANALYZED or REJECTED, got %', new.reviewer_decision using errcode='23514';
    end if;
    if old.reviewer_decision = 'ANALYZED' and new.reviewer_decision not in ('APPROVED','REJECTED') then
      raise exception 'S08_REVIEW_LIFECYCLE_ILLEGAL: ANALYZED can only transition to APPROVED or REJECTED, got %', new.reviewer_decision using errcode='23514';
    end if;
    if old.reviewer_decision in ('APPROVED','REJECTED') and new.reviewer_decision is distinct from old.reviewer_decision then
      raise exception 'S08_REVIEW_LIFECYCLE_TERMINAL: % is terminal and cannot transition to %', old.reviewer_decision, new.reviewer_decision using errcode='23514';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_s08_frozen_review_writes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_s09_correction_writes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_authorized text := coalesce(current_setting('malik.s09_correction_change_authorized', true), '');
begin
  if tg_op = 'DELETE' then
    raise exception 'S09_CORRECTION_IMMUTABLE: corrections cannot be deleted, they are append-only.' using errcode='42501';
  end if;

  if tg_op = 'UPDATE' then
    if v_authorized <> 'true' then
      raise exception 'S09_CORRECTION_IMMUTABLE: direct updates forbidden, use s09_* RPCs.' using errcode='42501';
    end if;

    -- Immutable fields
    if old.company_id is distinct from new.company_id then
      raise exception 'S09_IMMUTABLE_FIELD: company_id cannot be changed' using errcode='42501';
    end if;
    if old.review_id is distinct from new.review_id then
      raise exception 'S09_IMMUTABLE_FIELD: review_id cannot be changed' using errcode='42501';
    end if;
    if old.accounting_period_id is distinct from new.accounting_period_id then
      raise exception 'S09_IMMUTABLE_FIELD: accounting_period_id cannot be changed' using errcode='42501';
    end if;
    if old.source_type is distinct from new.source_type or old.source_id is distinct from new.source_id then
      raise exception 'S09_IMMUTABLE_FIELD: source cannot be changed' using errcode='42501';
    end if;
    if old.request_id is distinct from new.request_id then
      raise exception 'S09_IMMUTABLE_FIELD: request_id cannot be changed' using errcode='42501';
    end if;
    if old.before_evidence is distinct from new.before_evidence then
      raise exception 'S09_IMMUTABLE_FIELD: before_evidence is immutable' using errcode='42501';
    end if;

    -- Lifecycle
    if old.status = 'DRAFT' and new.status not in ('VALIDATED','REVERSED') then
      -- DRAFT can go to VALIDATED, or be REVERSED? Actually DRAFT should not go directly to APPLIED, must via VALIDATED
      -- Allow DRAFT→REJECT? No, but allow DRAFT→REVERSED for cancellation? We'll allow DRAFT→VALIDATED only for strictness
      if new.status = 'DRAFT' then
        -- no self transition check, allow no-op
      else
        raise exception 'S09_LIFECYCLE_ILLEGAL: DRAFT can only transition to VALIDATED, got %', new.status using errcode='23514';
      end if;
    end if;
    if old.status = 'VALIDATED' and new.status not in ('APPLIED','REVERSED') then
      raise exception 'S09_LIFECYCLE_ILLEGAL: VALIDATED can only transition to APPLIED or REVERSED, got %', new.status using errcode='23514';
    end if;
    if old.status = 'APPLIED' and new.status <> 'REVERSED' then
      raise exception 'S09_LIFECYCLE_ILLEGAL: APPLIED can only transition to REVERSED, got %', new.status using errcode='23514';
    end if;
    if old.status = 'REVERSED' and new.status is distinct from old.status then
      raise exception 'S09_LIFECYCLE_TERMINAL: REVERSED is terminal' using errcode='23514';
    end if;

    -- Prevent downgrade
    if old.status = 'VALIDATED' and new.status = 'DRAFT' then
      raise exception 'S09_LIFECYCLE_ILLEGAL: cannot downgrade VALIDATED to DRAFT' using errcode='23514';
    end if;
    if old.status = 'APPLIED' and new.status in ('DRAFT','VALIDATED') then
      raise exception 'S09_LIFECYCLE_ILLEGAL: cannot downgrade APPLIED' using errcode='23514';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_s09_correction_writes"() OWNER TO "postgres";


