ALTER FUNCTION "public"."guard_taxable_line_tax_snapshot_immutable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_unit_archive_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if old.deleted_at is not null or new.deleted_at is null then
    return new;
  end if;

  if exists (
    select 1
    from public.contracts c
    where c.unit_id::text = new.id::text
      and c.company_id = new.company_id
  ) then
    raise exception 'Unit with contract history cannot be archived.'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.maintenance_records m
    where m.unit_id::text = new.id::text
      and m.company_id = new.company_id
      and m.deleted_at is null
      and lower(coalesce(m.status, '')) in ('open', 'in_progress')
  ) then
    raise exception 'Unit cannot be archived while maintenance is open.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_unit_archive_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_wp05_correction_proposal_writes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_authorized text := coalesce(current_setting('malik.wp05_proposal_change_authorized', true), '');
begin
  if tg_op = 'DELETE' then
    raise exception 'WP05_PROPOSAL_IMMUTABLE: correction proposals are append-only and cannot be deleted.' using errcode='42501';
  end if;

  if tg_op = 'UPDATE' then
    if v_authorized <> 'true' then
      raise exception 'WP05_PROPOSAL_IMMUTABLE: direct updates forbidden, use the wp05_*_correction_proposal RPCs.' using errcode='42501';
    end if;

    if old.company_id is distinct from new.company_id then
      raise exception 'WP05_PROPOSAL_IMMUTABLE_FIELD: company_id cannot be changed' using errcode='42501';
    end if;
    if old.as_of is distinct from new.as_of
       or old.reconciliation_class is distinct from new.reconciliation_class
       or old.account_no is distinct from new.account_no then
      raise exception 'WP05_PROPOSAL_IMMUTABLE_FIELD: reconciliation scope cannot be changed' using errcode='42501';
    end if;
    if old.reason_code is distinct from new.reason_code
       or old.variance_amount is distinct from new.variance_amount
       or old.subledger_balance is distinct from new.subledger_balance
       or old.gl_balance is distinct from new.gl_balance then
      raise exception 'WP05_PROPOSAL_IMMUTABLE_FIELD: finding and balances are immutable evidence' using errcode='42501';
    end if;
    if old.evidence is distinct from new.evidence then
      raise exception 'WP05_PROPOSAL_IMMUTABLE_FIELD: evidence is immutable' using errcode='42501';
    end if;
    if old.maker_user_id is distinct from new.maker_user_id then
      raise exception 'WP05_PROPOSAL_IMMUTABLE_FIELD: maker_user_id cannot be changed' using errcode='42501';
    end if;
    if old.request_id is distinct from new.request_id
       or old.idempotency_key is distinct from new.idempotency_key then
      raise exception 'WP05_PROPOSAL_IMMUTABLE_FIELD: idempotency identity cannot be changed' using errcode='42501';
    end if;

    if old.status <> new.status then
      if old.status <> 'PENDING_APPROVAL' then
        raise exception 'WP05_PROPOSAL_LIFECYCLE_TERMINAL: % is terminal, cannot move to %', old.status, new.status using errcode='23514';
      end if;
      if new.status not in ('APPROVED', 'REJECTED', 'SUPERSEDED') then
        raise exception 'WP05_PROPOSAL_LIFECYCLE_ILLEGAL: PENDING_APPROVAL can only move to APPROVED, REJECTED or SUPERSEDED, got %', new.status using errcode='23514';
      end if;
      if new.status in ('APPROVED', 'REJECTED') then
        if new.checker_user_id is null then
          raise exception 'WP05_PROPOSAL_CHECKER_REQUIRED: a checker is required to decide a proposal' using errcode='42501';
        end if;
        if new.maker_user_id is not null and new.checker_user_id = new.maker_user_id then
          raise exception 'WP05_PROPOSAL_MAKER_CHECKER_VIOLATION: the checker must differ from the maker' using errcode='42501';
        end if;
      end if;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_wp05_correction_proposal_writes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_bank_statement_batch_atomic"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_bank_account_id uuid;
  v_file_name text;
  v_file_fingerprint text;
  v_file_size integer;
  v_rows jsonb;
  v_total integer;
  v_existing_import public.bank_statement_imports%rowtype;
  v_import public.bank_statement_imports%rowtype;
  v_row jsonb;
  v_idx integer;
  v_transaction_date date;
  v_amount numeric;
  v_description text;
  v_reference text;
  v_balance numeric;
  v_currency text;
  v_fingerprint text;
  v_accepted integer := 0;
  v_duplicate integer := 0;
  v_possible integer := 0;
  v_existing_fps text[];
  v_seen_fps text[] := '{}';
  v_inserted_fps text[] := '{}';
  v_date_str text;
  v_amount_text text;
  v_dummy uuid;
  v_max_file_size integer := 5 * 1024 * 1024;
  v_max_rows integer := 5000;
  v_debit_text text;
  v_credit_text text;
  v_amount_supplied boolean;
  v_debit_supplied boolean;
  v_credit_supplied boolean;
  v_supplied_amount_count integer;
  v_debit numeric;
  v_credit numeric;
  v_canonical_rows jsonb := '[]'::jsonb;
  v_payload_digest text;
  v_preview jsonb;
begin
  -- Authoritative preview first: validates, never writes, detects content reuse.
  v_preview := public.preview_bank_statement_batch_atomic(payload);
  if coalesce((v_preview->>'is_duplicate_file')::boolean, false) then
    return v_preview || jsonb_build_object('write_attempted', false);
  end if;

  v_company_id := public.current_company_id();
  v_bank_account_id := nullif(payload->>'bank_account_id','')::uuid;
  v_file_name := nullif(payload->>'file_name','');
  v_file_fingerprint := nullif(payload->>'file_fingerprint','');
  v_file_size := nullif(payload->>'file_size','')::integer;
  v_rows := payload->'rows';
  v_total := jsonb_array_length(v_rows);
  v_accepted := coalesce((v_preview->>'accepted_rows')::integer, 0);
  v_duplicate := coalesce((v_preview->>'duplicate_rows')::integer, 0);
  v_possible := coalesce((v_preview->>'possible_duplicate_rows')::integer, 0);
  v_payload_digest := v_preview->>'payload_digest';

  select coalesce(array_agg(fingerprint), '{}') into v_existing_fps
  from public.bank_statement_lines
  where company_id = v_company_id
    and bank_account_id = v_bank_account_id
    and deleted_at is null
    and fingerprint is not null;

  -- Rebuild canonical rows with the same first-pass rules as preview.
  for v_idx in 0..v_total-1 loop
    v_row := v_rows->v_idx;
    v_date_str := v_row->>'transaction_date';
    v_amount_text := nullif(trim(both ' ' from coalesce(v_row->>'amount','')), '');
    v_debit_text := nullif(trim(both ' ' from coalesce(v_row->>'debit','')), '');
    v_credit_text := nullif(trim(both ' ' from coalesce(v_row->>'credit','')), '');
    v_amount_supplied := v_amount_text is not null;
    v_debit_supplied := v_debit_text is not null;
    v_credit_supplied := v_credit_text is not null;

    v_transaction_date := v_date_str::date;
    if v_amount_supplied then
      v_amount := v_amount_text::numeric;
    elsif v_debit_supplied then
      v_amount := -abs(v_debit_text::numeric);
    else
      v_amount := abs(v_credit_text::numeric);
    end if;

    v_description := trim(both ' ' from coalesce(v_row->>'description',''));
    if v_description = '' then v_description := 'حركة مستوردة'; end if;
    v_reference := lower(trim(both ' ' from coalesce(v_row->>'reference','')));
    v_currency := upper(trim(both ' ' from coalesce(v_row->>'currency','OMR')));
    v_balance := null;
    if nullif(v_row->>'balance','') is not null then
      v_balance := (v_row->>'balance')::numeric;
    end if;

    v_fingerprint := md5(
      coalesce(v_company_id::text,'') || '|' ||
      coalesce(v_bank_account_id::text,'') || '|' ||
      coalesce(v_transaction_date::text,'') || '|' ||
      coalesce(to_char(v_amount, 'FM9999999999990.000'),'') || '|' ||
      coalesce(v_currency,'OMR') || '|' ||
      coalesce(v_reference,'') || '|' ||
      lower(coalesce(v_description,''))
    );

    v_canonical_rows := v_canonical_rows || jsonb_build_array(jsonb_build_object(
      'transaction_date', v_transaction_date::text,
      'amount', to_char(v_amount, 'FM9999999999990.000'),
      'description', v_description,
      'reference', v_reference,
      'balance', case when v_balance is null then null else to_char(v_balance, 'FM9999999999990.000') end,
      'currency', v_currency,
      'fingerprint', v_fingerprint
    ));
  end loop;

  begin
    insert into public.bank_statement_imports (
      company_id, bank_account_id, statement_name, file_name, file_fingerprint,
      file_size, total_rows, accepted_rows, rejected_rows, duplicate_rows,
      possible_duplicate_rows, status, error_summary, processed_at, created_by,
      payload_digest
    ) values (
      v_company_id, v_bank_account_id,
      coalesce(v_file_name, 'استيراد ' || to_char(now(),'YYYY-MM-DD')),
      v_file_name, v_file_fingerprint, v_file_size, v_total, v_accepted, 0,
      v_duplicate, v_possible,
      case when v_accepted = 0 and v_duplicate > 0 then 'duplicate' else 'completed' end,
      jsonb_build_object('duplicate_rows', v_duplicate, 'possible_duplicate_rows', v_possible, 'accepted_rows', v_accepted),
      now(), auth.uid(), v_payload_digest
    ) returning * into v_import;
  exception when unique_violation then
    select * into v_existing_import
    from public.bank_statement_imports
    where company_id = v_company_id and file_fingerprint = v_file_fingerprint and deleted_at is null limit 1;
    if found then
      if v_existing_import.payload_digest is not null
         and v_existing_import.payload_digest <> v_payload_digest then
        raise exception 'file_fingerprint was already used with different content.' using errcode='22023';
      end if;
      return jsonb_build_object(
        'id', v_existing_import.id, 'reference', v_existing_import.reference,
        'bank_account_id', v_existing_import.bank_account_id,
        'file_name', v_existing_import.file_name,
        'file_fingerprint', v_existing_import.file_fingerprint,
        'total_rows', v_existing_import.total_rows,
        'accepted_rows', v_existing_import.accepted_rows,
        'rejected_rows', v_existing_import.rejected_rows,
        'duplicate_rows', v_existing_import.duplicate_rows,
        'possible_duplicate_rows', v_existing_import.possible_duplicate_rows,
        'status', v_existing_import.status, 'is_duplicate_file', true
      );
    else raise; end if;
  end;

  v_seen_fps := '{}';
  if v_accepted > 0 then
    for v_idx in 0..jsonb_array_length(v_canonical_rows)-1 loop
      v_row := v_canonical_rows->v_idx;
      v_transaction_date := (v_row->>'transaction_date')::date;
      v_amount := (v_row->>'amount')::numeric;
      v_description := v_row->>'description';
      v_reference := v_row->>'reference';
      v_balance := nullif(v_row->>'balance','')::numeric;
      v_currency := v_row->>'currency';
      v_fingerprint := v_row->>'fingerprint';

      if v_fingerprint = any(v_seen_fps) then continue; end if;
      v_seen_fps := array_append(v_seen_fps, v_fingerprint);
      if v_fingerprint = any(v_existing_fps) then continue; end if;
      if v_fingerprint = any(v_inserted_fps) then continue; end if;

      insert into public.bank_statement_lines (
        company_id, import_id, bank_account_id, transaction_date, description,
        reference, amount, balance, currency, external_reference, fingerprint, status
      ) values (
        v_company_id, v_import.id, v_bank_account_id, v_transaction_date, v_description,
        v_reference, v_amount, v_balance, v_currency, v_reference, v_fingerprint, 'unmatched'
      )
      on conflict (company_id, fingerprint) where fingerprint is not null and deleted_at is null do nothing
      returning id into v_dummy;
      if found then
        v_inserted_fps := array_append(v_inserted_fps, v_fingerprint);
      end if;
    end loop;
  end if;

  select * into v_import from public.bank_statement_imports where id = v_import.id;

  return jsonb_build_object(
    'id', v_import.id, 'reference', v_import.reference,
    'bank_account_id', v_import.bank_account_id,
    'file_name', v_import.file_name,
    'file_fingerprint', v_import.file_fingerprint,
    'payload_digest', v_import.payload_digest,
    'total_rows', v_import.total_rows,
    'accepted_rows', v_import.accepted_rows,
    'rejected_rows', v_import.rejected_rows,
    'duplicate_rows', v_import.duplicate_rows,
    'possible_duplicate_rows', v_import.possible_duplicate_rows,
    'status', v_import.status, 'is_duplicate_file', false
  );
end;
$$;


ALTER FUNCTION "public"."import_bank_statement_batch_atomic"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."import_bank_statement_batch_atomic"("payload" "jsonb") IS 'S02/GAP-017: atomic staged bank CSV import. Preview-first, content-reuse fail-closed, OMR 3dp, company isolation. No accounting postings.';



CREATE OR REPLACE FUNCTION "public"."invoice_document_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.document_status = 'POSTED' then
      raise exception 'POSTED_INVOICE_HARD_DELETE_BLOCKED: posted invoices cannot be hard-deleted; use VOID/CANCEL/REVERSAL/credit.'
        using errcode = '42501';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' and old.document_status = 'POSTED' then
    if new.amount is distinct from old.amount
       or new.tax_amount is distinct from old.tax_amount
       or new.tax_rate is distinct from old.tax_rate
       or new.contract_id is distinct from old.contract_id
       or new.issue_date is distinct from old.issue_date
       or new.due_date is distinct from old.due_date
       or new.billing_period_start is distinct from old.billing_period_start
       or new.billing_period_end is distinct from old.billing_period_end
       or new.charge_type is distinct from old.charge_type
       or new.document_status is distinct from old.document_status
       or new.invoice_agreement_version_id is distinct from old.invoice_agreement_version_id
       or new.invoice_operating_model is distinct from old.invoice_operating_model
       or new.invoice_collection_role is distinct from old.invoice_collection_role
       or new.invoice_accounting_classification is distinct from old.invoice_accounting_classification
       or new.invoice_posting_batch_id is distinct from old.invoice_posting_batch_id
       or new.tax_treatment is distinct from old.tax_treatment
       or new.tax_profile_id is distinct from old.tax_profile_id
       or new.tax_snapshot_id is distinct from old.tax_snapshot_id
       or new.tax_code is distinct from old.tax_code
       or new.tax_basis is distinct from old.tax_basis
    then
      raise exception 'POSTED_INVOICE_IMMUTABLE: financially meaningful invoice fields are immutable after POSTING; post a credit/reversal instead.'
        using errcode = '42501';
    end if;
    if old.reference is not null and new.reference is distinct from old.reference then
      raise exception 'POSTED_INVOICE_REFERENCE_IMMUTABLE: invoice reference cannot change after assignment.'
        using errcode = '42501';
    end if;
  end if;

  if tg_op = 'UPDATE' and old.document_status = 'DRAFT' and new.document_status = 'POSTED' then
    if new.amount is null or new.issue_date is null or new.due_date is null
       or new.billing_period_start is null or new.billing_period_end is null then
      raise exception 'INVOICE_POST_REQUIRES_FINANCIAL_FIELDS: amount, dates and billing period are required to POST an invoice.'
        using errcode = '22023';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."invoice_document_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invoice_lineage_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_contract_company uuid;
begin
  select c.company_id into v_contract_company
    from public.contracts c
   where c.id = new.contract_id;
  if v_contract_company is null then
    raise exception 'INVOICE_CONTRACT_NOT_FOUND: contract % does not exist.', new.contract_id
      using errcode = '23503';
  end if;
  if v_contract_company is distinct from new.company_id then
    raise exception 'INVOICE_COMPANY_MISMATCH: invoice company % does not match contract company % (cross-company injection rejected).', new.company_id, v_contract_company
      using errcode = '42501';
  end if;
  return new;
end;
$$;


