CREATE OR REPLACE FUNCTION "public"."list_fixed_monthly_accruals"("p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_date_from date := coalesce(nullif(p_payload->>'date_from', '')::date, date_trunc('month', current_date)::date);
  v_date_to date := coalesce(nullif(p_payload->>'date_to', '')::date, current_date);
  v_total integer;
  v_net numeric;
  v_tax numeric;
  v_gross numeric;
  v_reversed integer;
  v_rows jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'FIXED_MONTHLY_ROLE_REQUIRED: ADMIN, MANAGER or ACCOUNTANT is required.' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if not public.is_company_member(v_company_id, v_actor) then
    raise exception 'FIXED_MONTHLY_ACTIVE_COMPANY_MEMBERSHIP_REQUIRED' using errcode = '42501';
  end if;
  if v_date_from > v_date_to then
    raise exception 'FIXED_MONTHLY_LIST_RANGE_INVALID' using errcode = '22023';
  end if;
  if (v_date_to - v_date_from) > 365 then
    raise exception 'FIXED_MONTHLY_LIST_LIMIT_EXCEEDED: maximum range is 366 days.' using errcode = '22023';
  end if;

  select
    count(*)::integer,
    coalesce(sum(a.net_amount), 0),
    coalesce(sum(a.tax_amount), 0),
    coalesce(sum(a.gross_amount), 0),
    count(r.id)::integer
  into v_total, v_net, v_tax, v_gross, v_reversed
  from public.fixed_monthly_daily_accruals a
  left join public.fixed_monthly_daily_accrual_reversals r on r.accrual_id = a.id
  where a.company_id = v_company_id
    and a.accrual_date between v_date_from and v_date_to;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.accrual_date desc, x.id), '[]'::jsonb)
  into v_rows
  from (
    select
      a.id,
      a.owner_agreement_id,
      a.agreement_version_id,
      v.version_no,
      a.owner_id,
      coalesce(o.full_name, o.name, a.owner_id::text) as owner_name,
      a.property_id,
      coalesce(p.title, p.name, a.property_id) as property_name,
      a.accrual_date,
      a.monthly_contract_amount,
      a.monthly_amount_omr,
      a.net_amount,
      a.tax_amount,
      a.gross_amount,
      a.tax_authority_status,
      a.rounding_rule,
      case
        when r.id is not null then 'REVERSED'
        when a.journal_batch_id is null then 'ZERO_AMOUNT'
        else coalesce(b.status, 'SOURCE_ERROR')
      end as status,
      a.journal_batch_id,
      b.accounting_period_id,
      b.period_resolution_reason,
      b.posting_date,
      b.late_posting,
      r.id as reversal_id,
      r.reversal_journal_batch_id,
      r.reason as reversal_reason,
      r.created_at as reversed_at,
      a.created_at
    from public.fixed_monthly_daily_accruals a
    join public.owner_agreement_versions v on v.id = a.agreement_version_id
    left join public.owners o on o.id = a.owner_id and o.company_id = a.company_id
    left join public.properties p on p.id::text = a.property_id and p.company_id = a.company_id
    left join public.journal_batches b on b.id = a.journal_batch_id and b.company_id = a.company_id
    left join public.fixed_monthly_daily_accrual_reversals r on r.accrual_id = a.id and r.company_id = a.company_id
    where a.company_id = v_company_id
      and a.accrual_date between v_date_from and v_date_to
    order by a.accrual_date desc, a.id
    limit 500
  ) x;

  return jsonb_build_object(
    'success', true,
    'company_id', v_company_id,
    'date_from', v_date_from,
    'date_to', v_date_to,
    'total_count', v_total,
    'returned_count', jsonb_array_length(v_rows),
    'truncated', v_total > 500,
    'net_amount', round(v_net, 3),
    'tax_amount', round(v_tax, 3),
    'gross_amount', round(v_gross, 3),
    'reversed_count', v_reversed,
    'tax_authority_status', 'OUT_OF_SCOPE_NO_VERSIONED_AUTHORITY',
    'accruals', v_rows
  );
end;
$$;


ALTER FUNCTION "public"."list_fixed_monthly_accruals"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_journal_batches"("p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_status text := upper(nullif(btrim(coalesce(p_payload->>'status', '')), ''));
  v_source_type text := nullif(btrim(coalesce(p_payload->>'source_type', '')), '');
  v_source_id text := nullif(btrim(coalesce(p_payload->>'source_id', '')), '');
  v_from_date date := nullif(p_payload->>'from_date', '')::date;
  v_to_date date := nullif(p_payload->>'to_date', '')::date;
  v_limit integer := least(coalesce(nullif(p_payload->>'limit', '')::integer, 100), 500);
  v_rows jsonb;
begin
  if auth.uid() is null or not public.is_app_user() then
    raise exception 'Authenticated app user is required.' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();

  -- Apply filters and the LIMIT to the ROWS before aggregation so the cap
  -- limits the number of batches returned, not the aggregate rows.
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_rows
    from (
      select jsonb_build_object(
        'id', b.id, 'status', b.status, 'source_type', b.source_type,
        'source_id', b.source_id, 'event_id', b.event_id,
        'reversal_of_batch_id', b.reversal_of_batch_id,
        'effective_date', b.effective_date,
        'accounting_period_id', b.accounting_period_id,
        'period_resolution_reason', b.period_resolution_reason,
        'posted_at', b.posted_at, 'description', b.description,
        'created_at', b.created_at
      ) as x
      from public.journal_batches b
      where b.company_id = v_company_id
        and (v_status is null or b.status = v_status)
        and (v_source_type is null or b.source_type = v_source_type)
        and (v_source_id is null or b.source_id = v_source_id)
        and (v_from_date is null or b.effective_date >= v_from_date)
        and (v_to_date is null or b.effective_date <= v_to_date)
      order by b.created_at desc
      limit v_limit
    ) t;

  return jsonb_build_object('company_id', v_company_id, 'batches', v_rows);
end;
$$;


ALTER FUNCTION "public"."list_journal_batches"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_journal_lines"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_rows jsonb;
begin
  if auth.uid() is null or not public.is_app_user() then
    raise exception 'Authenticated app user is required.' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();

  if p_batch_id is null then
    raise exception 'GL_BATCH_ID_REQUIRED: batch_id is required.' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.journal_batches b
     where b.id = p_batch_id and b.company_id = v_company_id
  ) then
    raise exception 'GL_BATCH_NOT_FOUND: batch % does not exist in your company.', p_batch_id using errcode = 'P0002';
  end if;

  select jsonb_agg(jsonb_build_object(
    'id', l.id, 'batch_id', l.batch_id, 'account_id', l.account_id,
    'account_no', a.no, 'debit', l.debit, 'credit', l.credit,
    'line_description', l.line_description, 'created_at', l.created_at
  ) order by l.created_at, l.id)
    into v_rows
    from public.journal_lines l
    join public.accounts a on a.id = l.account_id and a.company_id = l.company_id
   where l.batch_id = p_batch_id
     and l.company_id = v_company_id;

  return jsonb_build_object('batch_id', p_batch_id, 'lines', coalesce(v_rows, '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."list_journal_lines"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_permission_requests_for_review"("p_status" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "requester_user_id" "uuid", "requester_name" "text", "requester_email" "text", "permission" "text", "resource_route" "text", "reason" "text", "status" "text", "reviewer_user_id" "uuid", "decided_at" timestamp with time zone, "decision_reason" "text", "created_at" timestamp with time zone, "grant_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_company uuid := public.require_company_id();
begin
  if not public.current_user_has_effective_app_permission('permission_requests.review') then
    raise exception 'Permission request review required' using errcode = '42501';
  end if;
  return query
  select pr.id, pr.requester_user_id, coalesce(u.full_name, u.name), u.email,
    pr.permission, pr.resource_route, pr.reason, pr.status,
    pr.reviewer_user_id, pr.decided_at, pr.decision_reason, pr.created_at,
    exists(select 1 from public.user_permission_grants g where g.company_id=pr.company_id and g.user_id=pr.requester_user_id and g.permission=pr.permission and g.revoked_at is null)
  from public.permission_requests pr left join public.users u on u.id = pr.requester_user_id
  where pr.company_id = v_company and (p_status is null or pr.status = upper(p_status))
  order by pr.created_at desc;
end;
$$;


ALTER FUNCTION "public"."list_permission_requests_for_review"("p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_document_reference"("p_company_id" "uuid", "p_doc_type" "text", "p_prefix" "text", "p_year" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_next bigint;
begin
  if p_company_id is null or p_doc_type is null or p_prefix is null or p_year is null then
    return null;
  end if;

  insert into public.document_reference_sequences (company_id, doc_type, prefix, year, last_value)
  values (p_company_id, p_doc_type, p_prefix, p_year, 1)
  on conflict (company_id, doc_type, year)
  do update set last_value = public.document_reference_sequences.last_value + 1
  returning last_value into v_next;

  return format('%s-%s-%s', p_prefix, p_year, lpad(v_next::text, 6, '0'));
end;
$$;


ALTER FUNCTION "public"."next_document_reference"("p_company_id" "uuid", "p_doc_type" "text", "p_prefix" "text", "p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_onboarding_requirement_completion_source"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.required
     and (new.completion_source is null or new.completion_source = 'NONE') then
    new.completion_source := case new.code
      when 'owner'    then 'OWNER_EXISTS'
      when 'property' then 'PROPERTY_EXISTS'
      when 'unit'     then 'UNIT_EXISTS'
      when 'contract' then 'CONTRACT_EXISTS'
      when 'invoice'  then 'INVOICE_EXISTS'
      else new.completion_source
    end;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_onboarding_requirement_completion_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_unit_status_contract"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  canonical_status text;
begin
  canonical_status := case btrim(lower(new.status::text))
    when 'available' then 'available'
    when 'occupied' then 'occupied'
    when 'rented' then 'occupied'
    when 'maintenance' then 'maintenance'
    when 'reserved' then 'reserved'
    else null
  end;

  if canonical_status is null then
    raise exception 'Unsupported public.units.status value: %', new.status;
  end if;

  new.status := canonical_status;
  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_unit_status_contract"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."offset_owner_receivable_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_dfo_id uuid := nullif(p_payload->>'due_from_owner_id','')::uuid;
  v_settlement_id text := nullif(btrim(coalesce(p_payload->>'owner_settlement_id','')), '');
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_amount numeric := public.wp02_gap008_round_omr(nullif(p_payload->>'amount','')::numeric);
  v_date date := nullif(p_payload->>'effective_date','')::date;
  v_evidence text := nullif(btrim(coalesce(p_payload->>'lawful_offset_evidence','')), '');
  v_dfo public.due_from_owners%rowtype;
  v_settlement public.owner_settlements%rowtype;
  v_ofp_id text; v_due_id text; v_post jsonb; v_batch_id uuid;
  v_fp text; v_cached jsonb; v_id uuid := gen_random_uuid(); v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DUE_FROM_OWNER_OFFSET_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if p_payload ?| array['company_id','amount_override','target_account'] then
    raise exception 'DUE_FROM_OWNER_OFFSET_SERVER_OWNED_FIELDS_FORBIDDEN' using errcode = '22023';
  end if;
  if v_dfo_id is null or v_settlement_id is null or v_request_id is null
     or v_amount is null or v_amount <= 0 or v_date is null or v_evidence is null or length(v_evidence) < 3 then
    raise exception 'DUE_FROM_OWNER_OFFSET_REQUEST_AMOUNT_DATE_EVIDENCE_REQUIRED' using errcode = '22023';
  end if;

  v_fp := encode(sha256(convert_to(jsonb_build_object(
    'due_from_owner_id', v_dfo_id,
    'owner_settlement_id', v_settlement_id,
    'amount', v_amount,
    'effective_date', v_date
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended('due_from_owner_offset:' || v_company_id::text || ':' || v_request_id, 0));

  select response_payload into v_cached
    from public.financial_operation_idempotency
   where operation_name = 'offset_owner_receivable_atomic:' || v_company_id::text
     and request_id = v_request_id for update;
  if v_cached is not null then
    if v_cached->>'_request_fingerprint' is distinct from v_fp or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode = '22023';
    end if;
    return v_cached->'response';
  end if;

  select * into v_dfo from public.due_from_owners
   where id = v_dfo_id and company_id = v_company_id for update;
  if not found then
    raise exception 'DUE_FROM_OWNER_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;
  if v_dfo.status = 'REVERSED' then
    raise exception 'DUE_FROM_OWNER_OFFSET_REVERSED' using errcode = '22023';
  end if;
  if not v_dfo.lawful_offset_right then
    raise exception 'DUE_FROM_OWNER_OFFSET_RIGHT_MISSING: no enforceable contractual/legal offset right on this receivable.' using errcode = '23514';
  end if;
  if v_amount > v_dfo.outstanding + 0.001 then
    raise exception 'DUE_FROM_OWNER_OFFSET_EXCEEDS_OUTSTANDING' using errcode = '22023';
  end if;

  select * into v_settlement from public.owner_settlements
   where id = v_settlement_id and company_id = v_company_id for update;
  if not found then
    raise exception 'DUE_FROM_OWNER_OFFSET_SETTLEMENT_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;
  if v_settlement.owner_id::uuid is distinct from v_dfo.owner_id then
    raise exception 'DUE_FROM_OWNER_OFFSET_OWNER_MISMATCH' using errcode = '42501';
  end if;
  if v_settlement.status <> 'APPROVED' then
    raise exception 'DUE_FROM_OWNER_OFFSET_SETTLEMENT_NOT_APPROVED: offset is only permitted against an APPROVED (unpaid) owner payable.' using errcode = '22023';
  end if;
  if v_amount > public.wp02_gap008_round_omr(v_settlement.net_payable - v_settlement.offset_applied) + 0.001 then
    raise exception 'DUE_FROM_OWNER_OFFSET_EXCEEDS_PAYABLE: would force Owner Funds Payable negative.' using errcode = '22023';
  end if;

  v_ofp_id := public.gl_pm_require_account(v_company_id, '2000');
  v_due_id := public.gl_pm_require_account(v_company_id, '1300');
  v_post := public.post_journal_event(jsonb_build_object(
    'company_id', v_company_id,
    'source_type', 'pm_due_from_owner_offset',
    'source_id', v_dfo_id::text,
    'event_id', 'offset',
    'effective_date', v_date,
    'description', 'Lawful settlement offset: Owner Funds Payable against Due from Owner',
    'lines', jsonb_build_array(
      jsonb_build_object('account_id', v_ofp_id, 'debit', v_amount, 'credit', 0,
        'ref_source_id', v_dfo_id::text, 'ref_entity_type', 'due_from_owner', 'ref_entity_id', v_dfo_id::text),
      jsonb_build_object('account_id', v_due_id, 'debit', 0, 'credit', v_amount,
        'ref_source_id', v_dfo_id::text, 'ref_entity_type', 'due_from_owner', 'ref_entity_id', v_dfo_id::text)
    )
  ));
  v_batch_id := (v_post->>'batch_id')::uuid;

  insert into public.due_from_owner_offsets (
    id, company_id, due_from_owner_id, owner_id, owner_settlement_id, amount, effective_date,
    request_id, source_fingerprint, journal_batch_id, lawful_offset_evidence, posted_by
  ) values (
    v_id, v_company_id, v_dfo_id, v_dfo.owner_id, v_settlement_id, v_amount, v_date,
    v_request_id, encode(sha256(convert_to(v_amount::text,'UTF8')),'hex'), v_batch_id, v_evidence, v_actor
  );

  -- Complete the RC1 2000 operational control in the same transaction. The
  -- owner-funds trigger sees the already-posted journal batch and therefore
  -- rejects atomically if this debit would make 2000 negative or if a required
  -- historical cutover has not been approved.
  insert into public.owner_funds_events (
    company_id, owner_id, contract_id, invoice_id, source_type, source_id,
    event_id, amount_delta, effective_date, journal_batch_id
  ) values (
    v_company_id, v_dfo.owner_id, null, null, 'OWNER_OFFSET', v_id::text,
    v_request_id, -v_amount, v_date, v_batch_id
  );

  update public.owner_settlements
     set offset_applied = public.wp02_gap008_round_omr(offset_applied + v_amount), updated_at = now()
   where id = v_settlement_id;

  update public.due_from_owners
     set offset_amount = public.wp02_gap008_round_omr(offset_amount + v_amount),
         outstanding = public.wp02_gap008_round_omr(outstanding - v_amount),
         status = case
           when public.wp02_gap008_round_omr(outstanding - v_amount) = 0 then 'CLOSED'
           else 'OFFSET' end,
         updated_at = now()
   where id = v_dfo_id;

  v_result := jsonb_build_object(
    'success', true, 'idempotent', false, 'due_from_owner_id', v_dfo_id,
    'owner_settlement_id', v_settlement_id, 'amount', v_amount,
    'outstanding', public.wp02_gap008_round_omr(v_dfo.outstanding - v_amount),
    'journal_batch_id', v_batch_id,
    'status', case when public.wp02_gap008_round_omr(v_dfo.outstanding - v_amount) = 0 then 'CLOSED' else 'OFFSET' end,
    'request_id', v_request_id
  );
  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('offset_owner_receivable_atomic:' || v_company_id::text, v_request_id,
          jsonb_build_object('_request_fingerprint', v_fp, 'response', v_result));
  return v_result;
end;
$$;


ALTER FUNCTION "public"."offset_owner_receivable_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."offset_owner_receivable_atomic"("p_payload" "jsonb") IS 'GAP-008 lawful Dr 2000 / Cr 1300 offset with RC1 append-only Owner Funds Payable control.';



CREATE OR REPLACE FUNCTION "public"."owner_agreement_version_for_contract_internal"("p_owner_agreement_id" "uuid", "p_company_id" "uuid", "p_start" "date", "p_end" "date") RETURNS "public"."owner_agreement_versions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_parent public.owner_agreements%rowtype;
  v_version public.owner_agreement_versions%rowtype;
begin
  select v.* into v_version
  from public.owner_agreement_versions v
  where v.owner_agreement_id=p_owner_agreement_id
    and v.company_id=p_company_id
    and v.effective_from <= p_start
    and (v.effective_to is null or v.effective_to >= p_end)
  order by v.version_no desc
  limit 1;
  if found then return v_version; end if;

  select * into v_parent
  from public.owner_agreements
  where id=p_owner_agreement_id
    and company_id=p_company_id
  for update;

  if not found or v_parent.agreement_type <> 'property_management' then
    raise exception 'CONTRACT_AGREEMENT_VERSION_COVERAGE_REQUIRED' using errcode='23514';
  end if;

  -- A concurrent first activation may have created version 1 while this
  -- transaction waited on the parent lock. Re-check after acquiring it.
  select v.* into v_version
  from public.owner_agreement_versions v
  where v.owner_agreement_id=p_owner_agreement_id
    and v.company_id=p_company_id
    and v.effective_from <= p_start
    and (v.effective_to is null or v.effective_to >= p_end)
  order by v.version_no desc
  limit 1;
  if found then return v_version; end if;

  -- Once any version exists, a missing covering version is intentional history
  -- or a real coverage gap; never manufacture a bridge across it.
  if exists (
    select 1 from public.owner_agreement_versions
    where owner_agreement_id=p_owner_agreement_id
      and company_id=p_company_id
  ) then
    raise exception 'CONTRACT_AGREEMENT_VERSION_COVERAGE_REQUIRED' using errcode='23514';
  end if;

  if v_parent.starts_on > p_start
     or (v_parent.ends_on is not null and v_parent.ends_on < p_end) then
    raise exception 'CONTRACT_AGREEMENT_VERSION_COVERAGE_REQUIRED' using errcode='23514';
  end if;

  insert into public.owner_agreement_versions (
    owner_agreement_id,company_id,version_no,operating_model,collection_role,
    commission_type,commission_value,commission_recognition_basis,
    offset_allowed,reserve_amount,effective_from,effective_to,notes,created_at
  ) values (
    v_parent.id,v_parent.company_id,1,'OWNER_AGENCY','OWNER_IS_CREDITOR',
    v_parent.commission_type,v_parent.commission_value,
    case when v_parent.commission_type='RATE' then 'ON_COLLECTION' else 'DAILY_ACCRUAL' end,
    false,0,v_parent.starts_on,v_parent.ends_on,v_parent.notes,coalesce(v_parent.created_at,now())
  ) returning * into v_version;

  update public.owner_agreements
  set current_version_id=v_version.id,
      updated_at=now()
  where id=v_parent.id
    and company_id=v_parent.company_id
    and current_version_id is null;

  return v_version;
end;
$$;


ALTER FUNCTION "public"."owner_agreement_version_for_contract_internal"("p_owner_agreement_id" "uuid", "p_company_id" "uuid", "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_settlement_maker_checker_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_maker uuid;
  v_checker uuid;
begin
  -- CREATE draft transition: record maker if authenticated
  if tg_op = 'INSERT' then
    if v_actor is not null then
      if new.maker_user_id is not null and new.maker_user_id <> v_actor then
        raise exception 'Owner settlement maker identity cannot be supplied for another user.'
          using errcode = '42501';
      end if;
      new.maker_user_id := v_actor;
    end if;
    return new;
  end if;

  -- Once established, maker/checker identities are immutable.
  if old.maker_user_id is not null
     and new.maker_user_id is distinct from old.maker_user_id then
    raise exception 'Owner settlement maker identity is immutable.'
      using errcode = '42501';
  end if;
  if old.checker_user_id is not null
     and new.checker_user_id is distinct from old.checker_user_id then
    raise exception 'Owner settlement checker identity is immutable.'
      using errcode = '42501';
  end if;

  v_maker := old.maker_user_id;
  v_checker := old.checker_user_id;

  if v_maker is null then
    v_maker := new.maker_user_id;
  end if;

  -- DRAFT -> APPROVED transition: enforce maker-checker
  if upper(coalesce(old.status::text, '')) = 'DRAFT'
     and upper(coalesce(new.status::text, '')) = 'APPROVED' then
    if v_actor is null then
      raise exception 'Authenticated checker identity is required to approve owner settlements.'
        using errcode = '42501';
    end if;
    if v_maker is null then
      raise exception 'Owner settlement maker identity cannot be proven; approval is blocked.'
        using errcode = '42501';
    end if;
    if v_actor = v_maker then
      if not public.wp01_is_sole_admin_allowed(new.company_id) then
        raise exception 'MAKER_CHECKER_SELF_APPROVAL_DENIED: settlement maker cannot approve the same settlement.'
          using errcode = '42501';
      end if;
      new.is_sole_admin_exception := true;
    end if;

    new.maker_user_id := v_maker;
    new.checker_user_id := v_actor;

    if new.approved_by is null or new.approved_by <> v_actor then
      raise exception 'Settlement approved_by must match the authenticated checker.'
        using errcode = '42501';
    end if;
  end if;

  -- APPROVED -> PAID transition: enforce original maker check
  if upper(coalesce(old.status::text, '')) = 'APPROVED'
     and upper(coalesce(new.status::text, '')) = 'PAID' then
    if v_actor is null then
      raise exception 'Authenticated payout actor is required for owner settlements.'
        using errcode = '42501';
    end if;
    if v_maker is null then
      raise exception 'Owner settlement maker identity cannot be proven; payout is blocked.'
        using errcode = '42501';
    end if;
    if v_actor = v_maker then
      if not public.wp01_is_sole_admin_allowed(new.company_id) then
        raise exception 'MAKER_CHECKER_SELF_PAYMENT_DENIED: settlement maker cannot pay the same settlement.'
          using errcode = '42501';
      end if;
      new.is_sole_admin_exception := true;
    end if;
    if v_checker is null then
      raise exception 'Owner settlement checker identity cannot be proven; payout is blocked.'
        using errcode = '42501';
    end if;

    new.maker_user_id := v_maker;
    new.checker_user_id := v_checker;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."owner_settlement_maker_checker_guard"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."owner_settlement_maker_checker_guard"() IS 'WP-01 SEC-008 authoritative table-boundary maker-checker guard for authenticated owner settlement create, approve and payout transitions.';



CREATE OR REPLACE FUNCTION "public"."owner_settlement_reservable_expenses"("p_company_id" "uuid", "p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text" DEFAULT NULL::"text") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  return query
    select e.id
      from public.expenses e
     where e.deleted_at is null
       and e.company_id = p_company_id
       and upper(coalesce(e.status, '')) = 'POSTED'
       and upper(coalesce(e.charged_to, '')) = 'OWNER'
       and (p_property_id is null or e.property_id::text = p_property_id::text)
       and public._safe_date(e.date_time) between p_period_start and p_period_end
       and exists (
         select 1
           from public.property_owners po
          where po.property_id = e.property_id
            and po.owner_id = p_owner_id
            and (po.starts_on is null or po.starts_on <= public._safe_date(e.date_time))
            and (po.ends_on is null or po.ends_on >= public._safe_date(e.date_time))
       );
end;
$$;


ALTER FUNCTION "public"."owner_settlement_reservable_expenses"("p_company_id" "uuid", "p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."owner_settlement_reservable_expenses"("p_company_id" "uuid", "p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text") IS 'FA-003: the deterministic set of owner-expense ids that belong to a settlement for a given company/owner/property/period.';



CREATE OR REPLACE FUNCTION "public"."owner_settlement_reservable_payments"("p_company_id" "uuid", "p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text" DEFAULT NULL::"text") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  return query
    select p.id
      from public.payments p
      join public.contracts c
        on c.id = p.contract_id
       and c.deleted_at is null
       and c.company_id = p_company_id
      join public.owner_agreements oa
        on oa.id = c.agreement_id
       and oa.owner_id = p_owner_id
       and oa.company_id = p_company_id
     where p.deleted_at is null
       and p.company_id = p_company_id
       and upper(coalesce(p.status, '')) <> 'VOID'
       and coalesce(p.payment_date, public._safe_date(p.date_time::text))
             between p_period_start and p_period_end
       and (p_property_id is null or c.property_id::text = p_property_id::text)
       and oa.agreement_type <> 'master_lease';
end;
$$;


ALTER FUNCTION "public"."owner_settlement_reservable_payments"("p_company_id" "uuid", "p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."owner_settlement_reservable_payments"("p_company_id" "uuid", "p_owner_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_property_id" "text") IS 'FA-003: the deterministic set of payment ids that belong to a settlement for a given company/owner/property/period. Shared by create, approve, pay, diagnostic and backfill so item membership is always derived from one source.';



CREATE OR REPLACE FUNCTION "public"."pay_commission_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_commission_id text := nullif(trim(p_payload->>'commission_id'), '');
  v_request_id text := nullif(trim(p_payload->>'request_id'), '');
  v_payment_date date := coalesce(nullif(trim(p_payload->>'payment_date'), '')::date, current_date);
  v_account_id text := nullif(trim(p_payload->>'account_id'), '');
  v_property_id uuid := nullif(trim(p_payload->>'property_id'), '')::uuid;
  v_comm public.commissions%rowtype;
  v_expense_id uuid;
  v_expense_no text;
  v_expense_account_id text;
  v_cash_account_id text;
  v_cached jsonb;
  v_result jsonb;
begin
  if auth.uid() is null or not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لصرف العمولة' using errcode = '42501';
  end if;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'سياق الشركة مطلوب لصرف العمولة' using errcode = '42501';
  end if;

  if v_commission_id is null then
    raise exception 'معرّف العمولة مطلوب' using errcode = '23514';
  end if;

  if v_request_id is null or v_request_id = '' then
    v_request_id := gen_random_uuid()::text;
  end if;

  -- Advisory lock per company + commission_id to prevent concurrent duplicate payment
  perform pg_advisory_xact_lock(
    hashtextextended('pay_commission_atomic:' || v_company_id::text || ':' || v_commission_id, 0)
  );

  -- Idempotency check scoped by company
  select response_payload into v_cached
  from public.financial_operation_idempotency
  where operation_name = 'pay_commission_atomic:' || v_company_id::text
    and request_id = v_request_id;
  if v_cached is not null then
    return v_cached || jsonb_build_object('idempotent', true);
  end if;

  -- Select commission with company isolation
  select * into v_comm
  from public.commissions
  where id = v_commission_id
    and company_id = v_company_id;

  if not found then
    raise exception 'العمولة غير موجودة أو لا تنتمي لشركتك' using errcode = '23514';
  end if;

  if lower(coalesce(v_comm.status, '')) = 'paid' or v_comm.expense_id is not null then
    raise exception 'العمولة مدفوعة بالفعل ولا يمكن تكرار صرفها' using errcode = '23514';
  end if;

  if lower(coalesce(v_comm.status, '')) = 'cancelled' then
    raise exception 'لا يمكن صرف عمولة ملغاة' using errcode = '23514';
  end if;

  if coalesce(v_comm.amount, 0) <= 0 then
    raise exception 'قيمة العمولة غير صحيحة أو تساوي صفراً' using errcode = '23514';
  end if;

  -- Resolve payment account: verify it belongs to current company and is an eligible account
  if v_account_id is not null then
    select id into v_cash_account_id
    from public.accounts
    where (id = v_account_id or no = v_account_id)
      and company_id = v_company_id
    limit 1;
    if v_cash_account_id is null then
      raise exception 'الحساب المحاسبي المحدد للدفع غير موجود في شركتك' using errcode = '23514';
    end if;
  else
    v_cash_account_id := public.require_company_account_id(v_company_id, '1111');
  end if;

  -- Resolve expense account via canonical company-scoped resolver
  v_expense_account_id := public.require_company_account_id(v_company_id, '6100');

  -- Resolve property_id if not explicitly provided and commission is contract-related
  if v_property_id is null and lower(coalesce(v_comm.type, '')) = 'contract' and v_comm.source_id is not null then
    select c.property_id into v_property_id
    from public.contracts c
    where c.id::text = v_comm.source_id
      and c.company_id = v_company_id
    limit 1;
  end if;

  if v_property_id is null then
    select id into v_property_id
    from public.properties
    where company_id = v_company_id
      and deleted_at is null
    order by id
    limit 1;
  end if;

  if v_property_id is null then
    raise exception 'يجب وجود عقار مسجل في الشركة لربط مصروف العمولة به' using errcode = '23514';
  end if;

  v_expense_id := gen_random_uuid();
  v_expense_no := 'CEXP-' || to_char(now(), 'YYYYMMDD') || '-' || substr(replace(v_request_id, '-', ''), 1, 6);

  -- Create POSTED expense record representing commission payout
  insert into public.expenses (
    id, property_id, category, amount, expense_date, description,
    status, date_time, no, company_id
  ) values (
    v_expense_id, v_property_id, 'Commission', v_comm.amount, v_payment_date,
    'صرف عمولة الوسيط/الموظف: ' || coalesce(v_comm.staff_name, 'غير محدد'),
    'POSTED', now(), v_expense_no, v_company_id
  );

  -- Insert balanced journal entries (DEBIT expense, CREDIT cash)
  insert into public.journal_entries (
    id, no, date, account_id, amount, type, source_id, entity_type, entity_id, created_at, company_id
  ) values
    (gen_random_uuid()::text, v_expense_no || '-D', v_payment_date::text, v_expense_account_id, v_comm.amount, 'DEBIT', v_expense_id::text, 'expense', v_expense_id::text, now(), v_company_id),
    (gen_random_uuid()::text, v_expense_no || '-C', v_payment_date::text, v_cash_account_id, v_comm.amount, 'CREDIT', v_expense_id::text, 'expense', v_expense_id::text, now(), v_company_id);

  -- Authorize financial trigger and update commission status
  perform set_config('malik.financial_commission_authorized', 'true', true);

  update public.commissions
  set status = 'paid',
      expense_id = v_expense_id,
      paid_at = floor(extract(epoch from now()) * 1000)::bigint,
      updated_at = now()
  where id = v_commission_id
    and company_id = v_company_id;

  -- Audit log entry
  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid()::text,
    extract(epoch from now())::bigint,
    auth.uid()::text,
    (select email from auth.users where id = auth.uid()),
    'CREATE', 'commissions', v_commission_id,
    'Commission financially paid with POSTED expense and balanced journal entry',
    'commissions', left(p_payload::text, 4000), now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'commission_id', v_commission_id,
    'expense_id', v_expense_id,
    'expense_no', v_expense_no,
    'amount', v_comm.amount
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload, created_at
  ) values (
    'pay_commission_atomic:' || v_company_id::text,
    v_request_id,
    v_result,
    now()
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."pay_commission_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_owner_settlement_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_id text := nullif(p_payload->>'settlement_id', '');
  v_status text;
  v_result jsonb;
begin
  v_company_id := public.current_company_id();

  if v_id is not null and v_company_id is not null then
    select s.status
      into v_status
      from public.owner_settlements s
     where s.id::text = v_id
       and s.company_id = v_company_id;

    if v_status = 'APPROVED' then
      perform public.assert_owner_settlement_totals_fresh(v_id);
    end if;
  end if;

  v_result := public.pay_owner_settlement_atomic_s02_base(p_payload);

  if not coalesce((v_result->>'idempotent')::boolean, false) then
    perform public.assert_owner_settlement_totals_fresh(v_result->>'settlement_id');
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."pay_owner_settlement_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pay_owner_settlement_atomic"("p_payload" "jsonb") IS 'S02-T05 guarded payment: FA-003 lifecycle semantics plus exact reserved-set parity and live stale-total rejection before first payment effect.';



CREATE OR REPLACE FUNCTION "public"."pay_owner_settlement_atomic_s02_base"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_id text := nullif(p_payload->>'settlement_id', '');
  v_method text := nullif(btrim(p_payload->>'method'), '');
  v_reference text := nullif(btrim(p_payload->>'payment_reference'), '');
  v_row public.owner_settlements%rowtype;
  v_owner_payable_account text;
  v_cash_account text;
  v_batch_id uuid;
  v_post jsonb;
  v_cached jsonb;
  v_result jsonb;
  v_operation_name text;
  v_request_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target_id text;
  v_updated_count integer;
  v_effective_payable numeric;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to pay owner settlements.'
      using errcode = '42501';
  end if;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Company context is required (no company_id claim in JWT).'
      using errcode = '42501';
  end if;
  if v_id is null or v_request_id is null or v_method is null then
    raise exception 'settlement_id, request_id, and method are required.'
      using errcode = '22023';
  end if;

  v_operation_name := 'pay_owner_settlement_atomic:' || v_company_id::text;
  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'settlement_id', v_id,
    'method', v_method,
    'payment_reference', v_reference
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_operation_name || ':' || v_request_id, 0)
  );

  select *
    into v_row
  from public.owner_settlements s
  where s.id::text = v_id
    and s.company_id = v_company_id
  for update;

  if not found then
    raise exception 'Owner settlement not found.'
      using errcode = 'P0002';
  end if;

  select response_payload
    into v_cached
  from public.financial_operation_idempotency
  where operation_name = v_operation_name
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    v_cached_target_id := v_cached->>'_target_id';
    if v_cached_fingerprint is null
       or v_cached_target_id is null
       or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        using errcode = '22023';
    end if;
    if v_cached_fingerprint <> v_request_fingerprint
       or v_cached_target_id <> v_id then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode = '22023';
    end if;
    return (v_cached->'response') || jsonb_build_object('idempotent', true);
  end if;

  if v_row.status <> 'APPROVED' then
    raise exception 'Only APPROVED settlements can be paid.'
      using errcode = '22023';
  end if;

  -- GAP-008: the lawful offset already debited 2000 / credited 1300.
  v_effective_payable := public.wp02_gap008_round_omr(v_row.net_payable - coalesce(v_row.offset_applied, 0));
  if v_effective_payable < 0 then
    raise exception 'OWNER_SETTLEMENT_EFFECTIVE_PAYABLE_NEGATIVE' using errcode = '22023';
  end if;

  -- ── FA-003: the paid settlement must own exactly its fully-reserved items and
  -- no released link. No new links are created here; the reserved set is the
  -- final set. PAID links stay released_at = NULL forever.
  if exists (
    select 1
      from public.owner_settlement_reservable_payments(
        v_company_id, v_row.owner_id::uuid, v_row.period_start, v_row.period_end, v_row.property_id::text) p
      left join public.owner_settlement_payment_links l
        on l.payment_id = p and l.settlement_id = v_row.id::text
       and l.company_id = v_company_id and l.released_at is null
     where l.id is null
  ) or exists (
    select 1
      from public.owner_settlement_reservable_expenses(
        v_company_id, v_row.owner_id::uuid, v_row.period_start, v_row.period_end, v_row.property_id::text) e
      left join public.owner_settlement_expense_links l
        on l.expense_id = e and l.settlement_id = v_row.id::text
       and l.company_id = v_company_id and l.released_at is null
     where l.id is null
  ) then
    raise exception 'OWNER_SETTLEMENT_INCOMPLETE_RESERVATION: settlement is not fully reserved by its derived items.'
      using errcode = 'P0001';
  end if;
  if exists (
    select 1 from public.owner_settlement_payment_links l
     where l.settlement_id = v_row.id::text and l.company_id = v_company_id and l.released_at is not null
  ) or exists (
    select 1 from public.owner_settlement_expense_links l
     where l.settlement_id = v_row.id::text and l.company_id = v_company_id and l.released_at is not null
  ) then
    raise exception 'OWNER_SETTLEMENT_HAS_RELEASED_LINKS: released items cannot be paid.'
      using errcode = 'P0001';
  end if;

  -- GAP-008 + S03 GL write boundary: the residual owner payout posts through
  -- the canonical posting engine (Dr 2000 Owner Funds Payable / Cr 1111 Cash),
  -- never through a new legacy journal_entries writer. When the lawful offset
  -- already cleared the full payable (effective payable = 0) the settlement is
  -- closed without creating a zero-value journal event: the offset itself was
  -- the final economic event (Dr 2000 / Cr 1300) and a 0/0 batch would be
  -- rejected by the engine's positive-side line contract anyway.
  if v_effective_payable > 0 then
    v_owner_payable_account := public.require_company_account_id(v_company_id, '2000');
    v_cash_account := public.require_company_account_id(v_company_id, '1111');

    -- Bootstrap only a company's very first accounting period (same rule as the
    -- S03 receipt path). Once any period exists, the fail-closed OPEN/SOFT_CLOSED/
    -- HARD_CLOSED resolver inside the engine remains authoritative.
    perform public.gl_ensure_initial_open_period(v_company_id, current_date);

    v_post := public.post_journal_event(jsonb_build_object(
      'company_id', v_company_id,
      'source_type', 'owner_settlement_payment',
      'source_id', v_id,
      'event_id', 'pay',
      'effective_date', current_date,
      'description', 'Owner settlement payout: Owner Funds Payable vs Cash (net of lawful offset)',
      'lines', jsonb_build_array(
        jsonb_build_object(
          'account_id', v_owner_payable_account, 'debit', v_effective_payable, 'credit', 0,
          'ref_source_id', v_id, 'ref_entity_type', 'owner_settlement_payment', 'ref_entity_id', v_id
        ),
        jsonb_build_object(
          'account_id', v_cash_account, 'debit', 0, 'credit', v_effective_payable,
          'ref_source_id', v_id, 'ref_entity_type', 'owner_settlement_payment', 'ref_entity_id', v_id
        )
      )
    ));
    v_batch_id := (v_post->>'batch_id')::uuid;
    if v_batch_id is null then
      raise exception 'OWNER_SETTLEMENT_JOURNAL_BATCH_MISSING'
        using errcode = 'P0001';
    end if;
  else
    v_batch_id := null;
  end if;

  update public.owner_settlements
     set status = 'PAID',
         method = v_method,
         payment_reference = v_reference,
         paid_at = now(),
         paid_by = auth.uid(),
         updated_at = now()
   where id::text = v_id
     and company_id = v_company_id;
  get diagnostics v_updated_count = row_count;
  if v_updated_count <> 1 then
    raise exception 'OWNER_SETTLEMENT_UPDATE_COUNT_MISMATCH'
      using errcode = 'P0001';
  end if;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'PAY', 'owner_settlements', v_id,
    case
      when v_effective_payable > 0
        then 'Owner settlement paid with balanced owner-payable/cash journal batch (canonical GL engine)'
      else 'Owner settlement closed as PAID: lawful offset fully cleared the payable; no zero-value journal event created'
    end,
    'owner_settlements', left(p_payload::text, 4000), now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'settlement_id', v_id,
    'status', 'PAID',
    'net_payable', v_row.net_payable,
    'offset_applied', coalesce(v_row.offset_applied, 0),
    'effective_payable', v_effective_payable,
    'journal_batch_id', v_batch_id,
    'request_id', v_request_id
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload
  ) values (
    v_operation_name,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_id,
      'response', v_result
    )
  )
  on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."pay_owner_settlement_atomic_s02_base"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pay_owner_settlement_atomic_s02_base"("p_payload" "jsonb") IS 'FA-003: payment requires full reservation, creates no new links, and leaves PAID links permanently unreleased.';



CREATE OR REPLACE FUNCTION "public"."payment_receipt_identity_preflight"() RETURNS TABLE("payments_without_receipt_id" bigint, "payment_id_receipt_id_mismatches" bigint, "receipts_with_multiple_payments" bigint, "receipts_without_payment" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    (select count(*) from public.payments p where p.receipt_id is null),
    (select count(*) from public.payments p where p.receipt_id is not null and p.id::text is distinct from p.receipt_id::text),
    (select count(*) from (select p.receipt_id from public.payments p group by p.receipt_id having count(*) > 1) d),
    (select count(*) from public.receipts r where not exists (select 1 from public.payments p where p.receipt_id::text = r.id::text));
$$;


ALTER FUNCTION "public"."payment_receipt_identity_preflight"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."phase3a1a_set_cost_center_company"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_property_company_id uuid;
begin
  if new.property_id is not null then
    select p.company_id into v_property_company_id
    from public.properties p
    where p.id::text = new.property_id::text
      and p.deleted_at is null;
    if v_property_company_id is null then
      raise exception 'Cost center property was not found.' using errcode = '23503';
    end if;
    if new.company_id is not null and new.company_id <> v_property_company_id then
      raise exception 'Cost center company does not match its property.' using errcode = '23514';
    end if;
    new.company_id := v_property_company_id;
  elsif new.company_id is null then
    new.company_id := public.current_company_id();
  end if;

  if new.company_id is null then
    raise exception 'Cost center company is required.' using errcode = '23502';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."phase3a1a_set_cost_center_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_journal_event"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_source_type text;
  v_source_id text;
  v_event_id text;
  v_effective_date date;
  v_description text;
  v_lines jsonb;
  v_normalized jsonb;
  v_fingerprint text;
  v_existing public.journal_batches%rowtype;
  v_existing_fingerprint text;
  v_batch_id uuid;
  v_result jsonb;
  v_created jsonb;
begin
  if current_user not in ('postgres', 'supabase_admin', 'service_role') then
    raise exception 'GL_ENGINE_SERVER_ONLY: the posting engine is only callable from a trusted server context.' using errcode = '42501';
  end if;

  v_company_id := nullif(p_payload->>'company_id', '')::uuid;
  v_source_type := nullif(btrim(coalesce(p_payload->>'source_type', '')), '');
  v_source_id := nullif(btrim(coalesce(p_payload->>'source_id', '')), '');
  v_event_id := nullif(btrim(coalesce(p_payload->>'event_id', '')), '');
  v_effective_date := nullif(p_payload->>'effective_date', '')::date;
  v_description := nullif(p_payload->>'description', '');
  v_lines := p_payload->'lines';

  if v_company_id is null or v_source_type is null or v_source_id is null or v_event_id is null or v_effective_date is null then
    raise exception 'GL_EVENT_METADATA_REQUIRED: company_id, source_type, source_id, event_id and effective_date are required.' using errcode = '22023';
  end if;

  v_normalized := public.gl_validate_and_normalize_lines(v_company_id, v_lines);
  v_fingerprint := public.gl_lines_fingerprint(v_normalized);

  perform pg_advisory_xact_lock(hashtextextended('gl_event:' || v_company_id::text || ':' || v_source_type || ':' || v_source_id || ':' || v_event_id, 0));

  select * into v_existing
    from public.journal_batches b
   where b.company_id = v_company_id
     and b.source_type = v_source_type
     and b.source_id = v_source_id
     and b.event_id = v_event_id;

  if found then
    -- Idempotency conflict detection: same event identity, materially
    -- different financial content must fail loudly.
    select coalesce(encode(sha256(convert_to(
      (select jsonb_agg(jsonb_build_object(
        'a', l.account_id, 'd', l.debit, 'c', l.credit
      ) order by l.account_id, l.debit, l.credit) from public.journal_lines l where l.batch_id = v_existing.id)::text, 'UTF8')), 'hex'))
      into v_existing_fingerprint;

    if v_existing_fingerprint is distinct from v_fingerprint then
      raise exception 'GL_EVENT_CONFLICT: event % was already recorded with different financial content. Retry must carry identical lines.', v_event_id using errcode = '23505';
    end if;

    if v_existing.status = 'REVERSED' then
      raise exception 'GL_EVENT_ALREADY_REVERSED: event % was already posted and reversed; it cannot be posted again.', v_event_id using errcode = 'P0001';
    end if;

    if v_existing.status = 'POSTED' then
      return public.gl_post_journal_batch(v_existing.id);
    end if;
  end if;

  v_created := public.gl_create_journal_batch(jsonb_build_object(
    'company_id', v_company_id,
    'source_type', v_source_type,
    'source_id', v_source_id,
    'event_id', v_event_id,
    'effective_date', v_effective_date,
    'description', v_description,
    'lines', v_normalized
  ));

  v_batch_id := (v_created->>'batch_id')::uuid;
  v_result := public.gl_post_journal_batch(v_batch_id);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."post_journal_event"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_receipt_atomic"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_receipt jsonb;
  v_allocations jsonb;
  v_journal_entries jsonb;
  v_request_id text;
  v_existing_id public.receipts.id%TYPE;
  v_invoice_id_text text;
  v_invoice record;
  v_allocation_total numeric;

  v_receipt_id public.receipts.id%TYPE;
  v_receipt_contract_id public.receipts.contract_id%TYPE;
  v_receipt_date_time public.receipts.date_time%TYPE;
  v_receipt_tenant_id public.receipts.tenant_id%TYPE;
  v_receipt_check_date public.receipts.check_date%TYPE;
  v_receipt_amount numeric;
  v_receipt_channel text;
  v_receipt_ref text;
  v_receipt_notes text;
  v_receipt_status text;

  v_allocation jsonb;
  v_allocation_id public.receipt_allocations.id%TYPE;
  v_allocation_receipt_id public.receipt_allocations.receipt_id%TYPE;
  v_allocation_invoice_id public.receipt_allocations.invoice_id%TYPE;
  v_allocation_tenant_id public.receipt_allocations.tenant_id%TYPE;

  v_journal jsonb;
  v_journal_id public.journal_entries.id%TYPE;
  v_journal_date public.journal_entries.date%TYPE;
  v_journal_source_id public.journal_entries.source_id%TYPE;

  v_company_id uuid;
  v_canonical_allocations jsonb;
  v_canonical_journals jsonb;
  v_request_fingerprint text;
  v_target_id text;
  v_cached jsonb;
  v_cached_fingerprint text;
  v_cached_target_id text;
  v_result jsonb;
  v_expected_invoice_update_count integer := 0;
  v_updated_invoice_count integer := 0;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.users AS app_user
    WHERE app_user.id = auth.uid()
      AND app_user.role::text IN ('ADMIN', 'MANAGER')
      AND app_user.status::text = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'غير مصرح: هذه العملية متاحة فقط للمدير أو المسؤول'
      USING ERRCODE = '42501';
  END IF;

  v_company_id := public.current_company_id();
  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'غير مصرح: لم يتم العثور على معرّف الشركة للمستخدم الحالي'
      USING ERRCODE = '42501';
  END IF;

  v_receipt := coalesce(payload->'receipt', '{}'::jsonb);
  v_allocations := coalesce(payload->'allocations', '[]'::jsonb);
  v_journal_entries := coalesce(payload->'journal_entries', '[]'::jsonb);
  v_request_id := nullif(coalesce(payload->>'request_id', v_receipt->>'request_id'), '');

  IF v_request_id IS NULL THEN
    RAISE EXCEPTION 'معرّف الطلب مطلوب لضمان عدم التكرار.';
  END IF;

  -- Canonicalize only financially effective client fields. Generated ids,
  -- created_at values, and now() defaults never participate in the binding.
  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'invoice_id', allocation_record.value->>'invoice_id',
        'amount', trim_scale((allocation_record.value->>'amount')::numeric),
        'tenant_id', nullif(allocation_record.value->>'tenant_id', '')
      )
      ORDER BY allocation_record.value->>'invoice_id',
               trim_scale((allocation_record.value->>'amount')::numeric),
               nullif(allocation_record.value->>'tenant_id', '')
    ),
    '[]'::jsonb
  )
  INTO v_canonical_allocations
  FROM jsonb_array_elements(v_allocations) AS allocation_record(value);

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'account_id', journal_record.value->>'account_id',
        'amount', trim_scale((journal_record.value->>'amount')::numeric),
        'type', journal_record.value->>'type',
        'date', nullif(journal_record.value->>'date', '')::date,
        'entity_type', nullif(journal_record.value->>'entity_type', ''),
        'entity_id', nullif(journal_record.value->>'entity_id', ''),
        'source_binding', CASE
          WHEN nullif(journal_record.value->>'source_id', '') IS NULL THEN NULL
          WHEN journal_record.value->>'source_id' = v_receipt->>'id' THEN 'receipt'
          ELSE journal_record.value->>'source_id'
        END
      )
      ORDER BY journal_record.value->>'account_id',
               journal_record.value->>'type',
               nullif(journal_record.value->>'date', '')::date,
               trim_scale((journal_record.value->>'amount')::numeric),
               nullif(journal_record.value->>'entity_type', ''),
               nullif(journal_record.value->>'entity_id', ''),
               CASE
                 WHEN nullif(journal_record.value->>'source_id', '') IS NULL THEN NULL
                 WHEN journal_record.value->>'source_id' = v_receipt->>'id' THEN 'receipt'
                 ELSE journal_record.value->>'source_id'
               END
    ),
    '[]'::jsonb
  )
  INTO v_canonical_journals
  FROM jsonb_array_elements(v_journal_entries) AS journal_record(value);

  v_target_id := CASE
    WHEN nullif(v_receipt->>'id', '') IS NOT NULL
      THEN 'receipt:' || (v_receipt->>'id')
    ELSE 'contract:' || coalesce(nullif(v_receipt->>'contract_id', ''), '<none>')
  END;
  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'receipt_id', nullif(v_receipt->>'id', ''),
    'contract_id', nullif(v_receipt->>'contract_id', ''),
    'amount', trim_scale((v_receipt->>'amount')::numeric),
    'channel', nullif(v_receipt->>'channel', ''),
    'date_time', nullif(v_receipt->>'date_time', '')::timestamptz,
    'status', coalesce(nullif(v_receipt->>'status', ''), 'POSTED'),
    'tenant_id', nullif(v_receipt->>'tenant_id', ''),
    'check_number', nullif(v_receipt->>'check_number', ''),
    'check_bank', nullif(v_receipt->>'check_bank', ''),
    'check_date', nullif(v_receipt->>'check_date', '')::date,
    'check_status', nullif(v_receipt->>'check_status', ''),
    'allocations', v_canonical_allocations,
    'journal_entries', v_canonical_journals
  )::text, 'UTF8')), 'hex');

  PERFORM pg_advisory_xact_lock(
    hashtextextended('post_receipt_atomic:' || v_company_id::text || ':' || v_request_id, 0)
  );

  SELECT response_payload
    INTO v_cached
  FROM public.financial_operation_idempotency
  WHERE operation_name = 'post_receipt_atomic:' || v_company_id::text
    AND request_id = v_request_id
  FOR UPDATE;

  IF v_cached IS NOT NULL THEN
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    v_cached_target_id := v_cached->>'_target_id';
    IF v_cached_fingerprint IS NULL
       OR v_cached_target_id IS NULL
       OR NOT (v_cached ? 'response') THEN
      RAISE EXCEPTION 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        USING ERRCODE = '22023';
    END IF;
    IF v_cached_fingerprint <> v_request_fingerprint
       OR v_cached_target_id <> v_target_id THEN
      RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        USING ERRCODE = '22023';
    END IF;
    RETURN (v_cached->'response') || jsonb_build_object('idempotent', true);
  END IF;

  -- A receipt left by an unbound/legacy implementation must never be replayed
  -- or executed again silently.
  SELECT receipt_record.id
    INTO v_existing_id
  FROM public.receipts AS receipt_record
  WHERE receipt_record.request_id = v_request_id
    AND receipt_record.company_id = v_company_id
  LIMIT 1;
  IF v_existing_id IS NOT NULL THEN
    RAISE EXCEPTION 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
      USING ERRCODE = '22023';
  END IF;

  -- Validate allocations don't exceed invoice balances
  FOR v_invoice_id_text IN
    SELECT DISTINCT allocation_record.value->>'invoice_id'
    FROM jsonb_array_elements(v_allocations) AS allocation_record(value)
    ORDER BY 1
  LOOP
    SELECT
      invoice_record.id,
      invoice_record.amount,
      invoice_record.tax_amount,
      invoice_record.paid_amount,
      invoice_record.status
    INTO v_invoice
    FROM public.invoices AS invoice_record
    WHERE invoice_record.id::text = v_invoice_id_text
      AND coalesce((to_jsonb(invoice_record)->>'company_id')::text, '') = v_company_id::text
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'فاتورة غير موجودة: %', v_invoice_id_text;
    END IF;

    SELECT sum((allocation_record->>'amount')::numeric)
      INTO v_allocation_total
    FROM jsonb_array_elements(v_allocations) AS allocation_record
    WHERE allocation_record->>'invoice_id' = v_invoice_id_text;

    IF coalesce(v_invoice.paid_amount, 0) + v_allocation_total
         > coalesce(v_invoice.amount, 0) + coalesce(v_invoice.tax_amount, 0) + 0.001 THEN
      RAISE EXCEPTION 'قيمة السداد تتجاوز المتبقي على الفاتورة: %', v_invoice_id_text;
    END IF;
  END LOOP;

  -- Extract receipt fields into variables
  v_receipt_id := coalesce(v_receipt->>'id', gen_random_uuid()::text);
  v_receipt_contract_id := nullif(v_receipt->>'contract_id', '');
  -- P0 (F-WR): the receipt contract must belong to the caller's company.
  IF v_receipt_contract_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.contracts contract_record
    WHERE contract_record.id::text = v_receipt_contract_id::text
      AND contract_record.company_id = v_company_id
      AND contract_record.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'غير مصرح: العقد لا ينتمي إلى شركتك.' USING ERRCODE = '42501';
  END IF;
  v_receipt_tenant_id := nullif(v_receipt->>'tenant_id', '');
  v_receipt_check_date := nullif(v_receipt->>'check_date', '');
  v_receipt_amount := (v_receipt->>'amount')::numeric;
  v_receipt_channel := v_receipt->>'channel';
  v_receipt_ref := coalesce(v_receipt->>'ref', '');
  v_receipt_notes := coalesce(v_receipt->>'notes', '');
  v_receipt_status := coalesce(v_receipt->>'status', 'POSTED');

  IF nullif(v_receipt->>'date_time', '') IS NULL THEN
    v_receipt_date_time := now();
  ELSE
    v_receipt_date_time := v_receipt->>'date_time';
  END IF;

  -- Insert receipt
  INSERT INTO public.receipts(
    id,
    no,
    contract_id,
    date_time,
    channel,
    amount,
    ref,
    notes,
    status,
    check_number,
    check_bank,
    check_date,
    check_status,
    created_at,
    request_id,
    tenant_id,
    company_id
  ) VALUES (
    v_receipt_id,
    v_receipt->>'no',
    v_receipt_contract_id,
    v_receipt_date_time,
    v_receipt_channel,
    v_receipt_amount,
    v_receipt_ref,
    v_receipt_notes,
    v_receipt_status,
    nullif(v_receipt->>'check_number', ''),
    nullif(v_receipt->>'check_bank', ''),
    v_receipt_check_date,
    nullif(v_receipt->>'check_status', ''),
    now(),
    v_request_id,
    v_receipt_tenant_id,
    v_company_id
  );

  -- Insert corresponding payments row (shadow record)
  INSERT INTO public.payments(
    receipt_id,
    contract_id,
    amount,
    payment_date,
    payment_method,
    reference_no,
    date_time,
    channel,
    status,
    notes,
    created_by,
    created_at,
    company_id
  ) VALUES (
    v_receipt_id,
    v_receipt_contract_id,
    v_receipt_amount,
    (v_receipt_date_time::date),
    v_receipt_channel,
    nullif(v_receipt_ref, ''),
    v_receipt_date_time,
    v_receipt_channel,
    v_receipt_status,
    nullif(v_receipt_notes, ''),
    auth.uid(),
    now(),
    v_company_id
  );

  -- Insert receipt allocations
  FOR v_allocation IN
    SELECT allocation_record.value
    FROM jsonb_array_elements(v_allocations) AS allocation_record(value)
  LOOP
    v_allocation_id := coalesce(v_allocation->>'id', gen_random_uuid()::text);
    v_allocation_receipt_id := v_receipt_id;
    v_allocation_invoice_id := v_allocation->>'invoice_id';
    v_allocation_tenant_id := nullif(v_allocation->>'tenant_id', '');

    INSERT INTO public.receipt_allocations(
      id,
      receipt_id,
      invoice_id,
      amount,
      created_at,
      tenant_id,
      company_id
    ) VALUES (
      v_allocation_id,
      v_allocation_receipt_id,
      v_allocation_invoice_id,
      (v_allocation->>'amount')::numeric,
      now(),
      v_allocation_tenant_id,
      v_company_id
    );
  END LOOP;

  -- Update invoice paid_amount and status
  WITH allocation_totals AS (
    SELECT
      allocation_record->>'invoice_id' AS invoice_id,
      sum((allocation_record->>'amount')::numeric) AS total
    FROM jsonb_array_elements(v_allocations) AS allocation_record
    GROUP BY 1
  )
  UPDATE public.invoices AS invoice_record
  SET
    paid_amount = coalesce(invoice_record.paid_amount, 0) + allocation_totals.total,
    status = CASE
      WHEN coalesce(invoice_record.paid_amount, 0) + allocation_totals.total
        >= coalesce(invoice_record.amount, 0) + coalesce(invoice_record.tax_amount, 0) - 0.001
        THEN 'PAID'
      WHEN coalesce(invoice_record.paid_amount, 0) + allocation_totals.total > 0
        THEN 'PARTIALLY_PAID'
      ELSE invoice_record.status
    END
  FROM allocation_totals
  WHERE invoice_record.id::text = allocation_totals.invoice_id
    AND invoice_record.company_id = v_company_id
    AND invoice_record.deleted_at IS NULL;

  GET DIAGNOSTICS v_updated_invoice_count = ROW_COUNT;
  SELECT count(DISTINCT allocation_record.value->>'invoice_id')::integer
    INTO v_expected_invoice_update_count
  FROM jsonb_array_elements(v_allocations) AS allocation_record(value);
  IF v_updated_invoice_count <> v_expected_invoice_update_count THEN
    RAISE EXCEPTION
      'INVOICE_ALLOCATION_UPDATE_COUNT_MISMATCH: expected %, updated %',
      v_expected_invoice_update_count,
      v_updated_invoice_count
      USING ERRCODE = 'P0001';
  END IF;

  -- Stage S03: post receipt/payment journal content through the canonical GL engine.
  -- Keep the existing company-account authorization error contract before entering
  -- the engine; the engine then re-validates account scope, side, amount and balance.
  FOR v_journal IN
    SELECT journal_record.value
    FROM jsonb_array_elements(v_journal_entries) AS journal_record(value)
  LOOP
    IF nullif(v_journal->>'account_id', '') IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts AS account_record
      WHERE account_record.id = v_journal->>'account_id'
        AND account_record.company_id = v_company_id
    ) THEN
      RAISE EXCEPTION 'غير مصرح: حساب القيد لا ينتمي إلى شركتك: %', v_journal->>'account_id'
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  IF jsonb_array_length(v_journal_entries) > 0 THEN
    -- Bootstrap only the first period. Once any period exists, the normal
    -- OPEN/SOFT_CLOSED/HARD_CLOSED resolver remains fail-closed and authoritative.
    PERFORM public.gl_ensure_initial_open_period(v_company_id, v_receipt_date_time::date);

    PERFORM public.post_journal_event(jsonb_build_object(
      'company_id', v_company_id,
      'source_type', 'receipt',
      'source_id', v_receipt_id::text,
      'event_id', v_request_id,
      'effective_date', v_receipt_date_time::date,
      'description', coalesce(nullif(v_receipt_notes, ''), 'Receipt ' || v_receipt_id::text),
      'lines', (
        SELECT coalesce(
          jsonb_agg(
            jsonb_build_object(
              'account_id', journal_record.value->>'account_id',
              'debit', CASE
                WHEN upper(coalesce(journal_record.value->>'type', '')) = 'DEBIT'
                  THEN round((journal_record.value->>'amount')::numeric, 3)
                ELSE 0
              END,
              'credit', CASE
                WHEN upper(coalesce(journal_record.value->>'type', '')) = 'CREDIT'
                  THEN round((journal_record.value->>'amount')::numeric, 3)
                ELSE 0
              END,
              'line_description', nullif(journal_record.value->>'no', ''),
              'ref_source_id', coalesce(nullif(journal_record.value->>'source_id', ''), v_receipt_id::text),
              'ref_entity_type', nullif(journal_record.value->>'entity_type', ''),
              'ref_entity_id', nullif(journal_record.value->>'entity_id', '')
            )
            ORDER BY journal_record.ordinality
          ),
          '[]'::jsonb
        )
        FROM jsonb_array_elements(v_journal_entries) WITH ORDINALITY
          AS journal_record(value, ordinality)
      )
    ));
  END IF;

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'request_id', v_request_id,
    'receipt_id', v_receipt_id
  );

  INSERT INTO public.financial_operation_idempotency(
    operation_name,
    request_id,
    response_payload
  ) VALUES (
    'post_receipt_atomic:' || v_company_id::text,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_target_id,
      'response', v_result
    )
  )
  ON CONFLICT (operation_name, request_id) DO NOTHING;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."post_receipt_atomic"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_receipt_atomic"("payload" "jsonb") IS 'Internal/service receipt-allocation engine. Not browser-executable because its journal payload is server-owned; RC1 UI uses record_invoice_payment_atomic.';



CREATE OR REPLACE FUNCTION "public"."post_taxable_collection_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_net numeric := public.gl_pm_round_omr(nullif(p_payload->>'net_amount','')::numeric);
  v_cash_no text := coalesce(nullif(p_payload->>'cash_account_no',''), '1120');
  v_date date := nullif(p_payload->>'effective_date','')::date;
  v_profile record;
  v_tax numeric;
  v_gross numeric;
  v_cash_id text; v_ofp_id text; v_vat_id text;
  v_post jsonb; v_batch_id uuid;
  v_fp text; v_cached jsonb; v_id uuid := gen_random_uuid(); v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'TAXABLE_COLLECTION_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if p_payload ?| array['company_id','tax_code','tax_rate','tax_amount'] then
    raise exception 'TAXABLE_COLLECTION_CLIENT_TAX_FORBIDDEN: tax is server-resolved from the authoritative profile.' using errcode = '22023';
  end if;
  if v_request_id is null or v_net is null or v_net <= 0 or v_date is null then
    raise exception 'TAXABLE_COLLECTION_REQUEST_NET_DATE_REQUIRED' using errcode = '22023';
  end if;
  if v_cash_no not in ('1111','1120') then
    raise exception 'TAXABLE_COLLECTION_CASH_ACCOUNT_INVALID' using errcode = '22023';
  end if;

  -- Authoritative resolution — fails closed when no profile covers the date.
  select * into v_profile from public.resolve_active_tax_profile(v_company_id, v_date);
  v_tax := public.compute_tax_amount(v_net, v_profile.tax_rate);
  v_gross := public.gl_pm_round_omr(v_net + v_tax);

  v_fp := encode(sha256(convert_to(jsonb_build_object('net_amount', v_net, 'effective_date', v_date)::text, 'UTF8')), 'hex');
  perform pg_advisory_xact_lock(hashtextextended('taxable_collection:' || v_company_id::text || ':' || v_request_id, 0));

  select response_payload into v_cached
    from public.financial_operation_idempotency
   where operation_name = 'post_taxable_collection_atomic:' || v_company_id::text
     and request_id = v_request_id for update;
  if v_cached is not null then
    if v_cached->>'_request_fingerprint' is distinct from v_fp or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode = '22023';
    end if;
    return v_cached->'response';
  end if;

  v_cash_id := public.gl_pm_require_account(v_company_id, v_cash_no);
  v_ofp_id  := public.gl_pm_require_account(v_company_id, '2000');
  v_vat_id  := public.gl_pm_require_account(v_company_id, '2100');

  v_post := public.post_journal_event(jsonb_build_object(
    'company_id', v_company_id, 'source_type', 'pm_taxable_collection', 'source_id', v_id::text,
    'event_id', 'collect', 'effective_date', v_date,
    'description', 'Taxable owner-agency collection (authoritative tax resolved)',
    'lines', jsonb_build_array(
      jsonb_build_object('account_id', v_cash_id, 'debit', v_gross, 'credit', 0,
        'ref_source_id', v_id::text, 'ref_entity_type', 'taxable_collection', 'ref_entity_id', v_id::text),
      jsonb_build_object('account_id', v_ofp_id, 'debit', 0, 'credit', v_net,
        'ref_source_id', v_id::text, 'ref_entity_type', 'taxable_collection', 'ref_entity_id', v_id::text),
      jsonb_build_object('account_id', v_vat_id, 'debit', 0, 'credit', v_tax,
        'ref_source_id', v_id::text, 'ref_entity_type', 'taxable_collection', 'ref_entity_id', v_id::text)
    )
  ));
  v_batch_id := (v_post->>'batch_id')::uuid;

  insert into public.taxable_line_tax_snapshots (
    company_id, source_type, source_id, journal_batch_id, account_no,
    tax_code, tax_rate, net_amount, tax_amount, effective_date
  ) values (
    v_company_id, 'pm_taxable_collection', v_id::text, v_batch_id, '2100',
    v_profile.tax_code, v_profile.tax_rate, v_net, v_tax, v_date
  );

  v_result := jsonb_build_object(
    'success', true, 'idempotent', false, 'source_id', v_id::text, 'net_amount', v_net,
    'tax_code', v_profile.tax_code, 'tax_rate', v_profile.tax_rate, 'tax_amount', v_tax,
    'gross_amount', v_gross, 'journal_batch_id', v_batch_id, 'request_id', v_request_id
  );
  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('post_taxable_collection_atomic:' || v_company_id::text, v_request_id,
          jsonb_build_object('_request_fingerprint', v_fp, 'response', v_result));
  return v_result;
end;
$$;


ALTER FUNCTION "public"."post_taxable_collection_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_account_deletion_if_referenced"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_lines bigint;
begin
  if to_regclass('public.journal_lines') is not null then
    select count(*) into v_lines
      from public.journal_lines l
     where l.account_id = old.id;
    if v_lines > 0 then
      raise exception 'ACCOUNT_REFERENCED_BY_JOURNAL: account % (%) cannot be deleted because it is referenced by journal lines. Deactivate it instead.', old.no, old.id
        using errcode = '23503';
    end if;
  end if;
  if to_regclass('public.journal_entries_archive') is not null then
    select count(*) into v_lines
      from public.journal_entries_archive a
     where a.account_id = old.id;
    if v_lines > 0 then
      raise exception 'ACCOUNT_REFERENCED_BY_LEGACY_JOURNAL: account % (%) cannot be deleted because it is referenced by archived journal entries. Deactivate it instead.', old.no, old.id
        using errcode = '23503';
    end if;
  end if;
  return old;
end;
$$;


ALTER FUNCTION "public"."prevent_account_deletion_if_referenced"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_owner_delete_with_balances"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.owner_balances AS owner_balance
    WHERE owner_balance.owner_id::text = OLD.id::text
  ) THEN
    RAISE EXCEPTION
      'Cannot hard-delete owner % because owner_balances rows exist; use soft-delete/archive to preserve financial history.',
      OLD.id
      USING ERRCODE = '23503';
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."prevent_owner_delete_with_balances"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_payment_receipt_identity_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.id is distinct from old.id or new.receipt_id is distinct from old.receipt_id then
    raise exception 'payments.id and payments.receipt_id are immutable after insert' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_payment_receipt_identity_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_posted_journal_entry_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.status = 'posted' THEN
    RAISE EXCEPTION 'Posted journal entries are immutable. Use reverse entry.'
      USING ERRCODE = 'P0001';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    RETURN NEW;
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."prevent_posted_journal_entry_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_bank_statement_batch_atomic"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_company_id uuid;
  v_bank_account_id uuid;
  v_file_name text;
  v_file_fingerprint text;
  v_file_size integer;
  v_rows jsonb;
  v_total integer;
  v_existing_import public.bank_statement_imports%rowtype;
  v_row jsonb;
  v_idx integer;
  v_transaction_date date;
  v_amount numeric;
  v_description text;
  v_reference text;
  v_balance numeric;
  v_currency text;
  v_fingerprint text;
  v_accepted integer := 0;
  v_duplicate integer := 0;
  v_possible integer := 0;
  v_existing_fps text[];
  v_seen_fps text[] := '{}';
  v_date_str text;
  v_amount_text text;
  v_max_file_size integer := 5 * 1024 * 1024;
  v_max_rows integer := 5000;
  v_debit_text text;
  v_credit_text text;
  v_amount_supplied boolean;
  v_debit_supplied boolean;
  v_credit_supplied boolean;
  v_supplied_amount_count integer;
  v_debit numeric;
  v_credit numeric;
  v_canonical_rows jsonb := '[]'::jsonb;
  v_payload_digest text;
begin
  if auth.uid() is null or not coalesce(public.is_app_user(), false) then
    raise exception 'Authenticated app user is required.' using errcode = '42501';
  end if;
  if not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'Only managers can import bank statements.' using errcode = '42501';
  end if;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'Company context is required.' using errcode = '42501';
  end if;

  v_bank_account_id := nullif(payload->>'bank_account_id','')::uuid;
  v_file_name := nullif(payload->>'file_name','');
  v_file_fingerprint := nullif(payload->>'file_fingerprint','');
  v_file_size := nullif(payload->>'file_size','')::integer;
  v_rows := payload->'rows';

  if v_bank_account_id is null then
    raise exception 'bank_account_id is required.' using errcode='22023';
  end if;
  if v_file_fingerprint is null then
    raise exception 'file_fingerprint is required.' using errcode='22023';
  end if;
  if v_file_size is null then
    raise exception 'file_size is required.' using errcode='22023';
  end if;
  if v_file_size <= 0 then
    raise exception 'file_size must be greater than zero.' using errcode='22023';
  end if;
  if v_file_size > v_max_file_size then
    raise exception 'file_size exceeds % byte limit.', v_max_file_size using errcode='22023';
  end if;
  if v_rows is null or jsonb_typeof(v_rows) <> 'array' or jsonb_array_length(v_rows)=0 then
    raise exception 'No rows to import.' using errcode='22023';
  end if;

  v_total := jsonb_array_length(v_rows);

  if v_total > v_max_rows then
    raise exception 'Row count exceeds % row limit.', v_max_rows using errcode='22023';
  end if;

  if not exists (
    select 1 from public.bank_accounts
    where id = v_bank_account_id
      and company_id = v_company_id
      and deleted_at is null
  ) then
    raise exception 'Bank account not found or not in your company.' using errcode='42501';
  end if;

  select coalesce(array_agg(fingerprint), '{}') into v_existing_fps
  from public.bank_statement_lines
  where company_id = v_company_id
    and bank_account_id = v_bank_account_id
    and deleted_at is null
    and fingerprint is not null;

  for v_idx in 0..v_total-1 loop
    v_row := v_rows->v_idx;
    v_date_str := v_row->>'transaction_date';
    v_amount_text := nullif(trim(both ' ' from coalesce(v_row->>'amount','')), '');
    v_debit_text := nullif(trim(both ' ' from coalesce(v_row->>'debit','')), '');
    v_credit_text := nullif(trim(both ' ' from coalesce(v_row->>'credit','')), '');
    v_amount_supplied := v_amount_text is not null;
    v_debit_supplied := v_debit_text is not null;
    v_credit_supplied := v_credit_text is not null;
    v_supplied_amount_count :=
      (case when v_amount_supplied then 1 else 0 end) +
      (case when v_debit_supplied then 1 else 0 end) +
      (case when v_credit_supplied then 1 else 0 end);

    if v_supplied_amount_count <> 1 then
      raise exception 'Exactly one of amount, debit or credit is required at row %', v_idx+1 using errcode='22023';
    end if;

    begin
      v_transaction_date := v_date_str::date;
    exception when others then
      raise exception 'Invalid transaction_date at row %: %', v_idx+1, v_date_str using errcode='22023';
    end;

    if v_amount_supplied then
      begin
        v_amount := v_amount_text::numeric;
      exception when others then
        raise exception 'Invalid amount at row %: %', v_idx+1, v_amount_text using errcode='22023';
      end;
      if round(v_amount, 3) <> v_amount then
        raise exception 'Amount must have at most 3 decimals at row %', v_idx+1 using errcode='22023';
      end if;
    elsif v_debit_supplied then
      begin
        v_debit := v_debit_text::numeric;
      exception when others then
        raise exception 'Invalid debit at row %: %', v_idx+1, v_debit_text using errcode='22023';
      end;
      if round(v_debit, 3) <> v_debit then
        raise exception 'Debit must have at most 3 decimals at row %', v_idx+1 using errcode='22023';
      end if;
      v_amount := -abs(v_debit);
    else
      begin
        v_credit := v_credit_text::numeric;
      exception when others then
        raise exception 'Invalid credit at row %: %', v_idx+1, v_credit_text using errcode='22023';
      end;
      if round(v_credit, 3) <> v_credit then
        raise exception 'Credit must have at most 3 decimals at row %', v_idx+1 using errcode='22023';
      end if;
      v_amount := abs(v_credit);
    end if;

    if v_amount = 0 then
      raise exception 'Amount must be non-zero at row %', v_idx+1 using errcode='22023';
    end if;

    v_description := trim(both ' ' from coalesce(v_row->>'description',''));
    if v_description = '' then v_description := 'حركة مستوردة'; end if;
    v_reference := lower(trim(both ' ' from coalesce(v_row->>'reference','')));
    v_currency := upper(trim(both ' ' from coalesce(v_row->>'currency','OMR')));
    if v_currency !~ '^[A-Z]{3}$' then
      raise exception 'Invalid currency at row %: %', v_idx+1, v_currency using errcode='22023';
    end if;
    if v_currency <> 'OMR' then
      raise exception 'Unsupported currency at row %: %', v_idx+1, v_currency using errcode='22023';
    end if;

    v_balance := null;
    if nullif(v_row->>'balance','') is not null then
      begin
        v_balance := (v_row->>'balance')::numeric;
      exception when others then
        raise exception 'Invalid balance at row %: %', v_idx+1, v_row->>'balance' using errcode='22023';
      end;
      if round(v_balance, 3) <> v_balance then
        raise exception 'Balance must have at most 3 decimals at row %', v_idx+1 using errcode='22023';
      end if;
    end if;

    v_fingerprint := md5(
      coalesce(v_company_id::text,'') || '|' ||
      coalesce(v_bank_account_id::text,'') || '|' ||
      coalesce(v_transaction_date::text,'') || '|' ||
      coalesce(to_char(v_amount, 'FM9999999999990.000'),'') || '|' ||
      coalesce(v_currency,'OMR') || '|' ||
      coalesce(v_reference,'') || '|' ||
      lower(coalesce(v_description,''))
    );

    if v_fingerprint = any(v_seen_fps) then
      v_duplicate := v_duplicate + 1;
    else
      v_seen_fps := array_append(v_seen_fps, v_fingerprint);
      if v_fingerprint = any(v_existing_fps) then
        v_duplicate := v_duplicate + 1;
      else
        if exists (
          select 1 from public.bank_statement_lines
          where company_id = v_company_id
            and bank_account_id = v_bank_account_id
            and transaction_date = v_transaction_date
            and amount = v_amount
            and deleted_at is null
          limit 1
        ) then
          v_possible := v_possible + 1;
        end if;
        v_accepted := v_accepted + 1;
      end if;
    end if;

    v_canonical_rows := v_canonical_rows || jsonb_build_array(jsonb_build_object(
      'transaction_date', v_transaction_date::text,
      'amount', to_char(v_amount, 'FM9999999999990.000'),
      'description', v_description,
      'reference', v_reference,
      'balance', case when v_balance is null then null else to_char(v_balance, 'FM9999999999990.000') end,
      'currency', v_currency,
      'fingerprint', v_fingerprint
    ));
  end loop;

  v_payload_digest := md5(v_file_fingerprint || '|' || v_canonical_rows::text);

  select * into v_existing_import
  from public.bank_statement_imports
  where company_id = v_company_id
    and file_fingerprint = v_file_fingerprint
    and deleted_at is null
  limit 1;

  if found then
    if v_existing_import.payload_digest is not null
       and v_existing_import.payload_digest <> v_payload_digest then
      raise exception 'file_fingerprint was already used with different content.' using errcode='22023';
    end if;
    if v_existing_import.payload_digest is null
       and v_existing_import.total_rows is distinct from v_total then
      raise exception 'file_fingerprint was already used with different content.' using errcode='22023';
    end if;

    return jsonb_build_object(
      'id', v_existing_import.id,
      'reference', v_existing_import.reference,
      'bank_account_id', v_existing_import.bank_account_id,
      'file_name', v_existing_import.file_name,
      'file_fingerprint', v_existing_import.file_fingerprint,
      'payload_digest', v_existing_import.payload_digest,
      'total_rows', v_existing_import.total_rows,
      'accepted_rows', v_existing_import.accepted_rows,
      'rejected_rows', v_existing_import.rejected_rows,
      'duplicate_rows', v_existing_import.duplicate_rows,
      'possible_duplicate_rows', v_existing_import.possible_duplicate_rows,
      'status', v_existing_import.status,
      'is_duplicate_file', true,
      'write_attempted', false
    );
  end if;

  return jsonb_build_object(
    'bank_account_id', v_bank_account_id,
    'file_name', v_file_name,
    'file_fingerprint', v_file_fingerprint,
    'payload_digest', v_payload_digest,
    'total_rows', v_total,
    'accepted_rows', v_accepted,
    'rejected_rows', 0,
    'duplicate_rows', v_duplicate,
    'possible_duplicate_rows', v_possible,
    'status', 'preview',
    'is_duplicate_file', false,
    'write_attempted', false
  );
end;
$_$;


ALTER FUNCTION "public"."preview_bank_statement_batch_atomic"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preview_bank_statement_batch_atomic"("payload" "jsonb") IS 'GAP-017: no-write server preview for staged bank CSV. Same guards as import; never inserts.';



CREATE TABLE IF NOT EXISTS "public"."bank_reconciliation_matches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "statement_line_id" "uuid" NOT NULL,
    "matched_entity_type" "text" NOT NULL,
    "matched_entity_id" "text" NOT NULL,
    "matched_amount" numeric(14,2) NOT NULL,
    "notes" "text",
    "matched_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "matched_by" "uuid" DEFAULT "auth"."uid"(),
    "company_id" "uuid" DEFAULT "public"."current_company_id"() NOT NULL,
    CONSTRAINT "bank_reconciliation_matches_amount_nonzero_chk" CHECK (("matched_amount" <> (0)::numeric)),
    CONSTRAINT "bank_reconciliation_matches_type_chk" CHECK (("matched_entity_type" = ANY (ARRAY['payment'::"text", 'receipt'::"text", 'expense'::"text", 'manual_adjustment'::"text"])))
);


ALTER TABLE "public"."bank_reconciliation_matches" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_bank_reconciliation_match_atomic"("payload" "jsonb") RETURNS "public"."bank_reconciliation_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_statement_line_id uuid := nullif(payload->>'statement_line_id', '')::uuid;
  v_matched_entity_type text := nullif(payload->>'matched_entity_type', '');
  v_matched_entity_id text := nullif(payload->>'matched_entity_id', '');
  v_matched_amount numeric := nullif(payload->>'matched_amount', '')::numeric;
  v_notes text := nullif(payload->>'notes', '');
  v_line public.bank_statement_lines%rowtype;
  v_match public.bank_reconciliation_matches%rowtype;
begin
  if auth.uid() is null or not coalesce(public.is_app_user(), false) then
    raise exception 'Authenticated app user is required.' using errcode = '42501';
  end if;

  if not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'Bank reconciliation matching requires ADMIN or MANAGER.' using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  if v_statement_line_id is null then
    raise exception 'statement_line_id is required.' using errcode = '22023';
  end if;
  if v_matched_entity_type not in ('payment', 'receipt', 'expense', 'manual_adjustment') then
    raise exception 'Invalid matched_entity_type.' using errcode = '22023';
  end if;
  if v_matched_entity_id is null then
    raise exception 'matched_entity_id is required.' using errcode = '22023';
  end if;
  if v_matched_amount is null or v_matched_amount = 0 then
    raise exception 'matched_amount must be non-zero.' using errcode = '22023';
  end if;

  select * into v_line
  from public.bank_statement_lines
  where id = v_statement_line_id
    and company_id = v_company_id
    and deleted_at is null
  for update;

  if not found then
    raise exception 'Bank statement line was not found.' using errcode = 'P0002';
  end if;
  if lower(coalesce(v_line.status, '')) <> 'unmatched' then
    raise exception 'Bank statement line is already processed.' using errcode = '23514';
  end if;

  if v_matched_amount <> v_line.amount then
    raise exception 'matched_amount must equal the bank statement line amount.' using errcode = '23514';
  end if;

  if v_matched_entity_type = 'payment' then
    if not exists (
      select 1 from public.payments p
      where p.id::text = v_matched_entity_id
        and p.company_id = v_company_id
        and p.deleted_at is null
    ) then
      raise exception 'Matched payment was not found in the active company.' using errcode = 'P0002';
    end if;
  elsif v_matched_entity_type = 'receipt' then
    if not exists (
      select 1 from public.receipts r
      where r.id::text = v_matched_entity_id
        and r.company_id = v_company_id
        and r.deleted_at is null
    ) then
      raise exception 'Matched receipt was not found in the active company.' using errcode = 'P0002';
    end if;
  elsif v_matched_entity_type = 'expense' then
    if not exists (
      select 1 from public.expenses e
      where e.id::text = v_matched_entity_id
        and e.company_id = v_company_id
        and e.deleted_at is null
    ) then
      raise exception 'Matched expense was not found in the active company.' using errcode = 'P0002';
    end if;
  end if;

  insert into public.bank_reconciliation_matches (
    statement_line_id,
    matched_entity_type,
    matched_entity_id,
    matched_amount,
    notes,
    matched_by,
    company_id
  ) values (
    v_statement_line_id,
    v_matched_entity_type,
    v_matched_entity_id,
    v_matched_amount,
    v_notes,
    auth.uid(),
    v_company_id
  )
  returning * into v_match;

  update public.bank_statement_lines
  set status = 'matched', updated_at = now()
  where id = v_statement_line_id
    and company_id = v_company_id;

  insert into public.audit_log (
    id, user_id, action, entity, entity_id, note, "table",
    old_value, new_value, action_timestamp, created_at, updated_at,
    company_id
  ) values (
    gen_random_uuid()::text,
    auth.uid(),
    'PROCESS_BANK_RECONCILIATION_MATCH_ATOMIC',
    'bank_reconciliation_match',
    v_match.id::text,
    'Bank statement line matched atomically through RPC.',
    'bank_reconciliation_matches',
    to_jsonb(v_line),
    jsonb_build_object('match', to_jsonb(v_match), 'statement_line_status', 'matched'),
    now(), now(), now(),
    v_company_id
  );

  return v_match;
end;
$$;


ALTER FUNCTION "public"."process_bank_reconciliation_match_atomic"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."project_invoice_payment_status_with_credits"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_satisfied numeric;
  v_total numeric;
begin
  -- Do not put paid_amount/credited_amount in the trigger UPDATE OF list:
  -- Phase-1's widening migration must remain replay-idempotent even after this
  -- later projection guard exists. Return unchanged rows immediately.
  if new.paid_amount is not distinct from old.paid_amount
     and new.credited_amount is not distinct from old.credited_amount then
    return new;
  end if;

  if coalesce(old.document_status, '') in ('VOIDED', 'REVERSED')
     or upper(coalesce(old.status, '')) = 'VOID' then
    return new;
  end if;

  v_satisfied := public.gl_pm_round_omr(coalesce(new.paid_amount, 0) + coalesce(new.credited_amount, 0));
  v_total := public.gl_pm_round_omr(new.amount + coalesce(new.tax_amount, 0));
  new.status := case
    when v_satisfied <= 0 and new.due_date < current_date then 'OVERDUE'
    when v_satisfied <= 0 then 'UNPAID'
    when v_satisfied < v_total - 0.001 then 'PARTIALLY_PAID'
    else 'PAID'
  end;
  return new;
end;
$$;


ALTER FUNCTION "public"."project_invoice_payment_status_with_credits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provision_company_chart_of_accounts"("p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_accounts jsonb[] := array[
    jsonb_build_object('no', '1111', 'name', 'Cash', 'type', 'asset', 'balance', 'debit'),
    jsonb_build_object('no', '1120', 'name', 'Bank', 'type', 'asset', 'balance', 'debit'),
    jsonb_build_object('no', '1201', 'name', 'Tenant Receivable', 'type', 'asset', 'balance', 'debit'),
    jsonb_build_object('no', '1300', 'name', 'Due from Owners', 'type', 'asset', 'balance', 'debit'),
    jsonb_build_object('no', '1600', 'name', 'Right-of-Use Asset', 'type', 'asset', 'balance', 'debit'),
    jsonb_build_object('no', '2000', 'name', 'Owner Funds Payable', 'type', 'liability', 'balance', 'credit'),
    jsonb_build_object('no', '2100', 'name', 'VAT Payable', 'type', 'liability', 'balance', 'credit'),
    jsonb_build_object('no', '2200', 'name', 'Tenant Deposits Payable', 'type', 'liability', 'balance', 'credit'),
    jsonb_build_object('no', '2300', 'name', 'Broker Commissions Payable', 'type', 'liability', 'balance', 'credit'),
    jsonb_build_object('no', '2500', 'name', 'Lease Liability', 'type', 'liability', 'balance', 'credit'),
    jsonb_build_object('no', '4000', 'name', 'Sublease Rental Revenue', 'type', 'revenue', 'balance', 'credit'),
    jsonb_build_object('no', '4100', 'name', 'Management Fee Revenue', 'type', 'revenue', 'balance', 'credit'),
    jsonb_build_object('no', '4200', 'name', 'Brokerage Revenue', 'type', 'revenue', 'balance', 'credit'),
    jsonb_build_object('no', '4300', 'name', 'Damage Compensation Revenue', 'type', 'revenue', 'balance', 'credit'),
    jsonb_build_object('no', '6100', 'name', 'Company Operating Expense', 'type', 'expense', 'balance', 'debit'),
    jsonb_build_object('no', '6110', 'name', 'Broker Commission Expense', 'type', 'expense', 'balance', 'debit'),
    jsonb_build_object('no', '6200', 'name', 'ROU Depreciation', 'type', 'expense', 'balance', 'debit'),
    jsonb_build_object('no', '6300', 'name', 'Lease Interest Expense', 'type', 'expense', 'balance', 'debit')
  ];
  v_acc jsonb;
  v_id text;
  v_created integer := 0;
  v_existing integer := 0;
  v_results jsonb := '[]'::jsonb;
begin
  if p_company_id is null then
    raise exception 'company_id is required.' using errcode = '22023';
  end if;

  if not exists (select 1 from public.companies where id = p_company_id) then
    raise exception 'Company % does not exist.', p_company_id using errcode = 'P0002';
  end if;

  -- Serialize provisioning per company; the composite unique constraint is the
  -- authoritative concurrency backstop.
  perform pg_advisory_xact_lock(
    hashtextextended('chart_of_accounts:' || p_company_id::text, 0)
  );

  foreach v_acc in array v_accounts loop
    v_id := 'coa:' || p_company_id::text || ':' || (v_acc->>'no');

    insert into public.accounts (
      id, no, name, company_id, account_type, normal_balance,
      currency_code, precision, is_active, created_at, updated_at
    ) values (
      v_id, v_acc->>'no', v_acc->>'name', p_company_id, v_acc->>'type', v_acc->>'balance',
      'OMR', 3, true, now(), now()
    )
    on conflict (company_id, no) do nothing;

    if found then
      v_created := v_created + 1;
    else
      v_existing := v_existing + 1;
    end if;

    v_results := v_results || jsonb_build_object(
      'account_no', v_acc->>'no',
      'name', v_acc->>'name',
      'account_type', v_acc->>'type',
      'normal_balance', v_acc->>'balance',
      'currency_code', 'OMR',
      'precision', 3
    );
  end loop;

  return jsonb_build_object(
    'success', true,
    'company_id', p_company_id,
    'created_count', v_created,
    'existing_count', v_existing,
    'accounts', v_results
  );
end;
$$;


ALTER FUNCTION "public"."provision_company_chart_of_accounts"("p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rc1_owner_agency_vat_payable_balance"("p_company_id" "uuid", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("balance" numeric, "cnt" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_office numeric := 0;
  v_owner numeric := 0;
  v_rate_fee numeric := 0;
  v_fixed_fee numeric := 0;
  v_office_count bigint := 0;
  v_owner_count bigint := 0;
  v_rate_fee_count bigint := 0;
  v_fixed_fee_count bigint := 0;
begin
  if p_company_id is null then
    raise exception 'RC1_VAT_SUBLEDGER_COMPANY_REQUIRED' using errcode='22023';
  end if;

  -- OFFICE_IS_CREDITOR rent VAT is recognized on invoice issue and reduced by
  -- active credits using the original immutable invoice tax lineage.
  select
    public.wp05_round_omr(coalesce(sum(i.tax_amount - coalesce(c.credit_tax, 0)), 0)),
    count(*) filter (where abs(i.tax_amount - coalesce(c.credit_tax, 0)) > 0.0005)::bigint
  into v_office, v_office_count
  from public.invoices i
  left join lateral (
    select coalesce(sum(ic.tax_amount), 0) as credit_tax
      from public.invoice_credits ic
     where ic.company_id = i.company_id
       and ic.invoice_id = i.id
       and ic.status = 'POSTED'
  ) c on true
  where i.company_id = p_company_id
    and i.invoice_accounting_classification = 'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS'
    and i.document_status = 'POSTED'
    and i.issue_date <= p_as_of;

  -- OWNER_IS_CREDITOR rent VAT is recognized on an active collection only.
  select
    public.wp05_round_omr(coalesce(sum(pta.tax_amount), 0)),
    count(*) filter (where abs(pta.tax_amount) > 0.0005)::bigint
  into v_owner, v_owner_count
  from public.invoice_payment_tax_allocations pta
  join public.invoices i
    on i.id = pta.invoice_id
   and i.company_id = pta.company_id
  join public.receipts r
    on r.id = pta.receipt_id
   and r.company_id = pta.company_id
  where pta.company_id = p_company_id
    and i.invoice_accounting_classification = 'OWNER_AGENCY_OWNER_CREDITOR_OPERATIONAL'
    and upper(coalesce(r.status, '')) = 'POSTED'
    and r.deleted_at is null
    and r.date_time::date <= p_as_of;

  -- RATE management-fee VAT follows its immutable fee snapshot. A governed
  -- receipt VOID excludes the snapshot economically while preserving history.
  select
    public.wp05_round_omr(coalesce(sum(s.tax_amount),0)),
    count(*) filter (where abs(s.tax_amount) > 0.0005)::bigint
  into v_rate_fee, v_rate_fee_count
  from public.management_fee_tax_snapshots s
  join public.receipts r
    on r.id = s.receipt_id
   and r.company_id = s.company_id
  where s.company_id = p_company_id
    and s.effective_date <= p_as_of
    and upper(coalesce(r.status,'')) = 'POSTED'
    and r.deleted_at is null;

  -- FIXED_MONTHLY VAT is recognized on its economic day. Its append-only
  -- reversal relation removes the original economic effect from the basis.
  select
    public.wp05_round_omr(coalesce(sum(a.tax_amount),0)),
    count(*) filter (where abs(a.tax_amount) > 0.0005)::bigint
  into v_fixed_fee, v_fixed_fee_count
  from public.fixed_monthly_daily_accruals a
  left join public.fixed_monthly_daily_accrual_reversals rev
    on rev.accrual_id = a.id
   and rev.company_id = a.company_id
  where a.company_id = p_company_id
    and a.accrual_date <= p_as_of
    and a.journal_batch_id is not null
    and rev.id is null;

  return query
  select
    public.wp05_round_omr(v_office + v_owner + v_rate_fee + v_fixed_fee),
    coalesce(v_office_count,0)
      + coalesce(v_owner_count,0)
      + coalesce(v_rate_fee_count,0)
      + coalesce(v_fixed_fee_count,0);
end;
$$;


ALTER FUNCTION "public"."rc1_owner_agency_vat_payable_balance"("p_company_id" "uuid", "p_as_of" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rc1_owner_agency_vat_payable_balance"("p_company_id" "uuid", "p_as_of" "date") IS 'RC1 2100 operational basis: owner-agency rent VAT + active RATE fee VAT + unreversed FIXED_MONTHLY fee VAT, all from immutable source lineage.';



CREATE OR REPLACE FUNCTION "public"."recalculate_all_balances"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
begin
  if auth.uid() is null then
    raise exception 'غير مصرح: يجب تسجيل الدخول' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.users u
    where u.id = auth.uid() and u.role in ('ADMIN', 'MANAGER')
  ) then
    raise exception 'غير مصرح: هذه العملية متاحة فقط للمدير أو المسؤول' using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  delete from public.contract_balances where company_id = v_company_id;
  insert into public.contract_balances (
    contract_id, tenant_id, unit_id, total_invoiced, total_paid, balance_due, updated_at, company_id
  )
  select
    c.id::text,
    c.tenant_id::text,
    c.unit_id::text,
    coalesce(sum(i.amount + coalesce(i.tax_amount, 0)), 0),
    coalesce(sum(i.paid_amount), 0),
    coalesce(sum(i.amount + coalesce(i.tax_amount, 0) - i.paid_amount), 0),
    now(),
    c.company_id
  from public.contracts c
  left join public.invoices i
    on i.contract_id = c.id
   and i.deleted_at is null
   and i.company_id = v_company_id
  where c.company_id = v_company_id
  group by c.id, c.tenant_id, c.unit_id, c.company_id;

  delete from public.tenant_balances where company_id = v_company_id;
  insert into public.tenant_balances (tenant_id, balance_due, updated_at, company_id)
  select
    c.tenant_id::text,
    coalesce(sum(i.amount + coalesce(i.tax_amount, 0) - i.paid_amount), 0),
    now(),
    c.company_id
  from public.contracts c
  left join public.invoices i
    on i.contract_id = c.id
   and i.deleted_at is null
   and i.company_id = v_company_id
  where c.company_id = v_company_id
  group by c.tenant_id, c.company_id;

  delete from public.owner_balances where company_id = v_company_id;
  insert into public.owner_balances (
    owner_id, total_income, total_expenses, commission, net_balance, updated_at, company_id
  )
  select
    p.owner_id::text,
    coalesce(sum(case when i.deleted_at is null then i.paid_amount else 0 end), 0),
    coalesce((
      select sum(e.amount)
      from public.expenses e
      join public.units u2 on u2.id::text = e.property_id::text
      join public.properties p2 on p2.id = u2.property_id
      where p2.owner_id = p.owner_id
        and p2.company_id = v_company_id
        and e.company_id = v_company_id
        and e.deleted_at is null
    ), 0),
    0,
    0,
    now(),
    p.company_id
  from public.properties p
  join public.units u
    on u.property_id = p.id
   and u.company_id = v_company_id
  join public.contracts c
    on c.unit_id = u.id
   and c.company_id = v_company_id
  left join public.invoices i
    on i.contract_id = c.id
   and i.company_id = v_company_id
  where p.company_id = v_company_id
  group by p.owner_id, p.company_id;
end;
$$;


ALTER FUNCTION "public"."recalculate_all_balances"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_invoice_status"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.invoices i
  set status = case
      when i.status = 'VOID' then 'VOID'
      when coalesce(i.paid_amount, 0) + coalesce(i.credited_amount, 0) <= 0
           and i.due_date < current_date then 'OVERDUE'
      when coalesce(i.paid_amount, 0) + coalesce(i.credited_amount, 0) <= 0 then 'UNPAID'
      when coalesce(i.paid_amount, 0) + coalesce(i.credited_amount, 0)
           < (i.amount + coalesce(i.tax_amount, 0)) then 'PARTIALLY_PAID'
      else 'PAID'
    end,
    updated_at = now()
  where i.id = p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."recalculate_invoice_status"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_owner_balance"("p_owner_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_income numeric := 0;
  v_expenses numeric := 0;
  v_commission numeric := 0;
  v_balance_owner_id public.owner_balances.owner_id%TYPE := p_owner_id;
  v_company_id uuid;
BEGIN
  SELECT owner_record.company_id
    INTO v_company_id
  FROM public.owners AS owner_record
  WHERE owner_record.id = p_owner_id;

  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'Owner company scope could not be resolved.';
  END IF;

  SELECT COALESCE(sum(p.amount), 0),
    COALESCE(sum(CASE WHEN oa.commission_type = 'RATE'
      THEN p.amount * oa.commission_value / 100 ELSE 0 END), 0)
  INTO v_income, v_commission
  FROM public.payments p
  JOIN public.contracts c ON c.id = p.contract_id AND c.deleted_at IS NULL
  JOIN public.owner_agreements oa ON oa.id = c.agreement_id AND oa.owner_id = p_owner_id
  WHERE p.deleted_at IS NULL
    AND p.company_id = v_company_id
    AND c.company_id = v_company_id
    AND upper(COALESCE(p.status, '')) <> 'VOID';

  -- The clean canonical expense table deliberately has no owner/office charge
  -- classifier. Do not guess ownership there. The legacy live table can still
  -- contribute explicitly classified OWNER expenses until it is converged.
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'expenses' AND column_name = 'charged_to'
  ) AND EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'expenses' AND column_name = 'status'
  ) AND EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'expenses' AND column_name = 'date_time'
  ) THEN
    EXECUTE $owner_expenses$
      SELECT COALESCE(sum(e.amount), 0)
      FROM public.expenses e
      WHERE e.deleted_at IS NULL
        AND upper(COALESCE(e.status, '')) = 'POSTED'
        AND upper(COALESCE(e.charged_to, '')) = 'OWNER'
        AND e.company_id = $2
        AND EXISTS (
          SELECT 1 FROM public.property_owners po
          WHERE po.property_id = e.property_id AND po.owner_id = $1
            AND (po.starts_on IS NULL OR po.starts_on <= public._safe_date(e.date_time))
            AND (po.ends_on IS NULL OR po.ends_on >= public._safe_date(e.date_time))
        )
    $owner_expenses$ INTO v_expenses USING p_owner_id, v_company_id;
  ELSE
    v_expenses := 0;
  END IF;

  INSERT INTO public.owner_balances(
    owner_id, total_income, total_expenses, commission, net_balance, updated_at, company_id
  )
  VALUES (v_balance_owner_id, public._r3(v_income), public._r3(v_expenses), public._r3(v_commission),
    public._r3(v_income - v_expenses - v_commission), now(), v_company_id)
  ON CONFLICT (owner_id) DO UPDATE SET
    total_income = EXCLUDED.total_income,
    total_expenses = EXCLUDED.total_expenses,
    commission = EXCLUDED.commission,
    net_balance = EXCLUDED.net_balance,
    company_id = EXCLUDED.company_id,
    updated_at = now();
END;
$_$;


ALTER FUNCTION "public"."recalculate_owner_balance"("p_owner_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalculate_owner_balance"("p_owner_id" "uuid") IS 'Collected-basis owner balance from non-VOID payments, owner expenses, and RATE agreement fees. FIXED_MONTHLY accrual is settlement-controlled.';



CREATE OR REPLACE FUNCTION "public"."recalculate_unit_statuses"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_updated integer;
begin
  update public.units u
  set status = public.resolve_unit_operational_status(u.id, u.status)
  where u.deleted_at is null
    and u.status is distinct from public.resolve_unit_operational_status(u.id, u.status);

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


ALTER FUNCTION "public"."recalculate_unit_statuses"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_invoice_payment_atomic"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_result jsonb;
  v_receipt_id uuid;
  v_payment_id uuid;
  v_reference text := nullif(btrim(coalesce(payload->>'reference', '')), '');
begin
  if v_actor is null then
    raise exception 'Authentication is required to record invoice payments'
      using errcode = '42501';
  end if;
  if not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'ADMIN or MANAGER role is required to record invoice payments'
      using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  v_result := public.record_invoice_payment_atomic_engine(payload);
  v_receipt_id := nullif(v_result->>'receipt_id', '')::uuid;

  if v_receipt_id is not null then
    if v_reference is not null then
      update public.payments
         set reference_number = coalesce(nullif(btrim(reference_number), ''), v_reference),
             reference_no = coalesce(nullif(btrim(reference_no), ''), v_reference),
             updated_at = now()
       where company_id = v_company_id
         and deleted_at is null
         and (
           receipt_id = v_receipt_id
           or id = v_receipt_id
         );
    end if;

    select p.id
      into v_payment_id
    from public.payments p
    where p.company_id = v_company_id
      and p.deleted_at is null
      and (p.receipt_id = v_receipt_id or p.id = v_receipt_id)
    order by p.created_at desc nulls last, p.id
    limit 1;
  end if;

  if v_payment_id is null then
    raise exception 'PAYMENT_ROW_MISSING_AFTER_RECEIPT: receipt_id=%', v_receipt_id
      using errcode = 'P0002';
  end if;

  return v_result || jsonb_build_object('payment_id', v_payment_id);
end;
$$;


ALTER FUNCTION "public"."record_invoice_payment_atomic"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_invoice_payment_atomic"("payload" "jsonb") IS 'Public collect RPC. Delegates accounting to record_invoice_payment_atomic_engine and returns the persisted payment_id plus dual reference fields required by lifecycle verify.';



CREATE OR REPLACE FUNCTION "public"."record_invoice_payment_atomic_engine"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_invoice_id uuid;
  v_amount numeric;
  v_method text;
  v_date date;
  v_reference text;
  v_request_id text;
  v_invoice public.invoices%rowtype;
  v_contract public.contracts%rowtype;
  v_agreement_version public.owner_agreement_versions%rowtype;
  v_total_due numeric;
  v_paid_amount numeric;
  v_credited_amount numeric;
  v_outstanding numeric;
  v_receipt_id uuid := gen_random_uuid();
  v_allocation_id uuid := gen_random_uuid();
  v_cash_account_no text;
  v_cash_account_id text;
  v_receivable_account_id text;
  v_owner_payable_account_id text;
  v_fee_revenue_account_id text;
  v_vat_account_id text;
  v_internal_payload jsonb;
  v_internal_result jsonb;
  v_existing_result jsonb;
  v_result jsonb;
  v_company_id uuid;
  v_request_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target_id text;
  v_operating_model text;
  v_collection_role text;
  v_commission_type text;
  v_commission_value numeric;
  v_commission_net numeric := 0;
  v_journal_entries jsonb;
  v_is_owner_creditor boolean := false;
  v_taxable boolean := false;
  v_prior_receipt_tax numeric := 0;
  v_prior_credit_tax numeric := 0;
  v_prior_credit_unclassified integer := 0;
  v_remaining_tax numeric := 0;
  v_collection_tax numeric := 0;
  v_collection_net numeric;
  v_tax_snapshot public.taxable_line_tax_snapshots%rowtype;
  v_tax_allocation_receipt_id uuid;
  v_actual_receipt_id uuid;
  v_owner_funds_batch_id uuid;
  v_owner_id uuid;
  v_fee_treatment_id uuid;
  v_fee_tax_profile_id uuid;
  v_fee_tax_code text;
  v_fee_tax_rate numeric := 0;
  v_fee_tax numeric := 0;
  v_fee_gross numeric := 0;
  v_historical_4000 boolean := false;
begin
  if v_actor is null then
    raise exception 'Authentication is required to record invoice payments' using errcode='42501';
  end if;
  if not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'ADMIN or MANAGER role is required to record invoice payments' using errcode='42501';
  end if;

  v_company_id := public.require_company_id();
  if payload ?| array['company_id','account_id','cash_account_id','journal_entries','tax_rate','tax_code','tax_amount'] then
    raise exception 'PAYMENT_SERVER_OWNED_ACCOUNTING_FIELDS_FORBIDDEN' using errcode='22023';
  end if;

  v_request_id := nullif(btrim(coalesce(payload->>'request_id', '')), '');
  v_invoice_id := nullif(payload->>'invoice_id', '')::uuid;
  v_amount := public.gl_pm_round_omr(coalesce((payload->>'amount')::numeric, 0));
  v_method := lower(coalesce(nullif(payload->>'method', ''), nullif(payload->>'channel', ''), nullif(payload->>'payment_method', ''), 'cash'));
  v_date := coalesce(nullif(payload->>'date', '')::date, current_date);
  v_reference := nullif(payload->>'reference', '');

  if v_request_id is null or v_invoice_id is null then
    raise exception 'PAYMENT_REQUEST_AND_INVOICE_REQUIRED' using errcode='22023';
  end if;
  if v_amount <= 0 then
    raise exception 'PAYMENT_AMOUNT_MUST_BE_POSITIVE' using errcode='22023';
  end if;

  case v_method
    when 'cash' then v_cash_account_no := '1111';
    when 'bank_transfer', 'bank' then v_cash_account_no := '1120';
    else
      raise exception 'PAYMENT_METHOD_ACCOUNTING_UNAVAILABLE: RC1 supports only cash or bank_transfer until a controlled clearing-account policy is approved.'
        using errcode='22023';
  end case;

  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'invoice_id', v_invoice_id::text,
    'amount', trim_scale(v_amount),
    'method', v_method,
    'date', nullif(payload->>'date', '')::date,
    'reference', v_reference
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended('record_invoice_payment_atomic:' || v_company_id::text || ':' || v_request_id, 0)
  );

  select response_payload into v_existing_result
    from public.financial_operation_idempotency
   where operation_name = 'record_invoice_payment_atomic:' || v_company_id::text
     and request_id = v_request_id
   for update;
  if v_existing_result is not null then
    v_cached_fingerprint := v_existing_result->>'_request_fingerprint';
    v_cached_target_id := v_existing_result->>'_target_id';
    if v_cached_fingerprint is null
       or v_cached_target_id is null
       or not (v_existing_result ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED' using errcode='22023';
    end if;
    if v_cached_fingerprint <> v_request_fingerprint
       or v_cached_target_id <> v_invoice_id::text then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode='22023';
    end if;
    return v_existing_result->'response';
  end if;

  select * into v_invoice
    from public.invoices
   where id = v_invoice_id
     and company_id = v_company_id
     and deleted_at is null
   for update;
  if not found then
    raise exception 'PAYMENT_INVOICE_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;
  if v_invoice.document_status <> 'POSTED' then
    raise exception 'PAYMENT_INVOICE_NOT_POSTED' using errcode='22023';
  end if;

  select * into v_contract
    from public.contracts
   where id = v_invoice.contract_id
     and company_id = v_company_id
     and deleted_at is null
   for update;
  if not found then
    raise exception 'PAYMENT_CONTRACT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;

  -- RC1 accepts only a fully classified immutable owner-agency invoice.
  -- Historical/null/other models are not guessed into 1201: review the source
  -- under S08 and use a governed correction where approved.
  if v_invoice.invoice_accounting_classification not in (
       'OWNER_AGENCY_OWNER_CREDITOR_OPERATIONAL',
       'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS'
     )
     or v_invoice.invoice_operating_model is distinct from 'OWNER_AGENCY'
     or v_invoice.invoice_collection_role not in ('OWNER_IS_CREDITOR','OFFICE_IS_CREDITOR')
     or v_invoice.invoice_agreement_version_id is null then
    raise exception 'HISTORICAL_INVOICE_ACCOUNTING_REVIEW_REQUIRED: payment requires immutable RC1 owner-agency accounting lineage.'
      using errcode='23514';
  end if;

  select * into v_agreement_version
    from public.owner_agreement_versions av
   where av.id = v_invoice.invoice_agreement_version_id
     and av.company_id = v_company_id;
  if not found then
    raise exception 'OWNER_AGENCY_COLLECTION_TERMS_MISSING' using errcode='23514';
  end if;

  select oa.owner_id into v_owner_id
    from public.owner_agreements oa
   where oa.id = v_agreement_version.owner_agreement_id
     and oa.company_id = v_company_id;
  if v_owner_id is null
     or v_invoice.invoice_operating_model is distinct from v_contract.operating_model_snapshot
     or v_invoice.invoice_collection_role is distinct from v_contract.collection_role_snapshot then
    raise exception 'PAYMENT_INVOICE_CONTRACT_LINEAGE_MISMATCH' using errcode='23514';
  end if;

  v_operating_model := v_invoice.invoice_operating_model;
  v_collection_role := v_invoice.invoice_collection_role;
  v_commission_type := v_agreement_version.commission_type;
  v_commission_value := v_agreement_version.commission_value;

  v_total_due := public.gl_pm_round_omr(v_invoice.amount + coalesce(v_invoice.tax_amount, 0));
  v_paid_amount := coalesce(v_invoice.paid_amount, 0);
  v_credited_amount := coalesce(v_invoice.credited_amount, 0);
  v_outstanding := public.gl_pm_round_omr(v_total_due - v_paid_amount - v_credited_amount);
  if v_amount > v_outstanding + 0.001 then
    raise exception 'PAYMENT_EXCEEDS_OUTSTANDING: payment % exceeds invoice outstanding % after credits.', v_amount, v_outstanding
      using errcode='22023';
  end if;

  -- Tax allocation is based on the invoice's immutable snapshot and active
  -- prior credit/payment components; no current profile is consulted here.
  if v_invoice.tax_treatment = 'TAXABLE' then
    select * into v_tax_snapshot
      from public.taxable_line_tax_snapshots s
     where s.id = v_invoice.tax_snapshot_id
       and s.company_id = v_company_id
       and s.source_type = 'invoice'
       and s.source_id = v_invoice.id::text;
    if not found
       or v_invoice.tax_profile_id is null
       or v_tax_snapshot.tax_code is distinct from v_invoice.tax_code
       or v_tax_snapshot.tax_rate is distinct from v_invoice.tax_rate
       or v_tax_snapshot.tax_amount is distinct from v_invoice.tax_amount then
      raise exception 'PAYMENT_TAX_LINEAGE_MISSING' using errcode='23514';
    end if;
    v_taxable := true;

    select coalesce(sum(pta.tax_amount), 0)
      into v_prior_receipt_tax
      from public.invoice_payment_tax_allocations pta
      join public.receipts r on r.id = pta.receipt_id and r.company_id = v_company_id
     where pta.company_id = v_company_id
       and pta.invoice_id = v_invoice.id
       and upper(coalesce(r.status,'')) <> 'VOID'
       and r.deleted_at is null;

    select
      coalesce(sum(ic.tax_amount) filter (where ic.status = 'POSTED'), 0),
      count(*) filter (where ic.status = 'POSTED' and ic.tax_amount is null)
    into v_prior_credit_tax, v_prior_credit_unclassified
    from public.invoice_credits ic
    where ic.company_id = v_company_id
      and ic.invoice_id = v_invoice.id;

    if v_prior_credit_unclassified > 0 then
      raise exception 'PAYMENT_EXISTING_CREDIT_TAX_LINEAGE_REVIEW_REQUIRED' using errcode='23514';
    end if;
    if v_paid_amount > 0 and v_prior_receipt_tax = 0 and v_invoice.tax_amount > 0 then
      raise exception 'PAYMENT_HISTORICAL_TAX_ALLOCATION_REVIEW_REQUIRED: prior taxable collections have no immutable component lineage.'
        using errcode='23514';
    end if;

    v_remaining_tax := public.gl_pm_round_omr(v_invoice.tax_amount - v_prior_credit_tax - v_prior_receipt_tax);
    if v_remaining_tax < -0.001 then
      raise exception 'PAYMENT_TAX_LINEAGE_BALANCE_INVALID' using errcode='23514';
    end if;
    if v_amount >= v_outstanding - 0.001 then
      v_collection_tax := greatest(v_remaining_tax, 0);
    elsif v_outstanding > 0 then
      v_collection_tax := public.gl_pm_round_omr(v_amount * greatest(v_remaining_tax, 0) / v_outstanding);
    end if;
  elsif v_invoice.tax_treatment = 'NON_TAXABLE' then
    if coalesce(v_invoice.tax_amount, 0) <> 0 then
      raise exception 'PAYMENT_NON_TAXABLE_INVOICE_TAX_INVALID' using errcode='23514';
    end if;
  elsif coalesce(v_invoice.tax_amount, 0) > 0 then
    raise exception 'PAYMENT_LEGACY_TAX_LINEAGE_REVIEW_REQUIRED' using errcode='23514';
  end if;

  v_collection_net := public.gl_pm_round_omr(v_amount - v_collection_tax);
  v_is_owner_creditor := v_operating_model = 'OWNER_AGENCY' and v_collection_role = 'OWNER_IS_CREDITOR';

  if v_commission_type = 'RATE' then
    if v_commission_value is null or v_commission_value < 0 or v_commission_value > 100 then
      raise exception 'OWNER_AGENCY_RATE_TERMS_INVALID' using errcode='23514';
    end if;
    v_commission_net := public.gl_pm_round_omr(v_collection_net * v_commission_value / 100);
    if v_commission_net > 0 then
      select treatment_id, tax_profile_id, tax_code, tax_rate
        into v_fee_treatment_id, v_fee_tax_profile_id, v_fee_tax_code, v_fee_tax_rate
        from public.resolve_active_fee_tax_treatment(v_company_id, 'RATE_MANAGEMENT_FEE', v_date);
      v_fee_tax := public.compute_tax_amount(v_commission_net, v_fee_tax_rate);
      v_fee_gross := public.gl_pm_round_omr(v_commission_net + v_fee_tax);
    end if;
  end if;

  v_cash_account_id := public.require_company_account_id(v_company_id, v_cash_account_no);
  v_receivable_account_id := public.require_company_account_id(v_company_id, '1201');
  v_owner_payable_account_id := public.require_company_account_id(v_company_id, '2000');
  if v_collection_tax > 0 or v_fee_tax > 0 then
    v_vat_account_id := public.require_company_account_id(v_company_id, '2100');
  end if;
  if v_commission_net > 0 then
    v_fee_revenue_account_id := public.require_company_account_id(v_company_id, '4100');
  end if;

  v_journal_entries := jsonb_build_array(
    jsonb_build_object(
      'id', gen_random_uuid(),
      'no', 'PAY-' || left(replace(v_request_id, '-', ''), 12) || '-D',
      'date', v_date::text,
      'account_id', v_cash_account_id,
      'amount', v_amount,
      'type', 'DEBIT',
      'source_id', v_receipt_id,
      'entity_type', 'contract',
      'entity_id', v_invoice.contract_id,
      'created_at', timezone('utc', now())
    )
  );

  if v_is_owner_creditor then
    v_journal_entries := v_journal_entries || jsonb_build_array(
      jsonb_build_object(
        'id', gen_random_uuid(),
        'no', 'PAY-' || left(replace(v_request_id, '-', ''), 12) || '-C-OFP',
        'date', v_date::text,
        'account_id', v_owner_payable_account_id,
        'amount', v_collection_net,
        'type', 'CREDIT',
        'source_id', v_receipt_id,
        'entity_type', 'contract',
        'entity_id', v_invoice.contract_id,
        'created_at', timezone('utc', now())
      )
    );
    if v_collection_tax > 0 then
      v_journal_entries := v_journal_entries || jsonb_build_array(
        jsonb_build_object(
          'id', gen_random_uuid(),
          'no', 'PAY-' || left(replace(v_request_id, '-', ''), 12) || '-C-VAT',
          'date', v_date::text,
          'account_id', v_vat_account_id,
          'amount', v_collection_tax,
          'type', 'CREDIT',
          'source_id', v_receipt_id,
          'entity_type', 'contract',
          'entity_id', v_invoice.contract_id,
          'created_at', timezone('utc', now())
        )
      );
    end if;
  else
    v_journal_entries := v_journal_entries || jsonb_build_array(
      jsonb_build_object(
        'id', gen_random_uuid(),
        'no', 'PAY-' || left(replace(v_request_id, '-', ''), 12) || '-C-AR',
        'date', v_date::text,
        'account_id', v_receivable_account_id,
        'amount', v_amount,
        'type', 'CREDIT',
        'source_id', v_receipt_id,
        'entity_type', 'contract',
        'entity_id', v_invoice.contract_id,
        'created_at', timezone('utc', now())
      )
    );
  end if;

  if v_commission_net > 0 then
    v_journal_entries := v_journal_entries || jsonb_build_array(
      jsonb_build_object(
        'id', gen_random_uuid(),
        'no', 'FEE-' || left(replace(v_request_id, '-', ''), 12) || '-D',
        'date', v_date::text,
        'account_id', v_owner_payable_account_id,
        'amount', v_fee_gross,
        'type', 'DEBIT',
        'source_id', v_receipt_id,
        'entity_type', 'contract',
        'entity_id', v_invoice.contract_id,
        'created_at', timezone('utc', now())
      ),
      jsonb_build_object(
        'id', gen_random_uuid(),
        'no', 'FEE-' || left(replace(v_request_id, '-', ''), 12) || '-C',
        'date', v_date::text,
        'account_id', v_fee_revenue_account_id,
        'amount', v_commission_net,
        'type', 'CREDIT',
        'source_id', v_receipt_id,
        'entity_type', 'contract',
        'entity_id', v_invoice.contract_id,
        'created_at', timezone('utc', now())
      )
    );
    if v_fee_tax > 0 then
      v_journal_entries := v_journal_entries || jsonb_build_array(
        jsonb_build_object(
          'id', gen_random_uuid(),
          'no', 'FEE-' || left(replace(v_request_id, '-', ''), 12) || '-C-VAT',
          'date', v_date::text,
          'account_id', v_vat_account_id,
          'amount', v_fee_tax,
          'type', 'CREDIT',
          'source_id', v_receipt_id,
          'entity_type', 'contract',
          'entity_id', v_invoice.contract_id,
          'created_at', timezone('utc', now())
        )
      );
    end if;
  end if;

  v_internal_payload := jsonb_build_object(
    'request_id', v_request_id,
    'receipt', jsonb_build_object(
      'id', v_receipt_id,
      'contract_id', v_invoice.contract_id,
      'date_time', v_date::text,
      'channel', v_method,
      'amount', v_amount,
      'ref', coalesce(v_reference, v_request_id),
      'notes', 'Invoice payment ' || v_invoice_id::text,
      'status', 'POSTED',
      'created_at', timezone('utc', now()),
      'request_id', v_request_id
    ),
    'allocations', jsonb_build_array(jsonb_build_object(
      'id', v_allocation_id,
      'invoice_id', v_invoice_id,
      'amount', v_amount,
      'created_at', timezone('utc', now())
    )),
    'journal_entries', v_journal_entries
  );

  v_internal_result := public.post_receipt_atomic(v_internal_payload);
  v_actual_receipt_id := coalesce(nullif(v_internal_result->>'receipt_id','')::uuid, v_receipt_id);
  select jb.id into v_owner_funds_batch_id
    from public.journal_batches jb
   where jb.company_id = v_company_id
     and jb.source_type = 'receipt'
     and jb.source_id = v_actual_receipt_id::text
   order by jb.created_at, jb.id
   limit 1;

  if v_taxable then
    v_tax_allocation_receipt_id := v_actual_receipt_id;
    insert into public.invoice_payment_tax_allocations (
      company_id, receipt_id, invoice_id, tax_snapshot_id, net_amount, tax_amount
    ) values (
      v_company_id, v_tax_allocation_receipt_id, v_invoice_id,
      v_invoice.tax_snapshot_id, v_collection_net, v_collection_tax
    );
  end if;

  if v_commission_net > 0 then
    insert into public.management_fee_tax_snapshots (
      company_id, receipt_id, invoice_id, fee_kind, treatment_id, tax_profile_id,
      tax_code, tax_rate, net_amount, tax_amount, effective_date, journal_batch_id
    ) values (
      v_company_id, v_actual_receipt_id, v_invoice_id, 'RATE_MANAGEMENT_FEE',
      v_fee_treatment_id, v_fee_tax_profile_id, v_fee_tax_code, v_fee_tax_rate,
      v_commission_net, v_fee_tax, v_date, v_owner_funds_batch_id
    );
  end if;

  if v_is_owner_creditor then
    insert into public.owner_funds_events (
      company_id, owner_id, contract_id, invoice_id, source_type, source_id,
      event_id, amount_delta, effective_date, journal_batch_id
    ) values (
      v_company_id, v_owner_id, v_invoice.contract_id, v_invoice_id,
      'OWNER_COLLECTION', v_actual_receipt_id::text, 'collection',
      v_collection_net, v_date, v_owner_funds_batch_id
    );
  end if;

  if v_commission_net > 0 then
    insert into public.owner_funds_events (
      company_id, owner_id, contract_id, invoice_id, source_type, source_id,
      event_id, amount_delta, effective_date, journal_batch_id
    ) values (
      v_company_id, v_owner_id, v_invoice.contract_id, v_invoice_id,
      'MANAGEMENT_FEE', v_actual_receipt_id::text, 'fee',
      -v_fee_gross, v_date, v_owner_funds_batch_id
    );
  end if;

  v_result := v_internal_result || jsonb_build_object(
    'status', 'recorded',
    'request_id', v_request_id,
    'invoice_id', v_invoice_id,
    'receipt_id', coalesce(nullif(v_internal_result->>'receipt_id', '')::uuid, v_receipt_id),
    'accounting_model', coalesce(v_operating_model, 'STANDARD'),
    'collection_role', v_collection_role,
    'cash_account_no', v_cash_account_no,
    'collection_net', v_collection_net,
    'collection_tax', v_collection_tax,
    'management_fee_net', v_commission_net,
    'management_fee_tax', v_fee_tax,
    'management_fee_gross', v_fee_gross
  );

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values (
    'record_invoice_payment_atomic:' || v_company_id::text,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_invoice_id::text,
      'response', v_result
    )
  ) on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."record_invoice_payment_atomic_engine"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_invoice_payment_atomic_engine"("payload" "jsonb") IS 'Internal RC1 invoice collection engine. Not a browser RPC.';



CREATE OR REPLACE FUNCTION "public"."recover_owner_receivable_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_dfo_id uuid := nullif(p_payload->>'due_from_owner_id','')::uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_amount numeric := public.wp02_gap008_round_omr(nullif(p_payload->>'amount','')::numeric);
  v_cash_no text := coalesce(nullif(p_payload->>'cash_account_no',''), '1120');
  v_date date := nullif(p_payload->>'effective_date','')::date;
  v_dfo public.due_from_owners%rowtype;
  v_cash_id text; v_due_id text; v_post jsonb; v_batch_id uuid;
  v_fp text; v_cached jsonb; v_id uuid := gen_random_uuid(); v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DUE_FROM_OWNER_RECOVERY_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if p_payload ?| array['company_id','amount_override','target_account'] then
    raise exception 'DUE_FROM_OWNER_RECOVERY_SERVER_OWNED_FIELDS_FORBIDDEN' using errcode = '22023';
  end if;
  if v_dfo_id is null or v_request_id is null or v_amount is null or v_amount <= 0 or v_date is null then
    raise exception 'DUE_FROM_OWNER_RECOVERY_REQUEST_AMOUNT_DATE_REQUIRED' using errcode = '22023';
  end if;
  if v_cash_no not in ('1111','1120') then
    raise exception 'DUE_FROM_OWNER_RECOVERY_CASH_ACCOUNT_INVALID' using errcode = '22023';
  end if;

  v_fp := encode(sha256(convert_to(jsonb_build_object('due_from_owner_id', v_dfo_id, 'amount', v_amount, 'cash_account_no', v_cash_no, 'effective_date', v_date)::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended('due_from_owner_recover:' || v_company_id::text || ':' || v_request_id, 0));

  select response_payload into v_cached
    from public.financial_operation_idempotency
   where operation_name = 'recover_owner_receivable_atomic:' || v_company_id::text
     and request_id = v_request_id for update;
  if v_cached is not null then
    if v_cached->>'_request_fingerprint' is distinct from v_fp or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode = '22023';
    end if;
    return v_cached->'response';
  end if;

  select * into v_dfo from public.due_from_owners
   where id = v_dfo_id and company_id = v_company_id for update;
  if not found then
    raise exception 'DUE_FROM_OWNER_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;
  if v_dfo.status = 'REVERSED' then
    raise exception 'DUE_FROM_OWNER_RECOVERY_REVERSED' using errcode = '22023';
  end if;
  if v_amount > v_dfo.outstanding + 0.001 then
    raise exception 'DUE_FROM_OWNER_RECOVERY_EXCEEDS_OUTSTANDING' using errcode = '22023';
  end if;

  v_cash_id := public.gl_pm_require_account(v_company_id, v_cash_no);
  v_due_id := public.gl_pm_require_account(v_company_id, '1300');
  v_post := public.post_journal_event(jsonb_build_object(
    'company_id', v_company_id, 'source_type', 'pm_due_from_owner_recovery', 'source_id', v_dfo_id::text,
    'event_id', 'recover', 'effective_date', v_date,
    'description', 'Cash recovery of Due from Owner',
    'lines', jsonb_build_array(
      jsonb_build_object('account_id', v_cash_id, 'debit', v_amount, 'credit', 0,
        'ref_source_id', v_dfo_id::text, 'ref_entity_type', 'due_from_owner', 'ref_entity_id', v_dfo_id::text),
      jsonb_build_object('account_id', v_due_id, 'debit', 0, 'credit', v_amount,
        'ref_source_id', v_dfo_id::text, 'ref_entity_type', 'due_from_owner', 'ref_entity_id', v_dfo_id::text)
    )
  ));
  v_batch_id := (v_post->>'batch_id')::uuid;

  insert into public.due_from_owner_recoveries (
    id, company_id, due_from_owner_id, owner_id, amount, cash_account_no, effective_date,
    request_id, source_fingerprint, journal_batch_id, posted_by
  ) values (
    v_id, v_company_id, v_dfo_id, v_dfo.owner_id, v_amount, v_cash_no, v_date,
    v_request_id, v_fp, v_batch_id, v_actor
  );

  update public.due_from_owners
     set recovered_amount = public.wp02_gap008_round_omr(recovered_amount + v_amount),
         outstanding = public.wp02_gap008_round_omr(outstanding - v_amount),
         status = case
           when public.wp02_gap008_round_omr(outstanding - v_amount) = 0 then 'RECOVERED'
           when recovered_amount > 0 then 'PARTIALLY_RECOVERED'
           else 'OPEN' end,
         updated_at = now()
   where id = v_dfo_id;

  v_result := jsonb_build_object(
    'success', true, 'idempotent', false, 'due_from_owner_id', v_dfo_id, 'amount', v_amount,
    'outstanding', public.wp02_gap008_round_omr(v_dfo.outstanding - v_amount), 'journal_batch_id', v_batch_id,
    'status', case when public.wp02_gap008_round_omr(v_dfo.outstanding - v_amount) = 0 then 'RECOVERED' else 'PARTIALLY_RECOVERED' end,
    'request_id', v_request_id
  );
  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('recover_owner_receivable_atomic:' || v_company_id::text, v_request_id,
          jsonb_build_object('_request_fingerprint', v_fp, 'response', v_result));
  return v_result;
end;
$$;


ALTER FUNCTION "public"."recover_owner_receivable_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_property_owner_projection"("p_property_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner_id uuid;
  v_owner_name text;
BEGIN
  SELECT po.owner_id, COALESCE(NULLIF(btrim(o.display_name), ''), NULLIF(btrim(o.full_name), ''), o.name)
    INTO v_owner_id, v_owner_name
  FROM public.property_owners po
  JOIN public.owners o ON o.id = po.owner_id
  WHERE po.property_id::text = p_property_id
    AND (po.starts_on IS NULL OR po.starts_on <= current_date)
    AND (po.ends_on IS NULL OR po.ends_on >= current_date)
  ORDER BY po.is_primary DESC, po.starts_on DESC NULLS LAST, po.created_at
  LIMIT 1;

  UPDATE public.properties
  SET owner_id = v_owner_id,
      owner_name = v_owner_name,
      updated_at = now()
  WHERE id::text = p_property_id
    AND (owner_id IS DISTINCT FROM v_owner_id OR owner_name IS DISTINCT FROM v_owner_name);
END;
$$;


ALTER FUNCTION "public"."refresh_property_owner_projection"("p_property_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_property_owner_projection"("p_property_id" "text") IS 'Maintains properties.owner_id/owner_name as compatibility projections of the current property_owners relationship.';



CREATE OR REPLACE FUNCTION "public"."refund_deposit_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id', '');
  v_deposit_id text := nullif(p_payload->>'deposit_id', '');
  v_cached jsonb;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role required' using errcode = '42501';
  end if;
  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;
  if v_company_id is null then
    raise exception 'Active company is required.' using errcode = '42501';
  end if;
  if v_request_id is not null then
    select response_payload into v_cached
    from public.financial_operation_idempotency
    where operation_name = 'refund_deposit_atomic:' || v_company_id::text
      and request_id = v_request_id;
    if v_cached is not null then
      return v_cached || jsonb_build_object('idempotent', true);
    end if;
  end if;
  if v_deposit_id is null or not exists (
    select 1 from public.tenant_deposits td
    where td.id::text = v_deposit_id
      and td.company_id = v_company_id
      and td.deleted_at is null
  ) then
    raise exception 'Deposit not found in current company.' using errcode = '42501';
  end if;
  return public.refund_deposit_atomic_phase3a1a_impl(p_payload);
end;
$$;


ALTER FUNCTION "public"."refund_deposit_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_deposit_atomic_phase3a1a_impl"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_request_id text := nullif(p_payload->>'request_id','');
  v_deposit_id text := nullif(p_payload->>'deposit_id','');
  v_amount numeric := nullif(p_payload->>'amount','')::numeric;
  v_payment_method text := nullif(p_payload->>'payment_method','');
  v_refund_date date := nullif(p_payload->>'refund_date','')::date;
  v_notes text := nullif(p_payload->>'notes','');
  v_deposit record;
  v_cached jsonb;
  v_result jsonb;
  v_cash_account_id text;
  v_deposit_account_id text;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role required' using errcode='42501';
  end if;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;

  if v_request_id is null then v_request_id := gen_random_uuid()::text; end if;
  select response_payload into v_cached from public.financial_operation_idempotency where operation_name='refund_deposit_atomic'||':'||v_company_id::text and request_id=v_request_id;
  if v_cached is not null then return v_cached || jsonb_build_object('idempotent', true); end if;

  if v_deposit_id is null then raise exception 'deposit_id required'; end if;
  if v_amount is null or v_amount <=0 then raise exception 'amount >0 required'; end if;
  if v_refund_date is null then v_refund_date := current_date; end if;
  if v_payment_method is null then v_payment_method := 'bank_transfer'; end if;

  perform pg_advisory_xact_lock(hashtextextended('refund_deposit:'||v_deposit_id,0));

  select * into v_deposit from public.tenant_deposits where id=v_deposit_id and deleted_at is null   AND company_id = v_company_id
for update;
  if not found then raise exception 'Deposit not found'; end if;

  if v_amount > v_deposit.remaining_amount then
    raise exception 'Insufficient remaining balance for refund';
  end if;

  update public.tenant_deposits
  set refunded_amount = refunded_amount + v_amount,
      remaining_amount = deposit_amount - deducted_amount - (refunded_amount + v_amount),
      status = case when (deposit_amount - deducted_amount - (refunded_amount + v_amount)) <=0 then 'refunded' else 'partially_refunded' end,
      settled_date = case when (deposit_amount - deducted_amount - (refunded_amount + v_amount)) <=0 then v_refund_date else settled_date end,
      updated_at = now()
  where id=v_deposit_id;

  insert into public.deposit_transactions (deposit_id, type, amount, reason, description, payment_method, request_id, company_id)
  values (v_deposit_id, 'refund', v_amount, 'refund_partial', v_notes, v_payment_method, v_request_id, v_company_id);

  v_cash_account_id := public.ensure_company_account(v_company_id, '1111', 'Cash');
  v_deposit_account_id := public.ensure_company_account(v_company_id, '2200', 'Tenant Deposits Payable');

  if v_cash_account_id is not null and v_deposit_account_id is not null then
    insert into public.journal_entries (id, no, date, account_id, amount, type, source_id, entity_type, entity_id, company_id)
    values
      (gen_random_uuid(), 'DEP-REF-'||substr(v_deposit_id,1,6)||'-D', v_refund_date, v_deposit_account_id, v_amount, 'DEBIT', v_deposit_id, 'deposit_refund', v_deposit_id, v_company_id),
      (gen_random_uuid(), 'DEP-REF-'||substr(v_deposit_id,1,6)||'-C', v_refund_date, v_cash_account_id, v_amount, 'CREDIT', v_deposit_id, 'deposit_refund', v_deposit_id, v_company_id);
  end if;

  v_result := jsonb_build_object('success',true,'deposit_id',v_deposit_id,'refunded',v_amount,'remaining', v_deposit.remaining_amount - v_amount,'request_id',v_request_id);

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('refund_deposit_atomic'||':'||v_company_id::text, v_request_id, v_result) on conflict (operation_name, request_id) do nothing;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."refund_deposit_atomic_phase3a1a_impl"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_deposit_governed_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_company_id uuid;
  v_deposit_id text:=nullif(btrim(coalesce(p_payload->>'deposit_id','')),'');
  v_request_id text:=nullif(btrim(coalesce(p_payload->>'request_id','')),'');
  v_amount numeric:=public.gl_pm_round_omr(nullif(p_payload->>'amount','')::numeric);
  v_date date:=nullif(p_payload->>'refund_date','')::date;
  v_method text:=lower(coalesce(nullif(p_payload->>'payment_method',''),'bank_transfer'));
  v_cash_no text; v_remaining numeric; v_refunded numeric; v_dep_account text; v_cash_account text;
  v_fp text; v_existing public.deposit_refund_events%rowtype; v_post jsonb; v_batch uuid; v_id uuid:=gen_random_uuid();
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then raise exception 'DEPOSIT_REFUND_ROLE_REQUIRED' using errcode='42501'; end if;
  v_company_id:=public.require_company_id();
  if p_payload ? 'company_id' then raise exception 'DEPOSIT_REFUND_COMPANY_SERVER_OWNED' using errcode='22023'; end if;
  if v_deposit_id is null or v_request_id is null or v_amount is null or v_amount<=0 or v_date is null then raise exception 'DEPOSIT_REFUND_DEPOSIT_REQUEST_AMOUNT_DATE_REQUIRED' using errcode='22023'; end if;
  if v_method not in ('cash','bank_transfer','check') then raise exception 'DEPOSIT_REFUND_METHOD_INVALID' using errcode='22023'; end if;
  v_cash_no:=case when v_method='cash' then '1111' else '1120' end;
  v_fp:=encode(sha256(convert_to(jsonb_build_object('deposit_id',v_deposit_id,'amount',v_amount,'date',v_date,'method',v_method)::text,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtextextended('deposit_refund:'||v_company_id::text||':'||v_request_id,0));
  select * into v_existing from public.deposit_refund_events where company_id=v_company_id and request_id=v_request_id;
  if found then
    if v_existing.source_fingerprint<>v_fp then raise exception 'DEPOSIT_REFUND_IDEMPOTENCY_CONFLICT' using errcode='22023'; end if;
    return jsonb_build_object('success',true,'idempotent',true,'refund_event_id',v_existing.id,'status',v_existing.status,'batch_id',v_existing.journal_batch_id);
  end if;
  select remaining_amount,refunded_amount into v_remaining,v_refunded from public.tenant_deposits
   where id::text=v_deposit_id and company_id=v_company_id and deleted_at is null for update;
  if not found then raise exception 'DEPOSIT_REFUND_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if;
  if v_amount>v_remaining then raise exception 'DEPOSIT_REFUND_EXCEEDS_REMAINING' using errcode='22023'; end if;
  v_dep_account:=public.gl_pm_require_account(v_company_id,'2200'); v_cash_account:=public.gl_pm_require_account(v_company_id,v_cash_no);
  v_post:=public.post_journal_event(jsonb_build_object('company_id',v_company_id,'source_type','pm_deposit_refund','source_id',v_id::text,'event_id','refund',
    'effective_date',v_date,'description','Governed tenant deposit refund',
    'lines',jsonb_build_array(jsonb_build_object('account_id',v_dep_account,'debit',v_amount,'credit',0,'ref_source_id',v_id::text,'ref_entity_type','deposit_refund','ref_entity_id',v_deposit_id),jsonb_build_object('account_id',v_cash_account,'debit',0,'credit',v_amount,'ref_source_id',v_id::text,'ref_entity_type','deposit_refund','ref_entity_id',v_deposit_id))));
  v_batch:=(v_post->>'batch_id')::uuid;
  insert into public.deposit_transactions(deposit_id,type,amount,reason,description,payment_method,request_id,company_id,journal_batch_id)
  values(v_deposit_id,'refund',v_amount,'refund_partial','Governed deposit refund',v_method,v_request_id,v_company_id,v_batch);
  update public.tenant_deposits set refunded_amount=public.gl_pm_round_omr(refunded_amount+v_amount),remaining_amount=public.gl_pm_round_omr(remaining_amount-v_amount),
    status=case when public.gl_pm_round_omr(remaining_amount-v_amount)=0 then 'refunded' else 'partially_refunded' end,
    settled_date=case when public.gl_pm_round_omr(remaining_amount-v_amount)=0 then v_date else settled_date end,updated_at=now()
   where id::text=v_deposit_id and company_id=v_company_id;
  insert into public.deposit_refund_events(id,company_id,deposit_id,amount,cash_account_no,effective_date,request_id,source_fingerprint,journal_batch_id,posted_by)
  values(v_id,v_company_id,v_deposit_id,v_amount,v_cash_no,v_date,v_request_id,v_fp,v_batch,v_actor);
  return jsonb_build_object('success',true,'idempotent',false,'refund_event_id',v_id,'amount',v_amount,'batch_id',v_batch,
    'refunded',public.gl_pm_round_omr(v_refunded+v_amount),'remaining',public.gl_pm_round_omr(v_remaining-v_amount),'status','POSTED');
end;
$$;


ALTER FUNCTION "public"."refund_deposit_governed_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_contract_atomic"("p_contract_id" "text", "p_checker_signature" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := public.require_company_id();
  v_actor uuid := auth.uid();
  v_contract public.contracts%rowtype;
  v_now timestamptz := now();
  v_result jsonb;
begin
  if v_actor is null or not public.is_admin_or_manager() then
    raise exception 'CONTRACT_APPROVAL_FORBIDDEN' using errcode='42501';
  end if;
  if nullif(btrim(coalesce(p_checker_signature,'')), '') is null then
    raise exception 'CHECKER_SIGNATURE_REQUIRED' using errcode='22023';
  end if;
  if nullif(btrim(coalesce(p_reason,'')), '') is null then
    raise exception 'REJECTION_REASON_REQUIRED' using errcode='22023';
  end if;

  select * into v_contract
  from public.contracts
  where id::text = p_contract_id
    and company_id = v_company
    and deleted_at is null
  for update;

  if not found then
    raise exception 'CONTRACT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;
  if lower(coalesce(v_contract.status,'')) <> 'draft'
     or v_contract.approval_status <> 'PENDING' then
    raise exception 'CONTRACT_NOT_PENDING_APPROVAL' using errcode='22023';
  end if;
  if v_contract.maker_user_id is null or v_actor = v_contract.maker_user_id then
    raise exception 'MAKER_CHECKER_MUST_BE_DISTINCT' using errcode='42501';
  end if;

  update public.contracts c
  set checker_user_id = v_actor,
      checker_signature = btrim(p_checker_signature),
      approval_status = 'REJECTED',
      approved_at = null,
      rejected_at = v_now,
      rejection_reason = btrim(p_reason),
      approval_evidence = coalesce(v_contract.approval_evidence,'{}'::jsonb) || jsonb_build_object(
        'checker_user_id', v_actor,
        'checker_signature', btrim(p_checker_signature),
        'rejected_at', v_now,
        'reason', btrim(p_reason)
      ),
      updated_at = v_now
  where c.id::text = p_contract_id
    and c.company_id = v_company
  returning to_jsonb(c) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."reject_contract_atomic"("p_contract_id" "text", "p_checker_signature" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reject_contract_atomic"("p_contract_id" "text", "p_checker_signature" "text", "p_reason" "text") IS 'S04-T03: distinct checker rejects a draft contract pending approval with signature and reason.';



CREATE OR REPLACE FUNCTION "public"."reject_deposit_application_claim_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_claim_id uuid := nullif(p_payload->>'claim_id','')::uuid;
  v_reason text := nullif(btrim(p_payload->>'rejection_reason'),'');
  v_claim public.deposit_application_claims%rowtype;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DEPOSIT_CLAIM_APPROVER_ROLE_REQUIRED' using errcode='42501';
  end if;
  if v_reason is null then raise exception 'DEPOSIT_REJECTION_REASON_REQUIRED' using errcode='22023'; end if;
  v_company_id := public.require_company_id();
  select * into v_claim from public.deposit_application_claims
   where id=v_claim_id and company_id=v_company_id for update;
  if not found then raise exception 'DEPOSIT_CLAIM_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if;
  if v_claim.status='REJECTED' then
    return jsonb_build_object('success',true,'idempotent',true,'claim_id',v_claim.id,'status','REJECTED');
  end if;
  if v_claim.status<>'PENDING' then raise exception 'DEPOSIT_CLAIM_NOT_PENDING' using errcode='22023'; end if;

  if v_claim.created_by=v_actor then
    if not public.wp01_is_sole_admin_allowed(v_company_id) then
      raise exception 'DEPOSIT_CLAIM_MAKER_CHECKER_REQUIRED' using errcode='42501';
    end if;
  end if;

  update public.deposit_application_claims
     set status='REJECTED',
         rejected_by=v_actor,
         rejected_at=now(),
         rejection_reason=v_reason,
         is_sole_admin_exception=(v_claim.created_by=v_actor),
         updated_at=now()
   where id=v_claim.id;
  return jsonb_build_object('success',true,'idempotent',false,'claim_id',v_claim.id,'status','REJECTED');
end;
$$;


ALTER FUNCTION "public"."reject_deposit_application_claim_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."renew_contract_atomic"("old_contract_id" "text", "new_contract_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid;
  v_old public.contracts%rowtype;
  v_new_id text;
  v_new_start_date date;
  v_new_end_date date;
  v_new_amount numeric;
  v_effective_agreement_id public.contracts.agreement_id%type;
  v_requested_agreement text;
  v_billing_day integer;
  v_grace_days integer;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لتجديد عقد'
      using errcode = '42501';
  end if;

  v_company := public.current_company_id();
  if v_company is null then
    raise exception 'سياق الشركة مطلوب لتجديد العقد' using errcode = '42501';
  end if;

  select * into v_old
  from public.contracts
  where id::text = old_contract_id and company_id = v_company and deleted_at is null
  for update;
  if not found then
    raise exception 'العقد الأصلي غير موجود' using errcode = 'P0002';
  end if;
  if lower(coalesce(v_old.status, '')) <> 'active' then
    raise exception 'يمكن تجديد العقود النشطة فقط' using errcode = '23514';
  end if;

  -- Canonical GAP-004 keys first; R4-era spellings accepted as fallback.
  v_new_start_date := coalesce(
    nullif(new_contract_data ->> 'new_start', ''),
    nullif(new_contract_data ->> 'start_date', '')
  )::date;
  v_new_end_date := coalesce(
    nullif(new_contract_data ->> 'new_end', ''),
    nullif(new_contract_data ->> 'end_date', '')
  )::date;
  v_new_amount := coalesce(
    nullif(new_contract_data ->> 'new_amount', ''),
    nullif(new_contract_data ->> 'rent_amount', '')
  )::numeric;
  if v_new_start_date is null or v_new_end_date is null or v_new_end_date <= v_new_start_date then
    raise exception 'فترة التجديد غير صالحة';
  end if;
  if v_new_amount is null or v_new_amount <= 0 then
    raise exception 'قيمة إيجار التجديد يجب أن تكون أكبر من صفر';
  end if;

  -- R4: the renewal inherits the ORIGINAL billing policy unless explicitly
  -- overridden — never a silent reset to billing_day=1.
  v_billing_day := coalesce(nullif(new_contract_data ->> 'billing_day', '')::integer, v_old.billing_day, 1);
  v_grace_days := coalesce(nullif(new_contract_data ->> 'grace_days', '')::integer, v_old.grace_days, 0);
  if v_billing_day < 1 or v_billing_day > 28 then
    raise exception 'CONTRACT_BILLING_DAY_INVALID: يوم الفوترة يجب أن يكون بين 1 و28' using errcode = '23514';
  end if;
  if v_grace_days < 0 or v_grace_days > 90 then
    raise exception 'CONTRACT_GRACE_DAYS_INVALID: أيام السماح يجب أن تكون بين 0 و90' using errcode = '23514';
  end if;

  v_requested_agreement := nullif(new_contract_data ->> 'agreement_id', '');
  if v_requested_agreement is not null then
    if not exists (
      select 1 from public.owner_agreements oa
      where oa.id::text = v_requested_agreement
        and oa.company_id = v_company
        and oa.property_id::text = v_old.property_id::text
        and oa.starts_on <= v_new_start_date
        and (oa.ends_on is null or oa.ends_on >= v_new_end_date)
    ) then
      raise exception 'اتفاقية المالك المحددة لا تغطي فترة التجديد' using errcode = '23514';
    end if;
    v_effective_agreement_id := v_requested_agreement;
  else
    select oa.id into v_effective_agreement_id
    from public.owner_agreements oa
    where oa.company_id = v_company
      and oa.property_id::text = v_old.property_id::text
      and oa.starts_on <= v_new_start_date
      and (oa.ends_on is null or oa.ends_on >= v_new_end_date)
    order by oa.starts_on desc
    limit 1;
    if v_effective_agreement_id is null then
      raise exception 'لا توجد اتفاقية مالك تغطي فترة التجديد' using errcode = '23514';
    end if;
  end if;

  insert into public.contracts (
    property_id, unit_id, tenant_id, agreement_id, start_date, end_date,
    rent_amount, payment_cycle, payment_terms_id, status, company_id,
    renewed_from_id, notes, billing_day, grace_days
  ) values (
    v_old.property_id, v_old.unit_id, v_old.tenant_id, v_effective_agreement_id,
    v_new_start_date, v_new_end_date, v_new_amount, v_old.payment_cycle,
    v_old.payment_terms_id, 'draft', v_company, v_old.id,
    nullif(btrim(coalesce(new_contract_data ->> 'notes', '')), ''),
    v_billing_day, v_grace_days
  )
  returning id::text into v_new_id;

  return jsonb_build_object(
    'status', 'renewed',
    'old_contract_id', old_contract_id,
    'new_contract_id', v_new_id,
    'agreement_id', v_effective_agreement_id,
    'billing_day', v_billing_day,
    'grace_days', v_grace_days
  );
end;
$$;


ALTER FUNCTION "public"."renew_contract_atomic"("old_contract_id" "text", "new_contract_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."renew_contract_atomic"("old_contract_id" "text", "new_contract_data" "jsonb") IS 'GAP-004 renewal authority + R4 billing-policy inheritance. Canonical payload keys: new_start/new_end/new_amount (R4-era start_date/end_date/rent_amount accepted as fallback).';



CREATE OR REPLACE FUNCTION "public"."request_permission"("p_permission" "text", "p_resource_route" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT ''::"text") RETURNS "public"."permission_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := public.require_company_id();
  v_permission text := btrim(coalesce(p_permission, ''));
  v_route text := nullif(btrim(coalesce(p_resource_route, '')), '');
  v_role text := public.current_app_role();
  result public.permission_requests;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if not exists(select 1 from public.app_permission_catalog c where c.permission = v_permission) then
    raise exception 'Unknown permission' using errcode = '22023';
  end if;
  if public.role_has_app_permission(v_role, v_permission)
     or exists(select 1 from public.user_permission_grants g where g.company_id = v_company and g.user_id = auth.uid() and g.permission = v_permission and g.revoked_at is null) then
    raise exception 'Permission is already granted' using errcode = '23505';
  end if;
  if not exists(select 1 from public.app_permission_catalog c where c.permission = v_permission and c.requestable) then
    raise exception 'Permission is not requestable' using errcode = '22023';
  end if;

  select * into result from public.permission_requests pr
  where pr.company_id = v_company and pr.requester_user_id = auth.uid()
    and pr.permission = v_permission and coalesce(pr.resource_route, '') = coalesce(v_route, '')
    and pr.status = 'PENDING'
  order by pr.created_at desc limit 1;
  if result.id is not null then return result; end if;

  insert into public.permission_requests(company_id, requester_user_id, permission, resource_route, reason)
  values (v_company, auth.uid(), v_permission, v_route, btrim(coalesce(p_reason, '')))
  returning * into result;

  insert into public.app_notifications(
    id, company_id, recipient_user_id, created_at, is_read, role, type, title, message,
    link, source_type, source_id, notification_type
  )
  select result.id::text || ':' || u.id::text || ':permission', v_company, u.id, now(), false, u.role::text,
    'permission_request', 'طلب صلاحية جديد',
    coalesce(requester.full_name, requester.name, requester.email, 'مستخدم') || ' طلب ' || catalog.label_ar,
    '/settings?section=users-permissions&sub=permission-requests', 'permission_request', result.id, 'permission_request'
  from public.users u
  join public.company_members cm on cm.user_id = u.id and cm.company_id = v_company and cm.is_active
  cross join public.app_permission_catalog catalog
  left join public.users requester on requester.id = auth.uid()
  where u.deleted_at is null and u.is_active and u.status::text = 'ACTIVE'
    and u.role::text in ('ADMIN','MANAGER') and catalog.permission = v_permission
  on conflict (id) do nothing;

  insert into public.audit_log(id, ts, user_id, action, entity, entity_id, note, "table", details, created_at)
  select gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(), 'PERMISSION_REQUESTED',
    'permission_request', result.id::text, 'طلب صلاحية جديد', 'permission_requests',
    jsonb_build_object('company_id', result.company_id, 'permission', result.permission, 'resource_route', result.resource_route)::text, now()
  where not exists(select 1 from public.audit_log a where a.action = 'PERMISSION_REQUESTED' and a.entity_id = result.id::text);
  return result;
end;
$$;


ALTER FUNCTION "public"."request_permission"("p_permission" "text", "p_resource_route" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_receipt_void_atomic"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid := public.current_company_id();
  v_requested_id text := nullif(btrim(payload->>'receipt_id'), '');
  v_reason text := nullif(btrim(payload->>'reason'), '');
  v_request_id text := nullif(btrim(payload->>'request_id'), '');
  v_receipt public.receipts%rowtype;
  v_existing public.receipt_void_requests%rowtype;
  v_row public.receipt_void_requests%rowtype;
begin
  if v_actor is null or not exists (
    select 1
    from public.users u
    where u.id = v_actor
      and u.status::text = 'ACTIVE'
      and u.role::text in ('ADMIN', 'MANAGER')
  ) then
    raise exception 'ADMIN or MANAGER role is required to request receipt VOID.'
      using errcode = '42501';
  end if;

  if v_company_id is null then
    raise exception 'Company context is required to request receipt VOID.'
      using errcode = '42501';
  end if;

  if v_requested_id is null or v_reason is null or v_request_id is null then
    raise exception 'receipt_id, reason, and request_id are required.'
      using errcode = '22023';
  end if;

  select r.*
    into v_receipt
  from public.receipts r
  where r.company_id = v_company_id
    and r.deleted_at is null
    and (
      r.id::text = v_requested_id
      or exists (
        select 1
        from public.payments p
        where p.company_id = v_company_id
          and p.deleted_at is null
          and p.id::text = v_requested_id
          and p.receipt_id::text = r.id::text
      )
    )
  order by case when r.id::text = v_requested_id then 0 else 1 end
  limit 1
  for update;

  if v_receipt.id is null then
    raise exception 'Receipt was not found in the active company.'
      using errcode = 'P0002';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('receipt_void_request:' || v_company_id::text || ':' || v_receipt.id::text, 0)
  );

  select q.*
    into v_existing
  from public.receipt_void_requests q
  where q.company_id = v_company_id
    and q.request_id = v_request_id
  for update;

  if v_existing.id is not null then
    if v_existing.receipt_id <> v_receipt.id::text
       or v_existing.reason <> v_reason
       or v_existing.requested_by <> v_actor then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode = '22023';
    end if;

    return jsonb_build_object(
      'success', true,
      'idempotent', true,
      'void_request_id', v_existing.id,
      'request_id', v_existing.request_id,
      'receipt_id', v_existing.receipt_id,
      'status', v_existing.status,
      'reason', v_existing.reason,
      'requested_by', v_existing.requested_by,
      'requested_at', v_existing.requested_at
    );
  end if;

  if upper(coalesce(v_receipt.status::text, '')) <> 'POSTED' then
    raise exception 'Only POSTED receipts can enter the VOID approval lifecycle.'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.payments p
    where p.company_id = v_company_id
      and p.deleted_at is null
      and p.receipt_id::text = v_receipt.id::text
      and upper(coalesce(p.status::text, '')) = 'POSTED'
  ) then
    raise exception 'A linked POSTED payment is required to request receipt VOID.'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.receipt_void_requests q
    where q.company_id = v_company_id
      and q.receipt_id = v_receipt.id::text
      and q.status = 'PENDING'
  ) then
    raise exception 'RECEIPT_VOID_ALREADY_PENDING'
      using errcode = '23505';
  end if;

  insert into public.receipt_void_requests (
    company_id, receipt_id, reason, requested_by, request_id
  ) values (
    v_company_id, v_receipt.id::text, v_reason, v_actor, v_request_id
  )
  returning * into v_row;

  update public.receipts
     set maker_user_id = v_actor,
         updated_at = now()
   where id::text = v_receipt.id::text
     and company_id = v_company_id;

  insert into public.audit_log (
    id, ts, user_id, action, entity, entity_id, note, "table", details,
    old_value, new_value, action_timestamp, created_at, updated_at
  ) values (
    gen_random_uuid()::text,
    extract(epoch from now())::bigint,
    v_actor::text,
    'REQUEST_RECEIPT_VOID',
    'receipt_void_request',
    v_row.id::text,
    'Receipt VOID requested; financial state remains unchanged pending separate approval.',
    'receipt_void_requests',
    jsonb_build_object(
      'company_id', v_company_id,
      'receipt_id', v_row.receipt_id,
      'reason', v_row.reason,
      'request_id', v_row.request_id,
      'requested_by', v_row.requested_by
    )::text,
    null,
    jsonb_build_object('status', 'PENDING'),
    now(), now(), now()
  );

  return jsonb_build_object(
    'success', true,
    'idempotent', false,
    'void_request_id', v_row.id,
    'request_id', v_row.request_id,
    'receipt_id', v_row.receipt_id,
    'status', v_row.status,
    'reason', v_row.reason,
    'requested_by', v_row.requested_by,
    'requested_at', v_row.requested_at
  );
end;
$$;


ALTER FUNCTION "public"."request_receipt_void_atomic"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_receipt_void_atomic"("payload" "jsonb") IS 'WP-01 OPS-007/SEC-008: creates an idempotent company-scoped PENDING receipt VOID request with mandatory reason and immutable maker identity.';



CREATE OR REPLACE FUNCTION "public"."require_company_account_id"("p_company_id" "uuid", "p_account_no" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_count integer; v_id text;
begin
 if p_company_id is null or nullif(btrim(p_account_no),'') is null then raise exception 'company_id and account number are required' using errcode='22023'; end if;
 select count(*), min(id) into v_count,v_id from public.accounts where company_id=p_company_id and no=btrim(p_account_no);
 if v_count=0 then raise exception 'Account % is not configured for company %',p_account_no,p_company_id using errcode='P0001'; end if;
 if v_count<>1 then raise exception 'Account % is ambiguous for company %',p_account_no,p_company_id using errcode='23505'; end if;
 return v_id;
end $$;


ALTER FUNCTION "public"."require_company_account_id"("p_company_id" "uuid", "p_account_no" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_company_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if public.current_company_id() is null then
    raise exception 'Company context is required (no company_id claim in JWT).' using errcode = '42501';
  end if;
  return public.current_company_id();
end;
$$;


ALTER FUNCTION "public"."require_company_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_company_onboarding_atomic"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company  uuid := public.require_company_id();
  v_actor    uuid := auth.uid();
  v_authority text := coalesce(public.current_app_role(), 'ADMIN');
  v_waived_count integer;
begin
  if v_actor is null or not public.is_admin() then
    raise exception 'ONBOARDING_WAIVER_ADMIN_REQUIRED' using errcode = '42501';
  end if;

  -- Mark every effective waiver revoked (do not delete the grant history).
  update public.company_onboarding_waivers
  set revoked_at = coalesce(revoked_at, now()),
      revoked_by = coalesce(revoked_by, v_actor)
  where company_id = v_company;

  get diagnostics v_waived_count = row_count;

  -- Clear the completion fact; the RESET event preserves the audit trail.
  delete from public.company_onboarding_completion where company_id = v_company;

  insert into public.company_onboarding_events (
    company_id, requirement_code, action, actor, authority
  ) values (
    v_company, null, 'RESET', v_actor, v_authority
  );

  return jsonb_build_object('reset', true, 'company_id', v_company, 'waivers_revoked', v_waived_count);
end;
$$;


ALTER FUNCTION "public"."reset_company_onboarding_atomic"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_active_fee_tax_treatment"("p_company_id" "uuid", "p_fee_kind" "text", "p_effective_date" "date") RETURNS TABLE("treatment_id" "uuid", "tax_profile_id" "uuid", "tax_code" "text", "tax_rate" numeric, "effective_from" "date", "effective_to" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_company_id is null or p_fee_kind not in ('RATE_MANAGEMENT_FEE','FIXED_MONTHLY') or p_effective_date is null then
    raise exception 'FEE_TAX_TREATMENT_RESOLVE_INPUT_REQUIRED' using errcode='22023';
  end if;
  return query
  select t.id, null::uuid, t.tax_code, t.tax_rate, t.effective_from, t.effective_to
    from public.company_fee_tax_treatments t
   where t.company_id = p_company_id
     and t.fee_kind = p_fee_kind
     and t.status = 'ACTIVE'
     and t.effective_from <= p_effective_date
     and (t.effective_to is null or p_effective_date <= t.effective_to)
   order by t.effective_from desc, t.version_no desc
   limit 1;
  if not found then
    raise exception 'FEE_TAX_TREATMENT_MISSING: no active fee tax treatment covers % for company %, fee kind %.', p_effective_date, p_company_id, p_fee_kind
      using errcode='P0001';
  end if;
end;
$$;


ALTER FUNCTION "public"."resolve_active_fee_tax_treatment"("p_company_id" "uuid", "p_fee_kind" "text", "p_effective_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_active_fee_tax_treatment"("p_company_id" "uuid", "p_fee_kind" "text", "p_effective_date" "date") IS 'Versioned management-fee tax authority. Raises FEE_TAX_TREATMENT_MISSING instead of assuming zero VAT.';



CREATE OR REPLACE FUNCTION "public"."resolve_active_tax_profile"("p_company_id" "uuid", "p_effective_date" "date") RETURNS TABLE("profile_id" "uuid", "tax_code" "text", "tax_rate" numeric, "effective_from" "date", "effective_to" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_company_id is null or p_effective_date is null then
    raise exception 'TAX_PROFILE_RESOLVE_INPUT_REQUIRED' using errcode = '22023';
  end if;

  return query
    select p.id, p.tax_code, p.tax_rate, p.effective_from, p.effective_to
      from public.company_tax_profiles p
     where p.company_id = p_company_id
       and p.status in ('APPROVED','ACTIVE','SUPERSEDED')
       and p.effective_from <= p_effective_date
       and (p.effective_to is null or p_effective_date <= p.effective_to)
     order by p.effective_from desc, p.version_no desc
     limit 1;

  if not found then
    raise exception 'TAX_PROFILE_MISSING: no authoritative tax profile covers %, company %. Posting blocked.',
      p_effective_date, p_company_id using errcode = 'P0001';
  end if;
end;
$$;


ALTER FUNCTION "public"."resolve_active_tax_profile"("p_company_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_active_tax_profile"("p_company_id" "uuid", "p_effective_date" "date") IS 'GAP-010 authoritative tax resolver; raises TAX_PROFILE_MISSING instead of defaulting.';



CREATE OR REPLACE FUNCTION "public"."resolve_maintenance_with_expense"("p_request_id" "text", "p_cost" numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_record public.maintenance_records;
  v_expense_id text;
  v_company_id uuid;
begin
  perform set_config('malek.maintenance_transition_sanctioned', 'true', true);

  if auth.uid() is null then
    raise exception 'غير مصرح: يجب تسجيل الدخول' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.users u
    where u.id = auth.uid() and u.role in ('ADMIN', 'MANAGER')
  ) then
    raise exception 'غير مصرح: هذه العملية متاحة فقط للمدير أو المسؤول' using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  if p_cost is null or p_cost < 0 then
    raise exception 'التكلفة يجب أن تكون رقماً موجباً';
  end if;

  select * into v_record
  from public.maintenance_records
  where id::text = p_request_id
    and company_id = v_company_id
    and deleted_at is null
  for update;

  if not found then
    raise exception 'طلب الصيانة غير موجود';
  end if;

  if v_record.status in ('resolved', 'closed', 'cancelled') then
    raise exception 'تم إغلاق هذا الطلب مسبقاً';
  end if;

  if p_cost > 0 then
    -- Canonical expenses columns only (no notes/ref columns exist on the
    -- clean chain): the maintenance linkage lives on maintenance_records
    -- (expense_id) and the note is folded into the description.
    insert into public.expenses (
      property_id, category, amount, expense_date, description, status, company_id
    ) values (
      v_record.property_id, 'صيانة', p_cost, current_date,
      coalesce(v_record.title, 'مصروف صيانة') || coalesce(' — ' || nullif(btrim(p_notes), ''), ''),
      'posted', v_company_id
    )
    returning id into v_expense_id;
  end if;

  update public.maintenance_records
  set status = 'resolved',
      cost = p_cost,
      resolved_at = now(),
      notes = coalesce(p_notes, notes),
      expense_id = coalesce(v_expense_id::uuid, expense_id)
  where id::text = p_request_id
    and company_id = v_company_id
  returning * into v_record;

  return jsonb_build_object(
    'maintenance', to_jsonb(v_record),
    'expense_id', v_expense_id
  );
end;
$$;


ALTER FUNCTION "public"."resolve_maintenance_with_expense"("p_request_id" "text", "p_cost" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_unit_operational_status"("p_unit_id" "uuid", "p_fallback_status" "text" DEFAULT 'available'::"text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  select case
    when exists (
      select 1
      from public.maintenance_records m
      where m.unit_id = p_unit_id
        and m.deleted_at is null
        and lower(coalesce(m.status, '')) in ('open', 'in_progress')
    ) then 'maintenance'
    when exists (
      select 1
      from public.contracts c
      where c.unit_id = p_unit_id
        and c.deleted_at is null
        and lower(coalesce(c.status, '')) = 'active'
        and btrim(coalesce(c.start_date::text, '')) ~ '^\d{4}-\d{2}-\d{2}$'
        and btrim(coalesce(c.end_date::text, '')) ~ '^\d{4}-\d{2}-\d{2}$'
        and current_date between btrim(c.start_date::text)::date and btrim(c.end_date::text)::date
    ) then 'occupied'
    when lower(coalesce(p_fallback_status, '')) = 'reserved' then 'reserved'
    else 'available'
  end;
$_$;


ALTER FUNCTION "public"."resolve_unit_operational_status"("p_unit_id" "uuid", "p_fallback_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_automation_run"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_run record;
  v_result jsonb;
  v_retry_count integer;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER required' using errcode='42501';
  end if;

  select *
    into v_run
  from public.automation_runs
  where id = p_run_id
  for update;

  if not found then
    raise exception 'Run not found';
  end if;

  if v_run.status <> 'failed' then
    raise exception 'Only failed runs can be retried';
  end if;

  if v_run.rule_id is null then
    raise exception 'Failed run is not linked to an automation rule';
  end if;

  if v_run.retry_count >= 3 then
    raise exception 'Max retries (3) exceeded';
  end if;

  -- Serialize admission with manual execution. The same transaction may acquire
  -- this advisory lock again inside execute_automation_rule().
  perform pg_advisory_xact_lock(
    hashtextextended('automation_rule:' || v_run.rule_id, 0)
  );

  -- A genuine active execution should prevent a retry without consuming one of
  -- the three attempts. The failed source row remains historical and therefore
  -- can never satisfy this predicate.
  if exists (
    select 1
    from public.automation_runs
    where rule_id = v_run.rule_id
      and status = 'running'
      and started_at > extract(epoch from (now() - interval '5 minutes')) * 1000
  ) then
    return jsonb_build_object(
      'success', false,
      'skipped', true,
      'reason', 'duplicate running execution prevented',
      'retried_from_run_id', p_run_id,
      'retry_count', v_run.retry_count
    );
  end if;

  -- Preserve the failed source row as immutable execution history. The retry is
  -- represented by the new automation_runs row created by execute_automation_rule().
  update public.automation_runs
  set retry_count = retry_count + 1,
      updated_at = now()
  where id = p_run_id
  returning retry_count into v_retry_count;

  v_result := public.execute_automation_rule(v_run.rule_id);

  return v_result || jsonb_build_object(
    'retried_from_run_id', p_run_id,
    'retry_count', v_retry_count
  );
end;
$$;


ALTER FUNCTION "public"."retry_automation_run"("p_run_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."retry_automation_run"("p_run_id" "uuid") IS 'Retries a failed automation run by creating a new execution while preserving the failed source row and incrementing its retry_count.';



CREATE OR REPLACE FUNCTION "public"."reverse_commission_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_commission_id text := nullif(trim(p_payload->>'commission_id'), '');
  v_reason text := nullif(trim(p_payload->>'reason'), '');
  v_request_id text := nullif(trim(p_payload->>'request_id'), '');
  v_comm public.commissions%rowtype;
  v_expense public.expenses%rowtype;
  v_reversal_no text;
  v_cached jsonb;
  v_result jsonb;
begin
  if auth.uid() is null or not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لعكس العمولة' using errcode = '42501';
  end if;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'سياق الشركة مطلوب لعكس العمولة' using errcode = '42501';
  end if;

  if v_commission_id is null then
    raise exception 'معرّف العمولة مطلوب' using errcode = '23514';
  end if;

  if v_reason is null then
    raise exception 'سبب العكس مطلوب' using errcode = '23514';
  end if;

  if v_request_id is null or v_request_id = '' then
    v_request_id := gen_random_uuid()::text;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('reverse_commission_atomic:' || v_company_id::text || ':' || v_commission_id, 0)
  );

  select response_payload into v_cached
  from public.financial_operation_idempotency
  where operation_name = 'reverse_commission_atomic:' || v_company_id::text
    and request_id = v_request_id;
  if v_cached is not null then
    return v_cached || jsonb_build_object('idempotent', true);
  end if;

  select * into v_comm
  from public.commissions
  where id = v_commission_id
    and company_id = v_company_id;

  if not found then
    raise exception 'العمولة غير موجودة أو لا تنتمي لشركتك' using errcode = '23514';
  end if;

  if lower(coalesce(v_comm.status, '')) <> 'paid' or v_comm.expense_id is null then
    raise exception 'العمولة غير مدفوعة مالياً ولا يمكن عكسها' using errcode = '23514';
  end if;

  select * into v_expense
  from public.expenses
  where id = v_comm.expense_id
    and company_id = v_company_id;

  if not found then
    raise exception 'المصروف المالي المرتبط بالعمولة غير موجود' using errcode = '23514';
  end if;

  if upper(coalesce(v_expense.status, '')) = 'VOID' then
    raise exception 'المصروف المالي معكوس بالفعل ولا يمكن تكرار العكس' using errcode = '23514';
  end if;

  v_reversal_no := 'REV-' || v_expense.no;

  -- Create balanced accounting reversal entries (CREDIT expense, DEBIT cash)
  insert into public.journal_entries (
    id, no, date, account_id, amount, type, source_id, entity_type, entity_id, created_at, company_id
  )
  select
    gen_random_uuid()::text,
    v_reversal_no || '-' || (case when je.type = 'DEBIT' then 'C' else 'D' end),
    current_date::text,
    je.account_id,
    je.amount,
    case when je.type = 'DEBIT' then 'CREDIT' else 'DEBIT' end,
    v_comm.id,
    'commission_reversal',
    v_comm.id,
    now(),
    v_company_id
  from public.journal_entries je
  where je.source_id::text = v_comm.expense_id::text
    and je.company_id = v_company_id;

  -- Mark original expense VOID (preserving record)
  update public.expenses
  set status = 'VOID',
      description = coalesce(description, '') || ' [تم العكس: ' || v_reason || ']'
  where id = v_comm.expense_id
    and company_id = v_company_id;

  -- Authorize financial trigger and revert commission status to cancelled
  perform set_config('malik.financial_commission_authorized', 'true', true);

  update public.commissions
  set status = 'cancelled',
      paid_at = null,
      updated_at = now()
  where id = v_commission_id
    and company_id = v_company_id;

  -- Audit log entry
  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid()::text,
    extract(epoch from now())::bigint,
    auth.uid()::text,
    (select email from auth.users where id = auth.uid()),
    'UPDATE', 'commissions', v_commission_id,
    'Commission payment reversed with balanced journal entries: ' || v_reason,
    'commissions', left(p_payload::text, 4000), now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'commission_id', v_commission_id,
    'reversed', true
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload, created_at
  ) values (
    'reverse_commission_atomic:' || v_company_id::text,
    v_request_id,
    v_result,
    now()
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."reverse_commission_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_deposit_claim_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_company_id uuid;
  v_claim_id uuid:=nullif(p_payload->>'claim_id','')::uuid;
  v_request_id text:=nullif(btrim(coalesce(p_payload->>'request_id','')),'');
  v_reason text:=nullif(btrim(coalesce(p_payload->>'reason','')),'');
  v_claim public.deposit_application_claims%rowtype; v_rev jsonb; v_rev_batch uuid;
  v_invoice_id uuid; v_invoice_paid numeric;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then raise exception 'DEPOSIT_REVERSAL_ROLE_REQUIRED' using errcode='42501'; end if;
  v_company_id:=public.require_company_id();
  if v_claim_id is null or v_request_id is null or v_reason is null or length(v_reason)<3 then raise exception 'DEPOSIT_REVERSAL_CLAIM_REQUEST_REASON_REQUIRED' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('deposit_claim_reverse:'||v_company_id::text||':'||v_claim_id::text,0));
  select * into v_claim from public.deposit_application_claims where id=v_claim_id and company_id=v_company_id for update;
  if not found then raise exception 'DEPOSIT_CLAIM_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if;
  if v_claim.status='REVERSED' then
    if v_claim.reversal_request_id<>v_request_id then raise exception 'DEPOSIT_REVERSAL_IDEMPOTENCY_CONFLICT' using errcode='22023'; end if;
    return jsonb_build_object('success',true,'idempotent',true,'claim_id',v_claim.id,'reversal_batch_id',v_claim.reversal_journal_batch_id,'status','REVERSED');
  end if;
  if v_claim.status<>'APPLIED' or v_claim.application_journal_batch_id is null then raise exception 'DEPOSIT_REVERSAL_APPLIED_CLAIM_REQUIRED' using errcode='22023'; end if;

  -- Reversal-after-downstream-incompatible-state protection: an OFFICE-creditor
  -- arrears reversal must atomically restore the invoice subledger. If the
  -- invoice was voided/cancelled after application, or its paid amount no
  -- longer covers the allocation, the reversal fails closed and must be
  -- handled through the governed review path.
  if v_claim.claim_kind='INVOICE_ARREARS' and v_claim.target_account_no='1201' and v_claim.invoice_id is not null then
    select i.id, coalesce(i.paid_amount,0)
      into v_invoice_id, v_invoice_paid
    from public.invoices i
    where i.id::text=v_claim.invoice_id
      and i.company_id=v_company_id
      and i.deleted_at is null
      and coalesce(upper(i.status::text),'') not in ('VOID','VOIDED','CANCELLED')
    for update;
    if not found then
      raise exception 'DEPOSIT_REVERSAL_INVOICE_STATE_INVALID: the settled invoice is no longer open.' using errcode='22023';
    end if;
    if v_invoice_paid < v_claim.allocation_amount - 0.001 then
      raise exception 'DEPOSIT_REVERSAL_INVOICE_PAID_INSUFFICIENT: invoice paid amount no longer covers the allocation.' using errcode='22023';
    end if;
  end if;

  v_rev:=public.reverse_journal_batch(v_claim.application_journal_batch_id);
  v_rev_batch:=(v_rev->>'reversal_batch_id')::uuid;

  if v_invoice_id is not null then
    update public.invoices
       set paid_amount = public.gl_pm_round_omr(coalesce(paid_amount,0) - v_claim.allocation_amount),
           updated_at = now()
     where id = v_invoice_id and company_id = v_company_id;
    perform public.recalculate_invoice_status(v_invoice_id);
  end if;

  insert into public.deposit_transactions(deposit_id,type,amount,reason,description,request_id,company_id,journal_batch_id,reversal_of_id)
  values(v_claim.deposit_id,'reversal',v_claim.allocation_amount,'claim_reversal','Compensating reversal of governed deposit claim '||v_claim.id::text,v_request_id,v_company_id,v_rev_batch,
    (select t.id from public.deposit_transactions t where t.request_id=v_claim.application_request_id and t.company_id=v_company_id limit 1));

  update public.tenant_deposits
     set deducted_amount=public.gl_pm_round_omr(deducted_amount-v_claim.allocation_amount),
         remaining_amount=public.gl_pm_round_omr(remaining_amount+v_claim.allocation_amount),
         status=case
           when public.gl_pm_round_omr(remaining_amount+v_claim.allocation_amount)=deposit_amount then 'held'
           when public.gl_pm_round_omr(deducted_amount-v_claim.allocation_amount)>0 then 'partially_deducted'
           when refunded_amount>0 then 'partially_refunded' else 'held' end,
         settled_date=case when public.gl_pm_round_omr(remaining_amount+v_claim.allocation_amount)<deposit_amount then settled_date else null end,
         updated_at=now()
   where id::text=v_claim.deposit_id and company_id=v_company_id;

  update public.deposit_application_claims
     set status='REVERSED',reversal_request_id=v_request_id,reversal_journal_batch_id=v_rev_batch,
         reversal_reason=v_reason,reversed_by=v_actor,reversed_at=now(),updated_at=now()
   where id=v_claim.id;
  return jsonb_build_object('success',true,'idempotent',false,'claim_id',v_claim.id,'reversal_batch_id',v_rev_batch,
    'invoice_id',v_claim.invoice_id,'status','REVERSED');
end;
$$;


ALTER FUNCTION "public"."reverse_deposit_claim_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_deposit_refund_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
 v_actor uuid:=auth.uid(); v_company_id uuid; v_event_id uuid:=nullif(p_payload->>'refund_event_id','')::uuid;
 v_request_id text:=nullif(btrim(coalesce(p_payload->>'request_id','')),''); v_reason text:=nullif(btrim(coalesce(p_payload->>'reason','')),'');
 v_event public.deposit_refund_events%rowtype; v_rev jsonb; v_rev_batch uuid;
begin
 if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then raise exception 'DEPOSIT_REFUND_REVERSAL_ROLE_REQUIRED' using errcode='42501'; end if;
 v_company_id:=public.require_company_id();
 if v_event_id is null or v_request_id is null or v_reason is null or length(v_reason)<3 then raise exception 'DEPOSIT_REFUND_REVERSAL_EVENT_REQUEST_REASON_REQUIRED' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('deposit_refund_reverse:'||v_company_id::text||':'||v_event_id::text,0));
 select * into v_event from public.deposit_refund_events where id=v_event_id and company_id=v_company_id for update;
 if not found then raise exception 'DEPOSIT_REFUND_EVENT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if;
 if v_event.status='REVERSED' then
   if v_event.reversal_request_id<>v_request_id then raise exception 'DEPOSIT_REFUND_REVERSAL_IDEMPOTENCY_CONFLICT' using errcode='22023'; end if;
   return jsonb_build_object('success',true,'idempotent',true,'refund_event_id',v_event.id,'status','REVERSED','reversal_batch_id',v_event.reversal_journal_batch_id);
 end if;
 v_rev:=public.reverse_journal_batch(v_event.journal_batch_id); v_rev_batch:=(v_rev->>'reversal_batch_id')::uuid;
 insert into public.deposit_transactions(deposit_id,type,amount,reason,description,request_id,company_id,journal_batch_id,reversal_of_id)
 values(v_event.deposit_id,'reversal',v_event.amount,'refund_reversal','Compensating reversal of deposit refund '||v_event.id::text,v_request_id,v_company_id,v_rev_batch,
   (select t.id from public.deposit_transactions t where t.request_id=v_event.request_id and t.company_id=v_company_id limit 1));
 update public.tenant_deposits set refunded_amount=public.gl_pm_round_omr(refunded_amount-v_event.amount),remaining_amount=public.gl_pm_round_omr(remaining_amount+v_event.amount),
   status=case when public.gl_pm_round_omr(remaining_amount+v_event.amount)=deposit_amount then 'held' when deducted_amount>0 then 'partially_deducted' when public.gl_pm_round_omr(refunded_amount-v_event.amount)>0 then 'partially_refunded' else 'held' end,
   settled_date=null,updated_at=now() where id::text=v_event.deposit_id and company_id=v_company_id;
 update public.deposit_refund_events set status='REVERSED',reversal_request_id=v_request_id,reversal_journal_batch_id=v_rev_batch,reversal_reason=v_reason,reversed_by=v_actor,reversed_at=now()
  where id=v_event.id;
 return jsonb_build_object('success',true,'idempotent',false,'refund_event_id',v_event.id,'status','REVERSED','reversal_batch_id',v_rev_batch);
end;
$$;


ALTER FUNCTION "public"."reverse_deposit_refund_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_fixed_monthly_accrual_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id', '')), '');
  v_accrual_id uuid := nullif(p_payload->>'accrual_id', '')::uuid;
  v_reason text := nullif(btrim(coalesce(p_payload->>'reason', '')), '');
  v_fingerprint text;
  v_cached jsonb;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'FIXED_MONTHLY_ROLE_REQUIRED: ADMIN, MANAGER or ACCOUNTANT is required.' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if not public.is_company_member(v_company_id, v_actor) then
    raise exception 'FIXED_MONTHLY_ACTIVE_COMPANY_MEMBERSHIP_REQUIRED' using errcode = '42501';
  end if;
  if p_payload ?| array['company_id','amount','tax_amount','lines','journal_batch_id'] then
    raise exception 'FIXED_MONTHLY_CLIENT_FINANCIAL_INPUT_FORBIDDEN' using errcode = '22023';
  end if;
  if v_request_id is null or length(v_request_id) > 200 then
    raise exception 'FIXED_MONTHLY_REQUEST_ID_REQUIRED' using errcode = '22023';
  end if;
  if v_accrual_id is null then
    raise exception 'FIXED_MONTHLY_ACCRUAL_ID_REQUIRED' using errcode = '22023';
  end if;
  if v_reason is null or length(v_reason) < 3 or length(v_reason) > 1000 then
    raise exception 'FIXED_MONTHLY_REVERSAL_REASON_REQUIRED' using errcode = '22023';
  end if;

  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'accrual_id', v_accrual_id,
    'reason', v_reason
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended(
    'reverse_fixed_monthly_accrual_atomic:' || v_company_id::text || ':' || v_request_id,
    0
  ));

  select response_payload into v_cached
  from public.financial_operation_idempotency
  where operation_name = 'reverse_fixed_monthly_accrual_atomic:' || v_company_id::text
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    if v_cached->>'_request_fingerprint' is distinct from v_fingerprint
       or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode = '22023';
    end if;
    return v_cached->'response';
  end if;

  v_result := public.gl_reverse_fixed_monthly_accrual(
    v_company_id,
    v_accrual_id,
    v_reason,
    v_actor
  );

  insert into public.financial_operation_idempotency(operation_name, request_id, response_payload)
  values (
    'reverse_fixed_monthly_accrual_atomic:' || v_company_id::text,
    v_request_id,
    jsonb_build_object('_request_fingerprint', v_fingerprint, 'response', v_result)
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."reverse_fixed_monthly_accrual_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_invoice_credit_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_credit_id uuid;
  v_reason text;
  v_request_id text;
  v_credit public.invoice_credits%rowtype;
  v_invoice public.invoices%rowtype;
  v_reversal_result jsonb;
  v_result jsonb;
  v_existing jsonb;
  v_period_id uuid;
  v_owner_id uuid;
  v_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target text;
begin
  if v_actor is null then
    raise exception 'Authentication is required to reverse invoice credits.' using errcode='42501';
  end if;
  if not coalesce(public.is_admin_or_manager(), false) and not coalesce(public.is_accountant(), false) then
    raise exception 'CREDIT_REVERSAL_ROLE_REQUIRED: ADMIN, MANAGER or ACCOUNTANT role is required.' using errcode='42501';
  end if;
  v_company_id := public.require_company_id();
  v_credit_id := nullif(p_payload->>'credit_id', '')::uuid;
  v_reason := nullif(btrim(coalesce(p_payload->>'reason', '')), '');
  v_request_id := nullif(p_payload->>'request_id', '');
  if v_credit_id is null or v_reason is null or v_request_id is null then
    raise exception 'CREDIT_REVERSAL_REQUIRED: credit_id, reason and request_id are required.' using errcode='22023';
  end if;
  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'credit_id', v_credit_id::text,
    'reason', v_reason
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended('invoice_credit_reversal:' || v_company_id::text || ':' || v_request_id, 0));

  select response_payload into v_existing
    from public.financial_operation_idempotency
   where operation_name = 'invoice_credit_reversal:' || v_company_id::text
     and request_id = v_request_id
   for update;
  if v_existing is not null then
    v_cached_fingerprint := v_existing->>'_fingerprint';
    v_cached_target := v_existing->>'_target';
    if v_cached_fingerprint is null or v_cached_target is null or not (v_existing ? 'response') then
      raise exception 'CREDIT_REVERSAL_IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED' using errcode='22023';
    end if;
    if v_cached_fingerprint <> v_fingerprint or v_cached_target <> v_credit_id::text then
      raise exception 'CREDIT_REVERSAL_IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST' using errcode='22023';
    end if;
    return v_existing->'response';
  end if;

  select * into v_credit
    from public.invoice_credits
   where id = v_credit_id
     and company_id = v_company_id
   for update;
  if not found then
    raise exception 'CREDIT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;
  if v_credit.status <> 'POSTED' then
    raise exception 'CREDIT_ALREADY_REVERSED: only POSTED credits can be reversed.' using errcode='22023';
  end if;

  select * into v_invoice
    from public.invoices
   where id = v_credit.invoice_id
     and company_id = v_company_id
   for update;
  if not found then
    raise exception 'CREDIT_INVOICE_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;
  if v_invoice.credited_amount < v_credit.amount then
    raise exception 'CREDIT_REVERSAL_BALANCE_INVALID: credited balance is less than the credit amount.' using errcode='22023';
  end if;

  select oa.owner_id into v_owner_id
    from public.owner_agreement_versions av
    join public.owner_agreements oa
      on oa.id = av.owner_agreement_id
     and oa.company_id = av.company_id
   where av.id = v_invoice.invoice_agreement_version_id
     and av.company_id = v_company_id;

  perform public.gl_ensure_initial_open_period(v_company_id, coalesce(v_credit.effective_date, current_date));
  select period_id into v_period_id
    from public.gl_resolve_accounting_period(v_company_id, coalesce(v_credit.effective_date, current_date));
  if v_period_id is null then
    raise exception 'CREDIT_REVERSAL_ACCOUNTING_PERIOD_UNAVAILABLE' using errcode='P0001';
  end if;

  if v_credit.journal_batch_id is not null then
    v_reversal_result := public.reverse_journal_batch(v_credit.journal_batch_id);
  else
    v_reversal_result := jsonb_build_object('reversal_batch_id', null);
  end if;

  update public.invoices
     set credited_amount = public.gl_pm_round_omr(credited_amount - v_credit.amount),
         updated_at = now()
   where id = v_credit.invoice_id
     and company_id = v_company_id;
  perform public.recalculate_invoice_status(v_credit.invoice_id);

  update public.invoice_credits
     set status = 'REVERSED',
         reversal_request_id = v_request_id,
         reversal_journal_batch_id = nullif(v_reversal_result->>'reversal_batch_id', '')::uuid,
         reversal_reason = v_reason,
         reversed_by = v_actor,
         reversed_at = now()
   where id = v_credit_id;

  if v_credit.accounting_classification = 'OWNER_AGENCY_OFFICE_CREDITOR_AR_OWNER_FUNDS' then
    if v_owner_id is null then
      raise exception 'CREDIT_REVERSAL_OWNER_FUNDS_OWNER_REQUIRED' using errcode='23514';
    end if;
    insert into public.owner_funds_events (
      company_id, owner_id, contract_id, invoice_id, source_type, source_id,
      event_id, amount_delta, effective_date, journal_batch_id
    ) values (
      v_company_id, v_owner_id, v_invoice.contract_id, v_invoice.id,
      'INVOICE_CREDIT_REVERSAL', v_credit_id::text, v_request_id,
      v_credit.net_amount, v_credit.effective_date,
      nullif(v_reversal_result->>'reversal_batch_id', '')::uuid
    );
  end if;

  v_result := jsonb_build_object(
    'success', true,
    'credit_id', v_credit_id::text,
    'reversal_request_id', v_request_id,
    'reversal_batch_id', v_reversal_result->>'reversal_batch_id'
  );

  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values (
    'invoice_credit_reversal:' || v_company_id::text,
    v_request_id,
    jsonb_build_object('_fingerprint', v_fingerprint, '_target', v_credit_id::text, 'response', v_result)
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."reverse_invoice_credit_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_invoice_credit_atomic"("p_payload" "jsonb") IS 'RC1 credit reversal with target-bound payload fingerprint idempotency; reused request ids cannot replay another credit.';



CREATE OR REPLACE FUNCTION "public"."reverse_journal_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_original public.journal_batches%rowtype;
  v_reversal_id uuid;
  v_period_id uuid;
  v_reason text;
  v_line_count integer;
begin
  if current_user not in ('postgres', 'supabase_admin', 'service_role') then
    raise exception 'GL_ENGINE_SERVER_ONLY: reversals are only callable from a trusted server context.' using errcode = '42501';
  end if;

  if p_batch_id is null then
    raise exception 'GL_BATCH_ID_REQUIRED: batch_id is required.' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('gl_reverse:' || p_batch_id::text, 0));

  select * into v_original
    from public.journal_batches b
   where b.id = p_batch_id
   for update;

  if not found then
    raise exception 'GL_BATCH_NOT_FOUND: batch % does not exist.', p_batch_id using errcode = 'P0002';
  end if;

  -- Idempotent retry: return the already-created reversal.
  if v_original.status = 'REVERSED' then
    select b.id into v_reversal_id
      from public.journal_batches b
     where b.company_id = v_original.company_id
       and b.source_type = 'journal_reversal'
       and b.source_id = v_original.id::text
       and b.event_id = 'REVERSAL-OF:' || v_original.id::text;

    if v_reversal_id is not null then
      return jsonb_build_object(
        'success', true,
        'idempotent', true,
        'original_batch_id', v_original.id,
        'reversal_batch_id', v_reversal_id,
        'status', 'REVERSED'
      );
    end if;
  end if;

  if v_original.status <> 'POSTED' then
    raise exception 'GL_REVERSAL_STATE_INVALID: only POSTED batches can be reversed; batch % is %.', p_batch_id, v_original.status using errcode = 'P0001';
  end if;

  select count(*) into v_line_count
    from public.journal_lines l
   where l.batch_id = v_original.id
     and l.deleted_at is null;

  if v_line_count = 0 then
    raise exception 'JOURNAL_BATCH_EMPTY: batch % has no lines and cannot be reversed.', p_batch_id using errcode = '22023';
  end if;

  -- Reversal follows accounting-period rules: the original effective date is
  -- kept; if its period is closed, the earliest eligible open period receives
  -- the reversal.
  select p.period_id, p.reason into v_period_id, v_reason
    from public.gl_resolve_accounting_period(v_original.company_id, v_original.effective_date) p;

  v_reversal_id := gen_random_uuid();

  insert into public.journal_batches (
    id, company_id, status, source_type, source_id, event_id,
    reversal_of_batch_id, effective_date, accounting_period_id,
    period_resolution_reason, posted_at, posted_by, description, created_at, updated_at
  ) values (
    v_reversal_id, v_original.company_id, 'POSTED',
    'journal_reversal', v_original.id::text, 'REVERSAL-OF:' || v_original.id::text,
    v_original.id, v_original.effective_date, v_period_id, v_reason,
    now(), auth.uid(),
    'Reversal of journal batch ' || v_original.id::text,
    now(), now()
  );

  insert into public.journal_lines (
    id, no, batch_id, company_id, account_id, debit, credit,
    line_description, ref_source_id, ref_entity_type, ref_entity_id, created_at
  )
  select
    gen_random_uuid()::text, 'REV-' || substr(replace(l.id, '-', ''), 1, 10),
    v_reversal_id, l.company_id, l.account_id, l.credit, l.debit,
    'Reversal of line ' || l.id,
    l.ref_source_id, l.ref_entity_type, l.ref_entity_id, now()
  from public.journal_lines l
  where l.batch_id = v_original.id;

  update public.journal_batches
     set status = 'REVERSED',
         reversal_of_batch_id = v_reversal_id,
         updated_at = now()
   where id = v_original.id;

  return jsonb_build_object(
    'success', true,
    'idempotent', false,
    'original_batch_id', v_original.id,
    'reversal_batch_id', v_reversal_id,
    'status', 'REVERSED',
    'reversal_period_id', v_period_id,
    'reversal_period_reason', v_reason
  );
end;
$$;


ALTER FUNCTION "public"."reverse_journal_batch"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_owner_receivable_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_dfo_id uuid := nullif(p_payload->>'due_from_owner_id','')::uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_reason text := nullif(btrim(coalesce(p_payload->>'reason','')), '');
  v_dfo public.due_from_owners%rowtype; v_rev jsonb; v_rev_batch uuid; v_cached jsonb; v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DUE_FROM_OWNER_REVERSE_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if v_dfo_id is null or v_request_id is null or v_reason is null or length(v_reason) < 3 then
    raise exception 'DUE_FROM_OWNER_REVERSE_REQUEST_REASON_REQUIRED' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('due_from_owner_reverse:' || v_company_id::text || ':' || v_dfo_id::text, 0));
  select * into v_dfo from public.due_from_owners where id = v_dfo_id and company_id = v_company_id for update;
  if not found then raise exception 'DUE_FROM_OWNER_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501'; end if;
  if v_dfo.status = 'REVERSED' then
    if v_dfo.reversed_request_id <> v_request_id then raise exception 'DUE_FROM_OWNER_REVERSE_IDEMPOTENCY_CONFLICT' using errcode = '22023'; end if;
    return jsonb_build_object('success', true, 'idempotent', true, 'due_from_owner_id', v_dfo_id, 'status', 'REVERSED', 'reversal_batch_id', v_dfo.reversal_journal_batch_id);
  end if;
  if v_dfo.journal_batch_id is null then raise exception 'DUE_FROM_OWNER_REVERSE_NO_BATCH' using errcode = '22023'; end if;
  if exists (select 1 from public.due_from_owner_recoveries r
              where r.due_from_owner_id = v_dfo_id and r.company_id = v_company_id and r.status = 'POSTED')
     or exists (select 1 from public.due_from_owner_offsets o
                 where o.due_from_owner_id = v_dfo_id and o.company_id = v_company_id and o.status = 'POSTED') then
    raise exception 'DUE_FROM_OWNER_REVERSE_HAS_DOWNSTREAM_SETTLEMENT: reverse recovery/offset first.' using errcode = '22023';
  end if;

  v_rev := public.reverse_journal_batch(v_dfo.journal_batch_id);
  v_rev_batch := (v_rev->>'reversal_batch_id')::uuid;

  update public.due_from_owners
     set status = 'REVERSED', outstanding = 0, reversed_request_id = v_request_id,
         reversal_journal_batch_id = v_rev_batch, updated_at = now()
   where id = v_dfo_id;

  v_result := jsonb_build_object('success', true, 'idempotent', false, 'due_from_owner_id', v_dfo_id, 'status', 'REVERSED', 'reversal_batch_id', v_rev_batch);
  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('reverse_owner_receivable_atomic:' || v_company_id::text, v_request_id, jsonb_build_object('response', v_result));
  return v_result;
end;
$$;


ALTER FUNCTION "public"."reverse_owner_receivable_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_owner_receivable_offset_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_event_id uuid := nullif(p_payload->>'offset_event_id','')::uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_reason text := nullif(btrim(coalesce(p_payload->>'reason','')), '');
  v_event public.due_from_owner_offsets%rowtype;
  v_rev jsonb;
  v_rev_batch uuid;
  v_rev_effective_date date;
  v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DUE_FROM_OWNER_OFFSET_REVERSE_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if v_event_id is null or v_request_id is null or v_reason is null or length(v_reason) < 3 then
    raise exception 'DUE_FROM_OWNER_OFFSET_REVERSE_REQUEST_REASON_REQUIRED' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('due_from_owner_offset_reverse:' || v_company_id::text || ':' || v_event_id::text, 0));
  select * into v_event
    from public.due_from_owner_offsets
   where id = v_event_id and company_id = v_company_id
   for update;
  if not found then
    raise exception 'DUE_FROM_OWNER_OFFSET_EVENT_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;
  if v_event.status = 'REVERSED' then
    if v_event.reversed_request_id <> v_request_id then
      raise exception 'DUE_FROM_OWNER_OFFSET_REVERSE_IDEMPOTENCY_CONFLICT' using errcode = '22023';
    end if;
    return jsonb_build_object(
      'success', true, 'idempotent', true, 'offset_event_id', v_event.id,
      'status', 'REVERSED', 'reversal_batch_id', v_event.reversal_journal_batch_id
    );
  end if;

  v_rev := public.reverse_journal_batch(v_event.journal_batch_id);
  v_rev_batch := (v_rev->>'reversal_batch_id')::uuid;
  select effective_date into v_rev_effective_date
    from public.journal_batches
   where id = v_rev_batch and company_id = v_company_id;
  if v_rev_effective_date is null then
    raise exception 'DUE_FROM_OWNER_OFFSET_REVERSE_BATCH_DATE_REQUIRED' using errcode='23514';
  end if;

  insert into public.owner_funds_events (
    company_id, owner_id, contract_id, invoice_id, source_type, source_id,
    event_id, amount_delta, effective_date, journal_batch_id
  ) values (
    v_company_id, v_event.owner_id, null, null, 'OWNER_OFFSET_REVERSAL', v_event.id::text,
    v_request_id, v_event.amount, v_rev_effective_date, v_rev_batch
  );

  update public.owner_settlements
     set offset_applied = greatest(public.wp02_gap008_round_omr(offset_applied - v_event.amount), 0),
         updated_at = now()
   where id = v_event.owner_settlement_id;

  update public.due_from_owners
     set offset_amount = public.wp02_gap008_round_omr(offset_amount - v_event.amount),
         outstanding = public.wp02_gap008_round_omr(outstanding + v_event.amount),
         status = case
           when public.wp02_gap008_round_omr(offset_amount - v_event.amount) <= 0 then 'OPEN'
           when public.wp02_gap008_round_omr(outstanding + v_event.amount) = 0 then 'CLOSED'
           else 'OFFSET' end,
         updated_at = now()
   where id = v_event.due_from_owner_id;

  update public.due_from_owner_offsets
     set status = 'REVERSED',
         reversed_request_id = v_request_id,
         reversal_journal_batch_id = v_rev_batch,
         updated_at = now()
   where id = v_event.id;

  v_result := jsonb_build_object(
    'success', true, 'idempotent', false, 'offset_event_id', v_event.id,
    'status', 'REVERSED', 'reversal_batch_id', v_rev_batch
  );
  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('reverse_owner_receivable_offset_atomic:' || v_company_id::text,
          v_request_id, jsonb_build_object('response', v_result));
  return v_result;
end;
$$;


ALTER FUNCTION "public"."reverse_owner_receivable_offset_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_owner_receivable_offset_atomic"("p_payload" "jsonb") IS 'Compensating reversal of a lawful owner offset; restores 2000 control through an append-only owner-funds event.';



CREATE OR REPLACE FUNCTION "public"."reverse_owner_receivable_recovery_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_event_id uuid := nullif(p_payload->>'recovery_event_id','')::uuid;
  v_request_id text := nullif(btrim(coalesce(p_payload->>'request_id','')), '');
  v_reason text := nullif(btrim(coalesce(p_payload->>'reason','')), '');
  v_event public.due_from_owner_recoveries%rowtype; v_rev jsonb; v_rev_batch uuid; v_cached jsonb; v_result jsonb;
begin
  if v_actor is null or not (public.is_admin_or_manager() or public.is_accountant()) then
    raise exception 'DUE_FROM_OWNER_RECOVERY_REVERSE_ROLE_REQUIRED' using errcode = '42501';
  end if;
  v_company_id := public.require_company_id();
  if v_event_id is null or v_request_id is null or v_reason is null or length(v_reason) < 3 then
    raise exception 'DUE_FROM_OWNER_RECOVERY_REVERSE_REQUEST_REASON_REQUIRED' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('due_from_owner_recover_reverse:' || v_company_id::text || ':' || v_event_id::text, 0));
  select * into v_event from public.due_from_owner_recoveries where id = v_event_id and company_id = v_company_id for update;
  if not found then raise exception 'DUE_FROM_OWNER_RECOVERY_EVENT_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501'; end if;
  if v_event.status = 'REVERSED' then
    if v_event.reversed_request_id <> v_request_id then raise exception 'DUE_FROM_OWNER_RECOVERY_REVERSE_IDEMPOTENCY_CONFLICT' using errcode = '22023'; end if;
    return jsonb_build_object('success', true, 'idempotent', true, 'recovery_event_id', v_event.id, 'status', 'REVERSED', 'reversal_batch_id', v_event.reversal_journal_batch_id);
  end if;
  v_rev := public.reverse_journal_batch(v_event.journal_batch_id);
  v_rev_batch := (v_rev->>'reversal_batch_id')::uuid;

  update public.due_from_owners
     set recovered_amount = public.wp02_gap008_round_omr(recovered_amount - v_event.amount),
         outstanding = public.wp02_gap008_round_omr(outstanding + v_event.amount),
         status = case
           when public.wp02_gap008_round_omr(recovered_amount - v_event.amount) <= 0 then 'OPEN'
           when public.wp02_gap008_round_omr(outstanding + v_event.amount) = 0 then 'RECOVERED'
           else 'PARTIALLY_RECOVERED' end,
         updated_at = now()
   where id = v_event.due_from_owner_id;

  update public.due_from_owner_recoveries
     set status = 'REVERSED', reversed_request_id = v_request_id, reversal_journal_batch_id = v_rev_batch, updated_at = now()
   where id = v_event.id;

  v_result := jsonb_build_object('success', true, 'idempotent', false, 'recovery_event_id', v_event.id, 'status', 'REVERSED', 'reversal_batch_id', v_rev_batch);
  insert into public.financial_operation_idempotency (operation_name, request_id, response_payload)
  values ('reverse_owner_receivable_recovery_atomic:' || v_company_id::text, v_request_id, jsonb_build_object('response', v_result));
  return v_result;
end;
$$;


ALTER FUNCTION "public"."reverse_owner_receivable_recovery_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_contract_inspection_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_company uuid:=public.require_company_id(); v_record public.contract_inspections%rowtype; v_action text:=upper(p_payload->>'action'); v_request text:=nullif(btrim(p_payload->>'request_id'),''); v_old text;
begin
  if v_actor is null or not public.contract_evidence_actor_can_verify() then raise exception 'CONTRACT_EVIDENCE_VERIFY_FORBIDDEN' using errcode='42501'; end if;
  select * into v_record from public.contract_inspections where id=nullif(p_payload->>'inspection_id','')::uuid and company_id=v_company for update;
  if not found then raise exception 'INSPECTION_NOT_FOUND' using errcode='42501'; end if;
  if v_record.review_request_id=v_request then return to_jsonb(v_record); end if;
  if v_record.status<>'COMPLETED' or v_request is null then raise exception 'INSPECTION_NOT_REVIEWABLE' using errcode='22023'; end if;
  if v_record.completed_by=v_actor then raise exception 'INSPECTION_SELF_REVIEW_FORBIDDEN' using errcode='42501'; end if;
  v_old:=v_record.status;
  if v_action='APPROVE' then
    update public.contract_inspections set status='REVIEWED',review_request_id=v_request,reviewed_by=v_actor,reviewed_at=now(),review_reason=null,updated_at=now()
      where id=v_record.id returning * into v_record;
  elsif v_action='REQUEST_CHANGES' then
    if nullif(btrim(p_payload->>'reason'),'') is null then raise exception 'INSPECTION_REVIEW_REASON_REQUIRED' using errcode='22023'; end if;
    update public.contract_inspections set status='CHANGES_REQUESTED',review_request_id=v_request,reviewed_by=v_actor,reviewed_at=now(),review_reason=btrim(p_payload->>'reason'),updated_at=now()
      where id=v_record.id returning * into v_record;
  else raise exception 'INSPECTION_REVIEW_ACTION_INVALID' using errcode='22023'; end if;
  insert into public.contract_evidence_events(company_id,contract_id,entity_type,entity_id,event_type,from_status,to_status,reason,payload,actor_id)
    values(v_company,v_record.contract_id,'INSPECTION',v_record.id,v_action,v_old,v_record.status,v_record.review_reason,jsonb_build_object('request_id',v_request),v_actor);
  return to_jsonb(v_record);
end;
$$;


ALTER FUNCTION "public"."review_contract_inspection_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_onboarding_waiver_atomic"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := public.require_company_id();
  v_actor   uuid := auth.uid();
  v_authority text := coalesce(public.current_app_role(), 'ADMIN');
  v_updated integer;
begin
  if v_actor is null or not public.is_admin() then
    raise exception 'ONBOARDING_WAIVER_ADMIN_REQUIRED' using errcode = '42501';
  end if;

  update public.company_onboarding_waivers
  set revoked_at = now(),
      revoked_by = v_actor
  where company_id = v_company
    and requirement_code = p_code
    and revoked_at is null;

  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    raise exception 'ONBOARDING_WAIVER_NOT_ACTIVE' using errcode = '22023';
  end if;

  insert into public.company_onboarding_events (
    company_id, requirement_code, action, actor, authority
  ) values (
    v_company, p_code, 'REVOKE', v_actor, v_authority
  );

  return jsonb_build_object('revoked', true, 'company_id', v_company, 'code', p_code);
end;
$$;


ALTER FUNCTION "public"."revoke_onboarding_waiver_atomic"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_permission_grant"("p_user_id" "uuid", "p_permission" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_company uuid := public.require_company_id(); v_grant_id uuid;
begin
  if not public.current_user_has_effective_app_permission('permission_requests.review') then raise exception 'Permission request review required' using errcode = '42501'; end if;
  if p_user_id=auth.uid() then raise exception 'Reviewer cannot revoke own grant' using errcode = '42501'; end if;
  if nullif(btrim(coalesce(p_reason,'')), '') is null then raise exception 'Revocation reason is required' using errcode = '22023'; end if;
  if not exists(select 1 from public.app_permission_catalog where permission=p_permission) then raise exception 'Unknown permission' using errcode = '22023'; end if;
  if not public.current_user_can_delegate_app_permission(p_permission) then raise exception 'Reviewer cannot revoke this permission' using errcode = '42501'; end if;
  update public.user_permission_grants set revoked_at=now() where company_id=v_company and user_id=p_user_id and permission=p_permission and revoked_at is null returning id into v_grant_id;
  if v_grant_id is not null then
    insert into public.audit_log(id,ts,user_id,action,entity,entity_id,note,"table",details,created_at) values(gen_random_uuid(),extract(epoch from now())::bigint,auth.uid(),'PERMISSION_REVOKED','permission_grant',v_grant_id::text,btrim(p_reason),'user_permission_grants',jsonb_build_object('user_id',p_user_id,'permission',p_permission,'company_id',v_company)::text,now());
    insert into public.app_notifications(id,company_id,recipient_user_id,created_at,is_read,type,title,message,link,source_type,source_id,notification_type) values(v_grant_id::text||':'||p_user_id::text||':revoked',v_company,p_user_id,now(),false,'permission_decision','تم إلغاء صلاحية',btrim(p_reason),'/settings?section=security','permission_grant',v_grant_id,'permission_revoked') on conflict(id) do nothing;
  end if;
  return jsonb_build_object('revoked', v_grant_id is not null);
end;
$$;


ALTER FUNCTION "public"."revoke_permission_grant"("p_user_id" "uuid", "p_permission" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."role_has_app_permission"("p_role" "text", "p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case upper(coalesce(p_role, ''))
    when 'ADMIN' then
      exists(select 1 from public.app_permission_catalog c where c.permission = p_permission)
    when 'MANAGER' then
      p_permission = any(array[
        'app.dashboard.view','maintenance.view','permission_requests.review','cost_centers.manage','documents.write',
        'owners.hub.view','owners.detail.view','lands.view','leads.view','commissions.view','communication.view',
        'automation.view','auth.password.change','properties.write','contracts.write','expenses.view','expenses.write',
        'arrears.view','financial.deposits.view','financial.invoices.generate','financial.invoices.export',
        'financial.payments.create','financial.receipts.void','financial.reports.export',
        'financial.bank_reconciliation.view','financial.bank_reconciliation.match','financial.owner_settlements.view',
        'service_providers.view','service_providers.write',
        'financial.fixed_monthly_accruals.view','financial.fixed_monthly_accruals.execute',
        'financial.fixed_monthly_accruals.reverse'
      ]::text[])
    when 'ACCOUNTANT' then
      p_permission = any(array[
        'app.dashboard.view','audit.view','expenses.view','arrears.view',
        'financial.deposits.view','financial.invoices.generate','financial.invoices.export',
        'financial.reports.export','financial.bank_reconciliation.view','financial.bank_reconciliation.match',
        'financial.owner_settlements.view','auth.password.change',
        'financial.fixed_monthly_accruals.view','financial.fixed_monthly_accruals.execute',
        'financial.fixed_monthly_accruals.reverse'
      ]::text[])
    when 'OPERATIONS' then
      p_permission = any(array[
        'app.dashboard.view','maintenance.view','service_providers.view','service_providers.write',
        'cost_centers.manage','documents.write','owners.hub.view','owners.detail.view','lands.view',
        'leads.view','communication.view','automation.view','auth.password.change','properties.write',
        'contracts.write','expenses.view','expenses.write','arrears.view'
      ]::text[])
    when 'USER' then
      p_permission = any(array['app.dashboard.view','auth.password.change']::text[])
    when 'VIEWER' then
      p_permission = any(array[
        'app.dashboard.view','maintenance.view','service_providers.view',
        'owners.hub.view','owners.detail.view','lands.view','leads.view','commissions.view',
        'communication.view','automation.view','expenses.view','arrears.view',
        'financial.deposits.view','financial.owner_settlements.view',
        'financial.bank_reconciliation.view','auth.password.change'
      ]::text[])
    else false
  end
$$;


ALTER FUNCTION "public"."role_has_app_permission"("p_role" "text", "p_permission" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."role_has_app_permission"("p_role" "text", "p_permission" "text") IS 'WP-01: six-role capability matrix. ADMIN is dynamic (all catalog permissions); other roles use explicit whitelists; unknown roles return false.';



CREATE OR REPLACE FUNCTION "public"."rpt_aged_receivables"("p_as_of" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_lines jsonb;
  v_totals jsonb;
  v_company_id uuid := public.require_company_id();
BEGIN
  WITH aged AS (
    SELECT t.id tenant_id, t.full_name tenant_name, t.phone tenant_phone,
      pr.title property_name, u.unit_number unit_name,
      public._r3(i.amount + COALESCE(i.tax_amount, 0) - i.paid_amount - COALESCE(i.credited_amount, 0)) remaining,
      (p_as_of - i.due_date)::int days_overdue
    FROM public.invoices i
    JOIN public.contracts c ON c.id::text = i.contract_id::text AND c.deleted_at IS NULL
    JOIN public.people t ON t.id::text = c.tenant_id::text AND t.type = 'tenant' AND t.deleted_at IS NULL
    JOIN public.units u ON u.id::text = c.unit_id::text AND u.deleted_at IS NULL
    JOIN public.properties pr ON pr.id::text = c.property_id::text AND pr.deleted_at IS NULL
    WHERE upper(COALESCE(i.status, '')) NOT IN ('PAID', 'VOID', 'CANCELLED')
      AND i.deleted_at IS NULL
      AND i.company_id = v_company_id
      AND i.due_date <= p_as_of
      AND (i.amount + COALESCE(i.tax_amount, 0) - i.paid_amount - COALESCE(i.credited_amount, 0)) > 0.001
  ), bucketed AS (
    SELECT tenant_id, tenant_name, tenant_phone, property_name, unit_name,
      public._r3(sum(remaining)) total,
      public._r3(sum(CASE WHEN days_overdue <= 0 THEN remaining ELSE 0 END)) bucket_current,
      public._r3(sum(CASE WHEN days_overdue BETWEEN 1 AND 30 THEN remaining ELSE 0 END)) bucket_1_30,
      public._r3(sum(CASE WHEN days_overdue BETWEEN 31 AND 60 THEN remaining ELSE 0 END)) bucket_31_60,
      public._r3(sum(CASE WHEN days_overdue BETWEEN 61 AND 90 THEN remaining ELSE 0 END)) bucket_61_90,
      public._r3(sum(CASE WHEN days_overdue > 90 THEN remaining ELSE 0 END)) bucket_90plus
    FROM aged
    GROUP BY tenant_id, tenant_name, tenant_phone, property_name, unit_name
    HAVING sum(remaining) > 0
  )
  SELECT jsonb_agg(jsonb_build_object(
      'tenant_id', tenant_id, 'tenant_name', tenant_name, 'tenant_phone', tenant_phone,
      'property_name', property_name, 'unit_name', unit_name, 'total', total,
      'current', bucket_current, '1_30', bucket_1_30, '31_60', bucket_31_60,
      '61_90', bucket_61_90, '90plus', bucket_90plus) ORDER BY total DESC),
    jsonb_build_object('total', public._r3(sum(total)), 'current', public._r3(sum(bucket_current)),
      '1_30', public._r3(sum(bucket_1_30)), '31_60', public._r3(sum(bucket_31_60)),
      '61_90', public._r3(sum(bucket_61_90)), '90plus', public._r3(sum(bucket_90plus)))
  INTO v_lines, v_totals FROM bucketed;

  RETURN jsonb_build_object(
    'lines', COALESCE(v_lines, '[]'::jsonb),
    'totals', COALESCE(v_totals, '{"total":0,"current":0,"1_30":0,"31_60":0,"61_90":0,"90plus":0}'::jsonb),
    'as_of', p_as_of);
END;
$$;


ALTER FUNCTION "public"."rpt_aged_receivables"("p_as_of" "date") OWNER TO "postgres";


