CREATE OR REPLACE FUNCTION "public"."rpt_overdue_invoices"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rows jsonb;
  v_total numeric;
  v_count bigint;
  v_company_id uuid := public.require_company_id();
begin
  select jsonb_agg(jsonb_build_object(
      'invoice_id', i.id, 'invoice_no', i.no, 'due_date', i.due_date,
      'days_overdue', (p_as_of - i.due_date)::int,
      'amount', public._r3(i.amount + COALESCE(i.tax_amount, 0)),
      'paid', public._r3(i.paid_amount),
      'credited', public._r3(COALESCE(i.credited_amount, 0)),
      'remaining', public._r3(i.amount + COALESCE(i.tax_amount, 0) - i.paid_amount - COALESCE(i.credited_amount, 0)),
      'tenant_name', t.full_name, 'tenant_phone', t.phone,
      'unit_name', u.unit_number, 'property_name', pr.title, 'contract_id', c.id)
      ORDER BY (p_as_of - i.due_date) DESC),
    public._r3(sum(i.amount + COALESCE(i.tax_amount, 0) - i.paid_amount - COALESCE(i.credited_amount, 0))), count(*)
  into v_rows, v_total, v_count
  FROM public.invoices i
  JOIN public.contracts c ON c.id::text = i.contract_id::text AND c.deleted_at IS NULL
  JOIN public.people t ON t.id::text = c.tenant_id::text AND t.type = 'tenant' AND t.deleted_at IS NULL
  JOIN public.units u ON u.id::text = c.unit_id::text AND u.deleted_at IS NULL
  JOIN public.properties pr ON pr.id::text = c.property_id::text AND pr.deleted_at IS NULL
  WHERE upper(COALESCE(i.status, '')) NOT IN ('PAID', 'VOID', 'CANCELLED')
    AND i.deleted_at IS NULL
    AND i.company_id = v_company_id
    AND i.due_date < p_as_of
    AND (i.amount + COALESCE(i.tax_amount, 0) - i.paid_amount - COALESCE(i.credited_amount, 0)) > 0.001;

  return jsonb_build_object(
    'rows', COALESCE(v_rows, '[]'::jsonb),
    'total_overdue', COALESCE(v_total, 0),
    'count', COALESCE(v_count, 0),
    'as_of', p_as_of
  );
end;
$$;


ALTER FUNCTION "public"."rpt_overdue_invoices"("p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpt_owner_financial_position"("p_owner_id" "uuid", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_period record;
  v_settlements jsonb;
  v_funds jsonb;
  v_settled_net numeric := 0;
  v_paid_net numeric := 0;
  v_remaining numeric := 0;
  v_draft_count bigint := 0;
  v_approved_count bigint := 0;
  v_paid_count bigint := 0;
  v_cancelled_count bigint := 0;
  v_funds_held numeric := 0;
begin
  if auth.uid() is null or not coalesce(public.is_app_user(), false) then
    raise exception 'Authenticated app user is required.' using errcode = '42501';
  end if;

  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'A valid position period is required.' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.owners o
    where o.id = p_owner_id and o.company_id = v_company_id and o.deleted_at is null
  ) then
    raise exception 'Position target owner is not in your company.' using errcode = '42501';
  end if;

  -- ── Period derivation: EXACTLY the settlement write-path authority. ───────
  select * into v_period
  from public.calculate_owner_net_payout(p_owner_id, p_from, p_to, null);

  -- ── All-time settlement lifecycle aggregates + bounded drill-down rows. ───
  -- CONTRACT (R13): this section is intentionally ALL-TIME — an outstanding
  -- DRAFT/APPROVED settlement from a prior period is still payable to the
  -- owner, and paid history is lifetime history. It is never scoped to
  -- p_from/p_to, and the key lifecycle_all_time makes that explicit.
  select
    coalesce(sum(s.net_payable) filter (where upper(coalesce(s.status, '')) in ('DRAFT', 'APPROVED')), 0),
    coalesce(sum(s.net_payable) filter (where upper(coalesce(s.status, '')) = 'PAID'), 0),
    count(*) filter (where upper(coalesce(s.status, '')) = 'DRAFT'),
    count(*) filter (where upper(coalesce(s.status, '')) = 'APPROVED'),
    count(*) filter (where upper(coalesce(s.status, '')) = 'PAID'),
    count(*) filter (where upper(coalesce(s.status, '')) = 'CANCELLED')
  into v_settled_net, v_paid_net, v_draft_count, v_approved_count, v_paid_count, v_cancelled_count
  from public.owner_settlements s
  where s.company_id = v_company_id
    and s.owner_id::text = p_owner_id::text;

  v_remaining := public._r3(v_settled_net);

  select coalesce(jsonb_agg(row_data order by created_at desc), '[]'::jsonb)
  into v_settlements
  from (
    select
      jsonb_build_object(
        'id', s.id,
        'reference', s.no,
        'property_id', s.property_id,
        'period_start', s.period_start,
        'period_end', s.period_end,
        'gross_collected', public._r3(coalesce(s.gross_collected, 0)),
        'management_fee', public._r3(coalesce(s.office_fee, 0)),
        'owner_expenses', public._r3(coalesce(s.owner_expenses, 0)),
        'fee_vat', public._r3(coalesce(s.tax_amount, 0)),
        'net_payable', public._r3(coalesce(s.net_payable, 0)),
        'status', upper(coalesce(s.status, 'DRAFT')),
        'approved_at', s.approved_at,
        'paid_at', s.paid_at,
        'payment_reference', s.payment_reference,
        'cancelled_at', s.cancelled_at,
        'cancellation_reason', s.cancellation_reason
      ) as row_data,
      s.created_at
    from public.owner_settlements s
    where s.company_id = v_company_id
      and s.owner_id::text = p_owner_id::text
    order by s.created_at desc
    limit 24
  ) recent;

  -- ── Owner funds held: RC1 append-only control (0 when no events exist). ───
  select coalesce(sum(e.amount_delta), 0)
  into v_funds_held
  from public.owner_funds_events e
  where e.company_id = v_company_id
    and e.owner_id = p_owner_id;

  select coalesce(jsonb_agg(row_data order by effective_date desc), '[]'::jsonb)
  into v_funds
  from (
    select
      jsonb_build_object(
        'id', e.id,
        'source_type', e.source_type,
        'source_id', e.source_id,
        'amount_delta', public._r3(e.amount_delta),
        'effective_date', e.effective_date,
        'journal_batch_id', e.journal_batch_id
      ) as row_data,
      e.effective_date
    from public.owner_funds_events e
    where e.company_id = v_company_id
      and e.owner_id = p_owner_id
    order by e.effective_date desc, e.created_at desc
    limit 24
  ) recent_events;

  return jsonb_build_object(
    'meta', jsonb_build_object(
      'owner_id', p_owner_id,
      'from', p_from,
      'to', p_to,
      'source', 'rpt_owner_financial_position',
      'derivation_authority', 'calculate_owner_net_payout (ADR 0001)'
    ),
    'period', jsonb_build_object(
      'tenant_collections', public._r3(coalesce(v_period.gross_collected, 0)),
      'management_fees', jsonb_build_object(
        'amount', public._r3(coalesce(v_period.office_fee, 0)),
        'breakdown', coalesce(v_period.breakdown, '{}'::jsonb)
      ),
      'owner_expenses', public._r3(coalesce(v_period.owner_expenses, 0)),
      'fee_vat', public._r3(coalesce(v_period.tax_amount, 0)),
      'authorized_adjustments', 0,
      'adjustments_note', 'no_adjustments_authority_defined',
      'net_payable', public._r3(coalesce(v_period.net_payable, 0))
    ),
    'lifecycle_all_time', jsonb_build_object(
      'settled_pending_net', public._r3(v_settled_net),
      'paid_net', public._r3(v_paid_net),
      'remaining_payable', v_remaining,
      'draft_count', v_draft_count,
      'approved_count', v_approved_count,
      'paid_count', v_paid_count,
      'cancelled_count', v_cancelled_count
    ),
    'owner_funds', jsonb_build_object(
      'held', public._r3(v_funds_held),
      'events', v_funds
    ),
    'settlements', v_settlements
  );
end;
$$;


ALTER FUNCTION "public"."rpt_owner_financial_position"("p_owner_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rpt_owner_financial_position"("p_owner_id" "uuid", "p_from" "date", "p_to" "date") IS 'R13 Owner Financial Position: "period" is period-scoped economics (calculate_owner_net_payout); "lifecycle_all_time" is the lifetime settlement position (settled/paid/remaining/counts) — the scope distinction is explicit so period truth and lifetime truth are never conflated.';



CREATE OR REPLACE FUNCTION "public"."rpt_owner_statement"("p_owner_id" "uuid", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner_name text;
  v_commission_type text;
  v_commission_value numeric := 0;
  v_transactions jsonb;
  v_total_gross numeric := 0;
  v_total_deductions numeric := 0;
  v_total_net numeric := 0;
  v_company_id uuid := public.require_company_id();
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_app_user() THEN
    RAISE EXCEPTION 'Authentication is required' USING ERRCODE = '42501';
  END IF;
  IF p_from > p_to THEN RAISE EXCEPTION 'Invalid owner statement period'; END IF;

  SELECT COALESCE(NULLIF(btrim(display_name), ''), NULLIF(btrim(full_name), ''), name)
    INTO v_owner_name
  FROM public.owners WHERE id = p_owner_id AND company_id = v_company_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'owner not found'); END IF;

  SELECT oa.commission_type, oa.commission_value
    INTO v_commission_type, v_commission_value
  FROM public.owner_agreements oa
  WHERE oa.owner_id = p_owner_id
    AND oa.company_id = v_company_id
    AND oa.starts_on <= p_to
    AND (oa.ends_on IS NULL OR oa.ends_on >= p_from)
  ORDER BY oa.starts_on DESC LIMIT 1;

  WITH owner_contracts AS (
    SELECT c.id contract_id, c.property_id, u.unit_number unit_name, pr.title property_name,
      oa.commission_type, oa.commission_value
    FROM public.contracts c
    JOIN public.owner_agreements oa ON oa.id = c.agreement_id AND oa.owner_id = p_owner_id
    LEFT JOIN public.units u ON u.id = c.unit_id
    JOIN public.properties pr ON pr.id = c.property_id
    WHERE c.deleted_at IS NULL AND c.company_id = v_company_id
  ), payment_rows AS (
    SELECT COALESCE(p.payment_date::text, p.date_time::text) tx_date,
      'تحصيل — ' || oc.property_name || ' / ' || COALESCE(oc.unit_name, '—') ||
        ' (' || COALESCE(p.reference_number, p.reference_no, p.id::text) || ')' details,
      'payment' tx_type, oc.property_name, p.amount gross,
      CASE WHEN oc.commission_type = 'RATE'
        THEN public._r3(p.amount * oc.commission_value / 100) ELSE 0 END deduction,
      p.id::text sort_no
    FROM public.payments p
    JOIN owner_contracts oc ON oc.contract_id = p.contract_id
    WHERE p.deleted_at IS NULL AND p.company_id = v_company_id AND upper(COALESCE(p.status, '')) <> 'VOID'
      AND COALESCE(p.payment_date, public._safe_date(p.date_time::text)) BETWEEN p_from AND p_to
  ), expense_rows AS (
    SELECT * FROM public._owner_statement_expenses(p_owner_id, p_from, p_to)
  ), settlement_rows AS (
    SELECT s.date tx_date, 'تسوية مالية رقم ' || s.no details,
      'settlement' tx_type, '' property_name, -s.amount gross,
      0::numeric deduction, COALESCE(s.no, s.id) sort_no
    FROM public.owner_settlements s
    WHERE s.owner_id::text = p_owner_id::text AND s.company_id = v_company_id AND public._safe_date(s.date) BETWEEN p_from AND p_to
  ), all_tx AS (
    SELECT * FROM payment_rows UNION ALL SELECT * FROM expense_rows UNION ALL SELECT * FROM settlement_rows
  )
  SELECT jsonb_agg(jsonb_build_object(
      'date', tx_date, 'details', details, 'type', tx_type,
      'property_name', property_name, 'gross', public._r3(gross),
      'deduction', public._r3(deduction), 'net', public._r3(gross - deduction))
      ORDER BY tx_date, sort_no),
    public._r3(sum(gross)), public._r3(sum(deduction)), public._r3(sum(gross - deduction))
  INTO v_transactions, v_total_gross, v_total_deductions, v_total_net FROM all_tx;

  RETURN jsonb_build_object(
    'owner_name', v_owner_name, 'commission_type', v_commission_type,
    'commission_value', COALESCE(v_commission_value, 0),
    'transactions', COALESCE(v_transactions, '[]'::jsonb),
    'total_gross', COALESCE(v_total_gross, 0),
    'total_deductions', COALESCE(v_total_deductions, 0),
    'total_net', COALESCE(v_total_net, 0),
    'period_from', p_from, 'period_to', p_to);
END;
$$;


ALTER FUNCTION "public"."rpt_owner_statement"("p_owner_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpt_rc1_owner_agency_invoice_mapping_diagnostics"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("company_id" "uuid", "invoice_id" "uuid", "contract_id" "text", "issue_date" "date", "collection_role" "text", "invoice_accounting_classification" "text", "source_batch_id" "uuid", "source_type" "text", "source_account_numbers" "text"[], "affected_reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
begin
  if auth.uid() is null
     or not (coalesce(public.is_admin_or_manager(), false) or coalesce(public.is_accountant(), false)) then
    raise exception 'RC1_INVOICE_DIAGNOSTIC_ROLE_REQUIRED' using errcode = '42501';
  end if;

  return query
  select
    i.company_id,
    i.id,
    i.contract_id::text,
    i.issue_date,
    c.collection_role_snapshot,
    i.invoice_accounting_classification,
    b.id,
    b.source_type,
    coalesce(array_agg(distinct a.no order by a.no) filter (where a.no is not null), '{}'::text[]),
    case
      when bool_or(a.no = '4000') then 'OWNER_AGENCY_RENT_CREDITED_TO_4000_REVIEW_REQUIRED'
      when c.operating_model_snapshot is null then 'PRE_RC1_OWNER_AGENCY_SNAPSHOT_MISSING_REVIEW_REQUIRED'
      when i.invoice_accounting_classification is null then 'PRE_RC1_INVOICE_LINEAGE_UNCLASSIFIED_REVIEW_REQUIRED'
      else 'NO_RC1_MAPPING_ANOMALY'
    end
  from public.invoices i
  join public.contracts c
    on c.id = i.contract_id
   and c.company_id = i.company_id
  left join public.owner_agreements oa
    on oa.id = c.agreement_id
   and oa.company_id = c.company_id
  left join lateral (
    select jb.*
      from public.journal_batches jb
     where jb.company_id = i.company_id
       and jb.source_type = 'invoice'
       and jb.source_id = i.id::text
     order by jb.created_at asc, jb.id
     limit 1
  ) b on true
  left join public.journal_lines jl
    on jl.batch_id = b.id
   and jl.company_id = i.company_id
  left join public.accounts a
    on a.id = jl.account_id
   and a.company_id = i.company_id
  where i.company_id = v_company_id
    and (
      c.operating_model_snapshot = 'OWNER_AGENCY'
      or (c.operating_model_snapshot is null and oa.agreement_type = 'property_management')
    )
    and (p_from is null or i.issue_date >= p_from)
    and (p_to is null or i.issue_date <= p_to)
    and (
      i.invoice_accounting_classification is null
      or exists (
        select 1
          from public.journal_lines xjl
          join public.accounts xa on xa.id = xjl.account_id and xa.company_id = i.company_id
         where xjl.batch_id = b.id
           and xjl.company_id = i.company_id
           and xa.no = '4000'
      )
    )
  group by i.company_id, i.id, i.contract_id, i.issue_date,
           c.collection_role_snapshot, c.operating_model_snapshot, i.invoice_accounting_classification,
           b.id, b.source_type
  order by i.issue_date, i.id;
end;
$$;


ALTER FUNCTION "public"."rpt_rc1_owner_agency_invoice_mapping_diagnostics"("p_from" "date", "p_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rpt_rc1_owner_agency_invoice_mapping_diagnostics"("p_from" "date", "p_to" "date") IS 'Read-only RC1 historical diagnostic for owner-agency invoice source batches that used 4000 or lack immutable RC1 classification. Review via S08; no automatic correction.';



CREATE OR REPLACE FUNCTION "public"."rpt_rent_roll"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE 
  v_rows jsonb;
  v_company_id uuid := public.require_company_id();
BEGIN
  SELECT jsonb_agg(jsonb_build_object(
    'property_name', pr.title, 'unit_name', u.unit_number, 'unit_type', coalesce(u.name, 'Apartment'),
    'status', u.status, 'tenant_name', t.full_name, 'tenant_phone', t.phone,
    'contract_start', c.start_date, 'contract_end', c.end_date,
    'rent_amount', c.rent_amount, 
    'deposit', public._r3(coalesce((
       select sum(remaining_amount) from public.tenant_deposits d 
       where d.contract_id::text = c.id::text and d.deleted_at is null and d.company_id = v_company_id
    ), 0)),
    'days_to_expiry', (c.end_date - p_as_of)::int,
    'overdue_balance', public._r3(COALESCE((
      SELECT sum(i.amount + COALESCE(i.tax_amount, 0) - i.paid_amount)
      FROM public.invoices i
      WHERE i.contract_id::text = c.id::text AND i.deleted_at IS NULL
        AND i.company_id = v_company_id
        AND upper(COALESCE(i.status, '')) NOT IN ('PAID', 'VOID', 'CANCELLED')
        AND i.due_date < p_as_of
    ), 0))) ORDER BY pr.title, u.unit_number)
  INTO v_rows
  FROM public.units u
  JOIN public.properties pr ON pr.id::text = u.property_id::text AND pr.deleted_at IS NULL
  LEFT JOIN public.contracts c ON c.unit_id::text = u.id::text
    AND lower(COALESCE(c.status, '')) = 'active'
    AND c.deleted_at IS NULL
    AND c.start_date <= p_as_of
    AND c.end_date >= p_as_of
  LEFT JOIN public.people t ON t.id::text = c.tenant_id::text AND t.type = 'tenant' AND t.deleted_at IS NULL
  WHERE u.deleted_at IS NULL
    AND u.company_id = v_company_id;

  RETURN jsonb_build_object('rows', COALESCE(v_rows, '[]'::jsonb), 'as_of', p_as_of);
END;
$$;


ALTER FUNCTION "public"."rpt_rent_roll"("p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpt_tenant_statement"("p_contract_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE 
  v_contract record; 
  v_lines jsonb; 
  v_balance numeric;
  v_company_id uuid := public.require_company_id();
BEGIN
  -- Select contract with correct title field from properties
  SELECT c.*, t.full_name as tenant_name, t.phone as tenant_phone,
    u.name as unit_name, pr.title as property_name
  INTO v_contract 
  FROM public.contracts c
  JOIN public.people t ON t.id::text = c.tenant_id::text AND t.deleted_at IS NULL
  JOIN public.units u ON u.id::text = c.unit_id::text AND u.deleted_at IS NULL
  JOIN public.properties pr ON pr.id::text = u.property_id::text AND pr.deleted_at IS NULL 
  WHERE c.id::text = p_contract_id::text
    AND c.company_id = v_company_id;
    
  IF NOT FOUND THEN 
    RETURN jsonb_build_object('error', 'contract not found'); 
  END IF;

  WITH tx AS (
    SELECT i.due_date::text as tx_date,
      'فاتورة رقم '||coalesce(nullif(i.no, ''), i.id::text) as description,
      'invoice' as tx_type, i.amount+coalesce(i.tax_amount,0) as debit, 0 as credit, coalesce(nullif(i.no, ''), i.id::text) as ref_no
    FROM public.invoices i 
    WHERE i.contract_id::text = p_contract_id::text 
      AND i.deleted_at IS NULL
      AND i.company_id = v_company_id
      AND upper(coalesce(i.status, '')) NOT IN ('VOID', 'CANCELLED')
    UNION ALL
    SELECT coalesce(p.payment_date, public._safe_date(p.created_at::text))::text as tx_date,
      'سند قبض رقم '||coalesce(r.no, p.id::text)||coalesce(' — '||p.payment_method, '') as description,
      'receipt' as tx_type, 0 as debit, p.amount as credit, coalesce(r.no, p.id::text) as ref_no
    FROM public.payments p
    LEFT JOIN public.receipts r on r.id::text = p.receipt_id::text and r.deleted_at is null
    WHERE p.contract_id::text = p_contract_id::text
      AND p.deleted_at is null
      AND upper(coalesce(p.status, '')) = 'POSTED'
      AND p.company_id = v_company_id
  ),
  with_balance AS (
    SELECT tx_date, description, tx_type, debit, credit, ref_no,
      SUM(debit-credit) OVER (ORDER BY tx_date, ref_no ROWS UNBOUNDED PRECEDING) as running_balance 
    FROM tx
  )
  SELECT jsonb_agg(jsonb_build_object(
    'date', tx_date,
    'description', description,
    'type', tx_type,
    'debit', public._r3(debit),
    'credit', public._r3(credit),
    'balance', public._r3(running_balance)
  ) ORDER BY tx_date, ref_no),
    public._r3(SUM(debit-credit)) 
  INTO v_lines, v_balance 
  FROM with_balance;

  RETURN jsonb_build_object(
    'contract_id', p_contract_id,
    'tenant_name', v_contract.tenant_name,
    'tenant_phone', v_contract.tenant_phone,
    'unit_name', v_contract.unit_name,
    'property_name', v_contract.property_name,
    'start_date', v_contract.start_date,
    'end_date', v_contract.end_date,
    'lines', COALESCE(v_lines, '[]'::jsonb),
    'final_balance', COALESCE(v_balance, 0)
  );
END;
$$;


ALTER FUNCTION "public"."rpt_tenant_statement"("p_contract_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpt_trial_balance"("p_as_of" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  return public.wp05_rpt_trial_balance_gl(p_as_of);
end;
$$;


