CREATE OR REPLACE FUNCTION "public"."rpt_vat_return"("p_from_date" "date", "p_to_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_company_id uuid := public.require_company_id();
BEGIN
  -- FIX: Added COALESCE(UPPER(status), '') NOT IN ('VOID', 'CANCELLED') filter
  SELECT jsonb_build_object(
    'period', jsonb_build_object('from', p_from_date, 'to', p_to_date),
    'total_sales_amount', COALESCE(SUM(amount), 0),
    'total_tax_amount', COALESCE(SUM(tax_amount), 0),
    'invoice_count', COUNT(*)
  ) INTO v_result
  FROM public.invoices
  WHERE issue_date BETWEEN p_from_date AND p_to_date
    AND company_id = v_company_id
    AND deleted_at IS NULL
    AND COALESCE(UPPER(status), '') NOT IN ('VOID', 'CANCELLED');

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."rpt_vat_return"("p_from_date" "date", "p_to_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_scheduled_automation_rules"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rule record;
  v_results jsonb := '[]'::jsonb;
  v_single_result jsonb;
  v_processed_count int := 0;
  v_company_id uuid := null;
begin
  if auth.uid() is not null then
    if not exists (
      select 1 from public.users u
      where u.id = auth.uid() and u.role in ('ADMIN', 'MANAGER')
    ) then
      raise exception 'غير مصرح: هذه العملية متاحة فقط للمدير أو المسؤول' using errcode = '42501';
    end if;
    v_company_id := public.require_company_id();
  end if;

  for v_rule in
    select id
    from public.automation_rules
    where deleted_at is null
      and is_enabled = true
      and (v_company_id is null or company_id = v_company_id)
  loop
    if exists (
      select 1
      from public.automation_rules r
      where r.id = v_rule.id
        and (v_company_id is null or r.company_id = v_company_id)
        and (
          r.last_run_at is null
          or (r.schedule_interval_hours is not null and r.last_run_at < now() - (r.schedule_interval_hours || ' hours')::interval)
          or (r.schedule_interval_hours is null and r.last_run_at < now() - interval '1 hour')
        )
    ) then
      v_single_result := public.execute_automation_rule_internal(v_rule.id);
      v_results := v_results || jsonb_build_array(v_single_result);
      v_processed_count := v_processed_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'success', true,
    'processed_rules', v_processed_count,
    'results', v_results
  );
end;
$$;


ALTER FUNCTION "public"."run_scheduled_automation_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_analyze_deposit_exceptions"("p_company_id" "uuid", "p_period_id" "uuid") RETURNS TABLE("company_id" "uuid", "tenant_id" "text", "contract_id" "uuid", "property_id" "uuid", "deposit_id" "text", "transaction_id" "uuid", "beneficiary" "text", "claim_reference" "text", "period" "text", "amount" numeric, "available_balance" numeric, "exception_code" "text", "severity" "text", "explanation" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_caller uuid;
begin
  if p_company_id is null or p_period_id is null then
    raise exception 'S08_COMPANY_AND_PERIOD_REQUIRED' using errcode='22023';
  end if;
  v_caller := public.current_company_id();
  if v_caller is not null and v_caller <> p_company_id and current_user <> 'service_role' then
    raise exception 'S08_COMPANY_ISOLATION_VIOLATION' using errcode='42501';
  end if;
  return query
  select
    td.company_id,
    td.tenant_id::text as tenant_id,
    td.contract_id::uuid as contract_id,
    td.property_id::uuid as property_id,
    td.id::text as deposit_id,
    dt.id::uuid as transaction_id,
    coalesce(dt.reason,'')::text as beneficiary,
    coalesce(dt.request_id,'')::text as claim_reference,
    ap.name::text as period,
    public.s08_round_egp(dt.amount)::numeric as amount,
    public.s08_round_egp(td.remaining_amount)::numeric as available_balance,
    case
      when dt.reason is null then 'DEDUCTION_WITHOUT_BENEFICIARY'
      when dt.request_id is null then 'DEDUCTION_WITHOUT_APPROVED_CLAIM'
      when dt.amount > td.deposit_amount then 'REFUND_EXCEEDING_AVAILABLE_BALANCE'
      when dt.type = 'refund' and td.remaining_amount < 0 then 'DEPOSIT_SUBLEDGER_GL_MISMATCH'
      else 'DEPOSIT_ORPHAN_TRANSACTION'
    end::text as exception_code,
    'HIGH'::text as severity,
    'Deposit exception covering receipts/refunds/applications/deductions/reversals.'::text as explanation
  from public.tenant_deposits td
  join public.accounting_periods ap on ap.id = p_period_id and ap.company_id = p_company_id
  left join public.deposit_transactions dt on dt.deposit_id = td.id and dt.company_id = p_company_id
  where td.company_id = p_company_id
    and td.deleted_at is null
    and (
      dt.reason is null
      or dt.request_id is null
      or dt.amount > td.deposit_amount
      or (dt.type = 'deduction' and coalesce(td.remaining_amount,0) < 0)
    );
end;
$$;


ALTER FUNCTION "public"."s08_analyze_deposit_exceptions"("p_company_id" "uuid", "p_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_analyze_expense_misclassification"("p_company_id" "uuid", "p_period_id" "uuid") RETURNS TABLE("company_id" "uuid", "expense_id" "uuid", "charged_to" "text", "beneficiary" "text", "account_no" "text", "account_name" "text", "amount" numeric, "period" "text", "finding_code" "text", "severity" "text", "explanation" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_caller uuid;
begin
  if p_company_id is null or p_period_id is null then
    raise exception 'S08_COMPANY_AND_PERIOD_REQUIRED' using errcode='22023';
  end if;
  v_caller := public.current_company_id();
  if v_caller is not null and v_caller <> p_company_id and current_user <> 'service_role' then
    raise exception 'S08_COMPANY_ISOLATION_VIOLATION' using errcode='42501';
  end if;
  return query
  select
    exp.company_id,
    exp.id as expense_id,
    coalesce(exp.category::text, 'unknown')::text as charged_to,
    ''::text as beneficiary,
    coalesce(acc.no,'')::text as account_no,
    coalesce(acc.name,'')::text as account_name,
    public.s08_round_egp(exp.amount)::numeric as amount,
    ap.name::text as period,
    case
      when exp.category in ('OWNER','TENANT') and acc.no = '6100' then 'OWNER_TENANT_EXPENSE_IN_OFFICE_ACCOUNT'
      when exists (select 1 from public.journal_lines jl2 join public.journal_batches jb2 on jb2.id=jl2.batch_id where jl2.account_id=acc.id and jl2.company_id=p_company_id and jb2.status='POSTED' group by jl2.id having count(*)>1)
        then 'DUPLICATE_TENANT_RECEIVABLE'
      when exp.property_id is null then 'MISSING_PROPERTY_AGREEMENT_LINKAGE'
      else 'CHARGED_TO_BENEFICIARY_MISMATCH'
    end::text as finding_code,
    'MEDIUM'::text as severity,
    'Expense misclassification or linkage mismatch; 6100 only flagged if account 6100 exists and is office expense.'::text as explanation
  from public.expenses exp
  join public.accounting_periods ap on ap.id = p_period_id and ap.company_id = p_company_id
  -- Expense IDs are UUIDs, whereas Stage 3 journal source IDs are text.
  -- The explicit UUID-to-text conversion is at the source-reference boundary;
  -- account IDs remain in their canonical text domain.
  left join public.journal_batches jb on jb.company_id = p_company_id
    and lower(jb.source_type) in ('expense', 'expenses')
    and jb.source_id = exp.id::text
  left join public.journal_lines jl on jl.company_id = p_company_id and jl.batch_id = jb.id
  left join public.accounts acc on acc.company_id = p_company_id and acc.id = jl.account_id
  where exp.company_id = p_company_id
    and exp.deleted_at is null
    and (
      (exp.category in ('OWNER','TENANT') and acc.no = '6100' and exists (select 1 from public.accounts a2 where a2.company_id=p_company_id and a2.no='6100'))
      or exp.property_id is null
    );
end;
$$;


ALTER FUNCTION "public"."s08_analyze_expense_misclassification"("p_company_id" "uuid", "p_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_analyze_frozen_review"("p_review_id" "uuid", "p_analysis_results" "jsonb" DEFAULT NULL::"jsonb", "p_reconciliation_evidence" "jsonb" DEFAULT NULL::"jsonb", "p_exceptions" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_review public.s08_frozen_reviews%rowtype;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER required for S08 analysis' using errcode='42501';
  end if;

  if p_review_id is null then
    raise exception 'S08_REVIEW_ID_REQUIRED' using errcode='22023';
  end if;

  select * into v_review from public.s08_frozen_reviews where id = p_review_id and company_id = v_company_id for update;
  if not found then
    raise exception 'S08_REVIEW_NOT_FOUND: review % not found for company %', p_review_id, v_company_id using errcode='P0002';
  end if;

  if v_review.reviewer_decision <> 'CREATED' then
    raise exception 'S08_REVIEW_LIFECYCLE_ILLEGAL: only CREATED can transition to ANALYZED, current %', v_review.reviewer_decision using errcode='23514';
  end if;

  perform set_config('malik.s08_review_change_authorized', 'true', true);

  update public.s08_frozen_reviews
  set analysis_results = coalesce(p_analysis_results, analysis_results),
      reconciliation_evidence = coalesce(p_reconciliation_evidence, reconciliation_evidence),
      exceptions = coalesce(p_exceptions, exceptions),
      reviewer_decision = 'ANALYZED',
      updated_at = now()
  where id = p_review_id;

  perform set_config('malik.s08_review_change_authorized', 'false', true);

  return jsonb_build_object('success', true, 'id', p_review_id, 'status', 'ANALYZED');
end;
$$;


ALTER FUNCTION "public"."s08_analyze_frozen_review"("p_review_id" "uuid", "p_analysis_results" "jsonb", "p_reconciliation_evidence" "jsonb", "p_exceptions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_analyze_settlement_duplicates"("p_company_id" "uuid", "p_period_id" "uuid") RETURNS TABLE("company_id" "uuid", "company_name" "text", "owner_id" "uuid", "owner_name" "text", "property_id" "uuid", "property_name" "text", "agreement_id" "uuid", "settlement_id" "uuid", "settlement_status" "text", "accounting_period" "text", "source_type" "text", "source_id" "text", "source_date" "date", "source_amount" numeric, "currency" "text", "finding_code" "text", "severity" "text", "explanation" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_caller uuid;
begin
  if p_company_id is null or p_period_id is null then
    raise exception 'S08_COMPANY_AND_PERIOD_REQUIRED' using errcode='22023';
  end if;
  v_caller := public.current_company_id();
  -- service_role/auth with null caller allowed for staging; otherwise enforce
  if v_caller is not null and v_caller <> p_company_id and current_user <> 'service_role' then
    raise exception 'S08_COMPANY_ISOLATION_VIOLATION' using errcode='42501';
  end if;
  return query
  with dup_pay as (
    select l.payment_id as source_id, count(distinct l.settlement_id) as cnt
    from public.owner_settlement_payment_links l
    where l.company_id = p_company_id
    group by l.payment_id
    having count(distinct l.settlement_id) > 1
  ),
  dup_exp as (
    select l.expense_id as source_id, count(distinct l.settlement_id) as cnt
    from public.owner_settlement_expense_links l
    where l.company_id = p_company_id
    group by l.expense_id
    having count(distinct l.settlement_id) > 1
  )
  select
    os.company_id,
    coalesce(comp.name,'')::text as company_name,
    null::uuid as owner_id,
    ''::text as owner_name,
    null::uuid as property_id,
    ''::text as property_name,
    null::uuid as agreement_id,
    os.id::uuid as settlement_id,
    upper(coalesce(os.status::text,'DRAFT'))::text as settlement_status,
    ap.name::text as accounting_period,
    'PAYMENT'::text as source_type,
    dp.source_id::text as source_id,
    pay.payment_date::date as source_date,
    public.s08_round_egp(pay.amount)::numeric as source_amount,
    'EGP'::text as currency,
    'DUPLICATE_PAYMENT_ACROSS_SETTLEMENTS'::text as finding_code,
    'HIGH'::text as severity,
    'Payment reused across multiple settlements (grouped by source_id).'::text as explanation
  from dup_pay dp
  join public.owner_settlement_payment_links l on l.payment_id = dp.source_id and l.company_id = p_company_id
  join public.owner_settlements os on os.id = l.settlement_id and os.company_id = p_company_id
  join public.accounting_periods ap on ap.id = p_period_id and ap.company_id = p_company_id
  join public.payments pay on pay.id = dp.source_id and pay.company_id = p_company_id
  left join public.companies comp on comp.id = p_company_id
  where upper(coalesce(os.status::text,'')) in ('PAID','POSTED')
  union all
  select
    os.company_id,
    coalesce(comp.name,'')::text,
    null::uuid, ''::text,
    null::uuid, ''::text,
    null::uuid, os.id::uuid,
    upper(coalesce(os.status::text,'DRAFT'))::text,
    ap.name::text,
    'EXPENSE'::text, de.source_id::text,
    exp.expense_date::date,
    public.s08_round_egp(exp.amount)::numeric,
    'EGP'::text,
    'DUPLICATE_EXPENSE_ACROSS_SETTLEMENTS'::text, 'HIGH'::text,
    'Expense reused across multiple settlements (grouped by source_id).'::text
  from dup_exp de
  join public.owner_settlement_expense_links l on l.expense_id = de.source_id and l.company_id = p_company_id
  join public.owner_settlements os on os.id = l.settlement_id and os.company_id = p_company_id
  join public.accounting_periods ap on ap.id = p_period_id and ap.company_id = p_company_id
  join public.expenses exp on exp.id = de.source_id and exp.company_id = p_company_id
  left join public.companies comp on comp.id = p_company_id
  where upper(coalesce(os.status::text,'')) in ('PAID','POSTED');
end;
$$;


ALTER FUNCTION "public"."s08_analyze_settlement_duplicates"("p_company_id" "uuid", "p_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_approve_frozen_review"("p_review_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_review public.s08_frozen_reviews%rowtype;
  v_is_accountant boolean;
begin
  if auth.uid() is null then
    raise exception 'Authentication required for S08 approval' using errcode='42501';
  end if;

  -- Approval is accounting control: require ACCOUNTANT or ADMIN
  v_is_accountant := public.is_accountant() or public.is_admin();
  if not v_is_accountant then
    raise exception 'S08_APPROVAL_REQUIRES_ACCOUNTANT: ACCOUNTANT or ADMIN role required to approve frozen review' using errcode='42501';
  end if;

  if p_review_id is null then
    raise exception 'S08_REVIEW_ID_REQUIRED' using errcode='22023';
  end if;

  select * into v_review from public.s08_frozen_reviews where id = p_review_id and company_id = v_company_id for update;
  if not found then
    raise exception 'S08_REVIEW_NOT_FOUND' using errcode='P0002';
  end if;

  if v_review.reviewer_decision <> 'ANALYZED' then
    raise exception 'S08_REVIEW_LIFECYCLE_ILLEGAL: only ANALYZED can be APPROVED, current %', v_review.reviewer_decision using errcode='23514';
  end if;

  -- Verify fingerprint still matches current dataset (no silent change under approval)
  declare v_current_fp text;
  begin
    v_current_fp := public.s08_compute_dataset_fingerprint(v_company_id, v_review.accounting_period_id);
    if v_current_fp <> v_review.dataset_fingerprint then
      raise exception 'S08_FINGERPRINT_CHANGED_UNDER_REVIEW: current fingerprint % does not match review fingerprint % — dataset changed after review creation, approval blocked', v_current_fp, v_review.dataset_fingerprint using errcode='P0001';
    end if;
  end;

  perform set_config('malik.s08_review_change_authorized', 'true', true);

  update public.s08_frozen_reviews
  set reviewer_decision = 'APPROVED',
      reviewer_id = auth.uid(),
      reviewed_at = now(),
      review_notes = coalesce(p_notes, review_notes),
      updated_at = now()
  where id = p_review_id;

  perform set_config('malik.s08_review_change_authorized', 'false', true);

  return jsonb_build_object('success', true, 'id', p_review_id, 'status', 'APPROVED', 'fingerprint', v_review.dataset_fingerprint);
end;
$$;


ALTER FUNCTION "public"."s08_approve_frozen_review"("p_review_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_compute_dataset_fingerprint"("p_company_id" "uuid", "p_period_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_period_start date;
  v_period_end date;
  v_gl_hash text;
  v_subledger_hash text;
  v_combined text;
  v_digest text;
begin
  if p_company_id is null or p_period_id is null then
    raise exception 'S08_FINGERPRINT_COMPANY_AND_PERIOD_REQUIRED' using errcode='22023';
  end if;

  select start_date, end_date into v_period_start, v_period_end
  from public.accounting_periods
  where id = p_period_id and company_id = p_company_id;

  if not found then
    raise exception 'S08_PERIOD_NOT_FOUND: period % not found for company %', p_period_id, p_company_id using errcode='P0002';
  end if;

  -- GL hash: hash of all journal_batches + lines for company up to period end, ordered deterministically
  select encode(digest(
    coalesce(string_agg(
      jb.id::text || '|' || jb.status || '|' || jb.source_type || '|' || jb.source_id || '|' || jb.event_id || '|' || jb.effective_date::text || '|' ||
      jl.id || '|' || jl.account_id || '|' || jl.debit::text || '|' || jl.credit::text
      , ',' order by jb.effective_date, jb.id, jl.id
    ), ''), 'sha256'), 'hex')
  into v_gl_hash
  from public.journal_batches jb
  join public.journal_lines jl on jl.batch_id = jb.id and jl.company_id = p_company_id and jl.deleted_at is null
  where jb.company_id = p_company_id
    and jb.effective_date <= v_period_end;

  -- Subledger hash: hash of key subledger tables counts/balances
  with sub as (
    select 'tenant_deposits' as tbl, count(*)::text as cnt, coalesce(sum(remaining_amount),0)::text as bal from public.tenant_deposits where company_id = p_company_id and deleted_at is null
    union all
    select 'invoices', count(*)::text, coalesce(sum(amount + coalesce(tax_amount,0) - coalesce(paid_amount,0)),0)::text from public.invoices where company_id = p_company_id and deleted_at is null
    union all
    select 'payments', count(*)::text, coalesce(sum(amount),0)::text from public.payments where company_id = p_company_id and deleted_at is null
    union all
    select 'expenses', count(*)::text, coalesce(sum(amount),0)::text from public.expenses where company_id = p_company_id and deleted_at is null
    union all
    select 'commissions', count(*)::text, coalesce(sum(amount),0)::text from public.commissions where company_id = p_company_id
    union all
    select 'owner_balances', count(*)::text, coalesce(sum(net_balance),0)::text from public.owner_balances where company_id = p_company_id
  )
  select encode(digest(coalesce(string_agg(tbl || ':' || cnt || ':' || bal, ',' order by tbl), ''), 'sha256'), 'hex')
  into v_subledger_hash
  from sub;

  v_combined := p_company_id::text || '|' || p_period_id::text || '|' || v_period_start::text || '|' || v_period_end::text || '|' || coalesce(v_gl_hash,'') || '|' || coalesce(v_subledger_hash,'');

  select encode(digest(v_combined, 'sha256'), 'hex') into v_digest;

  return v_digest;
end;
$$;


ALTER FUNCTION "public"."s08_compute_dataset_fingerprint"("p_company_id" "uuid", "p_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_create_frozen_review"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_period_id uuid;
  v_review_scope jsonb;
  v_fingerprint text;
  v_lineage text;
  v_version text;
  v_evidence_ref text;
  v_results jsonb;
  v_recon jsonb;
  v_exceptions jsonb;
  v_id uuid;
  v_computed_fingerprint text;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role required for S08 review creation' using errcode='42501';
  end if;

  v_company_id := public.require_company_id();
  v_period_id := nullif(p_payload->>'accounting_period_id','')::uuid;
  v_review_scope := coalesce(p_payload->'review_scope', '{}'::jsonb);
  v_version := coalesce(nullif(btrim(p_payload->>'analysis_version'),''), 'v1');
  v_evidence_ref := nullif(p_payload->>'evidence_reference','');
  v_results := p_payload->'analysis_results';
  v_recon := p_payload->'reconciliation_evidence';
  v_exceptions := p_payload->'exceptions';
  v_lineage := coalesce(nullif(btrim(p_payload->>'dataset_lineage'),''), 'default-lineage');

  if v_period_id is null then
    raise exception 'S08_REVIEW_PERIOD_REQUIRED: accounting_period_id required' using errcode='22023';
  end if;

  -- Compute fingerprint deterministically
  v_computed_fingerprint := public.s08_compute_dataset_fingerprint(v_company_id, v_period_id);
  v_fingerprint := coalesce(nullif(btrim(p_payload->>'dataset_fingerprint'),''), v_computed_fingerprint);

  -- Fail-closed if provided fingerprint does not match computed (prevents silent change)
  if btrim(p_payload->>'dataset_fingerprint') <> '' and v_fingerprint <> v_computed_fingerprint then
    raise exception 'S08_FINGERPRINT_MISMATCH: provided fingerprint % does not match computed % for company % period %', v_fingerprint, v_computed_fingerprint, v_company_id, v_period_id using errcode='22023';
  end if;

  insert into public.s08_frozen_reviews (
    company_id, accounting_period_id, review_scope, dataset_fingerprint, dataset_lineage,
    analysis_version, analysis_results, reconciliation_evidence, exceptions, evidence_reference,
    reviewer_decision, created_by
  ) values (
    v_company_id, v_period_id, v_review_scope, v_fingerprint, v_lineage,
    v_version, v_results, v_recon, v_exceptions, v_evidence_ref,
    'CREATED', auth.uid()
  )
  returning id into v_id;

  return jsonb_build_object('success', true, 'id', v_id, 'company_id', v_company_id, 'period_id', v_period_id, 'fingerprint', v_fingerprint, 'status', 'CREATED');
end;
$$;


ALTER FUNCTION "public"."s08_create_frozen_review"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_list_frozen_reviews"("p_period_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_rows jsonb;
begin
  if auth.uid() is null or not public.is_app_user() then
    raise exception 'Authenticated app user required' using errcode='42501';
  end if;

  select jsonb_agg(jsonb_build_object(
    'id', r.id,
    'company_id', r.company_id,
    'accounting_period_id', r.accounting_period_id,
    'dataset_fingerprint', r.dataset_fingerprint,
    'dataset_lineage', r.dataset_lineage,
    'analysis_version', r.analysis_version,
    'reviewer_decision', r.reviewer_decision,
    'creation_timestamp', r.creation_timestamp,
    'reviewed_at', r.reviewed_at,
    'evidence_reference', r.evidence_reference,
    'created_at', r.created_at
  ) order by r.creation_timestamp desc)
  into v_rows
  from public.s08_frozen_reviews r
  where r.company_id = v_company_id
    and (p_period_id is null or r.accounting_period_id = p_period_id);

  return jsonb_build_object('company_id', v_company_id, 'reviews', coalesce(v_rows, '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."s08_list_frozen_reviews"("p_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_orphan_postings"("p_company_id" "uuid", "p_period_id" "uuid") RETURNS TABLE("company_id" "uuid", "batch_id" "uuid", "source_type" "text", "source_id" "text", "status" "text", "finding_code" "text", "severity" "text", "explanation" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_caller uuid;
begin
  if p_company_id is null or p_period_id is null then
    raise exception 'S08_COMPANY_AND_PERIOD_REQUIRED' using errcode='22023';
  end if;
  v_caller := public.current_company_id();
  if v_caller is not null and v_caller <> p_company_id and current_user <> 'service_role' then
    raise exception 'S08_COMPANY_ISOLATION_VIOLATION' using errcode='42501';
  end if;
  return query
  -- Source without posting (invoice -> no batch)
  select
    p_company_id as company_id,
    null::uuid as batch_id,
    'INVOICE'::text as source_type,
    inv.id::text as source_id,
    coalesce(inv.status::text,'DRAFT')::text as status,
    'SOURCE_WITHOUT_POSTING'::text as finding_code,
    'MEDIUM'::text as severity,
    'Invoice has no journal batch posting (bidirectional).'::text as explanation
  from public.invoices inv
  where inv.company_id = p_company_id
    and inv.deleted_at is null
    and inv.status in ('POSTED','PAID')
    and not exists (
      select 1 from public.journal_batches jb
      where jb.company_id = p_company_id
        and jb.source_id = inv.id::text
        and jb.source_type in ('invoice','invoices')
        and jb.accounting_period_id = p_period_id
    )
  union all
  -- Posting without source
  select
    jb.company_id,
    jb.id as batch_id,
    jb.source_type::text,
    jb.source_id::text,
    jb.status::text,
    'POSTING_WITHOUT_SOURCE'::text,
    'HIGH'::text,
    'Journal batch references missing source.'::text
  from public.journal_batches jb
  where jb.company_id = p_company_id
    and jb.accounting_period_id = p_period_id
    and jb.source_type = 'invoice'
    and not exists (
      select 1 from public.invoices inv where inv.id::text = jb.source_id and inv.company_id = p_company_id
    )
  union all
  -- Voided/cancelled with surviving postings
  select
    p_company_id,
    null::uuid,
    'INVOICE'::text,
    inv.id::text,
    inv.status::text,
    'VOIDED_SURVIVING_POSTING'::text,
    'HIGH'::text,
    'Voided/cancelled invoice has active postings without reversal.'::text
  from public.invoices inv
  where inv.company_id = p_company_id
    and upper(coalesce(inv.status::text,'')) in ('VOID','VOIDED','CANCELLED')
    and exists (
      select 1 from public.journal_batches jb
      where jb.company_id = p_company_id and jb.source_id = inv.id::text and jb.status='POSTED'
    )
    and not exists (
      select 1 from public.journal_batches jb
      where jb.company_id = p_company_id and jb.reversal_of_batch_id is not null
    )
  union all
  -- Reversal without original
  select
    jb.company_id,
    jb.id,
    jb.source_type::text,
    jb.source_id::text,
    jb.status::text,
    'REVERSAL_WITHOUT_ORIGINAL'::text,
    'HIGH'::text,
    'Reversal references missing original batch.'::text
  from public.journal_batches jb
  where jb.company_id = p_company_id
    and jb.accounting_period_id = p_period_id
    and jb.reversal_of_batch_id is not null
    and not exists (select 1 from public.journal_batches o where o.id = jb.reversal_of_batch_id and o.company_id = p_company_id);
end;
$$;


ALTER FUNCTION "public"."s08_orphan_postings"("p_company_id" "uuid", "p_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."s08_reject_frozen_review"("p_review_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_review public.s08_frozen_reviews%rowtype;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER required for S08 rejection' using errcode='42501';
  end if;

  if p_review_id is null then
    raise exception 'S08_REVIEW_ID_REQUIRED' using errcode='22023';
  end if;

  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'S08_REJECTION_REASON_REQUIRED: reason required for rejection' using errcode='22023';
  end if;

  select * into v_review from public.s08_frozen_reviews where id = p_review_id and company_id = v_company_id for update;
  if not found then
    raise exception 'S08_REVIEW_NOT_FOUND' using errcode='P0002';
  end if;

  if v_review.reviewer_decision not in ('CREATED','ANALYZED') then
    raise exception 'S08_REVIEW_LIFECYCLE_ILLEGAL: only CREATED or ANALYZED can be REJECTED, current %', v_review.reviewer_decision using errcode='23514';
  end if;

  perform set_config('malik.s08_review_change_authorized', 'true', true);

  update public.s08_frozen_reviews
  set reviewer_decision = 'REJECTED',
      reviewer_id = auth.uid(),
      reviewed_at = now(),
      review_notes = p_reason,
      updated_at = now()
  where id = p_review_id;

  perform set_config('malik.s08_review_change_authorized', 'false', true);

  return jsonb_build_object('success', true, 'id', p_review_id, 'status', 'REJECTED');
end;
$$;


