CREATE OR REPLACE FUNCTION "public"."soft_delete_contract_atomic"("p_contract_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old public.contracts%rowtype;
  v_company_id uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin_or_manager() THEN
    RAISE EXCEPTION 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لحذف عقد' USING ERRCODE = '42501';
  END IF;

  v_company_id := (auth.jwt() -> 'app_metadata' ->> 'company_id')::uuid;

  SELECT * INTO v_old
  FROM public.contracts
  WHERE id = p_contract_id AND deleted_at IS NULL
    AND company_id = v_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'العقد غير موجود';
  END IF;

  -- Protect financial integrity: reject soft deletion if paid invoices exist
  IF EXISTS (
    SELECT 1 FROM public.invoices
    WHERE contract_id = p_contract_id
      AND deleted_at IS NULL
      AND COALESCE(paid_amount, 0) > 0
  ) THEN
    RAISE EXCEPTION 'لا يمكن حذف عقد يحتوي على فواتير مدفوعة أو دفعات مسجلة؛ يرجى إنهاء العقد بدلاً من ذلك';
  END IF;

  -- Protect financial integrity: reject soft deletion if receipts exist
  IF EXISTS (
    SELECT 1 FROM public.receipts
    WHERE contract_id = p_contract_id
      AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'لا يمكن حذف عقد يحتوي على إيصالات مالية؛ يرجى إنهاء العقد بدلاً من ذلك';
  END IF;

  -- Cancel and soft-delete future unpaid invoices so they do not remain open
  UPDATE public.invoices
  SET status = 'CANCELLED',
      deleted_at = now(),
      updated_at = now()
  WHERE contract_id = p_contract_id
    AND company_id = v_company_id
    AND deleted_at IS NULL
    AND COALESCE(paid_amount, 0) = 0
    AND status NOT IN ('CANCELLED', 'PAID')
    AND due_date::date > current_date;

  -- Soft-delete the contract
  UPDATE public.contracts
  SET deleted_at = now(),
      updated_at = now()
  WHERE id = p_contract_id
    AND company_id = v_company_id;

  RETURN jsonb_build_object(
    'status', 'deleted',
    'contract_id', p_contract_id
  );
END;
$$;


ALTER FUNCTION "public"."soft_delete_contract_atomic"("p_contract_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_contract_for_approval_atomic"("p_contract_id" "text", "p_maker_signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company uuid := public.require_company_id();
  v_actor uuid := auth.uid();
  v_contract public.contracts%rowtype;
  v_result jsonb;
begin
  if v_actor is null or not public.is_admin_or_manager() then
    raise exception 'CONTRACT_APPROVAL_FORBIDDEN' using errcode='42501';
  end if;
  if nullif(btrim(coalesce(p_maker_signature,'')), '') is null then
    raise exception 'MAKER_SIGNATURE_REQUIRED' using errcode='22023';
  end if;

  select * into v_contract
  from public.contracts
  where id::text = p_contract_id
    and company_id = v_company
    and deleted_at is null
  for update;

  if not found then
    raise exception 'CONTRACT_NOT_FOUND_OR_FORBIDDEN' using errcode='42501';
  end if;
  if lower(coalesce(v_contract.status,'')) <> 'draft' then
    raise exception 'CONTRACT_SUBMISSION_STATE_INVALID' using errcode='22023';
  end if;
  if v_contract.approval_status = 'APPROVED' then
    raise exception 'CONTRACT_ALREADY_APPROVED' using errcode='22023';
  end if;

  update public.contracts c
  set maker_user_id = v_actor,
      checker_user_id = null,
      maker_signature = btrim(p_maker_signature),
      checker_signature = null,
      approval_status = 'PENDING',
      submitted_at = now(),
      approved_at = null,
      rejected_at = null,
      rejection_reason = null,
      approval_evidence = jsonb_build_object(
        'maker_user_id', v_actor,
        'maker_signature', btrim(p_maker_signature),
        'submitted_at', now()
      ),
      updated_at = now()
  where c.id::text = p_contract_id
    and c.company_id = v_company
  returning to_jsonb(c) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."submit_contract_for_approval_atomic"("p_contract_id" "text", "p_maker_signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_contract_for_approval_atomic"("p_contract_id" "text", "p_maker_signature" "text") IS 'S04-T03: record maker identity/signature and mark approval sub-state PENDING while canonical contract status stays draft.';



CREATE OR REPLACE FUNCTION "public"."submit_contract_registration_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_company uuid := public.require_company_id();
  v_contract public.contracts%rowtype; v_profile public.contract_registration_requirement_profiles%rowtype;
  v_existing public.contract_registration_records%rowtype; v_record public.contract_registration_records%rowtype;
  v_contract_id uuid := nullif(p_payload->>'contract_id','')::uuid;
  v_request text := nullif(btrim(p_payload->>'request_id'),'');
  v_doc uuid := nullif(p_payload->>'evidence_document_id','')::uuid;
begin
  if v_actor is null or not public.contract_evidence_actor_can_operate() then raise exception 'CONTRACT_EVIDENCE_FORBIDDEN' using errcode='42501'; end if;
  if v_request is null or v_contract_id is null then raise exception 'CONTRACT_REGISTRATION_INPUT_REQUIRED' using errcode='22023'; end if;
  select * into v_existing from public.contract_registration_records where company_id=v_company and submission_request_id=v_request;
  if found then return to_jsonb(v_existing); end if;
  select * into v_contract from public.contracts where id=v_contract_id and company_id=v_company and deleted_at is null;
  if not found then raise exception 'CONTRACT_NOT_FOUND' using errcode='42501'; end if;
  select * into v_profile from public.contract_registration_requirement_profiles p
   where p.company_id=v_company and p.effective_from<=v_contract.start_date
     and (p.effective_to is null or p.effective_to>=v_contract.start_date)
   order by p.effective_from desc limit 1;
  if not found then raise exception 'CONTRACT_REGISTRATION_NOT_CONFIGURED' using errcode='55000'; end if;
  if not v_profile.registration_required then raise exception 'CONTRACT_REGISTRATION_NOT_REQUIRED' using errcode='22023'; end if;
  if v_doc is not null then perform public.contract_evidence_assert_documents(v_company,v_contract_id,array[v_doc]); end if;
  if exists(select 1 from public.contract_registration_records where company_id=v_company and contract_id=v_contract_id and status in ('SUBMITTED','REGISTERED')) then
    raise exception 'CONTRACT_REGISTRATION_ALREADY_OPEN' using errcode='23505';
  end if;
  insert into public.contract_registration_records(
    company_id,contract_id,requirement_profile_id,jurisdiction_code_snapshot,authority_name_snapshot,
    legal_reference_snapshot,deadline_days_snapshot,fee_mode_snapshot,fee_value_snapshot,currency_snapshot,
    status,submitted_on,external_request_reference,evidence_document_id,submission_request_id,submitted_by
  ) values (
    v_company,v_contract_id,v_profile.id,v_profile.jurisdiction_code,v_profile.authority_name,
    v_profile.legal_reference,v_profile.deadline_days,v_profile.fee_mode,v_profile.fee_value,v_profile.currency,
    'SUBMITTED',coalesce(nullif(p_payload->>'submitted_on','')::date,current_date),nullif(btrim(p_payload->>'external_request_reference'),''),
    v_doc,v_request,v_actor
  ) returning * into v_record;
  insert into public.contract_evidence_events(company_id,contract_id,entity_type,entity_id,event_type,to_status,payload,actor_id)
    values(v_company,v_contract_id,'REGISTRATION',v_record.id,'SUBMITTED','SUBMITTED',jsonb_build_object('request_id',v_request),v_actor);
  return to_jsonb(v_record);
end;
$$;


ALTER FUNCTION "public"."submit_contract_registration_atomic"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_owner_compatibility_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.full_name IS DISTINCT FROM OLD.full_name AND NEW.name IS NOT DISTINCT FROM OLD.name THEN
      NEW.name := NEW.full_name;
    ELSIF NEW.name IS DISTINCT FROM OLD.name AND NEW.full_name IS NOT DISTINCT FROM OLD.full_name THEN
      NEW.full_name := NEW.name;
    END IF;
  END IF;

  NEW.full_name := COALESCE(NULLIF(btrim(NEW.full_name), ''), NULLIF(btrim(NEW.name), ''), NULLIF(btrim(NEW.display_name), ''));
  NEW.name := COALESCE(NULLIF(btrim(NEW.name), ''), NEW.full_name);

  IF NEW.name IS NULL OR NEW.full_name IS NULL THEN
    RAISE EXCEPTION 'اسم المالك مطلوب';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_owner_compatibility_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_payment_reference_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.reference_number := coalesce(new.reference_number, new.reference_no);
    new.reference_no := coalesce(new.reference_no, new.reference_number);
  elsif new.reference_number is distinct from old.reference_number then
    new.reference_no := new.reference_number;
  elsif new.reference_no is distinct from old.reference_no then
    new.reference_number := new.reference_no;
  else
    new.reference_number := coalesce(new.reference_number, new.reference_no);
    new.reference_no := coalesce(new.reference_no, new.reference_number);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_payment_reference_fields"() OWNER TO "postgres";


