CREATE OR REPLACE FUNCTION "public"."transition_maintenance_status_atomic"("p_request_id" "text", "p_next_status" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_row public.maintenance_records%rowtype;
  v_current text;
  v_next text := lower(btrim(coalesce(p_next_status, '')));
begin
  if auth.uid() is null or not coalesce(public.is_app_user(), false) then
    raise exception 'Authenticated app user is required.' using errcode = '42501';
  end if;
  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'Company context is required.' using errcode = '42501';
  end if;

  select * into v_row
  from public.maintenance_records
  where id::text = p_request_id and company_id = v_company_id and deleted_at is null
  for update;
  if not found then
    raise exception 'طلب الصيانة غير موجود' using errcode = 'P0002';
  end if;

  v_current := lower(coalesce(v_row.status, 'open'));

  -- Resolution is financially coupled and owns its own RPC.
  if v_next = 'resolved' then
    raise exception 'MAINTENANCE_RESOLVE_VIA_RPC: استخدم resolve_maintenance_with_expense لإقفال العمل مع التكلفة'
      using errcode = '23514';
  end if;

  if v_next not in ('open', 'in_progress', 'cancelled', 'closed') then
    raise exception 'MAINTENANCE_TRANSITION_UNSUPPORTED: % ليست حالة انتقال مدعومة عبر هذا الأمر', v_next
      using errcode = '23514';
  end if;

  -- Legal transition matrix (Cancelled ≠ Closed).
  if v_current = 'open' and v_next in ('in_progress', 'cancelled') then null;
  elsif v_current = 'in_progress' and v_next in ('open', 'cancelled') then null;
  elsif v_current = 'resolved' and v_next = 'closed' then null;
  elsif v_current in ('closed', 'cancelled') then
    raise exception 'MAINTENANCE_LIFECYCLE_TERMINAL: الحالة % نهائية ولا يمكن تغييرها', v_current
      using errcode = '23514';
  else
    raise exception 'MAINTENANCE_TRANSITION_ILLEGAL: الانتقال من % إلى % غير مسموح', v_current, v_next
      using errcode = '23514';
  end if;

  if v_next = 'cancelled' and nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'MAINTENANCE_CANCELLATION_REASON_REQUIRED: سبب الإلغاء إلزامي'
      using errcode = '22023';
  end if;

  -- Transaction-local sanction key: the status trigger only admits status
  -- writes that flow through a sanctioned command.
  perform set_config('malek.maintenance_transition_sanctioned', 'true', true);

  update public.maintenance_records
     set status = v_next,
         cancelled_at = case when v_next = 'cancelled' then now() else cancelled_at end,
         cancellation_reason = case when v_next = 'cancelled' then btrim(p_reason) else cancellation_reason end,
         resolved_at = case when v_next = 'closed' then coalesce(resolved_at, now()) else resolved_at end,
         updated_at = now()
   where id::text = p_request_id;

  -- Canonical audit contract (same column set as receipt-void audits).
  insert into public.audit_log (
    id, ts, user_id, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid()::text,
    extract(epoch from now())::bigint,
    auth.uid()::text,
    'STATUS_' || upper(v_next),
    'maintenance_records',
    p_request_id,
    case when v_next = 'cancelled'
      then 'إلغاء طلب صيانة: ' || btrim(p_reason)
      else 'انتقال حالة صيانة عبر الأمر المعتمد' end,
    'maintenance_records',
    jsonb_build_object('from', v_current, 'to', v_next, 'reason', nullif(btrim(coalesce(p_reason, '')), ''))::text,
    now()
  );

  return (select to_jsonb(m) from public.maintenance_records m where m.id::text = p_request_id);
end;
$$;


ALTER FUNCTION "public"."transition_maintenance_status_atomic"("p_request_id" "text", "p_next_status" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transition_maintenance_status_atomic"("p_request_id" "text", "p_next_status" "text", "p_reason" "text") IS 'R8: the only sanctioned maintenance status transition path. Cancelled ≠ Closed; terminal states immutable; cancellation requires a reason; resolution flows through resolve_maintenance_with_expense.';



CREATE OR REPLACE FUNCTION "public"."update_accounting_period_status"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_period_id uuid := nullif(p_payload->>'period_id', '')::uuid;
  v_new_status text := upper(coalesce(nullif(btrim(p_payload->>'status', ''), ''), ''));
  v_reason text := nullif(btrim(coalesce(p_payload->>'reason', '')), '');
  v_period public.accounting_periods%rowtype;
  v_old_status text;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to manage accounting periods.' using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  if v_period_id is null then
    raise exception 'ACCOUNTING_PERIOD_ID_REQUIRED: period_id is required.' using errcode = '22023';
  end if;
  if v_new_status not in ('OPEN', 'SOFT_CLOSED', 'HARD_CLOSED') then
    raise exception 'ACCOUNTING_PERIOD_STATUS_INVALID: status must be OPEN, SOFT_CLOSED or HARD_CLOSED.' using errcode = '22023';
  end if;

  select * into v_period
    from public.accounting_periods p
   where p.id = v_period_id
     and p.company_id = v_company_id;

  if not found then
    raise exception 'ACCOUNTING_PERIOD_NOT_FOUND: period % does not exist in your company.', v_period_id using errcode = 'P0002';
  end if;

  v_old_status := v_period.status;

  if v_old_status = v_new_status then
    return jsonb_build_object('success', true, 'id', v_period_id, 'status', v_new_status, 'changed', false);
  end if;

  if v_old_status = 'HARD_CLOSED' then
    raise exception 'ACCOUNTING_PERIOD_HARD_CLOSED_IMMUTABLE: a HARD_CLOSED period cannot be reopened or changed.' using errcode = '42501';
  end if;

  if v_new_status = 'OPEN' and v_reason is null then
    raise exception 'ACCOUNTING_PERIOD_REOPEN_REASON_REQUIRED: reopening a period requires an explicit reason.' using errcode = '22023';
  end if;

  perform set_config('malik.accounting_period_change_authorized', 'true', true);

  update public.accounting_periods
     set status = v_new_status,
         closed_at = case when v_new_status in ('SOFT_CLOSED', 'HARD_CLOSED') then now() else closed_at end,
         closed_by = case when v_new_status in ('SOFT_CLOSED', 'HARD_CLOSED') then auth.uid() else closed_by end,
         reopen_reason = case when v_new_status = 'OPEN' then v_reason else reopen_reason end,
         updated_at = now()
   where id = v_period_id;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid()::text, extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'UPDATE', 'accounting_periods', v_period_id::text,
    'Accounting period status changed: ' || v_old_status || ' -> ' || v_new_status || coalesce(' — reason: ' || v_reason, ''),
    'accounting_periods', left(p_payload::text, 4000), now()
  );

  return jsonb_build_object(
    'success', true,
    'id', v_period_id,
    'status', v_new_status,
    'changed', true,
    'old_status', v_old_status
  );
end;
$$;


ALTER FUNCTION "public"."update_accounting_period_status"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_commission_atomic"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_id text := nullif(btrim(p_payload->>'commission_id'), '');
  v_request_id text := nullif(btrim(p_payload->>'request_id'), '');
  v_staff_name text := nullif(btrim(p_payload->>'staff_name'), '');
  v_type text := lower(nullif(btrim(p_payload->>'type'), ''));
  v_requested_status text := lower(nullif(btrim(p_payload->>'requested_status'), ''));
  v_source_id text := nullif(btrim(p_payload->>'source_id'), '');
  v_deal_value numeric := nullif(btrim(p_payload->>'deal_value'), '')::numeric;
  v_percentage numeric := nullif(btrim(p_payload->>'percentage'), '')::numeric;
  v_amount numeric := nullif(btrim(p_payload->>'amount'), '')::numeric;
  v_comm public.commissions%rowtype;
  v_cached jsonb;
  v_result jsonb;
  v_operation_name text;
  v_request_fingerprint text;
  v_cached_fingerprint text;
  v_cached_target_id text;
  v_old_status text;
  v_updated_count integer;
begin
  if auth.uid() is null or not coalesce(public.is_admin_or_manager(), false) then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لتعديل عمولة'
      using errcode = '42501';
  end if;

  v_company_id := public.require_company_id();

  if v_id is null then
    raise exception 'معرّف العمولة مطلوب' using errcode = '22023';
  end if;
  if v_staff_name is null then
    raise exception 'اسم الموظف أو الوسيط مطلوب.' using errcode = '22023';
  end if;
  if v_type is null or v_type not in ('contract', 'payment', 'owner', 'lead', 'land') then
    raise exception 'نوع مصدر العمولة غير صحيح.' using errcode = '22023';
  end if;
  if v_requested_status is null or v_requested_status not in ('pending', 'approved') then
    raise exception 'تعديل العمولة يسمح فقط بحالة pending أو approved؛ استخدم أمر الإلغاء أو الصرف للحالات النهائية.'
      using errcode = '22023';
  end if;
  if v_deal_value is not null and v_deal_value < 0 then
    raise exception 'قيمة الصفقة يجب أن تكون صفراً أو أكبر.' using errcode = '22023';
  end if;
  if v_percentage is not null and (v_percentage < 0 or v_percentage > 100) then
    raise exception 'نسبة العمولة يجب أن تكون بين صفر و100.' using errcode = '22023';
  end if;

  if v_amount is null and v_deal_value is not null and v_percentage is not null then
    v_amount := round(v_deal_value * (v_percentage / 100.0), 2);
  end if;
  if v_amount is null or v_amount <= 0 then
    raise exception 'أدخل قيمة عمولة أكبر من صفر أو قيمة الصفقة والنسبة.'
      using errcode = '22023';
  end if;

  if v_request_id is null then
    v_request_id := gen_random_uuid()::text;
  end if;

  v_operation_name := 'update_commission_atomic:' || v_company_id::text;
  v_request_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'commission_id', v_id,
    'staff_name', v_staff_name,
    'type', v_type,
    'requested_status', v_requested_status,
    'source_id', v_source_id,
    'deal_value', v_deal_value,
    'percentage', v_percentage,
    'amount', v_amount
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_operation_name || ':' || v_request_id, 0)
  );

  select *
    into v_comm
  from public.commissions
  where id = v_id
    and company_id = v_company_id
  for update;

  if not found then
    raise exception 'COMMISSION_NOT_FOUND_OR_FORBIDDEN' using errcode = '42501';
  end if;

  select response_payload
    into v_cached
  from public.financial_operation_idempotency
  where operation_name = v_operation_name
    and request_id = v_request_id
  for update;

  if v_cached is not null then
    v_cached_fingerprint := v_cached->>'_request_fingerprint';
    v_cached_target_id := v_cached->>'_target_id';
    if v_cached_fingerprint is null
       or v_cached_target_id is null
       or not (v_cached ? 'response') then
      raise exception 'IDEMPOTENCY_CACHED_RESPONSE_UNVERIFIED'
        using errcode = '22023';
    end if;
    if v_cached_fingerprint <> v_request_fingerprint or v_cached_target_id <> v_id then
      raise exception 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_REQUEST'
        using errcode = '22023';
    end if;
    return (v_cached->'response') || jsonb_build_object('idempotent', true);
  end if;

  v_old_status := lower(coalesce(v_comm.status, ''));
  if v_old_status = 'paid' then
    raise exception 'COMMISSION_PAID_IMMUTABLE' using errcode = '22023';
  end if;
  if v_old_status = 'cancelled' then
    raise exception 'COMMISSION_CANCELLED_IMMUTABLE' using errcode = '22023';
  end if;

  update public.commissions
     set staff_name = v_staff_name,
         type = v_type,
         status = v_requested_status,
         source_id = v_source_id,
         deal_value = v_deal_value,
         percentage = v_percentage,
         amount = v_amount,
         updated_at = now()
   where id = v_id
     and company_id = v_company_id
  returning * into v_comm;

  get diagnostics v_updated_count = row_count;
  if v_updated_count <> 1 then
    raise exception 'COMMISSION_UPDATE_COUNT_MISMATCH' using errcode = 'P0001';
  end if;

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'UPDATE', 'commissions', v_id,
    'Commission updated through trusted RPC',
    'commissions',
    left(jsonb_build_object(
      'request_id', v_request_id,
      'old_status', v_old_status,
      'new_status', v_requested_status,
      'staff_name', v_staff_name,
      'type', v_type,
      'source_id', v_source_id,
      'deal_value', v_deal_value,
      'percentage', v_percentage,
      'amount', v_amount
    )::text, 4000),
    now()
  );

  v_result := jsonb_build_object(
    'success', true,
    'idempotent', false,
    'commission_id', v_comm.id,
    'status', v_comm.status,
    'request_id', v_request_id,
    'commission', to_jsonb(v_comm)
  );

  insert into public.financial_operation_idempotency (
    operation_name, request_id, response_payload
  ) values (
    v_operation_name,
    v_request_id,
    jsonb_build_object(
      '_request_fingerprint', v_request_fingerprint,
      '_target_id', v_id,
      'response', v_result
    )
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."update_commission_atomic"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_commission_atomic"("p_payload" "jsonb") IS 'PR-C: updates operational commission fields and only pending/approved status. Paid/cancelled rows are immutable.';



CREATE OR REPLACE FUNCTION "public"."update_contract_atomic"("p_contract_id" "text", "p_property_id" "text", "p_unit_id" "uuid", "p_tenant_id" "uuid", "p_agreement_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_payment_cycle" "text", "p_payment_terms_id" "uuid", "p_status" "text", "p_cancellation_reason" "text", "p_notes" "text", "p_attachment_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_company_id uuid;
  v_old public.contracts%rowtype;
  v_property_id public.contracts.property_id%type;
  v_unit_id public.contracts.unit_id%type;
  v_tenant_id public.contracts.tenant_id%type;
  v_agreement_id public.contracts.agreement_id%type;
  v_payment_terms_id public.contracts.payment_terms_id%type;
  v_result jsonb;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'غير مصرح: يجب أن تكون مديراً أو مشرفاً لتعديل عقد'
      using errcode = '42501';
  end if;

  v_company_id := public.current_company_id();
  if v_company_id is null then
    raise exception 'سياق الشركة مطلوب لتعديل العقد'
      using errcode = '42501';
  end if;

  -- Assignment through destination-column types keeps this RPC compatible
  -- with both the clean UUID replay and the live text compatibility schema.
  v_property_id := p_property_id;
  v_unit_id := p_unit_id;
  v_tenant_id := p_tenant_id;
  v_agreement_id := p_agreement_id;
  v_payment_terms_id := p_payment_terms_id;

  select *
    into v_old
  from public.contracts
  where id::text = p_contract_id
    and company_id = v_company_id
    and deleted_at is null
  for update;

  if not found then
    raise exception 'العقد غير موجود'
      using errcode = 'P0002';
  end if;

  if lower(coalesce(v_old.status, '')) = 'terminated'
     and lower(coalesce(p_status, '')) <> 'terminated' then
    raise exception 'لا يمكن إعادة فتح عقد تم إنهاؤه بالفعل';
  end if;
  if p_start_date is null or p_end_date is null or p_end_date <= p_start_date then
    raise exception 'تاريخ نهاية العقد يجب أن يكون بعد تاريخ البداية';
  end if;
  if p_rent_amount is null or p_rent_amount <= 0 then
    raise exception 'قيمة الإيجار يجب أن تكون أكبر من صفر';
  end if;
  if lower(coalesce(p_status, '')) not in ('draft', 'active', 'expired', 'terminated') then
    raise exception 'حالة العقد غير مدعومة';
  end if;
  if p_payment_cycle not in ('monthly', 'quarterly', 'semi_annual', 'annual') then
    raise exception 'دورة السداد غير مدعومة';
  end if;

  if v_unit_id::text is distinct from v_old.unit_id::text and exists (
    select 1
    from public.units u
    where u.id::text = v_unit_id::text
      and u.company_id = v_company_id
      and u.deleted_at is null
      and lower(u.status) in ('maintenance', 'reserved')
  ) then
    raise exception 'لا يمكن نقل العقد إلى وحدة تحت الصيانة أو محجوزة تشغيلياً';
  end if;

  if exists (
    select 1
    from public.contracts contract_record
    where contract_record.unit_id::text = v_unit_id::text
      and contract_record.id::text <> p_contract_id
      and contract_record.company_id = v_company_id
      and contract_record.deleted_at is null
      and lower(contract_record.status) in ('active', 'draft')
      and btrim(coalesce(contract_record.start_date::text, '')) ~ '^\d{4}-\d{2}-\d{2}$'
      and btrim(coalesce(contract_record.end_date::text, '')) ~ '^\d{4}-\d{2}-\d{2}$'
      and btrim(contract_record.start_date::text)::date <= p_end_date
      and btrim(contract_record.end_date::text)::date >= p_start_date
  ) then
    raise exception 'الوحدة محجوزة خلال هذه الفترة';
  end if;

  -- GAP-004 hardening: the canonical lifecycle owns status transitions, and
  -- signed/approved commercial terms are never silently overwritten.
  --
  -- a) Company isolation: every referenced entity must belong to the current
  --    company and the agreement must belong to the selected property. UUID
  --    secrecy is never relied upon (SEC-003).
  if not exists (
    select 1 from public.people person_ref
    where person_ref.id::text = v_tenant_id::text
      and person_ref.company_id = v_company_id
      and person_ref.type = 'tenant'
      and person_ref.deleted_at is null
  ) then
    raise exception 'CONTRACT_REFERENCE_CROSS_COMPANY'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.properties property_ref
    where property_ref.id::text = v_property_id::text
      and property_ref.company_id = v_company_id
      and property_ref.deleted_at is null
  ) then
    raise exception 'CONTRACT_REFERENCE_CROSS_COMPANY'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.units unit_ref
    where unit_ref.id::text = v_unit_id::text
      and unit_ref.company_id = v_company_id
      and unit_ref.property_id::text = v_property_id::text
      and unit_ref.deleted_at is null
  ) then
    raise exception 'CONTRACT_REFERENCE_CROSS_COMPANY'
      using errcode = '42501';
  end if;
  if v_agreement_id is null or not exists (
    select 1 from public.owner_agreements agreement_ref
    where agreement_ref.id::text = v_agreement_id::text
      and agreement_ref.company_id = v_company_id
      and agreement_ref.property_id::text = v_property_id::text
  ) then
    raise exception 'CONTRACT_REFERENCE_CROSS_COMPANY'
      using errcode = '42501';
  end if;

  -- b) Lifecycle state is preserved by generic editing. The only status value a
  --    generic edit may supply is the contract's current status; every other
  --    transition is owned by a dedicated command (the activation RPC,
  --    terminate_contract_atomic, the controlled renewal workflow, or the
  --    submit/approve/reject RPCs). This makes draft->expired, draft->terminated,
  --    terminated->active, active->draft, active->expired and approved-draft
  --    status flips all fail closed through the generic editor.
  if lower(coalesce(p_status, '')) <> lower(coalesce(v_old.status, '')) then
    if lower(coalesce(v_old.status, '')) = 'active' then
      raise exception 'CONTRACT_ACTIVE_STATUS_IMMUTABLE'
        using errcode = '23514';
    elsif lower(coalesce(p_status, '')) = 'active' then
      raise exception 'CONTRACT_ACTIVATION_VIA_RPC'
        using errcode = '23514';
    else
      raise exception 'CONTRACT_LIFECYCLE_STATUS_IMMUTABLE'
        using errcode = '23514';
    end if;
  end if;

  -- c) Signed/approved commercial terms are never silently overwritten. An
  --    active or APPROVED contract's material terms are frozen; changes flow
  --    through reject/re-submit, termination or the renewal/amendment workflow.
  if lower(coalesce(v_old.status, '')) = 'active'
     and (
       v_property_id::text is distinct from v_old.property_id::text
       or v_unit_id::text is distinct from v_old.unit_id::text
       or v_tenant_id::text is distinct from v_old.tenant_id::text
       or v_agreement_id::text is distinct from v_old.agreement_id::text
       or btrim(coalesce(p_start_date::text, '')) is distinct from btrim(coalesce(v_old.start_date::text, ''))
       or btrim(coalesce(p_end_date::text, '')) is distinct from btrim(coalesce(v_old.end_date::text, ''))
       or p_rent_amount is distinct from v_old.rent_amount
       or p_payment_cycle is distinct from v_old.payment_cycle
       or v_payment_terms_id::text is distinct from v_old.payment_terms_id::text
     ) then
    raise exception 'CONTRACT_SIGNED_TERMS_IMMUTABLE'
      using errcode = '23514';
  elsif coalesce(v_old.approval_status, '') = 'APPROVED'
    and (
      v_property_id::text is distinct from v_old.property_id::text
      or v_unit_id::text is distinct from v_old.unit_id::text
      or v_tenant_id::text is distinct from v_old.tenant_id::text
      or v_agreement_id::text is distinct from v_old.agreement_id::text
      or btrim(coalesce(p_start_date::text, '')) is distinct from btrim(coalesce(v_old.start_date::text, ''))
      or btrim(coalesce(p_end_date::text, '')) is distinct from btrim(coalesce(v_old.end_date::text, ''))
      or p_rent_amount is distinct from v_old.rent_amount
      or p_payment_cycle is distinct from v_old.payment_cycle
      or v_payment_terms_id::text is distinct from v_old.payment_terms_id::text
    ) then
    raise exception 'CONTRACT_APPROVED_TERMS_IMMUTABLE'
      using errcode = '23514';
  end if;

  update public.contracts as contract_record
  set
    property_id = v_property_id,
    unit_id = v_unit_id,
    tenant_id = v_tenant_id,
    agreement_id = v_agreement_id,
    start_date = p_start_date,
    end_date = p_end_date,
    rent_amount = p_rent_amount,
    payment_cycle = p_payment_cycle,
    payment_terms_id = v_payment_terms_id,
    status = lower(p_status),
    cancellation_reason = nullif(btrim(p_cancellation_reason), ''),
    notes = nullif(btrim(p_notes), ''),
    attachment_url = nullif(btrim(p_attachment_url), ''),
    updated_at = now()
  where contract_record.id::text = p_contract_id
    and contract_record.company_id = v_company_id
    and contract_record.deleted_at is null
  returning to_jsonb(contract_record) into v_result;

  if v_result is null then
    raise exception 'العقد غير موجود'
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."update_contract_atomic"("p_contract_id" "text", "p_property_id" "text", "p_unit_id" "uuid", "p_tenant_id" "uuid", "p_agreement_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_payment_cycle" "text", "p_payment_terms_id" "uuid", "p_status" "text", "p_cancellation_reason" "text", "p_notes" "text", "p_attachment_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_contract_balance_from_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contract_id text;
  v_total_invoiced numeric;
  v_total_paid numeric;
  v_tenant_id text;
  v_unit_id text;
  v_company_id uuid;
BEGIN
  -- Get contract_id from the invoice referenced by this allocation
  IF TG_OP = 'DELETE' THEN
    SELECT i.contract_id::text INTO v_contract_id
    FROM public.invoices i
    WHERE i.id::text = OLD.invoice_id::text;
  ELSE
    SELECT i.contract_id::text INTO v_contract_id
    FROM public.invoices i
    WHERE i.id::text = NEW.invoice_id::text;
  END IF;

  IF v_contract_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Calculate totals for this contract
  SELECT 
    COALESCE(SUM(i.amount + COALESCE(i.tax_amount, 0)), 0),
    COALESCE(SUM(i.paid_amount), 0),
    c.tenant_id::text,
    c.unit_id::text,
    c.company_id
  INTO v_total_invoiced, v_total_paid, v_tenant_id, v_unit_id, v_company_id
  FROM public.contracts c
  LEFT JOIN public.invoices i ON i.contract_id::text = c.id::text AND i.deleted_at IS NULL
  WHERE c.id::text = v_contract_id::text
  GROUP BY c.tenant_id, c.unit_id, c.company_id;

  IF NOT FOUND THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Upsert contract_balances
  INSERT INTO public.contract_balances (
    contract_id, tenant_id, unit_id, total_invoiced, total_paid, balance_due, updated_at, company_id
  ) VALUES (
    v_contract_id::uuid,
    v_tenant_id::uuid,
    v_unit_id::uuid,
    v_total_invoiced,
    v_total_paid,
    v_total_invoiced - v_total_paid,
    now(),
    v_company_id
  )
  ON CONFLICT (contract_id) DO UPDATE SET
    tenant_id = EXCLUDED.tenant_id,
    unit_id = EXCLUDED.unit_id,
    total_invoiced = EXCLUDED.total_invoiced,
    total_paid = EXCLUDED.total_paid,
    balance_due = EXCLUDED.balance_due,
    updated_at = now();

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."update_contract_balance_from_allocation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_contract_balance_from_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contract_id text;
  v_total_invoiced numeric;
  v_total_paid numeric;
  v_tenant_id text;
  v_unit_id text;
  v_company_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_contract_id := OLD.contract_id::text;
  ELSE
    v_contract_id := NEW.contract_id::text;
  END IF;

  IF v_contract_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT 
    COALESCE(SUM(i.amount + COALESCE(i.tax_amount, 0)), 0),
    COALESCE(SUM(i.paid_amount), 0),
    c.tenant_id::text,
    c.unit_id::text,
    c.company_id
  INTO v_total_invoiced, v_total_paid, v_tenant_id, v_unit_id, v_company_id
  FROM public.contracts c
  LEFT JOIN public.invoices i ON i.contract_id::text = c.id::text AND i.deleted_at IS NULL
  WHERE c.id::text = v_contract_id::text
  GROUP BY c.tenant_id, c.unit_id, c.company_id;

  IF NOT FOUND THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  INSERT INTO public.contract_balances (
    contract_id, tenant_id, unit_id, total_invoiced, total_paid, balance_due, company_id, updated_at
  ) VALUES (
    v_contract_id::uuid,
    v_tenant_id::uuid,
    v_unit_id::uuid,
    v_total_invoiced,
    v_total_paid,
    v_total_invoiced - v_total_paid,
    v_company_id,
    now()
  )
  ON CONFLICT (contract_id) DO UPDATE SET
    tenant_id = EXCLUDED.tenant_id,
    unit_id = EXCLUDED.unit_id,
    total_invoiced = EXCLUDED.total_invoiced,
    total_paid = EXCLUDED.total_paid,
    balance_due = EXCLUDED.balance_due,
    company_id = EXCLUDED.company_id,
    updated_at = now();

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."update_contract_balance_from_invoice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_contract_balance_on_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_contract_id text;
begin
  v_contract_id := case when tg_op = 'DELETE'
    then old.contract_id else new.contract_id end;

  insert into public.contract_balances (
    contract_id,
    tenant_id,
    unit_id,
    total_invoiced,
    total_paid,
    balance_due,
    updated_at,
    company_id
  )
  select
    c.id,
    c.tenant_id,
    c.unit_id::text,
    coalesce(sum(i.amount + coalesce(i.tax_amount, 0)), 0),
    coalesce(sum(i.paid_amount), 0),
    coalesce(sum(i.amount + coalesce(i.tax_amount, 0) - i.paid_amount), 0),
    now(),
    c.company_id
  from public.contracts c
  left join public.invoices i
    on i.contract_id = c.id
   and i.deleted_at is null
   and i.company_id = c.company_id
  where c.id = v_contract_id
  group by c.id, c.tenant_id, c.unit_id, c.company_id
  on conflict (contract_id) do update set
    tenant_id = excluded.tenant_id,
    unit_id = excluded.unit_id,
    total_invoiced = excluded.total_invoiced,
    total_paid = excluded.total_paid,
    balance_due = excluded.balance_due,
    updated_at = now(),
    company_id = excluded.company_id;

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."update_contract_balance_on_invoice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_contract_balance_on_receipt_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  insert into contract_balances (contract_id, tenant_id, unit_id, total_invoiced, total_paid, balance_due, company_id, updated_at)
  select c.id, c.tenant_id, c.unit_id,
    coalesce(sum(i.amount + coalesce(i.tax_amount, 0)), 0),
    coalesce(sum(i.paid_amount), 0),
    coalesce(sum(i.amount + coalesce(i.tax_amount, 0) - i.paid_amount), 0),
    c.company_id,
    now()
  from contracts c
  left join invoices i on i.contract_id = c.id and i.status != 'VOID'
  where c.id in (
    select distinct contract_id from invoices
    where id = coalesce(NEW.invoice_id, OLD.invoice_id)
  )
  group by c.id, c.tenant_id, c.unit_id, c.company_id
  on conflict (contract_id) do update set
    total_invoiced = excluded.total_invoiced,
    total_paid = excluded.total_paid,
    balance_due = excluded.balance_due,
    company_id = excluded.company_id,
    updated_at = now();
  return coalesce(NEW, OLD);
end;
$$;


