CREATE OR REPLACE FUNCTION "public"."update_owner_agreement_atomic"("p_agreement_id" "uuid", "payload" "jsonb") RETURNS "public"."owner_agreements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_company_id uuid;
  v_row public.owner_agreements%rowtype;
  v_old public.owner_agreements%rowtype;
  v_commission_value numeric;
  v_starts_on date;
  v_ends_on date;
  v_changed_fields jsonb := '{}'::jsonb;
  v_updated_count integer := 0;
begin
  if v_actor_id is null or not public.is_admin_or_manager() then
    raise exception 'غير مصرح: يحتاج هذا الإجراء صلاحية مدير أو مشرف.'
      using errcode = '42501';
  end if;

  -- The company is derived from the trusted JWT context.  A missing context
  -- fails before the agreement UUID is read, so it cannot be used as an
  -- existence oracle.
  v_company_id := public.require_company_id();

  -- Deliberately use the same not-found error for an unknown UUID and a UUID
  -- belonging to another company.  The row lock also serializes concurrent
  -- updates to the same in-company agreement.
  select oa.*
    into v_old
    from public.owner_agreements as oa
   where oa.id = p_agreement_id
     and oa.company_id = v_company_id
   for update;

  if not found then
    raise exception 'AGREEMENT_NOT_FOUND_OR_FORBIDDEN'
      using errcode = '42501';
  end if;

  -- Relationship columns are not part of the supported update contract.  If
  -- an old/new client sends them, reject a change rather than permitting a
  -- cross-company rebind.  This does not reveal the requested row.
  if payload ? 'company_id'
     and nullif(payload->>'company_id', '') is distinct from v_old.company_id::text then
    raise exception 'AGREEMENT_RELATIONSHIP_IMMUTABLE'
      using errcode = '42501';
  end if;
  if payload ? 'owner_id'
     and nullif(payload->>'owner_id', '')::uuid is distinct from v_old.owner_id then
    raise exception 'AGREEMENT_RELATIONSHIP_IMMUTABLE'
      using errcode = '42501';
  end if;
  if payload ? 'property_id'
     and nullif(payload->>'property_id', '') is distinct from v_old.property_id::text then
    raise exception 'AGREEMENT_RELATIONSHIP_IMMUTABLE'
      using errcode = '42501';
  end if;

  -- Validate the existing relationships as well as the requested row.  The
  -- update path never infers a company from owner_id or property_id.
  if not exists (
    select 1
      from public.owners as o
     where o.id = v_old.owner_id
       and o.company_id = v_company_id
       and o.deleted_at is null
  ) or not exists (
    select 1
      from public.properties as p
     where p.id::text = v_old.property_id::text
       and p.company_id = v_company_id
       and p.deleted_at is null
  ) then
    raise exception 'AGREEMENT_RELATIONSHIP_IMMUTABLE'
      using errcode = '42501';
  end if;

  -- Parse and validate before UPDATE.  PostgreSQL numeric accepts NaN, so it
  -- is rejected explicitly; table constraints remain the final backstop.
  if payload ? 'commission_type' then
    if nullif(btrim(payload->>'commission_type'), '') is null
       or payload->>'commission_type' not in ('RATE', 'FIXED_MONTHLY') then
      raise exception 'نوع العمولة غير مدعوم' using errcode = '22023';
    end if;
  end if;

  if payload ? 'commission_value'
     and nullif(btrim(payload->>'commission_value'), '') is null then
    raise exception 'قيمة العمولة مطلوبة عند إرسال commission_value'
      using errcode = '22023';
  end if;

  v_commission_value := case
    when payload ? 'commission_value' then (payload->>'commission_value')::numeric
    else v_old.commission_value
  end;
  if v_commission_value::text in ('NaN', 'Infinity', '-Infinity') then
    raise exception 'قيمة العمولة غير صالحة' using errcode = '22023';
  end if;

  if coalesce(nullif(payload->>'commission_type', ''), v_old.commission_type) = 'RATE'
     and (v_commission_value < 0 or v_commission_value > 100) then
    raise exception 'نسبة العمولة يجب أن تكون بين 0 و100 عند نوع RATE'
      using errcode = '22023';
  end if;
  if coalesce(nullif(payload->>'commission_type', ''), v_old.commission_type) = 'FIXED_MONTHLY'
     and v_commission_value < 0 then
    raise exception 'قيمة العمولة الثابتة لا يمكن أن تكون سالبة'
      using errcode = '22023';
  end if;

  v_starts_on := case
    when payload ? 'starts_on' then (payload->>'starts_on')::date
    else v_old.starts_on
  end;
  v_ends_on := case
    when payload ? 'ends_on' then nullif(payload->>'ends_on', '')::date
    else v_old.ends_on
  end;
  if v_starts_on is null or (v_ends_on is not null and v_ends_on < v_starts_on) then
    raise exception 'فترة الاتفاقية غير صحيحة' using errcode = '22023';
  end if;

  update public.owner_agreements as oa
     set agreement_type = coalesce(nullif(payload->>'agreement_type', ''), oa.agreement_type),
         commission_type = coalesce(nullif(payload->>'commission_type', ''), oa.commission_type),
         commission_value = case when payload ? 'commission_value' then v_commission_value else oa.commission_value end,
         starts_on = v_starts_on,
         ends_on = v_ends_on,
         notes = case when payload ? 'notes' then nullif(payload->>'notes', '') else oa.notes end,
         updated_at = now()
   where oa.id = p_agreement_id
     and oa.company_id = v_company_id
   returning oa.* into v_row;

  get diagnostics v_updated_count = row_count;
  if v_updated_count <> 1 or not found then
    raise exception 'AGREEMENT_NOT_FOUND_OR_FORBIDDEN'
      using errcode = '42501';
  end if;

  -- Audit only the in-company row and only changed, non-secret fields.  The
  -- company is included in details because audit_log has no company_id column.
  if v_old is distinct from v_row then
    if v_old.agreement_type is distinct from v_row.agreement_type then
      v_changed_fields := v_changed_fields || jsonb_build_object('agreement_type', jsonb_build_object('old', v_old.agreement_type, 'new', v_row.agreement_type));
    end if;
    if v_old.commission_type is distinct from v_row.commission_type then
      v_changed_fields := v_changed_fields || jsonb_build_object('commission_type', jsonb_build_object('old', v_old.commission_type, 'new', v_row.commission_type));
    end if;
    if v_old.commission_value is distinct from v_row.commission_value then
      v_changed_fields := v_changed_fields || jsonb_build_object('commission_value', jsonb_build_object('old', v_old.commission_value, 'new', v_row.commission_value));
    end if;
    if v_old.starts_on is distinct from v_row.starts_on then
      v_changed_fields := v_changed_fields || jsonb_build_object('starts_on', jsonb_build_object('old', v_old.starts_on, 'new', v_row.starts_on));
    end if;
    if v_old.ends_on is distinct from v_row.ends_on then
      v_changed_fields := v_changed_fields || jsonb_build_object('ends_on', jsonb_build_object('old', v_old.ends_on, 'new', v_row.ends_on));
    end if;
    if v_old.notes is distinct from v_row.notes then
      v_changed_fields := v_changed_fields || jsonb_build_object('notes', jsonb_build_object('old', v_old.notes, 'new', v_row.notes));
    end if;

    insert into public.audit_log (
      id, ts, user_id, username, action, entity, entity_id, note, "table",
      details, action_timestamp, created_at
    ) values (
      gen_random_uuid()::text,
      extract(epoch from now())::bigint,
      v_actor_id,
      v_actor_id::text,
      'UPDATE',
      'owner_agreement',
      v_row.id::text,
      'Owner agreement updated within the caller company.',
      'owner_agreements',
      jsonb_build_object(
        'company_id', v_company_id,
        'agreement_id', v_row.id,
        'actor_id', v_actor_id,
        'changed_fields', v_changed_fields,
        'timestamp', now()
      )::text,
      now(),
      now()
    );
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_owner_agreement_atomic"("p_agreement_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_owner_agreement_atomic"("p_agreement_id" "uuid", "payload" "jsonb") IS 'FA-004: company isolation is enforced inside this SECURITY DEFINER RPC; agreement reads and writes require the caller company.';



CREATE OR REPLACE FUNCTION "public"."update_owner_balance_from_operation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_new_contract_id public.contracts.id%TYPE;
  v_old_contract_id public.contracts.id%TYPE;
  v_new_property_id public.properties.id%TYPE;
  v_old_property_id public.properties.id%TYPE;
  v_owner_id uuid;
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    IF TG_TABLE_NAME = 'payments' THEN
      v_new_contract_id := NEW.contract_id;
    ELSE
      v_new_property_id := NEW.property_id;
    END IF;
  END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    IF TG_TABLE_NAME = 'payments' THEN
      v_old_contract_id := OLD.contract_id;
    ELSE
      v_old_property_id := OLD.property_id;
    END IF;
  END IF;

  FOR v_owner_id IN
    SELECT DISTINCT candidate.owner_id
    FROM (
      SELECT oa.owner_id
      FROM public.contracts c JOIN public.owner_agreements oa ON oa.id = c.agreement_id
      WHERE c.id IN (v_new_contract_id, v_old_contract_id)
      UNION ALL
      SELECT po.owner_id
      FROM public.property_owners po
      WHERE po.property_id IN (v_new_property_id, v_old_property_id)
    ) candidate
  LOOP
    PERFORM public.recalculate_owner_balance(v_owner_id);
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."update_owner_balance_from_operation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_owner_balance_on_expense"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_property_id text;
  v_contract_id text;
begin
  if tg_table_name = 'expenses' then
    v_property_id := coalesce(NEW.property_id, OLD.property_id);
    v_contract_id := coalesce(NEW.contract_id, OLD.contract_id);
  else
    v_property_id := null;
    v_contract_id := coalesce(NEW.contract_id, OLD.contract_id);
  end if;

  insert into owner_balances (owner_id, total_income, total_expenses, commission, net_balance, updated_at, company_id)
  select o.id,
    coalesce(sum(case when r.status = 'POSTED' then r.amount else 0 end), 0),
    coalesce(sum(case when e.status = 'POSTED' and e.charged_to in ('OWNER', 'OFFICE') then e.amount else 0 end), 0),
    coalesce(sum(case when r.status = 'POSTED' then r.amount * coalesce(o.commission_value / 100, 0.05) else 0 end), 0),
    0,
    now(),
    o.company_id
  from owners o
  left join properties p on p.owner_id = o.id
  left join units u on u.property_id = p.id
  left join contracts c on c.unit_id = u.id and c.deleted_at is null
  left join receipts r on r.contract_id = c.id
  left join expenses e on (e.contract_id = c.id or e.property_id = p.id)
  where o.id = coalesce(
    (select owner_id from properties where id = v_property_id),
    (select p2.owner_id from contracts c2 join properties p2 on p2.id = c2.property_id where c2.id = v_contract_id)
  )
  group by o.id, o.commission_value, o.company_id
  on conflict (owner_id) do update set
    total_income = excluded.total_income,
    total_expenses = excluded.total_expenses,
    commission = excluded.commission,
    net_balance = excluded.total_income - excluded.total_expenses - excluded.commission,
    updated_at = now();
  return coalesce(NEW, OLD);
end;
$$;


ALTER FUNCTION "public"."update_owner_balance_on_expense"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tenant_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant_id text;
  v_company_id uuid;
begin
  if tg_op = 'DELETE' then
    v_company_id := old.company_id;
  else
    v_company_id := new.company_id;
  end if;

  if tg_table_name = 'invoices' then
    if tg_op = 'DELETE' then
      select tenant_id
      into v_tenant_id
      from public.contracts
      where id = old.contract_id;
    else
      select tenant_id
      into v_tenant_id
      from public.contracts
      where id = new.contract_id;
    end if;
  else
    -- receipt_allocations: has its own tenant_id column, no contract_id.
    if tg_op = 'DELETE' then
      v_tenant_id := old.tenant_id;
    else
      v_tenant_id := new.tenant_id;
    end if;
  end if;

  if v_tenant_id is null then
    return coalesce(new, old);
  end if;

  insert into public.tenant_balances (
    tenant_id,
    balance_due,
    updated_at,
    company_id
  )
  select
    c.tenant_id,
    coalesce(sum(i.amount + coalesce(i.tax_amount, 0) - i.paid_amount), 0),
    now(),
    v_company_id
  from public.contracts c
  left join public.invoices i
    on i.contract_id = c.id
   and i.deleted_at is null
  where c.tenant_id = v_tenant_id
    and c.company_id = v_company_id
    and (i.id is null or i.company_id = v_company_id)
  group by c.tenant_id
  on conflict (tenant_id) do update set
    balance_due = excluded.balance_due,
    company_id = excluded.company_id,
    updated_at = now();

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."update_tenant_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_unit_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_unit_id uuid;
  v_unit_ids uuid[];
  v_current_status text;
  v_target_status text;
begin
  if tg_op = 'DELETE' then
    v_unit_ids := array[old.unit_id];
  elsif tg_op = 'INSERT' then
    v_unit_ids := array[new.unit_id];
  else
    v_unit_ids := array[old.unit_id, new.unit_id];
  end if;

  foreach v_unit_id in array v_unit_ids
  loop
    if v_unit_id is null then
      continue;
    end if;

    select u.status into v_current_status
    from public.units u
    where u.id = v_unit_id;

    if not found then
      continue;
    end if;

    v_target_status := public.resolve_unit_operational_status(v_unit_id, v_current_status);

    update public.units
    set status = v_target_status
    where id = v_unit_id
      and status is distinct from v_target_status;
  end loop;

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."update_unit_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_unit_status_from_activity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_unit_id uuid := coalesce(new.unit_id, old.unit_id);
begin
  if v_unit_id is null then
    return coalesce(new, old);
  end if;

  update public.units u
  set status = case
      when exists (
        select 1 from public.maintenance_records m
        where m.unit_id = v_unit_id
          and m.deleted_at is null
          and coalesce(m.status, '') in ('open', 'in_progress', 'urgent')
      ) then 'maintenance'
      when exists (
        select 1 from public.contracts c
        where c.unit_id = v_unit_id
          and c.deleted_at is null
          and lower(c.status) = 'active'
          and current_date between c.start_date and c.end_date
      ) then 'occupied'
      else 'available'
    end,
    updated_at = now()
  where u.id = v_unit_id;

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."update_unit_status_from_activity"() OWNER TO "postgres";


