CREATE OR REPLACE FUNCTION "public"."validate_journal_batch_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch_total numeric;
  v_entry_count integer;
BEGIN
  -- Only validate if batch_id is provided
  IF NEW.batch_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Calculate current batch balance
  SELECT 
    SUM(CASE WHEN type = 'DEBIT' THEN amount ELSE -amount END),
    COUNT(*)
  INTO v_batch_total, v_entry_count
  FROM public.journal_entries
  WHERE batch_id = NEW.batch_id;

  -- Log warning if imbalanced (batch may still be inserting)
  IF v_batch_total <> 0 AND v_entry_count >= 2 THEN
    INSERT INTO public.audit_log (
      id, user_id, action, entity, entity_id, note, "table", details, created_at, updated_at
    ) VALUES (
      gen_random_uuid(),
      auth.uid(),
      'JOURNAL_BATCH_IMBALANCE_WARNING',
      'journal_batch',
      NEW.batch_id::text,
      format('Batch %s has imbalance of %s after %s entries. Call close_journal_batch() to validate.', 
             NEW.batch_id, v_batch_total, v_entry_count),
      'journal_entries',
      jsonb_build_object('batch_id', NEW.batch_id, 'imbalance', v_batch_total, 'entry_count', v_entry_count)::text,
      now(),
      now()
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_journal_batch_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_maintenance_service_provider_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.service_provider_category_id is not null and not exists (
    select 1
    from public.service_provider_categories c
    where c.id = new.service_provider_category_id
      and c.company_id = new.company_id
      and c.is_active
      and c.deleted_at is null
  ) then
    raise exception 'نوع الخدمة غير متاح للشركة الحالية' using errcode = '23503';
  end if;

  if new.service_provider_id is not null and not exists (
    select 1
    from public.service_providers p
    where p.id = new.service_provider_id
      and p.company_id = new.company_id
      and p.is_active
      and p.deleted_at is null
  ) then
    raise exception 'مزود الخدمة غير متاح للشركة الحالية' using errcode = '23503';
  end if;

  if new.service_provider_id is not null
     and new.service_provider_category_id is not null
     and not exists (
       select 1
       from public.service_provider_category_links link
       where link.company_id = new.company_id
         and link.service_provider_id = new.service_provider_id
         and link.category_id = new.service_provider_category_id
     ) then
    raise exception 'مزود الخدمة المحدد لا يدعم نوع الخدمة المختار' using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_maintenance_service_provider_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_property_owner_active_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_other_active_percentage_total numeric;
begin
  if new.ends_on is not null then
    return new;
  end if;

  select coalesce(sum(ownership_percentage), 0)
    into v_other_active_percentage_total
  from public.property_owners
  where property_id = new.property_id
    and ends_on is null
    and id <> coalesce(new.id, '00000000-0000-0000-0000-000000000000'::uuid);

  if v_other_active_percentage_total + new.ownership_percentage > 100 then
    raise exception 'Active ownership percentages for a property cannot exceed 100.';
  end if;

  return new;
end;
$$;


