CREATE OR REPLACE FUNCTION "public"."void_receipt_atomic"("p_receipt_id" "uuid", "p_voided_at" timestamp with time zone DEFAULT "now"(), "p_invoice_updates" "jsonb" DEFAULT '[]'::"jsonb", "p_reverse_entries" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_receipt public.receipts%rowtype;
  v_allocation record;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'ADMIN or MANAGER role is required to void receipts' using errcode = '42501';
  end if;

  select * into v_receipt from public.receipts where id = p_receipt_id for update;
  if not found then
    raise exception 'Receipt not found';
  end if;
  if v_receipt.status = 'VOID' then
    return jsonb_build_object('success', true, 'idempotent', true, 'voided_at', coalesce(v_receipt.voided_at, p_voided_at)::text);
  end if;

  update public.receipts
  set status = 'VOID', voided_at = p_voided_at, updated_at = now()
  where id = p_receipt_id;

  update public.payments
  set status = 'VOID', deleted_at = p_voided_at, updated_at = now()
  where receipt_id = p_receipt_id;

  for v_allocation in select * from public.receipt_allocations where receipt_id = p_receipt_id
  loop
    update public.invoices
    set paid_amount = greatest(0, coalesce(paid_amount, 0) - v_allocation.amount),
      updated_at = now()
    where id = v_allocation.invoice_id;

    perform public.recalculate_invoice_status(v_allocation.invoice_id);
  end loop;

  delete from public.receipt_allocations where receipt_id = p_receipt_id;
  return jsonb_build_object('success', true, 'idempotent', false, 'voided_at', p_voided_at::text);
end;
$$;


ALTER FUNCTION "public"."void_receipt_atomic"("p_receipt_id" "uuid", "p_voided_at" timestamp with time zone, "p_invoice_updates" "jsonb", "p_reverse_entries" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."waive_onboarding_requirement_atomic"("p_code" "text", "p_reason" "text", "p_evidence_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company  uuid := public.require_company_id();
  v_actor    uuid := auth.uid();
  v_authority text := coalesce(public.current_app_role(), 'ADMIN');
  v_template public.onboarding_requirement_templates%rowtype;
  v_result   jsonb;
begin
  if v_actor is null or not public.is_admin() then
    raise exception 'ONBOARDING_WAIVER_ADMIN_REQUIRED' using errcode = '42501';
  end if;

  select * into v_template
  from public.onboarding_requirement_templates
  where code = p_code;

  if not found then
    raise exception 'ONBOARDING_REQUIREMENT_UNKNOWN' using errcode = '22023';
  end if;

  if v_template.waiver_policy = 'NON_WAIVABLE' then
    raise exception 'ONBOARDING_REQUIREMENT_NON_WAIVABLE' using errcode = '23514';
  end if;

  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'ONBOARDING_WAIVER_REASON_REQUIRED' using errcode = '22023';
  end if;

  insert into public.company_onboarding_waivers (
    company_id, requirement_code, waived_by, waiver_reason,
    waiver_authority, evidence_reference
  ) values (
    v_company, v_template.code, v_actor, btrim(p_reason),
    v_authority, nullif(btrim(coalesce(p_evidence_reference, '')), '')
  )
  on conflict (company_id, requirement_code) do update
    set waived_by          = excluded.waived_by,
        waived_at          = now(),
        waiver_reason      = excluded.waiver_reason,
        waiver_authority   = excluded.waiver_authority,
        evidence_reference = excluded.evidence_reference,
        revoked_at         = null,
        revoked_by         = null
  returning to_jsonb(public.company_onboarding_waivers.*) into v_result;

  insert into public.company_onboarding_events (
    company_id, requirement_code, action, actor, authority, reason, evidence_reference
  ) values (
    v_company, v_template.code, 'WAIVE', v_actor, v_authority,
    btrim(p_reason), nullif(btrim(coalesce(p_evidence_reference, '')), '')
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."waive_onboarding_requirement_atomic"("p_code" "text", "p_reason" "text", "p_evidence_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp01_audit_sole_admin_setting_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_old_val boolean := false;
  v_new_val boolean := coalesce(new.allow_sole_admin_self_approval, false);
  v_reason text := nullif(current_setting('public.set_sole_admin_rpc_reason', true), '');
  v_setting_changed boolean := false;
begin
  if tg_op = 'INSERT' then
    -- Initial FALSE/default FALSE is ordinary company-settings bootstrap and
    -- is not an activation. Initial TRUE is a sensitive activation and must
    -- come through the governed RPC.
    v_setting_changed := v_new_val = true;
  else
    v_old_val := coalesce(old.allow_sole_admin_self_approval, false);
    v_setting_changed := v_old_val is distinct from v_new_val;
  end if;

  if v_setting_changed then
    if nullif(current_setting('public.set_sole_admin_rpc_context', true), '') is distinct from 'active' then
      raise exception 'SOLE_ADMIN_SETTING_DIRECT_WRITE_PROHIBITED: allow_sole_admin_self_approval cannot be mutated directly; must use set_sole_admin_self_approval_atomic RPC.'
        using errcode = '42501';
    end if;

    if v_reason is null or length(btrim(v_reason)) < 4 then
      raise exception 'SOLE_ADMIN_REASON_REQUIRED: a non-empty reason of at least 4 characters is required to change this setting.'
        using errcode = '22023';
    end if;

    insert into public.audit_log (
      user_id,
      action,
      entity,
      entity_id,
      note,
      "table",
      details
    ) values (
      v_actor,
      'COMPANY_SETTING_CHANGE',
      'company_settings',
      new.company_id::text,
      'Sole Admin Self Approval setting ' ||
        case
          when tg_op = 'INSERT' then 'activated from default false to true'
          else 'changed from ' || v_old_val::text || ' to ' || v_new_val::text
        end ||
        ' with reason: ' || v_reason,
      'company_settings',
      jsonb_build_object(
        'field', 'allow_sole_admin_self_approval',
        'old_value', case when tg_op = 'INSERT' then false else v_old_val end,
        'new_value', v_new_val,
        'reason', v_reason,
        'actor', v_actor,
        'company_id', new.company_id,
        'timestamp', now()
      )::text
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."wp01_audit_sole_admin_setting_change"() OWNER TO "postgres";


