CREATE OR REPLACE FUNCTION "public"."wp05_approve_correction_proposal"("p_proposal_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_row public.wp05_correction_proposals%rowtype;
begin
  if auth.uid() is null or not (public.is_accountant() or public.is_admin()) then
    raise exception 'WP05_PROPOSAL_CHECKER_ROLE_REQUIRED: ACCOUNTANT or ADMIN required to approve a correction proposal' using errcode='42501';
  end if;
  if p_proposal_id is null then
    raise exception 'WP05_PROPOSAL_ID_REQUIRED' using errcode='22023';
  end if;

  select * into v_row
  from public.wp05_correction_proposals
  where id = p_proposal_id and company_id = v_company_id
  for update;

  if not found then
    raise exception 'WP05_PROPOSAL_NOT_FOUND: proposal % not found for company %', p_proposal_id, v_company_id using errcode='P0002';
  end if;
  if v_row.status <> 'PENDING_APPROVAL' then
    raise exception 'WP05_PROPOSAL_STATUS_INVALID: only PENDING_APPROVAL can be approved, current %', v_row.status using errcode='23514';
  end if;
  if v_row.maker_user_id is not null and v_row.maker_user_id = auth.uid() then
    raise exception 'WP05_PROPOSAL_MAKER_CHECKER_VIOLATION: the maker of a proposal cannot approve it' using errcode='42501';
  end if;

  perform set_config('malik.wp05_proposal_change_authorized', 'true', true);

  update public.wp05_correction_proposals
  set status = 'APPROVED',
      checker_user_id = auth.uid(),
      decided_at = now(),
      decision_note = nullif(btrim(coalesce(p_note, '')), ''),
      updated_at = now()
  where id = p_proposal_id and company_id = v_company_id;

  perform set_config('malik.wp05_proposal_change_authorized', 'false', true);

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at, old_value, new_value
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'WP05_PROPOSAL_APPROVED', 'wp05_correction_proposals', p_proposal_id::text,
    'Proposal approved for accounting action. Approval authorises an S09 correction; it does not post to the GL.',
    'wp05_correction_proposals', left(coalesce(p_note, ''), 4000), now(),
    jsonb_build_object('status', 'PENDING_APPROVAL'),
    jsonb_build_object('status', 'APPROVED', 'checker_user_id', auth.uid())
  );

  return jsonb_build_object(
    'success', true,
    'id', p_proposal_id,
    'status', 'APPROVED',
    'posted_to_gl', false,
    'next_step', 's09_create_correction_draft against an APPROVED S08 frozen review'
  );
end;
$$;


ALTER FUNCTION "public"."wp05_approve_correction_proposal"("p_proposal_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_assert_cash_flow"("p_from" "date", "p_to" "date", "p_allow_unclassified" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_report jsonb;
  v_variance numeric;
  v_unclassified numeric;
begin
  v_report := public.wp05_rpt_cash_flow_gl(p_from, p_to);
  v_variance := (v_report->>'variance')::numeric;
  v_unclassified := (v_report->>'unclassified')::numeric;

  if abs(coalesce(v_variance,0)) > 0.001 then
    raise exception 'WP05_CASHFLOW_VARIANCE_EXCEEDED: variance % exceeds tolerance 0.001 OMR, report %', v_variance, v_report::text using errcode='P0001';
  end if;

  if not p_allow_unclassified and abs(coalesce(v_unclassified,0)) > 0.001 then
    raise exception 'WP05_CASHFLOW_UNCLASSIFIED_PRESENT: unclassified cash movement % must be zero unless explicit governed exception exists, report %', v_unclassified, v_report::text using errcode='P0001';
  end if;

  return v_report;
end;
$$;


ALTER FUNCTION "public"."wp05_assert_cash_flow"("p_from" "date", "p_to" "date", "p_allow_unclassified" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_assert_no_unapproved_correction_postings"("p_company_id" "uuid" DEFAULT "public"."current_company_id"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_actor_user_id uuid := auth.uid();
  v_jwt_role text := coalesce(auth.role(), '');
  v_proposal_batches int;
  v_unapproved_s09 int;
  v_pending int;
  v_approved int;
  v_rejected int;
  v_offenders jsonb;
begin
  if v_actor_user_id is not null then
    if not public.is_app_user() then
      raise exception 'WP05_PROOF_APP_USER_REQUIRED: active app user required'
        using errcode = '42501';
    end if;

    v_company_id := public.require_company_id();
    if p_company_id is not null and p_company_id <> v_company_id then
      raise exception 'WP05_COMPANY_ISOLATION_VIOLATION'
        using errcode = '42501';
    end if;
  elsif v_jwt_role = 'service_role' or session_user in ('postgres', 'supabase_admin') then
    v_company_id := coalesce(p_company_id, public.current_company_id());
  else
    raise exception 'WP05_PROOF_AUTH_REQUIRED: authenticated app user or service role required'
      using errcode = '42501';
  end if;

  if v_company_id is null then
    raise exception 'WP05_PROOF_COMPANY_REQUIRED: company_id required'
      using errcode = '22023';
  end if;

  select count(*)::int into v_proposal_batches
  from public.journal_batches jb
  where jb.company_id = v_company_id
    and jb.source_type in ('wp05_correction_proposal', 'wp05_variance_correction');

  select count(*)::int into v_unapproved_s09
  from public.s09_corrections c
  join public.s08_frozen_reviews r on r.id = c.review_id
  where c.company_id = v_company_id
    and c.status = 'APPLIED'
    and r.reviewer_decision is distinct from 'APPROVED';

  select
    count(*) filter (where status = 'PENDING_APPROVAL')::int,
    count(*) filter (where status = 'APPROVED')::int,
    count(*) filter (where status = 'REJECTED')::int
  into v_pending, v_approved, v_rejected
  from public.wp05_correction_proposals
  where company_id = v_company_id;

  select coalesce(
    jsonb_agg(jsonb_build_object(
      'batch_id', jb.id,
      'source_type', jb.source_type,
      'source_id', jb.source_id
    )),
    '[]'::jsonb
  )
  into v_offenders
  from public.journal_batches jb
  where jb.company_id = v_company_id
    and jb.source_type in ('wp05_correction_proposal', 'wp05_variance_correction');

  return jsonb_build_object(
    'success', (v_proposal_batches = 0 and v_unapproved_s09 = 0),
    'company_id', v_company_id,
    'proposal_sourced_gl_batches', v_proposal_batches,
    'applied_s09_without_approved_s08', v_unapproved_s09,
    'proposals_pending_approval', v_pending,
    'proposals_approved', v_approved,
    'proposals_rejected', v_rejected,
    'offending_batches', v_offenders
  );
end;
$$;


ALTER FUNCTION "public"."wp05_assert_no_unapproved_correction_postings"("p_company_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."wp05_assert_no_unapproved_correction_postings"("p_company_id" "uuid") IS 'WP-05 GAP-018: tenant-safe proof that no proposal lane posted to GL and APPLIED S09 corrections trace to approved S08 reviews. SECURITY DEFINER authority is derived from JWT/session identity, never current_user.';



CREATE OR REPLACE FUNCTION "public"."wp05_assert_reconciliation"("p_company_id" "uuid" DEFAULT "public"."current_company_id"(), "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_failures int;
  v_details jsonb;
begin
  if p_company_id is null then
    raise exception 'WP05_ASSERT_COMPANY_REQUIRED: company_id required' using errcode='22023';
  end if;

  if public.current_company_id() is not null and public.current_company_id() <> p_company_id
     and current_user not in ('service_role','postgres','supabase_admin') then
    raise exception 'WP05_COMPANY_ISOLATION_VIOLATION' using errcode='42501';
  end if;

  select count(*)::int into v_failures
  from public.wp05_reconcile_all(p_company_id, p_as_of)
  where reconciliation_status = 'FAIL';

  select jsonb_agg(to_jsonb(r)) into v_details
  from public.wp05_reconcile_all(p_company_id, p_as_of) r;

  if v_failures > 0 then
    raise exception 'WP05_RECONCILIATION_FAILED: % class(es) exceed tolerance 0.001 OMR: %', v_failures, v_details::text using errcode='P0001';
  end if;

  return jsonb_build_object('success', true, 'company_id', p_company_id, 'as_of', p_as_of, 'details', v_details);
end;
$$;


ALTER FUNCTION "public"."wp05_assert_reconciliation"("p_company_id" "uuid", "p_as_of" "date") OWNER TO "postgres";


