CREATE OR REPLACE FUNCTION "public"."wp05_cash_flow_drillthrough"("p_from" "date", "p_to" "date", "p_classification" "text" DEFAULT NULL::"text") RETURNS TABLE("classification" "text", "account_id" "text", "account_no" "text", "account_name" "text", "batch_id" "uuid", "source_type" "text", "source_id" "text", "event_id" "text", "effective_date" "date", "posted_at" timestamp with time zone, "debit" numeric, "credit" numeric, "amount" numeric, "line_description" "text", "ref_source_id" "text", "ref_entity_type" "text", "ref_entity_id" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
begin
  if p_from is null or p_to is null then
    raise exception 'WP05_DRILLTHROUGH_PERIOD_REQUIRED' using errcode='22023';
  end if;

  return query
  with batches_with_cash as (
    select distinct jb.id
    from public.journal_batches jb
    join public.journal_lines jl on jl.batch_id = jb.id and jl.company_id = v_company_id
    join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
    where jb.company_id = v_company_id
      and jb.status in ('POSTED','REVERSED')
      and jb.effective_date between p_from and p_to
      and a.no = any(public.wp05_cash_accounts())
      and jl.deleted_at is null
  )
  select
    coalesce(cfc.classification, 'UNCLASSIFIED')::text as classification,
    a.id::text as account_id,
    a.no::text as account_no,
    a.name::text as account_name,
    jb.id as batch_id,
    jb.source_type::text,
    jb.source_id::text,
    jb.event_id::text,
    jb.effective_date,
    jb.posted_at,
    public.wp05_round_omr(jl.debit) as debit,
    public.wp05_round_omr(jl.credit) as credit,
    public.wp05_round_omr(jl.credit - jl.debit) as amount,
    jl.line_description::text,
    jl.ref_source_id::text,
    jl.ref_entity_type::text,
    jl.ref_entity_id::text
  from public.journal_batches jb
  join batches_with_cash bwc on bwc.id = jb.id
  join public.journal_lines jl on jl.batch_id = jb.id and jl.company_id = v_company_id and jl.deleted_at is null
  join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
  left join public.gl_cash_flow_classifications cfc on cfc.company_id = v_company_id and cfc.account_id = a.id and cfc.is_active = true
  where jb.company_id = v_company_id
    and a.no <> all(public.wp05_cash_accounts())
    and (p_classification is null or coalesce(cfc.classification, 'UNCLASSIFIED') = upper(p_classification))
  order by jb.effective_date, jb.created_at, jl.created_at;
end;
$$;


ALTER FUNCTION "public"."wp05_cash_flow_drillthrough"("p_from" "date", "p_to" "date", "p_classification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_enforce_proposal_governance_hardening"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_diag record;
  v_existing record;
  v_supersede_note constant text := 'Superseded by a refreshed variance diagnosis before approval.';
begin
  if tg_op = 'INSERT' then
    -- The proposal register is a maker lane only. Even privileged callers cannot
    -- inject a pre-decided row and make it look governed.
    if new.status <> 'PENDING_APPROVAL' then
      raise exception 'WP05_PROPOSAL_INITIAL_STATE_INVALID: proposals must be created PENDING_APPROVAL'
        using errcode = '42501';
    end if;
    if new.maker_user_id is null then
      raise exception 'WP05_PROPOSAL_MAKER_REQUIRED: maker_user_id is required'
        using errcode = '42501';
    end if;
    if new.checker_user_id is not null
       or new.decided_at is not null
       or new.decision_note is not null
       or new.s09_correction_id is not null then
      raise exception 'WP05_PROPOSAL_INITIAL_DECISION_INVALID: new proposals cannot contain checker, decision or S09 linkage data'
        using errcode = '42501';
    end if;

    -- A supplied accounting period must belong to the same company AND contain
    -- the diagnostic cut-off date. This prevents a July finding being labelled
    -- as a different accounting period even through privileged paths.
    if new.accounting_period_id is not null and not exists (
      select 1
      from public.accounting_periods ap
      where ap.id = new.accounting_period_id
        and ap.company_id = new.company_id
        and new.as_of between ap.start_date and ap.end_date
    ) then
      raise exception 'WP05_PROPOSAL_PERIOD_SCOPE_INVALID: period must belong to the company and contain as_of %', new.as_of
        using errcode = '23514';
    end if;

    -- A changed diagnosis for the same cut-off/class replaces only the ACTIVE
    -- pending decision. The old row is retained as SUPERSEDED evidence.
    for v_existing in
      select p.id, p.request_id, p.reconciliation_class
      from public.wp05_correction_proposals p
      where p.company_id = new.company_id
        and p.as_of = new.as_of
        and p.reconciliation_class = new.reconciliation_class
        and p.account_no is not distinct from new.account_no
        and p.status = 'PENDING_APPROVAL'
        and p.idempotency_key <> new.idempotency_key
      for update
    loop
      perform set_config('malik.wp05_proposal_change_authorized', 'true', true);

      update public.wp05_correction_proposals
      set status = 'SUPERSEDED',
          checker_user_id = null,
          decided_at = now(),
          decision_note = v_supersede_note,
          updated_at = now()
      where id = v_existing.id;

      perform set_config('malik.wp05_proposal_change_authorized', 'false', true);

      insert into public.audit_log (
        id, ts, user_id, username, action, entity, entity_id, note, "table",
        details, created_at, old_value, new_value
      ) values (
        gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
        (select email from auth.users where id = auth.uid()),
        'WP05_PROPOSAL_SUPERSEDED', 'wp05_correction_proposals', v_existing.id::text,
        v_supersede_note,
        'wp05_correction_proposals',
        format('request_id=%s; class=%s', v_existing.request_id, v_existing.reconciliation_class),
        now(),
        jsonb_build_object('status', 'PENDING_APPROVAL'),
        jsonb_build_object('status', 'SUPERSEDED', 'superseded_by_idempotency_key', new.idempotency_key)
      );
    end loop;

    return new;
  end if;

  -- The base guard already freezes company, scope, balances, evidence, maker and
  -- idempotency identity. Harden the remaining finding fields and period link.
  if old.accounting_period_id is distinct from new.accounting_period_id
     or old.reason_detail is distinct from new.reason_detail
     or old.proposal_type is distinct from new.proposal_type
     or old.recommended_action is distinct from new.recommended_action then
    raise exception 'WP05_PROPOSAL_IMMUTABLE_FIELD: period and finding metadata are immutable evidence'
      using errcode = '42501';
  end if;

  -- There is no governed S09-linking RPC in GAP-018. Until one exists, this link
  -- cannot be populated by an update that merely has the internal GUC set.
  if old.s09_correction_id is distinct from new.s09_correction_id then
    raise exception 'WP05_PROPOSAL_IMMUTABLE_FIELD: s09_correction_id requires a dedicated governed linkage path'
      using errcode = '42501';
  end if;

  if old.status = new.status then
    if old.checker_user_id is distinct from new.checker_user_id
       or old.decided_at is distinct from new.decided_at
       or old.decision_note is distinct from new.decision_note then
      raise exception 'WP05_PROPOSAL_DECISION_IMMUTABLE: decision metadata can change only with the PENDING_APPROVAL lifecycle transition'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if old.status <> 'PENDING_APPROVAL' then
    -- The base guard also enforces this; keeping it here makes the hardening
    -- invariant independent of trigger ordering.
    raise exception 'WP05_PROPOSAL_LIFECYCLE_TERMINAL: % is terminal', old.status
      using errcode = '23514';
  end if;

  if new.status = 'APPROVED' then
    if new.checker_user_id is null or new.decided_at is null then
      raise exception 'WP05_PROPOSAL_DECISION_INCOMPLETE: approval requires checker and decided_at'
        using errcode = '42501';
    end if;

    -- Approval is valid only while the exact frozen finding is still current.
    -- A same-size variance with changed underlying evidence is stale too.
    select * into v_diag
    from public.wp05_variance_diagnostics(new.company_id, new.as_of) d
    where d.reconciliation_class = new.reconciliation_class
      and d.account_no is not distinct from new.account_no
    limit 1;

    if not found
       or v_diag.reconciliation_status <> 'FAIL'
       or v_diag.reason_code is distinct from old.reason_code
       or v_diag.reason_detail is distinct from old.reason_detail
       or v_diag.proposal_type is distinct from old.proposal_type
       or v_diag.recommended_action is distinct from old.recommended_action
       or v_diag.subledger_balance is distinct from old.subledger_balance
       or v_diag.gl_balance is distinct from old.gl_balance
       or v_diag.variance is distinct from old.variance_amount
       or v_diag.evidence is distinct from old.evidence then
      raise exception 'WP05_PROPOSAL_STALE: diagnosis changed after proposal creation; regenerate before approval'
        using errcode = '23514';
    end if;

  elsif new.status = 'REJECTED' then
    if new.checker_user_id is null
       or new.decided_at is null
       or new.decision_note is null
       or btrim(new.decision_note) = '' then
      raise exception 'WP05_PROPOSAL_DECISION_INCOMPLETE: rejection requires checker, decided_at and a non-empty reason'
        using errcode = '42501';
    end if;

  elsif new.status = 'SUPERSEDED' then
    if new.checker_user_id is not null
       or new.decided_at is null
       or new.decision_note is null
       or btrim(new.decision_note) = '' then
      raise exception 'WP05_PROPOSAL_SUPERSEDE_INVALID: supersede requires decided_at/note and no checker'
        using errcode = '42501';
    end if;

  else
    raise exception 'WP05_PROPOSAL_LIFECYCLE_ILLEGAL: unsupported transition to %', new.status
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."wp05_enforce_proposal_governance_hardening"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_generate_correction_proposals"("p_as_of" "date" DEFAULT CURRENT_DATE, "p_request_id" "text" DEFAULT NULL::"text", "p_accounting_period_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_request_id text;
  v_row record;
  v_key text;
  v_id uuid;
  v_created int := 0;
  v_existing int := 0;
  v_reconciled int := 0;
  v_results jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not public.is_admin_or_manager() then
    raise exception 'WP05_PROPOSAL_MAKER_ROLE_REQUIRED: ADMIN or MANAGER required to generate correction proposals' using errcode='42501';
  end if;

  v_request_id := coalesce(nullif(btrim(coalesce(p_request_id, '')), ''),
                           'wp05-diag:' || v_company_id::text || ':' || p_as_of::text);

  if p_accounting_period_id is not null
     and not exists (select 1 from public.accounting_periods ap
                     where ap.id = p_accounting_period_id and ap.company_id = v_company_id) then
    raise exception 'WP05_PROPOSAL_PERIOD_NOT_FOUND: accounting period % not found for company %', p_accounting_period_id, v_company_id using errcode='P0002';
  end if;

  for v_row in
    select * from public.wp05_variance_diagnostics(v_company_id, p_as_of)
  loop
    if v_row.reconciliation_status = 'PASS' then
      v_reconciled := v_reconciled + 1;
      continue;
    end if;

    -- Deterministic identity: same company, cut-off, class, reason and variance
    -- always resolves to the same proposal row.
    v_key := encode(sha256(convert_to(
      v_company_id::text || '|' || p_as_of::text || '|' || v_row.reconciliation_class || '|' ||
      coalesce(v_row.account_no, '') || '|' || v_row.reason_code || '|' ||
      to_char(v_row.variance, 'FM9999999999990.000'), 'UTF8')), 'hex');

    select id into v_id
    from public.wp05_correction_proposals
    where company_id = v_company_id and idempotency_key = v_key;

    if v_id is not null then
      v_existing := v_existing + 1;
      v_results := v_results || jsonb_build_object(
        'id', v_id,
        'reconciliation_class', v_row.reconciliation_class,
        'reason_code', v_row.reason_code,
        'idempotent', true
      );
      continue;
    end if;

    insert into public.wp05_correction_proposals (
      company_id, accounting_period_id, as_of, reconciliation_class, account_no,
      reason_code, reason_detail, proposal_type, recommended_action, status,
      subledger_balance, gl_balance, variance_amount, evidence,
      maker_user_id, request_id, idempotency_key
    ) values (
      v_company_id, p_accounting_period_id, p_as_of, v_row.reconciliation_class, v_row.account_no,
      v_row.reason_code, v_row.reason_detail, v_row.proposal_type, v_row.recommended_action, 'PENDING_APPROVAL',
      v_row.subledger_balance, v_row.gl_balance, v_row.variance, v_row.evidence,
      auth.uid(), v_request_id, v_key
    )
    returning id into v_id;

    v_created := v_created + 1;
    v_results := v_results || jsonb_build_object(
      'id', v_id,
      'reconciliation_class', v_row.reconciliation_class,
      'reason_code', v_row.reason_code,
      'proposal_type', v_row.proposal_type,
      'variance', v_row.variance,
      'status', 'PENDING_APPROVAL',
      'idempotent', false
    );

    insert into public.audit_log (
      id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at, new_value
    ) values (
      gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
      (select email from auth.users where id = auth.uid()),
      'WP05_PROPOSAL_CREATED', 'wp05_correction_proposals', v_id::text,
      format('Variance proposal raised for %s (%s), left PENDING_APPROVAL; no GL posting performed.',
             v_row.reconciliation_class, v_row.reason_code),
      'wp05_correction_proposals',
      left(v_row.evidence::text, 4000), now(),
      jsonb_build_object('status', 'PENDING_APPROVAL', 'reason_code', v_row.reason_code,
                         'variance', v_row.variance, 'as_of', p_as_of)
    );
  end loop;

  return jsonb_build_object(
    'success', true,
    'company_id', v_company_id,
    'as_of', p_as_of,
    'request_id', v_request_id,
    'created', v_created,
    'already_present', v_existing,
    'reconciled_classes', v_reconciled,
    'posted_to_gl', false,
    'proposals', v_results
  );
end;
$$;


ALTER FUNCTION "public"."wp05_generate_correction_proposals"("p_as_of" "date", "p_request_id" "text", "p_accounting_period_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."wp05_generate_correction_proposals"("p_as_of" "date", "p_request_id" "text", "p_accounting_period_id" "uuid") IS 'WP-05 GAP-018: maker step. Turns FAIL reconciliation classes into PENDING_APPROVAL proposals. Deterministic and idempotent; performs no GL posting.';



CREATE OR REPLACE FUNCTION "public"."wp05_gl_balance"("p_company_id" "uuid", "p_account_no" "text", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_bal numeric;
begin
  if p_company_id is null or p_account_no is null then
    raise exception 'WP05_GL_BALANCE_REQUIRED: company_id and account_no required' using errcode='22023';
  end if;

  select public.wp05_round_omr(coalesce(sum(
    case
      when a.no in ('1201','1300','1111','1120','1600') then (jl.debit - jl.credit)
      when a.no in ('2000','2100','2200','2300','2500') then (jl.credit - jl.debit)
      when a.account_type = 'asset' or a.account_type = 'expense' then (jl.debit - jl.credit)
      else (jl.credit - jl.debit)
    end
  ),0))
  into v_bal
  from public.journal_lines jl
  join public.journal_batches jb on jb.id = jl.batch_id
  join public.accounts a on a.id = jl.account_id and a.company_id = jl.company_id
  where jl.company_id = p_company_id
    and a.no = p_account_no
    and a.company_id = p_company_id
    and jb.company_id = p_company_id
    and jb.status in ('POSTED','REVERSED')
    and jb.effective_date <= p_as_of
    and jl.deleted_at is null;

  return coalesce(v_bal, 0);
end;
$$;


ALTER FUNCTION "public"."wp05_gl_balance"("p_company_id" "uuid", "p_account_no" "text", "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_gl_drillthrough"("p_from" "date", "p_to" "date", "p_account_no" "text" DEFAULT NULL::"text") RETURNS TABLE("account_no" "text", "account_name" "text", "batch_id" "uuid", "source_type" "text", "source_id" "text", "event_id" "text", "effective_date" "date", "posted_at" timestamp with time zone, "status" "text", "debit" numeric, "credit" numeric, "line_description" "text", "ref_source_id" "text", "ref_entity_type" "text", "ref_entity_id" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
begin
  return query
  select
    a.no::text,
    a.name::text,
    jb.id,
    jb.source_type::text,
    jb.source_id::text,
    jb.event_id::text,
    jb.effective_date,
    jb.posted_at,
    jb.status::text,
    public.wp05_round_omr(jl.debit),
    public.wp05_round_omr(jl.credit),
    jl.line_description::text,
    jl.ref_source_id::text,
    jl.ref_entity_type::text,
    jl.ref_entity_id::text
  from public.journal_lines jl
  join public.journal_batches jb on jb.id = jl.batch_id and jb.company_id = v_company_id and jb.status in ('POSTED','REVERSED') and jb.effective_date between p_from and p_to
  join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
  where jl.company_id = v_company_id
    and jl.deleted_at is null
    and (p_account_no is null or a.no = p_account_no)
  order by jb.effective_date, jb.created_at, jl.created_at;
end;
$$;


ALTER FUNCTION "public"."wp05_gl_drillthrough"("p_from" "date", "p_to" "date", "p_account_no" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_gl_line_count"("p_company_id" "uuid", "p_account_no" "text", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS bigint
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_cnt bigint;
begin
  if p_company_id is null or p_account_no is null then
    raise exception 'WP05_GL_COUNT_REQUIRED: company_id and account_no required' using errcode='22023';
  end if;

  select count(*)::bigint into v_cnt
  from public.journal_lines jl
  join public.journal_batches jb on jb.id = jl.batch_id
  join public.accounts a on a.id = jl.account_id and a.company_id = jl.company_id
  where jl.company_id = p_company_id
    and a.no = p_account_no
    and a.company_id = p_company_id
    and jb.company_id = p_company_id
    and jb.status in ('POSTED','REVERSED')
    and jb.effective_date <= p_as_of
    and jl.deleted_at is null;

  return coalesce(v_cnt,0);
end;
$$;


ALTER FUNCTION "public"."wp05_gl_line_count"("p_company_id" "uuid", "p_account_no" "text", "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_gl_side_totals"("p_company_id" "uuid", "p_account_no" "text", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("debits" numeric, "credits" numeric, "line_count" bigint, "account_exists" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_exists boolean;
begin
  if p_company_id is null or p_account_no is null then
    raise exception 'WP05_GL_SIDE_TOTALS_REQUIRED: company_id and account_no required' using errcode='22023';
  end if;

  select exists (
    select 1 from public.accounts a
    where a.company_id = p_company_id and a.no = p_account_no
  ) into v_exists;

  return query
  select
    public.wp05_round_omr(coalesce(sum(jl.debit), 0)),
    public.wp05_round_omr(coalesce(sum(jl.credit), 0)),
    count(*)::bigint,
    v_exists
  from public.journal_lines jl
  join public.journal_batches jb on jb.id = jl.batch_id
  join public.accounts a on a.id = jl.account_id and a.company_id = jl.company_id
  where jl.company_id = p_company_id
    and a.no = p_account_no
    and a.company_id = p_company_id
    and jb.company_id = p_company_id
    and jb.status in ('POSTED', 'REVERSED')
    and jb.effective_date <= p_as_of
    and jl.deleted_at is null;
end;
$$;


ALTER FUNCTION "public"."wp05_gl_side_totals"("p_company_id" "uuid", "p_account_no" "text", "p_as_of" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."wp05_gl_side_totals"("p_company_id" "uuid", "p_account_no" "text", "p_as_of" "date") IS 'WP-05 GAP-018: debit/credit totals and COA presence for one account, company-scoped, OMR 3dp.';



CREATE OR REPLACE FUNCTION "public"."wp05_list_correction_proposals"("p_status" "text" DEFAULT NULL::"text", "p_as_of" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_rows jsonb;
begin
  if auth.uid() is null or not public.is_app_user() then
    raise exception 'Authenticated app user required' using errcode='42501';
  end if;

  select jsonb_agg(jsonb_build_object(
    'id', p.id,
    'company_id', p.company_id,
    'as_of', p.as_of,
    'reconciliation_class', p.reconciliation_class,
    'account_no', p.account_no,
    'reason_code', p.reason_code,
    'reason_detail', p.reason_detail,
    'proposal_type', p.proposal_type,
    'recommended_action', p.recommended_action,
    'status', p.status,
    'subledger_balance', p.subledger_balance,
    'gl_balance', p.gl_balance,
    'variance_amount', p.variance_amount,
    'evidence', p.evidence,
    'maker_user_id', p.maker_user_id,
    'checker_user_id', p.checker_user_id,
    'decided_at', p.decided_at,
    'decision_note', p.decision_note,
    's09_correction_id', p.s09_correction_id,
    'created_at', p.created_at
  ) order by p.created_at desc, p.reconciliation_class)
  into v_rows
  from public.wp05_correction_proposals p
  where p.company_id = v_company_id
    and (p_status is null or p.status = upper(p_status))
    and (p_as_of is null or p.as_of = p_as_of);

  return jsonb_build_object('company_id', v_company_id, 'proposals', coalesce(v_rows, '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."wp05_list_correction_proposals"("p_status" "text", "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_provision_default_cashflow_classifications"("p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_created int := 0;
begin
  if p_company_id is null then
    raise exception 'WP05_CASHFLOW_CLASSIFICATION_COMPANY_REQUIRED' using errcode='22023';
  end if;

  -- Map known canonical accounts to classifications (explicit, not inferred from memo)
  -- Operating: revenue, expenses, receivables, payables related to operations
  -- Investing: ROU asset, etc.
  -- Financing: lease liability, owner funds payable payouts, etc.
  insert into public.gl_cash_flow_classifications (company_id, account_id, account_no, classification)
  select p_company_id, a.id, a.no,
    case
      when a.no in ('1201','1300','2100','2200','2300','4000','4100','4200','4300','6100','6110','6200') then 'OPERATING'
      when a.no in ('1600') then 'INVESTING'
      when a.no in ('2000','2500','6300') then 'FINANCING'
      else 'OPERATING'
    end
  from public.accounts a
  where a.company_id = p_company_id
    and a.no in ('1201','1300','1600','2000','2100','2200','2300','2500','4000','4100','4200','4300','6100','6110','6200','6300')
    and not exists (
      select 1 from public.gl_cash_flow_classifications c
      where c.company_id = p_company_id and c.account_id = a.id
    )
  on conflict (company_id, account_id) do nothing;

  get diagnostics v_created = row_count;

  return jsonb_build_object('company_id', p_company_id, 'created', v_created);
end;
$$;


ALTER FUNCTION "public"."wp05_provision_default_cashflow_classifications"("p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_reconcile_all"("p_company_id" "uuid" DEFAULT "public"."current_company_id"(), "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("reconciliation_class" "text", "account_no" "text", "account_name" "text", "subledger_balance" numeric, "gl_balance" numeric, "variance" numeric, "abs_variance" numeric, "currency" "text", "reconciliation_status" "text", "subledger_count" bigint, "gl_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant_bal numeric; v_tenant_cnt bigint; v_tenant_gl numeric; v_tenant_gl_cnt bigint;
  v_owner_bal numeric; v_owner_cnt bigint; v_owner_gl numeric; v_owner_gl_cnt bigint;
  v_dep_bal numeric; v_dep_cnt bigint; v_dep_gl numeric; v_dep_gl_cnt bigint;
  v_due_bal numeric; v_due_cnt bigint; v_due_gl numeric; v_due_gl_cnt bigint;
  v_comm_bal numeric; v_comm_cnt bigint; v_comm_gl numeric; v_comm_gl_cnt bigint;
  v_vat_bal numeric; v_vat_cnt bigint; v_vat_gl numeric; v_vat_gl_cnt bigint;
begin
  if p_company_id is null then
    raise exception 'WP05_RECONCILE_COMPANY_REQUIRED: company_id required' using errcode='22023';
  end if;

  if public.current_company_id() is not null and public.current_company_id() <> p_company_id then
    if current_user not in ('service_role','postgres','supabase_admin') then
      raise exception 'WP05_COMPANY_ISOLATION_VIOLATION: caller company does not match requested company' using errcode='42501';
    end if;
  end if;

  select balance, cnt into v_tenant_bal, v_tenant_cnt
    from public.wp05_subledger_tenant_receivables(p_company_id, p_as_of);
  v_tenant_gl := public.wp05_gl_balance(p_company_id, '1201', p_as_of);
  v_tenant_gl_cnt := public.wp05_gl_line_count(p_company_id, '1201', p_as_of);

  select balance, cnt into v_owner_bal, v_owner_cnt
    from public.wp05_subledger_owner_payables(p_company_id, p_as_of);
  v_owner_gl := public.wp05_gl_balance(p_company_id, '2000', p_as_of);
  v_owner_gl_cnt := public.wp05_gl_line_count(p_company_id, '2000', p_as_of);

  select balance, cnt into v_dep_bal, v_dep_cnt
    from public.wp05_subledger_security_deposits(p_company_id, p_as_of);
  v_dep_gl := public.wp05_gl_balance(p_company_id, '2200', p_as_of);
  v_dep_gl_cnt := public.wp05_gl_line_count(p_company_id, '2200', p_as_of);

  select balance, cnt into v_due_bal, v_due_cnt
    from public.wp05_subledger_due_from_owner(p_company_id, p_as_of);
  v_due_gl := public.wp05_gl_balance(p_company_id, '1300', p_as_of);
  v_due_gl_cnt := public.wp05_gl_line_count(p_company_id, '1300', p_as_of);

  select balance, cnt into v_comm_bal, v_comm_cnt
    from public.wp05_subledger_commission(p_company_id, p_as_of);
  v_comm_gl := public.wp05_gl_balance(p_company_id, '2300', p_as_of);
  v_comm_gl_cnt := public.wp05_gl_line_count(p_company_id, '2300', p_as_of);

  select balance, cnt into v_vat_bal, v_vat_cnt
    from public.rc1_owner_agency_vat_payable_balance(p_company_id, p_as_of);
  v_vat_gl := public.wp05_gl_balance(p_company_id, '2100', p_as_of);
  v_vat_gl_cnt := public.wp05_gl_line_count(p_company_id, '2100', p_as_of);

  return query
  select 'TENANT_RECEIVABLES'::text, '1201'::text, 'Tenant Receivable'::text,
         public.wp05_round_omr(v_tenant_bal), public.wp05_round_omr(v_tenant_gl),
         public.wp05_round_omr(v_tenant_bal - v_tenant_gl),
         public.wp05_round_omr(abs(v_tenant_bal - v_tenant_gl)),
         'OMR'::text,
         case when abs(v_tenant_bal - v_tenant_gl) <= 0.001 then 'PASS' else 'FAIL' end::text,
         v_tenant_cnt, v_tenant_gl_cnt
  union all
  select 'OWNER_PAYABLES'::text, '2000'::text, 'Owner Funds Payable'::text,
         public.wp05_round_omr(v_owner_bal), public.wp05_round_omr(v_owner_gl),
         public.wp05_round_omr(v_owner_bal - v_owner_gl),
         public.wp05_round_omr(abs(v_owner_bal - v_owner_gl)),
         'OMR'::text,
         case when abs(v_owner_bal - v_owner_gl) <= 0.001 then 'PASS' else 'FAIL' end::text,
         v_owner_cnt, v_owner_gl_cnt
  union all
  select 'SECURITY_DEPOSITS'::text, '2200'::text, 'Tenant Deposits Payable'::text,
         public.wp05_round_omr(v_dep_bal), public.wp05_round_omr(v_dep_gl),
         public.wp05_round_omr(v_dep_bal - v_dep_gl),
         public.wp05_round_omr(abs(v_dep_bal - v_dep_gl)),
         'OMR'::text,
         case when abs(v_dep_bal - v_dep_gl) <= 0.001 then 'PASS' else 'FAIL' end::text,
         v_dep_cnt, v_dep_gl_cnt
  union all
  select 'DUE_FROM_OWNER'::text, '1300'::text, 'Due from Owners'::text,
         public.wp05_round_omr(v_due_bal), public.wp05_round_omr(v_due_gl),
         public.wp05_round_omr(v_due_bal - v_due_gl),
         public.wp05_round_omr(abs(v_due_bal - v_due_gl)),
         'OMR'::text,
         case when abs(v_due_bal - v_due_gl) <= 0.001 then 'PASS' else 'FAIL' end::text,
         v_due_cnt, v_due_gl_cnt
  union all
  select 'COMMISSION'::text, '2300'::text, 'Broker Commissions Payable'::text,
         public.wp05_round_omr(v_comm_bal), public.wp05_round_omr(v_comm_gl),
         public.wp05_round_omr(v_comm_bal - v_comm_gl),
         public.wp05_round_omr(abs(v_comm_bal - v_comm_gl)),
         'OMR'::text,
         case when abs(v_comm_bal - v_comm_gl) <= 0.001 then 'PASS' else 'FAIL' end::text,
         v_comm_cnt, v_comm_gl_cnt
  union all
  select 'VAT_PAYABLE'::text, '2100'::text, 'VAT Payable'::text,
         public.wp05_round_omr(v_vat_bal), public.wp05_round_omr(v_vat_gl),
         public.wp05_round_omr(v_vat_bal - v_vat_gl),
         public.wp05_round_omr(abs(v_vat_bal - v_vat_gl)),
         'OMR'::text,
         case when abs(v_vat_bal - v_vat_gl) <= 0.001 then 'PASS' else 'FAIL' end::text,
         v_vat_cnt, v_vat_gl_cnt;
end;
$$;


ALTER FUNCTION "public"."wp05_reconcile_all"("p_company_id" "uuid", "p_as_of" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."wp05_reconcile_all"("p_company_id" "uuid", "p_as_of" "date") IS 'GAP-013 deterministic OMR 3dp reconciliation including 1201/1300/2000/2100/2200/2300 with 0.001 tolerance.';



CREATE OR REPLACE FUNCTION "public"."wp05_reject_correction_proposal"("p_proposal_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_row public.wp05_correction_proposals%rowtype;
begin
  if auth.uid() is null or not (public.is_accountant() or public.is_admin()) then
    raise exception 'WP05_PROPOSAL_CHECKER_ROLE_REQUIRED: ACCOUNTANT or ADMIN required to reject a correction proposal' using errcode='42501';
  end if;
  if p_proposal_id is null then
    raise exception 'WP05_PROPOSAL_ID_REQUIRED' using errcode='22023';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'WP05_PROPOSAL_REJECTION_REASON_REQUIRED: non-empty reason required' using errcode='22023';
  end if;

  select * into v_row
  from public.wp05_correction_proposals
  where id = p_proposal_id and company_id = v_company_id
  for update;

  if not found then
    raise exception 'WP05_PROPOSAL_NOT_FOUND: proposal % not found for company %', p_proposal_id, v_company_id using errcode='P0002';
  end if;
  if v_row.status <> 'PENDING_APPROVAL' then
    raise exception 'WP05_PROPOSAL_STATUS_INVALID: only PENDING_APPROVAL can be rejected, current %', v_row.status using errcode='23514';
  end if;

  perform set_config('malik.wp05_proposal_change_authorized', 'true', true);

  update public.wp05_correction_proposals
  set status = 'REJECTED',
      checker_user_id = auth.uid(),
      decided_at = now(),
      decision_note = btrim(p_reason),
      updated_at = now()
  where id = p_proposal_id and company_id = v_company_id;

  perform set_config('malik.wp05_proposal_change_authorized', 'false', true);

  insert into public.audit_log (
    id, ts, user_id, username, action, entity, entity_id, note, "table", details, created_at, old_value, new_value
  ) values (
    gen_random_uuid(), extract(epoch from now())::bigint, auth.uid(),
    (select email from auth.users where id = auth.uid()),
    'WP05_PROPOSAL_REJECTED', 'wp05_correction_proposals', p_proposal_id::text,
    'Proposal rejected by Accounting; no GL posting performed.',
    'wp05_correction_proposals', left(p_reason, 4000), now(),
    jsonb_build_object('status', 'PENDING_APPROVAL'),
    jsonb_build_object('status', 'REJECTED', 'checker_user_id', auth.uid())
  );

  return jsonb_build_object('success', true, 'id', p_proposal_id, 'status', 'REJECTED', 'posted_to_gl', false);
end;
$$;


ALTER FUNCTION "public"."wp05_reject_correction_proposal"("p_proposal_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_round_omr"("p_amount" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select round(coalesce(p_amount, 0)::numeric, 3)
$$;


ALTER FUNCTION "public"."wp05_round_omr"("p_amount" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."wp05_round_omr"("p_amount" numeric) IS 'WP-05 GAP-013: OMR canonical rounding to 3 decimals, exact decimal.';



CREATE OR REPLACE FUNCTION "public"."wp05_rpt_balance_sheet_gl"("p_as_of" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_assets numeric := 0;
  v_liabilities numeric := 0;
  v_equity numeric := 0;
  v_asset_rows jsonb;
  v_liability_rows jsonb;
  v_equity_rows jsonb;
begin
  if p_as_of is null then
    raise exception 'WP05_BS_AS_OF_REQUIRED' using errcode='22023';
  end if;

  with balances as (
    select
      a.no,
      a.name,
      a.account_type,
      public.wp05_round_omr(coalesce(sum(
        case
          when a.account_type = 'asset' then jl.debit - jl.credit
          else jl.credit - jl.debit
        end
      ),0)) as bal
    from public.accounts a
    left join (
      public.journal_lines jl
      join public.journal_batches jb
        on jb.id = jl.batch_id
       and jb.company_id = v_company_id
       and jb.status in ('POSTED','REVERSED')
       and jb.effective_date <= p_as_of
    ) on jl.account_id = a.id
      and jl.company_id = v_company_id
      and jl.deleted_at is null
    where a.company_id = v_company_id and a.is_active = true
    group by a.no, a.name, a.account_type
  )
  select
    public.wp05_round_omr(coalesce(sum(case when account_type = 'asset' then bal else 0 end),0)),
    public.wp05_round_omr(coalesce(sum(case when account_type = 'liability' then bal else 0 end),0)),
    public.wp05_round_omr(coalesce(sum(case when account_type in ('equity','revenue','expense') then bal else 0 end),0)),
    jsonb_agg(jsonb_build_object('code', no, 'name', name, 'amount', bal) order by no)
      filter (where account_type = 'asset' and abs(bal) > 0.0005),
    jsonb_agg(jsonb_build_object('code', no, 'name', name, 'amount', bal) order by no)
      filter (where account_type = 'liability' and abs(bal) > 0.0005),
    jsonb_agg(jsonb_build_object('code', no, 'name', name, 'amount', bal) order by no)
      filter (where account_type in ('equity','revenue','expense') and abs(bal) > 0.0005)
  into v_assets, v_liabilities, v_equity, v_asset_rows, v_liability_rows, v_equity_rows
  from balances;

  return jsonb_build_object(
    'as_of', p_as_of,
    'assets', coalesce(v_asset_rows, '[]'::jsonb),
    'liabilities', coalesce(v_liability_rows, '[]'::jsonb),
    'equity', coalesce(v_equity_rows, '[]'::jsonb),
    'total_assets', v_assets,
    'total_liabilities', v_liabilities,
    'total_equity', v_equity,
    'is_balanced', (abs(v_assets - (v_liabilities + v_equity)) <= 0.001)
  );
end;
$$;


ALTER FUNCTION "public"."wp05_rpt_balance_sheet_gl"("p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_rpt_cash_flow_gl"("p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_opening_cash numeric := 0;
  v_closing_cash numeric := 0;
  v_operating numeric := 0;
  v_investing numeric := 0;
  v_financing numeric := 0;
  v_unclassified numeric := 0;
  v_total_change numeric := 0;
  v_variance numeric := 0;
  v_opening_details jsonb;
  v_closing_details jsonb;
  v_period_from date := p_from;
  v_period_to date := p_to;
begin
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'WP05_CASHFLOW_PERIOD_REQUIRED: valid p_from and p_to required' using errcode='22023';
  end if;

  -- Company isolation enforced by require_company_id and RLS, but double-check
  if public.current_company_id() is not null and public.current_company_id() <> v_company_id then
    if current_user not in ('service_role','postgres','supabase_admin') then
      raise exception 'WP05_COMPANY_ISOLATION_VIOLATION' using errcode='42501';
    end if;
  end if;

  -- Opening cash: balance of cash accounts as of day before p_from
  select public.wp05_round_omr(coalesce(sum(
    case when a.normal_balance = 'debit' then jl.debit - jl.credit else jl.credit - jl.debit end
  ),0))
  into v_opening_cash
  from public.journal_lines jl
  join public.journal_batches jb on jb.id = jl.batch_id and jb.company_id = v_company_id and jb.status in ('POSTED','REVERSED') and jb.effective_date < p_from
  join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
  where jl.company_id = v_company_id and a.no = any(public.wp05_cash_accounts()) and jl.deleted_at is null;

  -- Closing cash: balance as of p_to inclusive
  select public.wp05_round_omr(coalesce(sum(
    case when a.normal_balance = 'debit' then jl.debit - jl.credit else jl.credit - jl.debit end
  ),0))
  into v_closing_cash
  from public.journal_lines jl
  join public.journal_batches jb on jb.id = jl.batch_id and jb.company_id = v_company_id and jb.status in ('POSTED','REVERSED') and jb.effective_date <= p_to
  join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
  where jl.company_id = v_company_id and a.no = any(public.wp05_cash_accounts()) and jl.deleted_at is null;

  -- Cash movements in period: for each batch with cash lines, attribute to classification via non-cash lines
  -- Contribution = credit - debit for non-cash? Actually cash change = sum_cash(debit-credit). And contribution per non-cash = credit - debit (which equals cash change portion)
  -- For batches without cash lines, ignore
  with batches_with_cash as (
    select distinct jb.id
    from public.journal_batches jb
    join public.journal_lines jl on jl.batch_id = jb.id and jl.company_id = v_company_id
    join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
    where jb.company_id = v_company_id
      and jb.status in ('POSTED','REVERSED')
      and jb.effective_date between p_from and p_to
      and a.no = any(public.wp05_cash_accounts())
      and jl.deleted_at is null
  ),
  cash_movements as (
    -- For each batch, sum non-cash lines grouped by classification
    select
      jb.id as batch_id,
      coalesce(cfc.classification, 'UNCLASSIFIED') as classification,
      public.wp05_round_omr(sum(jl.credit - jl.debit)) as amount
    from public.journal_batches jb
    join batches_with_cash bwc on bwc.id = jb.id
    join public.journal_lines jl on jl.batch_id = jb.id and jl.company_id = v_company_id and jl.deleted_at is null
    join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
    left join public.gl_cash_flow_classifications cfc on cfc.company_id = v_company_id and cfc.account_id = a.id and cfc.is_active = true
    where jb.company_id = v_company_id
      and a.no <> all(public.wp05_cash_accounts())
    group by jb.id, coalesce(cfc.classification, 'UNCLASSIFIED')
  )
  select
    public.wp05_round_omr(coalesce(sum(case when classification = 'OPERATING' then amount else 0 end),0)),
    public.wp05_round_omr(coalesce(sum(case when classification = 'INVESTING' then amount else 0 end),0)),
    public.wp05_round_omr(coalesce(sum(case when classification = 'FINANCING' then amount else 0 end),0)),
    public.wp05_round_omr(coalesce(sum(case when classification = 'UNCLASSIFIED' then amount else 0 end),0))
  into v_operating, v_investing, v_financing, v_unclassified
  from cash_movements;

  v_total_change := public.wp05_round_omr(v_operating + v_investing + v_financing + v_unclassified);
  v_variance := public.wp05_round_omr(v_closing_cash - (v_opening_cash + v_total_change));

  -- Fail-closed: if variance >0.001, this is financial exception, but we still return details
  -- For gate, we provide assert function

  return jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'company_id', v_company_id,
    'opening_cash', v_opening_cash,
    'operating', v_operating,
    'investing', v_investing,
    'financing', v_financing,
    'unclassified', v_unclassified,
    'total_change', v_total_change,
    'closing_cash', v_closing_cash,
    'variance', v_variance,
    'is_balanced', (abs(v_variance) <= 0.001),
    'currency', 'OMR',
    'precision', 3
  );
end;
$$;


ALTER FUNCTION "public"."wp05_rpt_cash_flow_gl"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_rpt_general_ledger_gl"("p_from" "date", "p_to" "date", "p_account_no" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_lines jsonb;
begin
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'WP05_GL_PERIOD_REQUIRED' using errcode='22023';
  end if;

  select jsonb_agg(jsonb_build_object(
    'batch_id', jb.id,
    'account_no', a.no,
    'account_name', a.name,
    'effective_date', jb.effective_date,
    'posted_at', jb.posted_at,
    'status', jb.status,
    'source_type', jb.source_type,
    'source_id', jb.source_id,
    'event_id', jb.event_id,
    'debit', public.wp05_round_omr(jl.debit),
    'credit', public.wp05_round_omr(jl.credit),
    'line_description', jl.line_description,
    'ref_source_id', jl.ref_source_id,
    'ref_entity_type', jl.ref_entity_type,
    'ref_entity_id', jl.ref_entity_id
  ) order by jb.effective_date, jb.created_at, jl.created_at)
  into v_lines
  from public.journal_lines jl
  join public.journal_batches jb on jb.id = jl.batch_id and jb.company_id = v_company_id and jb.status in ('POSTED','REVERSED') and jb.effective_date between p_from and p_to
  join public.accounts a on a.id = jl.account_id and a.company_id = v_company_id
  where jl.company_id = v_company_id
    and jl.deleted_at is null
    and (p_account_no is null or a.no = p_account_no);

  return jsonb_build_object(
    'from', p_from,
    'to', p_to,
    'account_no', p_account_no,
    'lines', coalesce(v_lines, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."wp05_rpt_general_ledger_gl"("p_from" "date", "p_to" "date", "p_account_no" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_rpt_profit_loss_gl"("p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_revenue numeric := 0;
  v_expenses numeric := 0;
  v_net numeric := 0;
  v_rev_rows jsonb;
  v_exp_rows jsonb;
begin
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'WP05_PL_PERIOD_REQUIRED: valid p_from and p_to required' using errcode='22023';
  end if;

  with period_lines as (
    select
      a.no,
      a.name,
      a.account_type,
      public.wp05_round_omr(coalesce(sum(case when a.account_type in ('revenue') then jl.credit - jl.debit when a.account_type in ('expense') then jl.debit - jl.credit else 0 end),0)) as amount
    from public.accounts a
    join public.journal_lines jl on jl.account_id = a.id and jl.company_id = v_company_id and jl.deleted_at is null
    join public.journal_batches jb on jb.id = jl.batch_id and jb.company_id = v_company_id and jb.status in ('POSTED','REVERSED') and jb.effective_date between p_from and p_to
    where a.company_id = v_company_id and a.is_active = true
      and (a.account_type = 'revenue' or a.account_type = 'expense')
    group by a.no, a.name, a.account_type
    having abs(coalesce(sum(case when a.account_type = 'revenue' then jl.credit - jl.debit else jl.debit - jl.credit end),0)) > 0.0005
  )
  select
    public.wp05_round_omr(coalesce(sum(case when account_type = 'revenue' then amount else 0 end),0)),
    public.wp05_round_omr(coalesce(sum(case when account_type = 'expense' then amount else 0 end),0)),
    jsonb_agg(jsonb_build_object('label', name, 'code', no, 'amount', amount) order by no)
      filter (where account_type = 'revenue'),
    jsonb_agg(jsonb_build_object('label', name, 'code', no, 'amount', amount) order by no)
      filter (where account_type = 'expense')
  into v_revenue, v_expenses, v_rev_rows, v_exp_rows
  from period_lines;

  v_net := public.wp05_round_omr(v_revenue - v_expenses);

  return jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'revenue', coalesce(v_rev_rows, '[]'::jsonb),
    'total_revenue', v_revenue,
    'expenses', coalesce(v_exp_rows, '[]'::jsonb),
    'total_expenses', v_expenses,
    'net_income', v_net
  );
end;
$$;


ALTER FUNCTION "public"."wp05_rpt_profit_loss_gl"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wp05_rpt_trial_balance_gl"("p_as_of" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := public.require_company_id();
  v_accounts jsonb;
  v_total_debits numeric := 0;
  v_total_credits numeric := 0;
begin
  if p_as_of is null then
    raise exception 'WP05_TB_AS_OF_REQUIRED: p_as_of date required' using errcode='22023';
  end if;

  with balances as (
    select
      a.no as code,
      a.name,
      a.account_type as type,
      a.normal_balance as balance_type,
      public.wp05_round_omr(coalesce(sum(case when a.normal_balance = 'debit' then jl.debit - jl.credit else jl.credit - jl.debit end),0)) as balance,
      public.wp05_round_omr(coalesce(sum(jl.debit),0)) as debits,
      public.wp05_round_omr(coalesce(sum(jl.credit),0)) as credits
    from public.accounts a
    left join (
      public.journal_lines jl
      join public.journal_batches jb
        on jb.id = jl.batch_id
       and jb.company_id = v_company_id
       and jb.status in ('POSTED','REVERSED')
       and jb.effective_date <= p_as_of
    ) on jl.account_id = a.id
      and jl.company_id = v_company_id
      and jl.deleted_at is null
    where a.company_id = v_company_id and a.is_active = true
    group by a.no, a.name, a.account_type, a.normal_balance
    having coalesce(sum(jl.debit),0) <> 0 or coalesce(sum(jl.credit),0) <> 0
  )
  select jsonb_agg(jsonb_build_object('code', code, 'name', name, 'type', type, 'balance_type', balance_type, 'balance', balance) order by code),
         public.wp05_round_omr(coalesce(sum(debits),0)),
         public.wp05_round_omr(coalesce(sum(credits),0))
  into v_accounts, v_total_debits, v_total_credits
  from balances;

  return jsonb_build_object(
    'as_of', p_as_of,
    'accounts', coalesce(v_accounts, '[]'::jsonb),
    'total_debits', v_total_debits,
    'total_credits', v_total_credits,
    'is_balanced', (abs(v_total_debits - v_total_credits) <= 0.001)
  );
end;
$$;


