CREATE OR REPLACE VIEW "public"."current_property_ownership" WITH ("security_invoker"='true') AS
 SELECT "pr"."id" AS "property_id",
    "pr"."title" AS "property_title",
    "pr"."company_id",
    "po"."id" AS "property_owner_id",
    "po"."owner_id",
    COALESCE(NULLIF("btrim"("o"."display_name"), ''::"text"), NULLIF("btrim"("o"."full_name"), ''::"text"), "o"."name") AS "owner_name",
    "po"."ownership_percentage",
    "po"."is_primary",
    "po"."starts_on" AS "ownership_starts_on",
    "po"."ends_on" AS "ownership_ends_on",
    "oa"."id" AS "agreement_id",
    "oa"."agreement_type",
    "oa"."commission_type",
    "oa"."commission_value",
    "oa"."starts_on" AS "agreement_starts_on",
    "oa"."ends_on" AS "agreement_ends_on"
   FROM ((("public"."properties" "pr"
     JOIN "public"."property_owners" "po" ON (("po"."property_id" = "pr"."id")))
     JOIN "public"."owners" "o" ON (("o"."id" = "po"."owner_id")))
     LEFT JOIN "public"."owner_agreements" "oa" ON ((("oa"."property_id" = "pr"."id") AND ("oa"."owner_id" = "po"."owner_id") AND (("oa"."starts_on" IS NULL) OR ("oa"."starts_on" <= CURRENT_DATE)) AND (("oa"."ends_on" IS NULL) OR ("oa"."ends_on" >= CURRENT_DATE)))))
  WHERE (("pr"."deleted_at" IS NULL) AND ("o"."deleted_at" IS NULL) AND "o"."is_active" AND (("po"."starts_on" IS NULL) OR ("po"."starts_on" <= CURRENT_DATE)) AND (("po"."ends_on" IS NULL) OR ("po"."ends_on" >= CURRENT_DATE)));


ALTER VIEW "public"."current_property_ownership" OWNER TO "postgres";


COMMENT ON VIEW "public"."current_property_ownership" IS 'Canonical view resolving active property ownership (property_owners) and management agreement (owner_agreements) per property as of CURRENT_DATE.';



