    CONSTRAINT "deposit_application_claims_claim_kind_check" CHECK (("claim_kind" = ANY (ARRAY['INVOICE_ARREARS'::"text", 'DAMAGE'::"text"]))),
    CONSTRAINT "deposit_application_claims_evidence_uri_check" CHECK ((("length"("btrim"("evidence_uri")) >= 3) AND ("length"("btrim"("evidence_uri")) <= 2000))),
