    CONSTRAINT "deposit_application_claims_reversal_shape_chk" CHECK ((("status" <> 'REVERSED'::"text") OR (("reversal_request_id" IS NOT NULL) AND ("reversal_journal_batch_id" IS NOT NULL) AND (NULLIF("btrim"("reversal_reason"), ''::"text") IS NOT NULL) AND ("reversed_by" IS NOT NULL) AND ("reversed_at" IS NOT NULL)))),
