COMMENT ON COLUMN "public"."invoices"."invoice_accounting_classification" IS 'RC1 immutable server-derived invoice accounting model. Null denotes pre-RC1 historical lineage requiring evidence-based review.';



COMMENT ON COLUMN "public"."invoices"."invoice_posting_batch_id" IS 'Canonical journal batch created by this invoice posting. Null is authoritative only for OWNER_IS_CREDITOR operational invoices.';



COMMENT ON COLUMN "public"."invoices"."tax_snapshot_id" IS 'Immutable taxable_line_tax_snapshots row for a TAXABLE RC1 invoice; credits reverse this original lineage rather than current tax configuration.';



CREATE TABLE IF NOT EXISTS "public"."journal_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" DEFAULT "public"."current_company_id"() NOT NULL,
    "status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "text" DEFAULT ''::"text" NOT NULL,
    "event_id" "text" NOT NULL,
    "reversal_of_batch_id" "uuid",
    "is_legacy_compat" boolean DEFAULT false NOT NULL,
    "effective_date" "date" NOT NULL,
    "accounting_period_id" "uuid",
    "period_resolution_reason" "text",
    "posted_at" timestamp with time zone,
    "posted_by" "uuid",
    "description" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "posting_date" "date",
    "late_posting" boolean DEFAULT false NOT NULL,
    CONSTRAINT "journal_batches_no_self_reversal_chk" CHECK ((("reversal_of_batch_id" IS NULL) OR ("reversal_of_batch_id" <> "id"))),
    CONSTRAINT "journal_batches_posted_traceability_chk" CHECK ((("status" <> ALL (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) OR (("btrim"("source_type") <> ''::"text") AND ("btrim"("event_id") <> ''::"text") AND ("posted_at" IS NOT NULL) AND ("is_legacy_compat" OR (("btrim"("source_id") <> ''::"text") AND ("accounting_period_id" IS NOT NULL)))))),
    CONSTRAINT "journal_batches_reversed_requires_reversal_chk" CHECK ((("status" <> 'REVERSED'::"text") OR ("reversal_of_batch_id" IS NOT NULL))),
    CONSTRAINT "journal_batches_status_chk" CHECK (("status" = ANY (ARRAY['DRAFT'::"text", 'POSTED'::"text", 'REVERSED'::"text"])))
);


ALTER TABLE "public"."journal_batches" OWNER TO "postgres";


COMMENT ON TABLE "public"."journal_batches" IS 'Stage 3 canonical journal batch. Posted batches are immutable; corrections use reversal batches.';



COMMENT ON COLUMN "public"."journal_batches"."event_id" IS 'Deterministic business-event identifier (never a timestamp or random value). The unique (company_id, source_type, source_id, event_id) key makes posting idempotent at the database level.';



COMMENT ON COLUMN "public"."journal_batches"."period_resolution_reason" IS 'Why the resolved accounting period differs from the effective date: open_period_contains_date, or redirected_earliest_open_period.';



COMMENT ON COLUMN "public"."journal_batches"."posting_date" IS 'Server-derived GL posting date. Equals effective_date in the containing OPEN period; for redirected late events it equals the receiving OPEN period start_date.';



COMMENT ON COLUMN "public"."journal_batches"."late_posting" IS 'True only when the canonical posting engine redirects an event from its effective period to the earliest eligible OPEN period.';



CREATE TABLE IF NOT EXISTS "public"."journal_lines" (
    "id" "text" NOT NULL,
    "no" "text",
    "date" "text",
    "batch_id" "uuid" NOT NULL,
    "company_id" "uuid" DEFAULT "public"."current_company_id"() NOT NULL,
    "account_id" "text" NOT NULL,
    "debit" numeric(18,3) DEFAULT 0 NOT NULL,
    "credit" numeric(18,3) DEFAULT 0 NOT NULL,
    "line_description" "text",
    "ref_source_id" "text",
    "ref_entity_type" "text",
    "ref_entity_id" "text",
    "request_id" "text",
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "journal_lines_debit_credit_chk" CHECK (((("debit" > (0)::numeric) AND ("credit" = (0)::numeric)) OR (("credit" > (0)::numeric) AND ("debit" = (0)::numeric)))),
    CONSTRAINT "journal_lines_precision_chk" CHECK ((("debit" = "round"("debit", 3)) AND ("credit" = "round"("credit", 3))))
);


ALTER TABLE "public"."journal_lines" OWNER TO "postgres";


COMMENT ON TABLE "public"."journal_lines" IS 'Stage 3 canonical journal line. Posted lines are immutable; corrections use reversal batches.';



CREATE OR REPLACE VIEW "public"."journal_entries" WITH ("security_invoker"='true') AS
 SELECT "l"."id",
    "l"."no",
    "l"."date",
    "l"."account_id",
        CASE
            WHEN ("l"."debit" > (0)::numeric) THEN "l"."debit"
            ELSE "l"."credit"
        END AS "amount",
        CASE
            WHEN ("l"."debit" > (0)::numeric) THEN 'DEBIT'::"text"
            ELSE 'CREDIT'::"text"
        END AS "type",
    "l"."ref_source_id" AS "source_id",
        CASE
            WHEN (("b"."source_type" = 'journal_reversal'::"text") AND ("original_batch"."source_type" = 'receipt'::"text")) THEN 'receipt_void'::"text"
            ELSE "l"."ref_entity_type"
        END AS "entity_type",
        CASE
            WHEN (("b"."source_type" = 'journal_reversal'::"text") AND ("original_batch"."source_type" = 'receipt'::"text")) THEN "original_batch"."source_id"
            ELSE "l"."ref_entity_id"
        END AS "entity_id",
    "l"."created_at",
    "b"."company_id",
    "b"."id" AS "batch_id",
    "l"."request_id",
        CASE "b"."status"
            WHEN 'DRAFT'::"text" THEN 'draft'::"text"
            ELSE 'posted'::"text"
        END AS "status",
    "l"."deleted_at"
   FROM (("public"."journal_lines" "l"
     JOIN "public"."journal_batches" "b" ON (("b"."id" = "l"."batch_id")))
     LEFT JOIN "public"."journal_batches" "original_batch" ON ((("original_batch"."id" = "b"."reversal_of_batch_id") AND ("original_batch"."company_id" = "b"."company_id"))));


ALTER VIEW "public"."journal_entries" OWNER TO "postgres";


COMMENT ON VIEW "public"."journal_entries" IS 'Stage 3 compatibility projection over canonical journal lines/batches. Receipt reversal rows are projected as receipt_void for legacy readers without mutating canonical reversal references.';



