CREATE OR REPLACE VIEW "public"."party_directory" WITH ("security_invoker"='true') AS
 SELECT ('owner:'::"text" || ("o"."id")::"text") AS "party_key",
    ("o"."id")::"text" AS "source_id",
    'owners'::"text" AS "source_table",
    'owner'::"text" AS "role",
    COALESCE(NULLIF("btrim"("o"."display_name"), ''::"text"), NULLIF("btrim"("o"."full_name"), ''::"text"), "o"."name") AS "display_name",
    "o"."full_name",
    "o"."phone",
    "o"."email",
    "o"."national_id",
    "o"."company_id",
    "o"."is_active" AS "active",
    ("o"."deleted_at" IS NULL) AS "live"
   FROM "public"."owners" "o"
UNION ALL
 SELECT ('person:'::"text" || ("p"."id")::"text") AS "party_key",
    ("p"."id")::"text" AS "source_id",
    'people'::"text" AS "source_table",
        CASE "p"."type"
            WHEN 'tenant'::"text" THEN 'tenant'::"text"
            WHEN 'contact'::"text" THEN 'contact'::"text"
            ELSE 'owner_legacy_person'::"text"
        END AS "role",
    "p"."full_name" AS "display_name",
    "p"."full_name",
    "p"."phone",
    "p"."email",
    "p"."national_id",
    "p"."company_id",
    true AS "active",
    ("p"."deleted_at" IS NULL) AS "live"
   FROM "public"."people" "p";


ALTER VIEW "public"."party_directory" OWNER TO "postgres";


COMMENT ON VIEW "public"."party_directory" IS 'R7 unified party identity read model: one row per identity+role across owners/people. security_invoker: RLS of the underlying tables applies. Legacy owner-typed person rows surface as owner_legacy_person so duplication is visible pending the governed Party merge.';



