CREATE OR REPLACE VIEW "public"."s08_liability_balances_by_period" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "company_id",
    "c"."name" AS "company_name",
    "ap"."id" AS "accounting_period_id",
    "ap"."name" AS "accounting_period",
    "ap"."start_date",
    "ap"."end_date",
    "a"."id" AS "gl_account_id",
    "a"."no" AS "gl_account_no",
    "a"."name" AS "gl_account_name",
        CASE
            WHEN ("a"."no" ~~ '1%'::"text") THEN 'asset'::"text"
            WHEN ("a"."no" ~~ '2%'::"text") THEN 'liability'::"text"
            ELSE 'other'::"text"
        END AS "account_type",
        CASE
            WHEN ("a"."no" = '2000'::"text") THEN "public"."wp05_round_omr"(COALESCE("ob"."net_balance", (0)::numeric))
            WHEN ("a"."no" = '1300'::"text") THEN "public"."wp05_round_omr"((COALESCE("ob_due"."balance_due", (0)::numeric) * ('-1'::integer)::numeric))
            WHEN ("a"."no" = '2200'::"text") THEN "public"."wp05_round_omr"(COALESCE("td_agg"."remaining_deposits", (0)::numeric))
            WHEN ("a"."no" = '2300'::"text") THEN "public"."wp05_round_omr"(COALESCE("comm_agg"."payable", (0)::numeric))
            ELSE "public"."wp05_round_omr"(COALESCE("gl_agg"."gl_balance", (0)::numeric))
        END AS "subledger_balance",
    "public"."wp05_round_omr"(COALESCE("gl_agg"."gl_balance", (0)::numeric)) AS "gl_balance",
    "public"."wp05_round_omr"((COALESCE("gl_agg"."gl_balance", (0)::numeric) -
        CASE
            WHEN ("a"."no" = '2000'::"text") THEN COALESCE("ob"."net_balance", (0)::numeric)
            WHEN ("a"."no" = '1300'::"text") THEN (COALESCE("ob_due"."balance_due", (0)::numeric) * ('-1'::integer)::numeric)
            WHEN ("a"."no" = '2200'::"text") THEN COALESCE("td_agg"."remaining_deposits", (0)::numeric)
            WHEN ("a"."no" = '2300'::"text") THEN COALESCE("comm_agg"."payable", (0)::numeric)
            ELSE COALESCE("gl_agg"."gl_balance", (0)::numeric)
        END)) AS "difference",
    NULL::"uuid" AS "owner_id",
    NULL::"uuid" AS "property_id",
    NULL::"uuid" AS "agreement_id",
        CASE
            WHEN ("a"."no" ~~ '1%'::"text") THEN 'asset'::"text"
            WHEN ("a"."no" ~~ '2%'::"text") THEN 'liability'::"text"
            ELSE 'other'::"text"
        END AS "source_class"
   FROM ((((((("public"."companies" "c"
     JOIN "public"."accounting_periods" "ap" ON (("ap"."company_id" = "c"."id")))
     JOIN "public"."accounts" "a" ON (("a"."company_id" = "c"."id")))
     LEFT JOIN LATERAL ( SELECT "sum"(
                CASE
                    WHEN ("a"."no" = ANY (ARRAY['1201'::"text", '1300'::"text", '1111'::"text", '1120'::"text", '1600'::"text"])) THEN ("jl"."debit" - "jl"."credit")
                    ELSE ("jl"."credit" - "jl"."debit")
                END) AS "gl_balance"
           FROM ("public"."journal_lines" "jl"
             JOIN "public"."journal_batches" "jb" ON (("jb"."id" = "jl"."batch_id")))
          WHERE (("jl"."account_id" = "a"."id") AND ("jl"."company_id" = "c"."id") AND ("jb"."company_id" = "c"."id") AND ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) AND ("jb"."effective_date" <= "ap"."end_date"))) "gl_agg" ON (true))
     LEFT JOIN LATERAL ( SELECT "avg"("ob2"."net_balance") AS "net_balance"
           FROM "public"."owner_balances" "ob2"
          WHERE ("ob2"."company_id" = "c"."id")) "ob" ON (("a"."no" = '2000'::"text")))
     LEFT JOIN LATERAL ( SELECT "sum"("cb"."balance_due") AS "balance_due"
           FROM "public"."contract_balances" "cb"
          WHERE ("cb"."company_id" = "c"."id")) "ob_due" ON (("a"."no" = '1300'::"text")))
     LEFT JOIN LATERAL ( SELECT "sum"("td"."remaining_amount") AS "remaining_deposits"
           FROM "public"."tenant_deposits" "td"
          WHERE (("td"."company_id" = "c"."id") AND ("td"."deleted_at" IS NULL))) "td_agg" ON (("a"."no" = '2200'::"text")))
     LEFT JOIN LATERAL ( SELECT "sum"("comm"."amount") AS "payable"
           FROM "public"."commissions" "comm"
          WHERE (("comm"."company_id" = "c"."id") AND ("upper"("comm"."status") = ANY (ARRAY['PENDING'::"text", 'APPROVED'::"text", 'PAYABLE'::"text"])))) "comm_agg" ON (("a"."no" = '2300'::"text")))
  WHERE (("c"."is_active" IS NOT NULL) AND ("a"."no" = ANY (ARRAY['2000'::"text", '1300'::"text", '2200'::"text", '2300'::"text", '2100'::"text", '1201'::"text", '1101'::"text"])));


ALTER VIEW "public"."s08_liability_balances_by_period" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."s08_master_lease_readiness" WITH ("security_invoker"='true') AS
 SELECT "oa"."id" AS "master_lease_id",
    "prop"."company_id",
    COALESCE("comp"."name", ("prop"."company_id")::"text") AS "company_name",
    "oa"."property_id",
    COALESCE("prop"."title", ''::"text") AS "property_name",
    "oa"."starts_on" AS "commencement_date",
        CASE
            WHEN (("oa"."ends_on" IS NOT NULL) AND ("oa"."starts_on" IS NOT NULL)) THEN (((("date_part"('year'::"text", "oa"."ends_on") - "date_part"('year'::"text", "oa"."starts_on")) * (12)::double precision) + ("date_part"('month'::"text", "oa"."ends_on") - "date_part"('month'::"text", "oa"."starts_on"))))::integer
            ELSE NULL::integer
        END AS "lease_term_months",
    NULL::numeric AS "discount_rate",
    'BUILDING'::"text" AS "asset_class",
    false AS "short_term_election",
    NULL::numeric AS "rou_asset_amount",
    NULL::numeric AS "lease_liability_amount",
        CASE
            WHEN ("oa"."agreement_type" <> 'master_lease'::"text") THEN 'NOT_A_MASTER_LEASE'::"text"
            WHEN (("oa"."starts_on" IS NULL) OR ("oa"."ends_on" IS NULL)) THEN 'MISSING_CRITICAL_DATA'::"text"
            WHEN (("oa"."starts_on" IS NOT NULL) AND ("oa"."ends_on" IS NOT NULL)) THEN 'PARTIALLY_READY'::"text"
            ELSE 'REQUIRES_ACCOUNTANT_REVIEW'::"text"
        END AS "readiness"
   FROM (("public"."owner_agreements" "oa"
     JOIN "public"."properties" "prop" ON (("prop"."id" = "oa"."property_id")))
     LEFT JOIN "public"."companies" "comp" ON (("comp"."id" = "prop"."company_id")))
  WHERE ("oa"."agreement_type" = ANY (ARRAY['master_lease'::"text", 'property_management'::"text"]));


ALTER VIEW "public"."s08_master_lease_readiness" OWNER TO "postgres";


COMMENT ON VIEW "public"."s08_master_lease_readiness" IS 'S08 T08: READY/PARTIALLY_READY/MISSING_CRITICAL_DATA/NOT_A_MASTER_LEASE/REQUIRES_ACCOUNTANT_REVIEW only.';



CREATE OR REPLACE VIEW "public"."s08_retroactive_version_differences" WITH ("security_invoker"='true') AS
 SELECT "prop"."company_id",
    "c"."id" AS "contract_id",
    ("c"."id")::"text" AS "contract_number",
    "oa"."id" AS "agreement_id",
    ("oa"."starts_on")::"text" AS "agreement_version",
    "oa"."commission_value" AS "current_commission_rate",
    "oa"."commission_type" AS "current_commission_type",
    NULL::"text" AS "current_collection_role",
    "oa"."agreement_type" AS "current_operating_model",
    NULL::numeric AS "snapshot_commission_rate",
    NULL::"text" AS "snapshot_collection_role",
        CASE
            WHEN ("oa"."commission_value" IS DISTINCT FROM "c"."rent_amount") THEN 'POSSIBLE_OVERPAYMENT'::"text"
            WHEN ("oa"."agreement_type" <> 'property_management'::"text") THEN 'NEEDS_REVIEW'::"text"
            WHEN ("oa"."commission_value" IS NULL) THEN 'MISSING_VERSION_EVIDENCE'::"text"
            ELSE 'NO_ACTION'::"text"
        END AS "classification"
   FROM (("public"."contracts" "c"
     JOIN "public"."owner_agreements" "oa" ON (("oa"."property_id" = "c"."property_id")))
     JOIN "public"."properties" "prop" ON (("prop"."id" = "c"."property_id")))
  WHERE ("c"."deleted_at" IS NULL);


ALTER VIEW "public"."s08_retroactive_version_differences" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."s08_subledger_gl_reconciliation" WITH ("security_invoker"='true') AS
 SELECT "s"."company_id",
    "comp"."name" AS "company_name",
    "s"."accounting_period",
    "s"."subledger",
    "s"."gl_account_no",
    "s"."opening_balance",
    "s"."period_movements",
    "s"."closing_balance",
    "s"."gl_balance",
    "s"."subledger_balance",
    "public"."wp05_round_omr"(("s"."gl_balance" - "s"."subledger_balance")) AS "difference",
    "s"."source_count",
    "s"."earliest_source",
    "s"."latest_source",
        CASE
            WHEN ("abs"("public"."wp05_round_omr"(("s"."gl_balance" - "s"."subledger_balance"))) <= 0.001) THEN 'RECONCILED'::"text"
            ELSE 'MISMATCH'::"text"
        END AS "finding_classification"
   FROM (( SELECT "c"."id" AS "company_id",
            "ap"."name" AS "accounting_period",
            'Tenant Receivables'::"text" AS "subledger",
            '1201'::"text" AS "gl_account_no",
            (0)::numeric AS "opening_balance",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."debit" - "jl"."credit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "period_movements",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."debit" - "jl"."credit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "closing_balance",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."debit" - "jl"."credit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "gl_balance",
            COALESCE("cb_agg"."balance_due", (0)::numeric) AS "subledger_balance",
            ("count"("jl"."id"))::integer AS "source_count",
            ("min"("jb"."effective_date"))::timestamp with time zone AS "earliest_source",
            ("max"("jb"."effective_date"))::timestamp with time zone AS "latest_source"
           FROM ((((("public"."companies" "c"
             CROSS JOIN "public"."accounting_periods" "ap")
             LEFT JOIN "public"."accounts" "a" ON ((("a"."company_id" = "c"."id") AND ("a"."no" = '1201'::"text"))))
             LEFT JOIN "public"."journal_lines" "jl" ON ((("jl"."account_id" = "a"."id") AND ("jl"."company_id" = "c"."id"))))
             LEFT JOIN "public"."journal_batches" "jb" ON ((("jb"."id" = "jl"."batch_id") AND ("jb"."accounting_period_id" = "ap"."id") AND ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])))))
             LEFT JOIN LATERAL ( SELECT "sum"("cb"."balance_due") AS "balance_due"
                   FROM "public"."contract_balances" "cb"
                  WHERE ("cb"."company_id" = "c"."id")) "cb_agg" ON (true))
          WHERE (("c"."is_active" IS NOT NULL) AND ("ap"."company_id" = "c"."id"))
          GROUP BY "c"."id", "ap"."name", "cb_agg"."balance_due"
        UNION ALL
         SELECT "c"."id",
            "ap"."name",
            'Owner Funds Payable'::"text" AS "text",
            '2000'::"text" AS "text",
            (0)::numeric AS "numeric",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("ob_agg"."net_balance", (0)::numeric) AS "coalesce",
            ("count"("jl"."id"))::integer AS "count",
            ("min"("jb"."effective_date"))::timestamp with time zone AS "min",
            ("max"("jb"."effective_date"))::timestamp with time zone AS "max"
           FROM ((((("public"."companies" "c"
             CROSS JOIN "public"."accounting_periods" "ap")
             LEFT JOIN "public"."accounts" "a" ON ((("a"."company_id" = "c"."id") AND ("a"."no" = '2000'::"text"))))
             LEFT JOIN "public"."journal_lines" "jl" ON ((("jl"."account_id" = "a"."id") AND ("jl"."company_id" = "c"."id"))))
             LEFT JOIN "public"."journal_batches" "jb" ON ((("jb"."id" = "jl"."batch_id") AND ("jb"."accounting_period_id" = "ap"."id") AND ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])))))
             LEFT JOIN LATERAL ( SELECT "sum"("ob"."net_balance") AS "net_balance"
                   FROM "public"."owner_balances" "ob"
                  WHERE ("ob"."company_id" = "c"."id")) "ob_agg" ON (true))
          WHERE (("c"."is_active" IS NOT NULL) AND ("ap"."company_id" = "c"."id"))
          GROUP BY "c"."id", "ap"."name", "ob_agg"."net_balance"
        UNION ALL
         SELECT "c"."id",
            "ap"."name",
            'Due from Owner'::"text" AS "text",
            '1300'::"text" AS "text",
            (0)::numeric AS "numeric",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."debit" - "jl"."credit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."debit" - "jl"."credit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."debit" - "jl"."credit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("cb_agg"."balance_due", (0)::numeric) AS "coalesce",
            ("count"("jl"."id"))::integer AS "count",
            ("min"("jb"."effective_date"))::timestamp with time zone AS "min",
            ("max"("jb"."effective_date"))::timestamp with time zone AS "max"
           FROM ((((("public"."companies" "c"
             CROSS JOIN "public"."accounting_periods" "ap")
             LEFT JOIN "public"."accounts" "a" ON ((("a"."company_id" = "c"."id") AND ("a"."no" = '1300'::"text"))))
             LEFT JOIN "public"."journal_lines" "jl" ON ((("jl"."account_id" = "a"."id") AND ("jl"."company_id" = "c"."id"))))
             LEFT JOIN "public"."journal_batches" "jb" ON ((("jb"."id" = "jl"."batch_id") AND ("jb"."accounting_period_id" = "ap"."id") AND ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])))))
             LEFT JOIN LATERAL ( SELECT "sum"(
                        CASE
                            WHEN ("cb"."balance_due" < (0)::numeric) THEN (- "cb"."balance_due")
                            ELSE (0)::numeric
                        END) AS "balance_due"
                   FROM "public"."contract_balances" "cb"
                  WHERE ("cb"."company_id" = "c"."id")) "cb_agg" ON (true))
          WHERE (("c"."is_active" IS NOT NULL) AND ("ap"."company_id" = "c"."id"))
          GROUP BY "c"."id", "ap"."name", "cb_agg"."balance_due"
        UNION ALL
         SELECT "c"."id",
            "ap"."name",
            'Tenant Deposits'::"text" AS "text",
            '2200'::"text" AS "text",
            (0)::numeric AS "numeric",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("td_agg"."remaining", (0)::numeric) AS "coalesce",
            ("count"("jl"."id"))::integer AS "count",
            ("min"("jb"."effective_date"))::timestamp with time zone AS "min",
            ("max"("jb"."effective_date"))::timestamp with time zone AS "max"
           FROM ((((("public"."companies" "c"
             CROSS JOIN "public"."accounting_periods" "ap")
             LEFT JOIN "public"."accounts" "a" ON ((("a"."company_id" = "c"."id") AND ("a"."no" = '2200'::"text"))))
             LEFT JOIN "public"."journal_lines" "jl" ON ((("jl"."account_id" = "a"."id") AND ("jl"."company_id" = "c"."id"))))
             LEFT JOIN "public"."journal_batches" "jb" ON ((("jb"."id" = "jl"."batch_id") AND ("jb"."accounting_period_id" = "ap"."id") AND ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])))))
             LEFT JOIN LATERAL ( SELECT "sum"("td"."remaining_amount") AS "remaining"
                   FROM "public"."tenant_deposits" "td"
                  WHERE (("td"."company_id" = "c"."id") AND ("td"."deleted_at" IS NULL))) "td_agg" ON (true))
          WHERE (("c"."is_active" IS NOT NULL) AND ("ap"."company_id" = "c"."id"))
          GROUP BY "c"."id", "ap"."name", "td_agg"."remaining"
        UNION ALL
         SELECT "c"."id",
            "ap"."name",
            'Broker/Staff Commission Payable'::"text" AS "text",
            '2300'::"text" AS "text",
            (0)::numeric AS "numeric",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("sum"(
                CASE
                    WHEN ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])) THEN ("jl"."credit" - "jl"."debit")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "coalesce",
            COALESCE("comm_agg"."payable", (0)::numeric) AS "coalesce",
            ("count"("jl"."id"))::integer AS "count",
            ("min"("jb"."effective_date"))::timestamp with time zone AS "min",
            ("max"("jb"."effective_date"))::timestamp with time zone AS "max"
           FROM ((((("public"."companies" "c"
             CROSS JOIN "public"."accounting_periods" "ap")
             LEFT JOIN "public"."accounts" "a" ON ((("a"."company_id" = "c"."id") AND ("a"."no" = '2300'::"text"))))
             LEFT JOIN "public"."journal_lines" "jl" ON ((("jl"."account_id" = "a"."id") AND ("jl"."company_id" = "c"."id"))))
             LEFT JOIN "public"."journal_batches" "jb" ON ((("jb"."id" = "jl"."batch_id") AND ("jb"."accounting_period_id" = "ap"."id") AND ("jb"."status" = ANY (ARRAY['POSTED'::"text", 'REVERSED'::"text"])))))
             LEFT JOIN LATERAL ( SELECT "sum"("comm"."amount") AS "payable"
                   FROM "public"."commissions" "comm"
                  WHERE (("comm"."company_id" = "c"."id") AND ("upper"("comm"."status") = ANY (ARRAY['PENDING'::"text", 'APPROVED'::"text", 'PAYABLE'::"text"])))) "comm_agg" ON (true))
          WHERE (("c"."is_active" IS NOT NULL) AND ("ap"."company_id" = "c"."id"))
          GROUP BY "c"."id", "ap"."name", "comm_agg"."payable") "s"
     JOIN "public"."companies" "comp" ON (("comp"."id" = "s"."company_id")));


