CREATE TABLE IF NOT EXISTS "public"."s09_corrections" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" DEFAULT "public"."current_company_id"() NOT NULL,
    "accounting_period_id" "uuid",
    "review_id" "uuid" NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "text" NOT NULL,
    "source_scope" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reason" "text" NOT NULL,
    "status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "before_evidence" "jsonb",
    "after_evidence" "jsonb",
    "original_journal_batch_id" "uuid",
    "correction_journal_batch_id" "uuid",
    "reversal_journal_batch_id" "uuid",
    "amount" numeric(18,3) NOT NULL,
    "debit_account_id" "text",
    "credit_account_id" "text",
    "debit_account_no" "text",
    "credit_account_no" "text",
    "lines" "jsonb",
    "actor_id" "uuid",
    "request_id" "text" NOT NULL,
    "idempotency_key" "text",
    "validated_at" timestamp with time zone,
    "applied_at" timestamp with time zone,
    "reversed_at" timestamp with time zone,
    "reversal_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "s09_corrections_accounts_required" CHECK (((("debit_account_id" IS NOT NULL) AND ("credit_account_id" IS NOT NULL)) OR ("lines" IS NOT NULL))),
    CONSTRAINT "s09_corrections_amount_check" CHECK (("amount" >= (0)::numeric)),
    CONSTRAINT "s09_corrections_amount_positive" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "s09_corrections_reason_not_empty" CHECK (("btrim"("reason") <> ''::"text")),
    CONSTRAINT "s09_corrections_request_id_not_empty" CHECK (("btrim"("request_id") <> ''::"text")),
    CONSTRAINT "s09_corrections_source_not_empty" CHECK ((("btrim"("source_type") <> ''::"text") AND ("btrim"("source_id") <> ''::"text"))),
    CONSTRAINT "s09_corrections_status_check" CHECK (("status" = ANY (ARRAY['DRAFT'::"text", 'VALIDATED'::"text", 'APPLIED'::"text", 'REVERSED'::"text"])))
);


ALTER TABLE "public"."s09_corrections" OWNER TO "postgres";


