CREATE OR REPLACE VIEW "public"."v_balance_reconciliation" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "contract_id",
    "c"."property_id",
    "c"."unit_id",
    "c"."tenant_id",
    COALESCE("sum"(("i"."amount" + COALESCE("i"."tax_amount", (0)::numeric))) FILTER (WHERE (("i"."deleted_at" IS NULL) AND ("i"."status" <> 'VOID'::"text"))), (0)::numeric) AS "invoiced_amount",
    COALESCE("sum"("i"."paid_amount") FILTER (WHERE (("i"."deleted_at" IS NULL) AND ("i"."status" <> 'VOID'::"text"))), (0)::numeric) AS "invoice_paid_amount",
    COALESCE("sum"("p"."amount") FILTER (WHERE (("p"."deleted_at" IS NULL) AND (COALESCE("p"."status", 'POSTED'::"text") <> 'VOID'::"text"))), (0)::numeric) AS "posted_payment_amount",
    COALESCE("sum"((("i"."amount" + COALESCE("i"."tax_amount", (0)::numeric)) - "i"."paid_amount")) FILTER (WHERE (("i"."deleted_at" IS NULL) AND ("i"."status" <> 'VOID'::"text"))), (0)::numeric) AS "outstanding_amount",
    (COALESCE("sum"("i"."paid_amount") FILTER (WHERE (("i"."deleted_at" IS NULL) AND ("i"."status" <> 'VOID'::"text"))), (0)::numeric) - COALESCE("sum"("p"."amount") FILTER (WHERE (("p"."deleted_at" IS NULL) AND (COALESCE("p"."status", 'POSTED'::"text") <> 'VOID'::"text"))), (0)::numeric)) AS "paid_vs_payment_drift"
   FROM (("public"."contracts" "c"
     LEFT JOIN "public"."invoices" "i" ON (("i"."contract_id" = "c"."id")))
     LEFT JOIN "public"."payments" "p" ON (("p"."contract_id" = "c"."id")))
  WHERE ("c"."deleted_at" IS NULL)
  GROUP BY "c"."id", "c"."property_id", "c"."unit_id", "c"."tenant_id";


ALTER VIEW "public"."v_balance_reconciliation" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_balance_reconciliation_drift" WITH ("security_invoker"='true') AS
 SELECT "contract_id",
    "property_id",
    "unit_id",
    "tenant_id",
    "invoiced_amount",
    "invoice_paid_amount",
    "posted_payment_amount",
    "outstanding_amount",
    "paid_vs_payment_drift"
   FROM "public"."v_balance_reconciliation"
  WHERE ("abs"("paid_vs_payment_drift") > 0.01);


ALTER VIEW "public"."v_balance_reconciliation_drift" OWNER TO "postgres";


