CREATE TABLE IF NOT EXISTS "public"."wp05_correction_proposals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" DEFAULT "public"."current_company_id"() NOT NULL,
    "accounting_period_id" "uuid",
    "as_of" "date" NOT NULL,
    "reconciliation_class" "text" NOT NULL,
    "account_no" "text",
    "reason_code" "text" NOT NULL,
    "reason_detail" "text" NOT NULL,
    "proposal_type" "text" NOT NULL,
    "recommended_action" "text" NOT NULL,
    "status" "text" DEFAULT 'PENDING_APPROVAL'::"text" NOT NULL,
    "subledger_balance" numeric(18,3) NOT NULL,
    "gl_balance" numeric(18,3) NOT NULL,
    "variance_amount" numeric(18,3) NOT NULL,
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "maker_user_id" "uuid",
    "checker_user_id" "uuid",
    "decided_at" timestamp with time zone,
    "decision_note" "text",
    "s09_correction_id" "uuid",
    "request_id" "text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "wp05_correction_proposals_proposal_type_check" CHECK (("proposal_type" = ANY (ARRAY['MAPPING_FIX'::"text", 'MISSING_GL_POSTING'::"text", 'SUBLEDGER_DATA_FIX'::"text", 'INVESTIGATE_ONLY'::"text"]))),
    CONSTRAINT "wp05_correction_proposals_status_check" CHECK (("status" = ANY (ARRAY['PENDING_APPROVAL'::"text", 'APPROVED'::"text", 'REJECTED'::"text", 'SUPERSEDED'::"text"]))),
    CONSTRAINT "wp05_proposal_decision_requires_checker" CHECK ((("status" = ANY (ARRAY['PENDING_APPROVAL'::"text", 'SUPERSEDED'::"text"])) OR ("checker_user_id" IS NOT NULL))),
    CONSTRAINT "wp05_proposal_idempotency_not_empty" CHECK (("btrim"("idempotency_key") <> ''::"text")),
    CONSTRAINT "wp05_proposal_reason_not_empty" CHECK ((("btrim"("reason_code") <> ''::"text") AND ("btrim"("reason_detail") <> ''::"text"))),
    CONSTRAINT "wp05_proposal_request_id_not_empty" CHECK (("btrim"("request_id") <> ''::"text"))
);


ALTER TABLE "public"."wp05_correction_proposals" OWNER TO "postgres";


COMMENT ON TABLE "public"."wp05_correction_proposals" IS 'WP-05 GAP-018: append-only register of subledger↔GL variance findings. Rows are created PENDING_APPROVAL and never post to the GL; approval only authorises an S09 correction through the existing S08→S09 gate.';



